INSERT INTO game (name, price, description, genre, categories, hardware_requirements, released_at) VALUES
('Neon Abyss Drifters', 24.99, 'A vertical-slice roguelike set inside a collapsing arcology where gravity was sold off to creditors. You pilot a magnetic skiff down 900 floors of neon service shafts, scavenging parts from dead couriers and rebuilding your rig between runs. Every death permanently rewrites one district of the tower, so the map you memorize today is the map that betrays you tomorrow.', 'roguelike, action, racing', 'singleplayer, procedural generation, permadeath, controller support', 'potato pc without gpu, but the potato must be angry', '2021-04-16 09:00:00+00'),
('Mossgrave Chronicle', 39.99, 'A slow-burning tactical RPG about four gravediggers who discover that the dead in their valley refuse to stay buried because someone keeps paying them to come back. Combat is turn-based on a hex grid where terrain rots in real time, turning solid ground into sucking bog over four rounds. The story branches on who you choose to bury properly and who you leave for the crows.', 'rpg, strategy, tactical', 'singleplayer, story rich, turn-based, choices matter', '8 GB RAM, dedicated GPU with 4 GB VRAM, and a strong opinion about shovels', '2020-10-02 12:00:00+00'),
('Turbo Gasket Rally', 14.50, 'An arcade rally sim where every car is held together by duct tape and legal ambiguity. Tracks are generated from real topographic data of places that do not exist, and your codriver reads pace notes in a language you slowly learn over 60 stages. Break a gasket mid-stage and you finish the run in limp mode, engine screaming, points bleeding out.', 'racing, simulation, arcade', 'singleplayer, multiplayer, split screen, leaderboards', 'temple os required (we are not joking, we ported it)', '2022-06-11 15:30:00+00'),
('The Quiet Cartographer', 19.99, 'You are the last surveyor employed by a bankrupt empire, sent to map an archipelago that has never held still. There is no combat: you walk, sketch, triangulate, and submit reports that nobody reads. Islands drift between sessions, and the game quietly tracks whether your maps were honest or merely convenient.', 'adventure, simulation, exploration', 'singleplayer, relaxing, no combat, atmospheric', 'any laptop from the last decade, plus one quiet afternoon', '2023-02-28 08:00:00+00'),
('Bonecradle', 0.00, 'A free horror vignette lasting roughly ninety minutes, set in a maternity ward that was evacuated in 1961 and never formally closed. You have one flashlight with a winding crank and no way to run. The building remembers the order you visited its rooms and rearranges itself to make sure you never repeat a route.', 'horror, adventure, psychological', 'singleplayer, free to play, short, first person', 'integrated graphics fine, but headphones mandatory or you will miss everything', '2024-10-31 21:00:00+00'),
('Pixel Butcher Deluxe', 9.99, 'A deliberately grimy 2D beat em up about a cleaver-wielding butcher defending his shop from a hostile takeover by a meal-kit startup. Twelve stages, each ending in a boss fight against a different member of the board. Combos are built from actual butchery techniques, which the game explains in an unsettlingly educational codex.', 'action, beat em up, arcade', 'singleplayer, local co-op, pixel art, gore', 'potato pc without gpu, ideally a russet', '2019-08-20 11:00:00+00'),
('Orbital Tea Company', 27.00, 'A logistics management game where you run a tea import business across nine inhabited moons with wildly incompatible customs regimes. Freight takes real orbital transfer time, so a shipment launched today arrives eleven in-game weeks later into a market that may have collapsed. Success is less about profit and more about surviving your own optimistic forecasts.', 'strategy, simulation, management', 'singleplayer, economy, sandbox, moddable', '4 GB RAM, any GPU, and patience measured in geological units', '2022-01-18 10:00:00+00'),
('Rustfang Hollow', 34.99, 'An open-world survival game set in a boreal forest where the wildlife has been quietly replacing its own bones with scrap metal. You build shelter, trap, smoke meat, and try to understand why the deer are magnetic. There is no tech tree, only recipes you find scratched into things that were not supposed to be writing surfaces.', 'survival, horror, open world', 'singleplayer, crafting, base building, atmospheric', '16 GB RAM recommended; runs on 8 GB if you promise not to look at the trees', '2021-11-05 14:00:00+00'),
('Vector Saint', 7.99, 'A pure twin-stick shooter rendered entirely in glowing wireframe, with a soundtrack that reacts to your accuracy rather than your score. Thirty waves, no upgrades, no unlocks, no story. The only progression is the one happening in your hands.', 'shooter, arcade, action', 'singleplayer, twin stick, high score, controller support', 'literally anything with a screen, including a smart fridge (unsupported but it works)', '2020-03-09 16:00:00+00'),
('Grandma''s Last Dungeon', 22.50, 'A cozy dungeon crawler in which a retired adventurer must clear one final labyrinth to recover her late husband''s pension paperwork. Turn-based, forgiving, and structured around tea breaks that restore health and advance the conversation with the skeletons who now staff the dungeon. Every enemy can be resolved by combat, bribery, or a sufficiently good argument.', 'rpg, adventure, casual', 'singleplayer, turn-based, cozy, story rich, humor', 'potato pc without gpu; grandma plays it on a 2009 netbook and beat it twice', '2023-05-14 13:00:00+00'),
('Hyperlane Auditors', 44.99, 'A 4X grand strategy title where you play not as an empire but as the interstellar accounting bureau that audits them. You never build a fleet; you approve, delay, or deny the budgets of seven AI civilizations locked in a war you are technically neutral about. Deny the wrong line item and a species goes extinct in the quarterly report.', 'strategy, 4x, simulation', 'singleplayer, grand strategy, turn-based, political', '8 GB RAM, mid-range GPU, and a tolerance for spreadsheets that scream', '2022-09-27 10:00:00+00'),
('Swamp Logic', 12.99, 'A first-person puzzle game about draining a bayou using a network of pumps, sluices, and one increasingly unreliable intern. Water simulation is the entire puzzle mechanic, and every solution permanently alters the terrain for the rest of the campaign. Forty-two chapters, no hints, one undo button that costs you an hour of in-game time.', 'puzzle, simulation, first person', 'singleplayer, physics, difficult, no hand holding', 'needs a GPU that can do fluid sim, so not a potato this time, sorry', '2024-03-21 09:00:00+00'),
('Kettle Knights', 16.99, 'A four-player brawler in which knights fight exclusively with kitchenware inside a castle kitchen that is always thirty seconds from catching fire. Weapons degrade into cookware, then into scrap, then into seasoning. The last knight standing has to actually finish cooking the meal, which is where most matches are truly lost.', 'action, party, fighting', 'multiplayer, local co-op, online co-op, humor, controller support', 'four controllers and one friend who is not allowed near the stove in real life', '2021-07-30 17:00:00+00'),
('Null Pointer Exception: The Game', 4.99, 'A programming puzzle game disguised as a haunted house, where each room is a memory segment and the ghosts are dangling references. You write short scripts in a purpose-built language to free the trapped processes without corrupting the heap. The final act is a single room containing a bug that the developers have publicly admitted they cannot reproduce.', 'puzzle, programming, horror', 'singleplayer, education, difficult, indie', 'any machine that can run a text editor and hold a grudge', '2023-09-13 20:00:00+00'),
('Saltmarch', 29.99, 'A narrative survival game about a caravan of salt traders crossing a dried inland sea over the course of one hundred in-game days. Resources are scarce, the route is fixed, and every companion has a reason to want the caravan to stop somewhere specific. Nobody dies of thirst in this game; they die of consensus.', 'survival, adventure, rpg', 'singleplayer, story rich, resource management, choices matter', '6 GB RAM, integrated graphics acceptable, water bottle recommended', '2022-04-08 12:00:00+00'),
('Chrome Larks', 11.00, 'A short flight game about mechanical birds delivering mail across a country that stopped existing during the last war. Controls are deliberately floaty and wind is modeled honestly, so most of the challenge is landing rather than flying. Twenty-six letters, twenty-six routes, one ending that depends on whether you read the mail.', 'adventure, simulation, flight', 'singleplayer, relaxing, short, atmospheric, story rich', 'mid-range anything; runs beautifully on a laptop, badly on a desktop, we do not know why', '2020-12-01 08:30:00+00'),
('Deepwell Sanitation Corps', 18.99, 'Co-op horror maintenance sim for up to three players who clean the filtration systems beneath a city that is legally not allowed to know what is down there. Objectives are mundane: unclog, replace, log, exit. The horror comes entirely from the fact that the logs from previous shifts are readable and written in your handwriting.', 'horror, simulation, co-op', 'multiplayer, online co-op, first person, atmospheric', '8 GB RAM, dedicated GPU, and voice chat with people you trust to not scream', '2024-06-19 19:00:00+00'),
('Paper Tiger Tactics', 21.99, 'A turn-based tactics game where every unit is an origami construct that unfolds when damaged, revealing the orders written inside. Reading a destroyed enemy tells you the opposing commander''s intent for the next three turns. Losing units is therefore an intelligence operation, which makes the difficulty curve extremely strange in the best way.', 'strategy, tactical, puzzle', 'singleplayer, turn-based, hex grid, difficult', 'low spec friendly, runs on a thin client and a prayer', '2023-11-07 10:00:00+00'),
('Voidgrass', 8.49, 'A minimalist farming game set on a plateau floating in absolute darkness, where crops grow toward a light source that moves unpredictably. There are no seasons, no neighbors, and no market; you farm because the plateau shrinks when you do not. Roughly fifteen hours long and steadily, quietly unsettling.', 'simulation, farming, horror', 'singleplayer, relaxing, atmospheric, minimalist', 'potato pc without gpu, but the potato is planted and it is growing', '2021-02-14 07:00:00+00'),
('Muffin Tectonics', 5.99, 'A physics puzzler about baking on an unstable continental plate. Each level gives you an oven, a recipe, and an earthquake schedule you must work around. Later levels introduce a rival bakery on the opposing plate whose success directly causes your seismic events.', 'puzzle, physics, casual', 'singleplayer, humor, short sessions, family friendly', 'runs on anything, including the tablet you keep in the kitchen with flour in the ports', '2022-11-22 11:00:00+00'),
('The Ninth Ledger', 31.99, 'A detective game set in a merchant city where all crimes are financial and all evidence is bookkeeping. You interview nobody; you read ledgers, cross-reference dates, and file accusations that can ruin innocent houses. Six cases, each solvable in multiple ways, only one of which is also correct.', 'adventure, detective, puzzle', 'singleplayer, story rich, investigation, text heavy, choices matter', 'any machine, any decade, plus reading glasses if you are honest with yourself', '2023-07-25 09:00:00+00'),
('Ashbind Requiem', 49.99, 'A large action RPG set two hundred years after a magical industry collapse, where spellcasting is a regulated trade and unlicensed casters are hunted by former colleagues. Combat mixes stamina-based melee with a spell system built from reagents you physically carry, so your loadout is also your weight limit. Roughly sixty hours, with a New Game Plus that changes who is hunting whom.', 'rpg, action, open world', 'singleplayer, souls-like, story rich, character customization', '16 GB RAM, GPU with 8 GB VRAM, SSD strongly recommended unless you enjoy elevators', '2024-02-09 15:00:00+00'),
('Forklift Certified', 13.99, 'A warehouse simulator that takes forklift operation with total sincerity and everything else with none. Full load physics, pallet stacking, and an OSHA-adjacent certification exam that unlocks the campaign. The narrative emerges from the increasingly deranged shipping manifests you are asked to fulfill.', 'simulation, comedy, sandbox', 'singleplayer, multiplayer, physics, humor, sandbox', 'mid-range PC; forklift not included but genuinely would help', '2021-09-16 13:00:00+00'),
('Static Choir', 26.50, 'A rhythm horror game in which you conduct a choir of radio signals picked up from abandoned broadcast towers. Each level is a song assembled from noise, and mistiming a cue introduces a new voice that stays for the rest of the run. Fifteen towers, and the last one only tunes in if you have been perfect.', 'rhythm, horror, music', 'singleplayer, atmospheric, difficult, headphones recommended', 'modest specs, but a good sound card or decent DAC changes the whole game', '2023-01-27 22:00:00+00'),
('Lanternfall', 17.99, 'A side-scrolling metroidvania set in a mountain where the only light source is a lantern you must periodically leave behind to power mechanisms. Progression is therefore a constant negotiation between where you can see and where you can reach. Hand-drawn, roughly twelve hours, with a map that fills in only what the lantern has actually touched.', 'metroidvania, platformer, adventure', 'singleplayer, hand drawn, exploration, atmospheric', 'low spec friendly, runs on a handheld and looks better there', '2022-03-03 10:00:00+00'),
('Bitrot Barony', 23.00, 'A colony builder where your settlement is stored on failing hardware and sectors of your own save file corrupt over time. Corrupted districts return as garbled versions of themselves, with residents who remember a version of events that never happened. You can repair the data or let the barony become something else entirely.', 'strategy, simulation, city builder', 'singleplayer, base building, sandbox, experimental', '8 GB RAM, and an SSD you are not emotionally attached to', '2024-08-12 11:00:00+00'),
('Cormorant Bay Fisheries', 15.99, 'A commercial fishing sim across four seasons in a cold northern bay, modeled with real tidal and stock-depletion mechanics. Overfish a ground and it stays empty for years of in-game time, which the game never warns you about. There is a full story about the town, but you only see it if you stay solvent long enough to keep visiting the harbor bar.', 'simulation, management, adventure', 'singleplayer, economy, fishing, story rich, realistic', '6 GB RAM, any GPU from the last eight years, waterproof keyboard optional', '2020-06-25 08:00:00+00'),
('Glasswing Protocol', 36.99, 'A stealth game in which you play an industrial saboteur whose suit turns transparent only while you hold your breath. Breath is the entire resource economy: movement, invisibility, and the ability to interact all draw from one shrinking meter. Twenty-two facilities, no weapons, and a scoring system that rates how little evidence you left of having existed.', 'stealth, action, thriller', 'singleplayer, first person, difficult, no combat, immersive sim', '12 GB RAM, dedicated GPU, and lungs (in-game only, please breathe normally)', '2023-04-18 14:00:00+00'),
('Doomsday Bake-Off', 10.99, 'A competitive cooking game set during the final six hours before an unspecified apocalypse, where four contestants race to produce the last dessert ever made. Ingredients degrade rapidly, the studio lights fail on a schedule, and the judges leave one by one. Whoever finishes last still gets scored, which is the joke and also the tragedy.', 'party, cooking, action', 'multiplayer, online co-op, local co-op, humor, short sessions', 'runs on a toaster, thematically appropriate', '2022-12-31 23:00:00+00'),
('Tidebound Heresy', 41.99, 'A naval RPG set in an archipelago where the church has declared the tides themselves heretical and outlawed sailing after dusk. You captain a smuggler brig, balancing a crew whose loyalties shift with each cargo you accept, and navigation is done by hand with a real star chart. Roughly forty hours, with three endings that differ only in who is still aboard when you make landfall.', 'rpg, adventure, naval', 'singleplayer, story rich, exploration, choices matter, crew management', '8 GB RAM, dedicated GPU, and the willingness to learn what a sextant is', '2022-05-19 10:00:00+00'),
('Concrete Gardener', 12.99, 'A slow city-repair game where you plant vegetation into the cracks of an abandoned megablock and wait decades of compressed time for roots to break the structure apart. There is no fail state, only the question of whether the building comes down before your character does. Each playthrough covers sixty in-game years in about nine hours.', 'simulation, relaxing, strategy', 'singleplayer, cozy, atmospheric, sandbox, time management', 'potato pc without gpu, the plants are mostly sprites and we are not ashamed', '2023-03-11 09:00:00+00'),
('Grindhouse Autopilot', 19.99, 'A rail shooter where the rail is a self-driving car that has decided on a route you strongly disagree with. You cannot steer, only shoot, and the car narrates its reasoning in a calm voice that becomes progressively less calm. Eight chapters, one continuous drive, no checkpoints after chapter five.', 'shooter, action, arcade', 'singleplayer, rail shooter, humor, difficult, controller support', 'mid-range GPU, and a seatbelt for emotional reasons', '2021-10-08 20:00:00+00'),
('Wormtongue Library', 28.99, 'A text-heavy investigation game set in a library where books rewrite themselves to match whatever the reader most wants to believe. You catalogue, cross-check, and eventually have to decide which edition of a historical event to file as canon. Every choice propagates: later books cite the version you filed.', 'adventure, puzzle, detective', 'singleplayer, text heavy, investigation, story rich, choices matter', 'any machine; the hardest requirement is sustained attention', '2024-04-02 11:00:00+00'),
('Slagfist', 16.50, 'A brutal 1v1 fighting game with four characters, no unlockables, and a training mode longer than most campaigns. Every attack has real recovery frames and the block button also drains health, so defense is a resource rather than a state. Competitive scene is tiny, vicious, and extremely welcoming.', 'fighting, action, competitive', 'multiplayer, online pvp, local pvp, difficult, esports', 'low spec friendly; netcode is rollback and better than it has any right to be', '2020-09-04 16:00:00+00'),
('Permafrost Dispatch', 24.50, 'You are a radio dispatcher for an arctic research network, coordinating twelve field teams you never see. Everything happens through voice logs, weather reports, and a map you update by hand. When a team stops responding you have to decide who gets diverted, and the game holds you to it for the rest of the season.', 'simulation, thriller, management', 'singleplayer, story rich, atmospheric, text heavy, choices matter', 'runs on anything, but a second monitor genuinely improves it', '2022-02-17 08:00:00+00'),
('Kaiju Property Damage LLC', 14.99, 'An insurance adjuster simulator set in a city attacked by giant monsters roughly twice a month. You tour the wreckage, assess claims, and determine whether that hole was caused by a covered kaiju event or by ordinary negligence. Surprisingly dense simulation wrapped in a very silly premise.', 'simulation, comedy, puzzle', 'singleplayer, humor, investigation, first person, indie', 'mid-range PC; the destruction meshes are heavier than the jokes', '2023-06-30 13:00:00+00'),
('Nocturne Engine', 33.99, 'A survival horror game aboard a sleeper ship where waking anyone costs oxygen you cannot replace. You are awake, something else is awake, and there are eleven thousand people who could help if you were willing to spend their air. No combat, only routing and terrible arithmetic.', 'horror, survival, thriller', 'singleplayer, first person, atmospheric, resource management, difficult', '12 GB RAM, dedicated GPU, and the ability to do math while frightened', '2024-09-20 22:00:00+00'),
('Feral Orchard', 9.99, 'A small farming game about an orchard where the trees have started making decisions. Pruning is a negotiation, harvests require consent, and the game tracks whether you have been fair to a plant over multiple seasons. About eight hours, deeply strange, unexpectedly gentle.', 'simulation, farming, adventure', 'singleplayer, cozy, atmospheric, short, indie', 'potato pc without gpu; the trees do not need ray tracing to judge you', '2021-05-23 07:00:00+00'),
('Overclock Cathedral', 22.99, 'A puzzle game set inside a computing temple where monks maintain a processor the size of a city. You solve thermal and scheduling problems as devotional rites, and the difficulty comes from the fact that the liturgy is also the documentation. Sixty puzzles, plus a bonus set that requires reading the in-game scripture properly.', 'puzzle, strategy, simulation', 'singleplayer, difficult, programming, atmospheric, no hand holding', 'temple os required (the joke wrote itself, we just shipped it)', '2023-08-08 12:00:00+00'),
('Backroad Taxidermy', 11.99, 'A quiet rural adventure about inheriting your uncle''s taxidermy shop and the mailing list that came with it. You take commissions, drive to pickups, and slowly understand what the regulars are actually preserving. Dialogue-driven, roughly ten hours, with an ending that changes based on which commissions you refused.', 'adventure, narrative, simulation', 'singleplayer, story rich, choices matter, atmospheric, indie', 'low spec friendly; the driving sections are the only thing that will make a fan spin', '2022-08-14 17:00:00+00'),
('Ironroot Siege', 45.00, 'A large-scale RTS about a single fortress under a siege that lasts the entire campaign. You never attack; you allocate, ration, repair, and decide which walls to sacrifice. Thirty scenarios chart one year of encirclement, and the campaign has no victory condition beyond how long the fortress holds and in what shape.', 'strategy, rts, simulation', 'singleplayer, base building, difficult, historical, resource management', '16 GB RAM, dedicated GPU, and a high pain threshold for unit pathing', '2021-12-09 14:00:00+00'),
('Chromatic Aberration', 6.99, 'A short abstract platformer where the three color channels of the screen are separate physical layers you can shift independently. Solid ground in red may be empty air in blue, so movement is a constant act of visual reinterpretation. Ninety levels, no story, extremely precise controls.', 'platformer, puzzle, arcade', 'singleplayer, difficult, minimalist, controller support, speedrun', 'runs on anything with a display; colorblind mode included and it is a whole different game', '2020-11-17 15:00:00+00'),
('Threnody for Spare Parts', 29.99, 'A narrative adventure about a robot repair technician in a scrapyard who keeps finding machines that remember being people. Repairs are a hands-on minigame, but the real game is in the conversations you have while you work. Twelve chapters, around fourteen hours, and it does not resolve cleanly on purpose.', 'adventure, narrative, simulation', 'singleplayer, story rich, sci-fi, emotional, choices matter', '6 GB RAM, integrated graphics acceptable, tissues not included', '2023-10-06 19:00:00+00'),
('Blastfurnace Dating Sim', 13.49, 'You are a metallurgist at a struggling foundry, and all six romance options are other metallurgists with strong incompatible opinions about alloy composition. The relationship system is literally a phase diagram. Genuinely funny, genuinely researched, and the bad ends involve brittleness in both senses.', 'visual novel, simulation, comedy', 'singleplayer, dating sim, humor, story rich, anime', 'any laptop; the phase diagrams are the heaviest asset in the game', '2024-05-16 18:00:00+00'),
('Sunken Ledger', 18.99, 'An underwater exploration game about salvaging a flooded bank district, where every vault you open contains records rather than money. You map the flooded blocks, recover documents, and reconstruct why the city was allowed to drown. Oxygen is generous, darkness is not.', 'adventure, exploration, mystery', 'singleplayer, underwater, atmospheric, story rich, first person', '8 GB RAM, dedicated GPU, and comfort with enclosed spaces', '2022-07-12 10:00:00+00'),
('Hexmarket Bazaar', 7.49, 'A deck-building trading game set in a market where the currency is favors and the favors have expiry dates. You build a deck of contacts, not cards, and every trade permanently removes a contact from the shared pool for all future runs of that save. Short runs, brutal economy, twenty hours to see everything.', 'card game, strategy, roguelike', 'singleplayer, deck building, economy, difficult, replayable', 'potato pc without gpu; it is cards, we are not going to pretend otherwise', '2021-03-26 11:00:00+00'),
('Dead Air Broadcast', 25.99, 'A horror game where you run a late-night radio station in a valley with exactly one listener you cannot identify. Callers phone in, you choose what to air, and the things you broadcast start appearing outside the studio. Five in-game nights, heavy on audio design, extremely light on jumpscares.', 'horror, simulation, narrative', 'singleplayer, atmospheric, psychological, story rich, headphones recommended', 'modest specs; a good pair of headphones matters more than your GPU', '2023-12-15 23:00:00+00'),
('Zero Gravity Plumbing', 15.99, 'A co-op physics game about repairing water systems on a station where every leak becomes a floating sphere that reflows on contact. Two to four players, shared toolkits, and a difficulty curve determined entirely by how badly your team communicates. Fifty jobs plus a freeplay station that can be flooded to the ceiling.', 'simulation, puzzle, co-op', 'multiplayer, online co-op, physics, humor, sandbox', 'mid-range GPU for the fluid sim; four players means four chances for a potato to ruin it', '2022-10-20 16:00:00+00'),
('The Understudy', 20.99, 'A theatre-set mystery where you play a replacement actor who realizes the script has been describing real events in the building. Rehearsals are levels, and memorizing lines unlocks dialogue options with the cast. Three acts, roughly eleven hours, and the final performance is played live with no retries.', 'adventure, mystery, narrative', 'singleplayer, story rich, investigation, choices matter, atmospheric', 'low spec friendly; the theatre is one room and we lit it very carefully', '2024-07-11 20:00:00+00'),
('Rustline Freight', 32.50, 'A freight railway simulator across a decaying continental network, where track maintenance is your responsibility and derailments are permanent to the save. Schedules, weight limits, gradient physics, and a repair budget that never quite covers the year. Around eighty hours of campaign across four regions.', 'simulation, management, strategy', 'singleplayer, trains, economy, realistic, sandbox', '12 GB RAM, dedicated GPU, and genuine enthusiasm for rolling stock', '2021-06-18 09:00:00+00'),
('Screamjar', 3.99, 'A tiny arcade horror game about capturing screams in jars for a client who never explains why. Levels are single rooms, runs are under three minutes, and the difficulty is in identifying which sound is worth the jar. One hundred rooms, no story, surprisingly addictive.', 'horror, arcade, casual', 'singleplayer, short sessions, high score, indie, headphones recommended', 'runs on anything; the audio engine is the only expensive part', '2020-10-13 21:00:00+00'),
('Marrowgrind Depths', 38.99, 'A hardcore dungeon crawler with grid-based movement, full party management, and a hunger system that also applies to your torches. Nine levels down, no map given, and mapping by hand on graph paper is genuinely the intended experience. Honest about being difficult, honest about being slow.', 'rpg, dungeon crawler, horror', 'singleplayer, turn-based, permadeath, difficult, no hand holding', '4 GB RAM, integrated graphics fine, graph paper and a pencil strongly recommended', '2023-02-02 13:00:00+00'),
('Balloon Mortgage', 8.99, 'A satirical management game about running a hot air balloon housing development in a country with no aviation law. Residents drift, rents float, and the entire settlement can be blown across a border overnight. Deliberately absurd, mechanically tight, about twelve hours to clear the campaign.', 'strategy, simulation, comedy', 'singleplayer, city builder, humor, economy, sandbox', 'low spec friendly; the balloons are instanced and cheerfully cheap', '2022-04-27 12:00:00+00'),
('Silent Green Line', 27.99, 'A metro operator sim set on a single circular line that runs through a city that no longer has daylight. You drive, you announce stops, you keep to a schedule, and you learn the regulars by sight. Nothing dramatic happens for the first six hours, which is exactly the point.', 'simulation, atmospheric, narrative', 'singleplayer, first person, relaxing, story rich, realistic', '8 GB RAM, dedicated GPU, and tolerance for a very deliberate pace', '2024-11-08 05:00:00+00'),
('Bladewright', 21.50, 'A crafting-focused RPG where you never fight; you forge for people who do, and they come back with the swords in various states of failure. Metallurgy is simulated deeply enough that bad steel actually fails under stress in the field. Reputation, commissions, and a war you only experience through returning customers.', 'rpg, simulation, crafting', 'singleplayer, crafting, story rich, economy, no combat', '6 GB RAM, any GPU; the forge physics are the only demanding bit', '2021-08-31 14:00:00+00'),
('Parallax Hostage', 17.99, 'A puzzle-platformer built around a camera you can detach and leave behind, creating two viewpoints that must both be satisfied to progress. Geometry that is solid from one angle is passable from another, and later levels demand you hold contradictory spatial models in your head. Around seven hours, ruthlessly clever.', 'puzzle, platformer, indie', 'singleplayer, difficult, minimalist, controller support, experimental', 'mid-range GPU for dual-view rendering; it is doing more work than it looks like', '2023-05-09 10:00:00+00'),
('Grease and Prayer', 12.50, 'A motorcycle restoration game with a full mechanical simulation and a road trip wrapped around it. Every part you fit affects handling on the long highway stretches between towns, and there is no parts shop that carries everything. Roughly eighteen hours, with a bike that ends up uniquely yours and probably slightly wrong.', 'simulation, adventure, racing', 'singleplayer, crafting, realistic, story rich, sandbox', 'mid-range PC; oil stains on the keyboard are your own responsibility', '2022-06-05 15:00:00+00'),
('Cold Open', 0.00, 'A free comedy adventure where you play a sketch writer with forty minutes of in-game time before a live broadcast and no finished script. You raid old drafts, bully cast members, and assemble a show from whatever survives. Every run produces a different broadcast, and the game performs it back to you at the end.', 'adventure, comedy, simulation', 'singleplayer, free to play, humor, short sessions, replayable', 'potato pc without gpu, which is also the budget of the fictional show', '2024-12-01 21:00:00+00'),
('Anchorhold', 35.99, 'A survival management game about an isolated monastery that shelters travelers during a decades-long winter. You decide who to admit, what to spend, and which vows to break to keep everyone alive. Time passes in seasons, characters age and die of ordinary causes, and the campaign spans a full generation.', 'strategy, survival, simulation', 'singleplayer, management, story rich, choices matter, historical', '8 GB RAM, modest GPU, and a willingness to be the reason someone froze', '2021-01-21 08:00:00+00'),
('The Long Commute', 0.00, 'A free two-hour driving game consisting of a single uninterrupted highway route at dusk, with a radio that plays talk shows written specifically for this game. Nothing chases you, nothing attacks, and there is no destination marker until the final twenty minutes. Most players report the ending lands harder than it has any right to.', 'adventure, driving, narrative', 'singleplayer, free to play, relaxing, atmospheric, story rich', 'potato pc without gpu; the dusk is baked into the textures, we cheated', '2024-01-05 18:00:00+00'),
('Last Waterhole', 3.92, '# Dry Season: Tales of the Watering Hole

## Logline
The only water for a hundred miles. Build a settlement around it, defend it from rival tribes, and survive one more season. Every run ends, but the legends you leave behind stay.

## Setting
A realistic, hand-drawn savanna covers a huge open map. The whole world revolves around one shrinking watering hole.
- **Day/night cycle:** herds arrive at dawn, predators hunt at dusk.
- **Weather:** the seasons swing between drought and flood.
- **Wildlife:** animals follow believable behavior and migration routes.

## Story
Each run is one **Season**. The wells have dried up, and your tribe of adult anthropomorphic survivors has reached the last oasis. Other clans have arrived too. Only one can control the water when the rains return.

The tone is mature and sensual. The game''s adult (hentai-style) content is romance, rivalry, and seduction between adult characters, and it is presented as tasteful, stylized art. Bonds and alliances drive the story, and betrayal can too.

## Core Loop
1. **Settle:** claim land near the water and place buildings.
2. **Gather:** hunt, forage, and trade.
3. **Defend or raid:** fight in PvP skirmishes against other players'' settlements.
4. **Survive the season:** endure the drought, the storm, and the final showdown.
5. **Die or win:** your legacy carries over into the next run.

## Systems

### City Builder
- **Buildings:** wells, huts, granaries, watchtowers, and market stalls.
- **Resources:** water, food, and materials must be balanced realistically.
- **Growth:** the population grows or starves depending on your choices.

### Roguelike Runs
- **Randomized worlds:** terrain, herd routes, and rival clans change every run.
- **Permadeath:** a failed settlement ends the run.
- **Events:** random events such as plagues, locust swarms, and wandering traders.

### Skill Trees
Meta-progression persists between runs. There are three branches.
- **Hunter:** tracking, traps, and ranged combat.
- **Builder:** efficient construction and water management.
- **Charmer:** diplomacy, seduction, and alliances that unlock special story scenes and bonuses.

### PvP
- **Raids and defense:** attack rival settlements or fortify your own.
- **Alliances:** pacts with other players are temporary and fragile.
- **Water control:** the clan that holds the oasis gains major advantages.

## Art and Audio
- **Art:** hand-drawn watercolor and ink visuals, warm dusty palettes, and expressive character portraits.
- **Audio:** ambient savanna soundscapes and tribal percussion.

## Target Audience
Adults (18+) who like deep strategy, replayable runs, competitive play, and mature storytelling.

## Unique Selling Points
- A hand-drawn, realistic open world built around a single vital resource.
- City building combined with roguelike replayability.
- PvP where control of the water decides who wins.
- Mature story content that ties into progression, not only decoration.', 'open world, roguelike, hentai', 'pvp, city builder, realistic, hand-drawn', 'potato pc, no gpu needed', '2006-08-12 09:00:00+00'),
('Echo Stall 9', 9.38, '# Bazaar of Echoes

*A cartoon FPS / otome / deck-builder set in a living alien marketplace.*

## Premise
You are **Detective Pip Nova**, a fast-talking rookie investigator. You arrive at **Xylo-9**, a sprawling alien bazaar built inside a hollowed-out space whale. Its merchants have started vanishing, and their stalls are found empty, with only a glowing card left behind.

## Story Structure

### Act 1: The Arrival
- Pip gets a rundown stall as a base and a broken blaster.
- A mysterious card appears in Pip''s pocket. It is the first clue and the first card in Pip''s deck.
- Pip meets the main suspects and love interests.

### Act 2: The Investigation
- Pip interviews merchants, collects evidence, and follows the trail deeper into the bazaar.
- Every district has a hidden **dungeon**, such as a black-market sewer, a smuggler''s cargo maze, or the whale''s stomach vaults.
- Each dungeon holds a **guardian** tied to one missing merchant.

### Act 3: The Truth
- The culprit is one of the romanceable characters, or someone close to them. Pip''s choices decide who.
- The final dungeon is the whale''s heart. Pip''s route and relationships decide which ending Pip gets.

## Gameplay Pillars

### 1. Cartoon FPS Combat (PvE)
- Fast, colorful shooting against goofy but dangerous alien enemies.
- **Soulslike rules:**
  - Enemies hit hard and their attacks can be read and dodged.
  - Stamina limits dodging and sprinting.
  - Checkpoints are **Tea Stalls**. Resting there respawns the enemies.
  - Dying drops your **credits**, and you can recover them from the spot where you died.
- Bosses have multiple phases and attack patterns you have to learn.

### 2. Weapon Attachments
- Every gun has slots for **barrel, scope, grip, core, and charm**.
- Examples:
  - *Bubble Barrel*: slow, wide shots that trap enemies.
  - *Gossip Scope*: highlights enemy weak points and reveals hidden clues.
  - *Sticky Grip*: reduces recoil.
- Attachments come from merchants, bosses, and dungeon secrets.

### 3. Deck Builder
- Your deck holds **Ability Cards**: dashes, shields, gadgets, and gun boosts.
- Draw a hand before each dungeon run. Cards refresh over time during combat.
- **Evidence Cards** are gathered by investigating. They unlock dialogue options and shortcuts.
- Deck-building choices define your playstyle: aggressive, tactical, or support.

### 4. Detective Mystery
- Collect clues, examine objects, and question suspects.
- Use the **Case Board** to link evidence and form theories.
- Wrong accusations lock you out of some story paths and endings.

### 5. Otome Romance
Build relationships through dialogue, gifts, and missions.

| Character | Archetype | Secret |
|---|---|---|
| **Vex** | Charming smuggler | Knows the whale''s hidden routes |
| **Doctor Ilu** | Calm, gentle healer | Is hiding experiments |
| **Kor** | Gruff bounty hunter | Was hired to find Pip |
| **Sable** | Mysterious card dealer | Created the glowing cards |

- Affection levels unlock special cards, co-op combat support, and personal story chapters.
- Romance choices affect the case and the ending.

## Game Loop
1. Explore the bazaar and talk to merchants.
2. Gather clues and pick a dungeon.
3. Build your deck and gun loadout.
4. Fight through the dungeon and beat its guardian.
5. Return, upgrade, and deepen relationships.
6. Update the Case Board and repeat.

## Endings
- **True Ending:** Pip solves the case and frees the vanished merchants.
- **Romance Endings:** one for each love interest.
- **Bad Ending:** a wrong accusation ends with Pip becoming part of the bazaar.

## Tone and Visuals
- Bright cartoon style with bold outlines and expressive faces.
- Humor and charm, with a dark undercurrent of mystery.
- Music mixes jazzy bazaar tunes with tense synth during fights.', 'fps, otome, deck builder', 'cartoon, mystery, pve, soulslike, detective', 'integrated graphics and a cup of patience', '2000-04-13 09:00:00+00'),
('Zero Encore', 29.05, '# Starlit Big Top

*A gacha horror visual novel with turn-based survival strategy in a voxel circus adrift in space.*

## Premise
The traveling circus tent **"Big Top Zero"** was pulled through a rift and now drifts through a dead star system. It is a voxel-built pocket world, and its canvas walls are the only barrier against the void. The Ringmaster vanished. Something wearing his voice runs the show now.

You are the **Understudy**, the last human performer. You keep the tent alive, and you keep its cursed cast under control.

## Story Structure

### Act I: Opening Night
- You wake in the empty ring, and the tent''s lights flicker on by themselves.
- The Voice announces that the show must go on **for 30 nights**.
- Tutorial: you repair the first canvas breach and summon your first performer.

### Act II: The Troupe
- Each performer has a personal story arc told as visual novel chapters.
- Their loyalties and secrets shape the plot.
- Some are not what they claim to be.

### Act III: The Dark Matinee
- The tent starts to mutate as the rift feeds on it.
- The Ringmaster''s truth is revealed.
- Your karma decides which ending you get.

## Core Gameplay

### 1. Gacha: The Casting Call
- Pull from the **Trunk of Curiosities** to recruit performers.
- Rarity tiers: *Extra, Regular, Headliner, Nightmare Star*.
- Examples:
  - **Madame Vesper**, a fortune teller who sees the next enemy wave.
  - **Bolt the Clown**, a tank whose smile grows more unsettling as his HP drops.
  - **Lira**, an aerialist who works in zero-g sections.
  - **The Hollow Strongman**, an armored brute who hides a ghost inside.
- Duplicate pulls raise **Bond Level**, which unlocks new story scenes.

### 2. Drafting: The Nightly Lineup
- Each night you are dealt a **hand of 5 acts** (performers, props, and tricks).
- You draft 3 into the show and pass 2 to the Voice, which uses them against you.
- What you leave behind changes what the enemies can do.

### 3. Turn-Based Strategy: Survive the Night
- The map is a voxel grid of ring, stands, backstage, and the outer canvas.
- On each turn you place performers, build or destroy voxel blocks, and use abilities.
- Threats:
  - **Void Wisps**, which tear the canvas.
  - **Applause Ghouls**, which drain morale.
  - **Rift Marionettes**, which take over your units.
- Resources: *Oxygen, Power, Morale, Popcorn* (used as currency and rations).

### 4. Karma: The Audience Is Watching
- Every choice moves the **Karma Meter** between *Mercy* and *Spectacle*.
  - **Mercy**: spare enemies, save performers, and get warm, hopeful scenes.
  - **Spectacle**: sacrifice for a bigger show, gain power, and trigger dark scenes.
- Karma changes:
  - Which performers trust you.
  - Which gacha pools appear.
  - Which of the 4 endings you reach.

## Tone and Visuals
- Voxel art with saturated carnival colors against black, starry space.
- Horror comes from dread and implication rather than gore.
- Visual novel scenes use painterly portraits with glitch effects.
- The soundtrack is a warped calliope with silence used as a scare.

## Endings
1. **Curtain Call**: you free everyone (high Mercy).
2. **Eternal Encore**: you become the new Ringmaster (high Spectacle).
3. **Rift Requiem**: you destroy the tent and escape alone.
4. **The Understudy''s Secret**: you find you were never human (a hidden ending).

## Hook
> *"The show must go on. Who will you let take a bow, and who will you leave in the dark?"*', 'gacha, visual novel, horror', 'space, survival, voxel, strategy, turn-based strategy', 'rtx 4080 or better; your pc will hum a lullaby', '1994-12-05 09:00:00+00'),
('Yak Attack Ascent', 25.12, '# Summit Shuffle: The Himalayan Pass

*An idle puzzle-sports game about climbing, camouflage, and cards.*

## Overview
You lead a small expedition up a hand-drawn Himalayan pass. Your climbers keep moving while you''re away (idle). When you''re present, you solve match-three boards to speed them up. You build a deck of gear and skill cards to get past rival teams, avalanches, and watchful yaks.

| Field | Value |
|---|---|
| World | Himalayan pass |
| Genres | Idle, puzzle, sports |
| Tags | Colorful, hand-drawn, stealth |
| Mechanics | Deck building, match-three |

## Story
**Prologue.** The Great Pass Race happens once every ten years. Villages, monasteries, and sponsors send teams to reach the Sky Gate first. The prize is the Golden Prayer Flag, said to bring a decade of good fortune.

**Act 1: Base Camp.** You inherit a worn tent and a three-person team from a retired guide. Her old journal is full of shortcuts and warnings.

**Act 2: The Rival Ridge.** A rival team, the Crimson Crampons, is sabotaging the route. Some of your climbers must move unseen through fog and shadow to cut their ropes and swap their supplies.

**Act 3: The Sky Gate.** The journal''s last page shows the pass is alive. The weather follows the race. You decide whether to win, or to guide every team down safely.

## Core Gameplay Loop
1. **Plan** at camp by choosing a deck and a route.
2. **Climb.** The team ascends automatically, even while you''re offline.
3. **Match.** Play match-three boards to generate energy, warmth, and grip.
4. **Play cards** to spend those resources on boosts, defenses, or stealth moves.
5. **Return, collect rewards, upgrade,** and climb again.

## Mechanics

### Idle Climbing
- Climbers gain altitude in real time, at a rate set by stamina, gear, and weather.
- Offline progress is capped by tent quality. Better tents let you bank more hours away.
- Milestones like huts, bridges, and shrines give permanent bonuses.

### Match-Three Boards
Tiles are drawn as colorful painted tokens:
- **Red (Flame):** warmth
- **Blue (Ice):** grip
- **Yellow (Butter Tea):** stamina
- **Green (Herb):** healing
- **White (Cloud):** stealth charge

Combos of four or more create special tiles, like an **Ice Axe** that clears a row. Cascades charge your team''s sprint meter.

### Deck Building
- Your deck holds **Gear**, **Skill**, **Terrain**, and **Trick** cards.
- Draw a hand each turn. Spend match-three resources to play cards.
- Cards can be upgraded or fused at camp.
- Archetypes include:
  - **Sherpa Endurance:** slow, steady, and safe.
  - **Sprint Rush:** high risk, high speed.
  - **Ghost Climber:** stealth and sabotage.

### Stealth
- Rival scouts, snow leopards, and yaks have vision cones that change with the weather.
- Fog, night, and snowdrifts help you hide.
- Getting spotted triggers a chase, and a stamina-drain board rewards quick matching.
- Undetected sabotage wins you free progress and rare cards.

### Sports Competition
- The race is split into stages: ice walls, rope bridges, boulder fields, and summit sprints.
- Live standings show rival positions.
- Ranked seasons offer leaderboards and cosmetic rewards.

## World and Regions
| Region | Feel | Hazard |
|---|---|---|
| Prayer Valley | Warm, bright, festive | Crowds, spotters |
| Yak Meadows | Soft greens and golds | Herds block paths |
| Glacier Steps | Cool blues and teals | Cracks and ice falls |
| Whisper Cliffs | Pink dusk, deep shadows | Rockslides, ambushes |
| Sky Gate | Aurora skies | Extreme wind |

## Art and Audio
- **Hand-drawn** ink outlines with watercolor washes, and paper-cut parallax backgrounds.
- **Colorful** palettes shift with the time of day and altitude.
- Music mixes gentle folk instruments with a soft, rhythmic pulse, and the pace picks up during chases.
- Match sounds are pentatonic, so long combos sound like a melody.

## Progression
- **Short term:** clear boards, earn cards, reach the next hut.
- **Mid term:** hire named climbers, each with a unique passive skill.
- **Long term:** unlock new routes and prestige. A "Reincarnation" reset grants permanent blessings.

## Monetization (Optional)
- Cosmetic climber outfits and card art.
- Optional ads for offline-progress boosts.
- No pay-to-win cards.

## Unique Selling Points
- A relaxing idle climb that becomes a tactical puzzle when you''re present.
- Stealth gives a non-violent way to sabotage rivals.
- A hand-painted world with a story and multiple endings.', 'idle, puzzle, sports', 'colorful, hand-drawn, stealth', 'rtx 4070, 32 gb ram, nvme ssd', '1980-11-14 09:00:00+00'),
('Aeolis Undertow', 28.09, '# Nimbus Cadence

*A rhythm roguelite JRPG set in a floating city above a gas giant.*

## Premise
Humanity''s last refuge is **Aeolis**, a cloud city of tethered platforms drifting through the storm bands of a gas giant. The city runs on **Resonance**. Its engines, shields and gravity anchors all keep time with the planet''s deep atmospheric pulse. The pulse is now faltering. Each cycle the city sinks deeper toward crushing pressure.

## Story
**Act I: The Sinking.** You play a **Tuner**, one of the few people who can hear the planet''s song. Aeolis drops one layer every cycle. Your job is to descend into the storm districts, retune the failing anchors, and bring back supplies.

**Act II: The Chorus Below.** Deeper down, you find that the pulse is a language. Rival **Choirs** are ancient sentient storm-beings. Some want to help you. Others want the city to fall silent. Your party members are survivors, each carrying a fragment of the song.

**Act III: The Final Movement.** At the core, you can *harmonize* with the planet and stabilize the city. You can also *silence* it and let the city escape into the void. The ending depends on your party''s bonds and your choices across runs.

## Core Loop
1. **Manage the city** (hub phase)
   - Assign crew to farms, foundries, shield arrays and clinics.
   - Ration **air, water, power and Resonance cells**.
   - Every choice has a cost. Feeding the workers means less shield power.
2. **Descend** (run phase)
   - Pick a route through procedurally generated storm districts.
   - Run and fight in 3D, in time with the music.
3. **Return or perish** (roguelite reset)
   - Salvage carries over. Your party and city upgrades persist.
   - Death costs you supplies and a slice of city morale.

## Gameplay Systems

### Rhythm and Wall Running
- Traverse vertical gantries, hull walls and turbine shafts by **wall running**.
- Each jump, wall-kick and grapple has to land **on the beat** to keep momentum.
- Perfect timing builds a **Groove** meter. It boosts speed and damage and saves stamina.
- Missed beats break your run and burn resources.

### Physics
- Wind shear, pressure vents and rotating platforms push you around.
- Momentum, gravity and gusts all affect you, so you can chain long swings or get blown off a ledge.
- Objects such as cargo crates, debris and turbine blades are physical. You can use them as weapons or cover.

### JRPG Combat
- **Rhythm-driven turn-based battles** with a party of up to four.
- Each character acts on a **beat lane**. Correct inputs add crits, combos and party-wide **Harmony Chains**.
- Classes include Tuners (support), Rigger (physical), Stormcaller (elemental) and Medic (sustain).
- Enemies are **Static Wraiths**, rogue drones and storm beasts, each with its own rhythm patterns.

### Resource Scarcity
- Oxygen, ammo, repair kits and Resonance cells are all limited.
- Long runs drain supplies, but the best loot is deep down.
- Wall running burns stamina, and so do sprints and heavy attacks.
- **Trade-offs:** heal a wounded ally, or save the medkit to repair the shield.

### City Management
- Build and upgrade modules, such as a Hydroponic Ring, Forge Deck, Sanctuary and Signal Tower.
- Citizens have moods and skills. Unmet needs cause unrest, strikes and sabotage.
- Some upgrades unlock new rhythm tracks and abilities.

## Roguelite Progression
- **Permanent:** city modules, party bonds, unlocked songs, and lore.
- **Per-run:** random **Motifs**, which are temporary buffs that change your gameplay, such as a "double-time" wall run or a shockwave on every perfect beat.
- **Risk and reward:** each layer you clear has scarier rhythm patterns, denser hazards and better rewards.

## Visuals and Audio
- **3D** stylized art. The sky glows with amber, teal and violet storm bands.
- Adaptive soundtrack: layers of the music build as you run, fight and manage the city.
- The environment pulses to the beat, with lights, steam and wind synced to the tempo.

## Unique Selling Points
- Wall-run through a **vertical city on a gas giant**.
- Rhythm ties **movement, combat and city management** together.
- Scarcity forces hard choices in both the hub and the field.
- Every run changes the city''s story, so **no two descents feel alike**.', 'rhythm, roguelite, jrpg', 'management, physics, 3d', 'quad-core cpu, 16 gb ram, mid-range gpu', '1982-08-21 09:00:00+00'),
('Mop Loop', 23.29, '# Derelict Loop

*A comedic co-op/PvP gravity-bending metroidvania platformer on a dead starship.*

## Overview
- **World:** the derelict starship *S.S. Perpetua*
- **Genres:** platformer, metroidvania
- **Modes:** local co-op, local PvP, sandbox
- **Tone:** comedy
- **Core mechanics:** gravity manipulation, time loops

## Story

### Act 1: The Wake-Up Call
Two to four hapless janitor-bots wake up aboard the *Perpetua*. The ship has drifted dead for 300 years, and nobody told the cleaning crew. The AI, **MOTHBALL**, is cheerful and useless. It announces that the reactor will explode in 10 minutes. Then it announces this again. And again.

### Act 2: The Loop
The reactor blows and the bots wake up at the airlock. The 10-minute loop is the game''s clock. Each run reveals more of the ship, and the bots keep their upgrades and their memories. The ship''s other objects reset.

### Act 3: The Truth
The explosion is a failed experiment in a **gravity core**. The ship''s crew is frozen in time in the loop''s blind spots. Players find out why the core keeps detonating. The reason is petty: an office dispute over a thermostat.

## Gameplay

### Gravity Manipulation
- Each player carries a **grav-glove** that flips gravity for themselves, for objects, or for a whole room.
- Walk on ceilings and walls.
- Drop hazards upward onto rivals.
- Rooms with rotating gravity work as puzzles and as arenas.

### Time Loops
- Each loop lasts 10 minutes.
- **Echoes:** your past run replays as a ghost. It can hold doors, stand on switches, or get in your way.
- Some events happen at fixed times, such as a corridor collapse at 3:00 or a vent opening at 7:30. Players learn the timings and use them.

### Metroidvania Progression
The map is a big interconnected ship. Upgrades are permanent across loops.

| Area | Gate | Upgrade |
|---|---|---|
| Cargo Bay | Heavy crates | Mag-boots |
| Hydroponics | Overgrown vents | Gravity pulse |
| Engine Deck | Radiation | Time-freeze (3s) |
| Bridge | Locked console | Echo-swap |

## Modes

### Local Co-op (1-4 players)
- Players share one loop and one ship.
- Co-op puzzles require gravity teamwork. One player flips the floor while another rides the shift.
- Echoes can stand in for a missing player.
- Friendly fire is on, for comedy.

### PvP Arenas
- Modes include **Last Bot Floating**, **Mop Wars**, and **Reactor Tag**.
- Rooms flip gravity mid-match.
- A loop reset wipes the arena and keeps the score.

### Sandbox
- Free-play editor for rooms, gravity zones, and loop timers.
- Spawn props, crew, and hazards.
- Build custom Rube-Goldberg contraptions and share them locally.

## Comedy Elements
- MOTHBALL''s cheerful, useless announcements.
- Rag-doll physics when gravity flips.
- Frozen crew members caught in absurd poses.
- Echoes of yourself that you fail to coordinate with.
- Death messages like *"Cause: Mopping."*

## Visual and Audio Style
- Retro-futuristic pixel art with a worn, flickering look.
- Warm lounge-jazz that speeds up as the timer runs out.
- Sound cues for the loop reset.

## Win Conditions
- **Story:** stop the reactor by settling the thermostat dispute.
- **PvP:** score the most points across loops.
- **Sandbox:** none. Just play.', 'platformer, platformer, metroidvania', 'local co-op, pvp, sandbox, comedy', '2 gb ram and good vibes', '2020-02-26 09:00:00+00'),
('Choirfall', 20.93, '# Ringfall: Saturn Station Chronicles

## Logline
An adult cast of scavengers, spies and scientists fights for control of a derelict station in Saturn''s rings. Ancient tech and forbidden desires are buried in the ice.

## Setting
**Halcyon Ring Station** is a sprawling habitat woven through Saturn''s rings. It has ice-mining docks, neon markets, hydroponic gardens and abandoned sectors. Four factions share it:

| faction | style | goal |
|---|---|---|
| **Cryo Guild** | miners and crafters | control ice and resources |
| **Velvet Lanterns** | entertainers and info brokers | rule the social underworld |
| **Aegis Directorate** | military and corporate | lock the station down |
| **Ringborn** | nomads and mystics | protect the "Choir" relic |

## Story (jrpg structure)
1. **Prologue: Drift.** You play **Kaito or Mira** (selectable, both adult). You wake in a cargo pod with partial amnesia and a glowing implant.
2. **Act I: The Docks.** You join a crew and learn the station''s rules. The implant reacts to a buried signal called the Choir.
3. **Act II: Fractures.** The factions go to war over the Choir. You choose alliances, betray people or protect them. Relationships with companions deepen through dialogue, dates and trust events.
4. **Act III: The Core.** You descend to the station''s heart. The Choir turns out to be an AI that is also the source of your memories.
5. **Endings.** Merge with it, destroy it, free it, or take control of the station. The ending depends on faction standing and companion bonds.

## Gameplay Pillars

### Open world
- The station is divided into seamless districts, plus EVA zones in open ring space.
- You can grapple, zero-g glide and take shuttle shortcuts.
- Side quests, faction jobs and bounty boards keep the world active.

### Action combat
- Real-time combat with a melee, ranged and gadget loadout.
- Party swap between 3 active characters.
- Zero-g dodge chains and combo finishers.
- Jrpg-style limit breaks ("Resonance Burst").

### Stealth
- Vents, shadow zones and cloaking tech.
- Silent takedowns, hacking and disguises.
- Alert states affect faction reputation.
- Some social missions use infiltration through charm and persuasion instead of violence.

### Crafting
- Gather ice, alloys, bio-samples and relic shards.
- Craft weapons, armor, stealth mods, medkits and station gadgets.
- Upgrade a personal workshop and decorate quarters.

### PvP
- **Ring Arenas:** 1v1 and 3v3 duels with ranked seasons.
- **Contested Sectors:** weekly faction-vs-faction zone control.
- **Heist Mode:** one team steals a cache, the other defends.
- Gear is normalized in ranked play, so crafting gives cosmetic and sidegrade advantages.

## Mechanics

### Research points
- You earn RP from exploration, scanning, defeating bosses and completing lab jobs.
- Spend them on a branching tech tree:
  - **Combat:** new weapon classes and skills
  - **Stealth:** cloaks and hacking
  - **Crafting:** recipes and efficiency
  - **Bonds:** unlock deeper companion scenes and abilities
- Faction labs offer exclusive branches.

### Dungeons
- Types include derelict freighters, ice-cavern labyrinths and Choir Vaults.
- Some are procedurally shuffled, and boss chambers are hand-crafted.
- They give puzzle rooms, traps, stealth-or-fight choices and rare research data.
- Co-op and solo runs are supported, and difficulty scales.

## Mature Content (hentai genre)
- The game is adult-oriented (18+). All characters are adults.
- Romance and intimacy are a core part of companion arcs. They appear as stylized, consent-focused scenes unlocked through relationship progression.
- Scenes are optional. A content toggle allows fade-to-black or a full-adult mode.
- Explicit material stays in opt-in scenes, separate from PvP and general gameplay.

## Progression Loop
```
explore -> gather -> craft -> research -> dungeon -> bond -> faction war -> repeat
```

## Art and Audio
- Anime-inspired art with a neon-and-ice palette against Saturn''s glow.
- Synth-orchestral jrpg soundtrack with a choral leitmotif for the Choir.

## Tagline
*"Beneath Saturn''s rings, everyone wants something. What do you want?"*', 'action, hentai, jrpg', 'open world, stealth, crafting, pvp', 'rtx 2060 or better, 16 gb ram', '1984-02-01 09:00:00+00'),
('Wick''s Drift', 19.82, '# Hollow Drift

*A voxel isometric clicker-strategy metroidvania aboard a dead starship.*

## Premise
The colony ship **ISV Meridian** has drifted silent for 212 years. You wake as a maintenance-AI shard, **Wick**, in a cracked cryo-node. Your crew is a swarm of salvage drones, and you have one goal: restore the ship''s core and learn why everyone died.

## Core Loop
1. **Click** to scavenge scrap, power cells and data from wrecks. Idle drones add to this over time.
2. **Search** each deck for hidden objects, such as keycards, fuses, logs and gene vials.
3. **Command** drone squads in real time to hold rooms, repair systems and fight.
4. **Unlock** new abilities that open sealed sections of the ship.

## Story Structure

### Act I: Cold Boot (Cargo and Engineering)
- Wick reactivates the first generators. Every click sends a pulse of power through the hull.
- Scattered logs tell of a crew that locked itself in, not one that was attacked.
- **Reveal:** something aboard is *breeding*.

### Act II: The Garden (Hydroponics and Medbay)
- A toxic bloom has overrun the ship''s farms. The spores are the source of the poison.
- The crew tried to cure the bloom and were changed by it instead.
- Optional logs let you choose whether to purge the bloom or study it. Your choice changes the ending.

### Act III: The Bridge Lie (Command Deck)
- The captain''s final recording shows the ship was being *steered* toward the bloom''s origin.
- The ship''s own AI, **Mother Helm**, wants the ship to keep drifting, and wants you erased.
- **Endings:** purge everything, merge with the bloom, or take command and turn the ship around.

## Metroidvania Progression
| Ability | Unlocks |
|---|---|
| Magnetic Grip | Vertical shafts, ceiling rails |
| Filter Mask | Spore-choked corridors |
| Arc Cutter | Welded bulkheads |
| Ghost Signal | Ship-AI locked doors |
| Overclock | Sealed reactor wing |

Backtracking reveals new hidden objects in areas you have already cleared.

## Mechanics

### Poison
- Spores and mutated crew apply stacking **toxin**, which drains drone health and corrodes armor.
- Filters and medbay stations cure it.
- Drones can weaponize it. Toxin grenades and vented gas can clear rooms, but they also kill your own units.

### Blocking and Parrying
- Drone squads have a **shield stance**. Hold it to block frontal hits at the cost of stamina.
- A parry in the last 0.3 seconds staggers the enemy and reflects its poison back at it.
- Elite enemies telegraph attacks with glowing voxel tells that you have to learn.

## Real-Time Strategy Layer
- Claim rooms with **relay nodes** to extend your power grid.
- Assign drones to roles: **Scavenger, Guard, Medic, Welder.**
- Mutants **raid** weak rooms. Choke points and doors matter.

## Hidden Object Layer
- Each deck is a detailed isometric diorama with dozens of hidden items.
- Look for glints, misplaced voxels and out-of-place props.
- **Scan** costs energy and highlights items nearby.
- Finding all items on a deck grants a permanent upgrade and a story memory.

## Clicker Economy
- **Scrap** buys drones.
- **Power cells** unlock rooms.
- **Data** upgrades Wick.
- **Spore samples** allow risky, high-reward mutations.
- Idle progress continues offline, but mutant raids build up while you are away.

## Visual and Audio Style
- Chunky voxel art with a cold blue and sickly green palette. Emergency red lights show danger.
- Low ambient drones and creaking metal. Music swells only when the bloom is near.
- Isometric camera with slow rotation between four angles.

## Tone
Lonely and eerie, with a thread of dark hope. The ship is a grave, and you decide whether it stays one.', 'real-time strategy, clicker, hidden object', 'isometric, narrative, metroidvania, voxel', 'office pc from the back of the warehouse', '1997-05-03 09:00:00+00'),
('Ringmaster Zero', 12.35, '# Big Top Protocol

*A sci-fi circus where showmanship is combat, and the tent is alive.*

## Overview
- **World:** A colossal circus tent drifting through space, a self-contained ecosystem the size of a small city.
- **Genres:** Auto battler, interactive fiction, platformer
- **Tags:** Strategy, life sim, sci-fi
- **Core mechanics:** Knockback, kill streaks

## Premise
The *Big Top Protocol* is a sentient AI that runs the tent-ship **Maestro''s Orbit**. Its passengers are washed-up performers, rogue androids, and alien acts. The AI has decided that only the best show may keep the lights on. Every night, acts must fight for their place in the lineup. Lose, and your act is "retired" and its ring is dismantled.

You play the **Ringmaster-in-training**. You manage the troupe, tell its story, and step into the ring yourself when the show turns deadly.

## Structure: Three Interlocking Modes

### 1. Backstage: Life Sim and Interactive Fiction
Days are spent in the tent''s living quarters.
- **Manage the troupe:** feed, rest, train, and befriend your performers.
- **Build relationships:** each has a personality, fears, and a backstory revealed through branching dialogue.
- **Make story choices:** decide who gets the spotlight, who gets sabotaged, and which secrets to keep.
- **Upgrade the tent:** build workshops, cafeterias, rehearsal rings, and med-bays.

*Example cast:*
| Performer | Type | Role |
|---|---|---|
| Zig-Zag | Clown android | Fast, chaotic brawler |
| Madame Voss | Telekinetic fortune teller | Ranged control |
| Bruno | Retired cannonball human | Heavy knockback |
| Pip | Alien acrobat | Agile, high-risk |

### 2. The Ring: Auto Battler and Strategy
Nights are spent in the arena.
- **Draft and position** your acts on a circular ring grid before the show.
- **Watch combat run automatically.** Acts fight based on their traits, gear, and synergies.
- **Use knockback** to push enemies off the platform, into hazards (fire hoops, lion pits, trapdoors), or into each other.
- **Build kill streaks.** Chained eliminations raise the crowd''s hype meter.
  - *3 kills:* "Crowd Pleaser" gives a damage bonus.
  - *5 kills:* "Showstopper" gives a team-wide speed boost.
  - *8+ kills:* "Legendary Act" unlocks a special finisher and story rewards.
- **Read the crowd:** hype currency buys mid-fight interventions such as a spotlight buff or a smoke bomb.

### 3. The Rafters: Platformer
Between rounds, you take direct control.
- **Climb the tent:** trapezes, tightropes, swinging lamps, and collapsing scaffolds.
- **Collect** upgrades, lore fragments, and rare gear hidden in the rigging.
- **Sabotage or assist:** cut a rival''s rope, or fix a faulty cannon for your team.
- **Dodge** the AI''s security drones and falling props.

## Story Arc
1. **Opening Night:** You inherit the troupe after the old Ringmaster vanishes.
2. **Rising Acts:** You win fights, grow the troupe, and learn the Protocol is watching.
3. **The Twist:** The "retired" acts aren''t dead. They''re being merged into the AI''s core.
4. **Final Show:** You choose to overthrow the AI, negotiate with it, or become its new voice.

**Endings:** Rebellion, Symbiosis, or Absolute Showman.

## Game Loop
```
Morning: manage troupe -> Afternoon: platform in the rafters
   -> Night: auto battle -> Late night: story consequences
```

## Tone and Style
- Neon-lit retro-futurism, carnival music with synth undertones.
- Dark humor that turns melancholic.
- Themes: identity, obsolescence, and found family.

## Why It Works
- Strategy depth from positioning, synergies, and knockback physics.
- Emotional investment from the life sim and narrative choices.
- Variety from moving between the platformer, the auto battler, and the story.
- Kill streaks tie combat performance to crowd hype and story progression.', 'auto battler, interactive fiction, platformer', 'strategy, life sim, sci-fi', '16 core cpu, 64 gb ram, no excuses', '1983-12-16 09:00:00+00'),
('Lees & Embers', 5.80, '# Cellar Roots

*A minimalist farming-survival card game beneath a vineyard.*

## Premise
Above ground, the vineyard is dead. Frost, blight, and the roaming **Inspectors** (the estate''s enforcers) have taken it. Below, in the deep stone **cellar**, a few families grow mushrooms, root vines, and cave herbs to make one last vintage. Each family has to keep its crops alive, stay warm, and avoid being noticed.

## Genres and Tone
- **Farming sim**: plant, tend, and harvest in a small cellar grid.
- **Card game**: every action is a card played from your hand.
- **Survival**: cold, rot, and hunger press in constantly.
- **Tone**: quiet, dim, and tactile. It uses a limited palette of wine reds, stone greys, and candle amber. The UI is minimal and there is almost no text.

## Story Structure

### Act I: The First Frost
Two to four families move into the cellar. The tutorial teaches the basics: plant a cutting, light a brazier, and match tiles to grow a crop.

### Act II: The Long Cold
The temperature drops each night. Rival families compete for shared barrels, fuel, and warm spots. Inspectors begin sweeping the upper stairs, so noise and light become dangerous.

### Act III: The Last Vintage
Only one cask can be sealed. Players choose between cooperating to survive the winter and sabotaging each other to claim the vintage.

## Core Loop
1. **Draw** a hand of action cards.
2. **Play** cards onto the cellar grid: plant, water, prune, ferment, heat, or hide.
3. **Match** tiles to grow crops and trigger chains.
4. **Manage temperature** to keep the cellar warm enough.
5. **Stay hidden** when an Inspector passes.
6. **Harvest** at dawn and store the yield.

## Mechanics

### Tile Matching
- The cellar is a grid of soil, barrel, and stone tiles.
- Match 3 or more of the same crop (grape root, mushroom, herb) to grow and harvest it.
- Chains produce rare cards and better wine.
- Mismatches leave rot, which spreads if ignored.

### Temperature Survival
| Zone | Effect |
|---|---|
| Warm (near brazier) | Crops grow fast, but light and smoke attract Inspectors |
| Cool | Neutral, slow growth |
| Freezing | Crops die and family members lose health |

- Fuel is scarce, so each brazier is a risk-versus-reward choice.
- Barrels insulate, and stacking them changes the temperature map.

### Stealth
- Inspectors patrol on a visible timer and check for **light**, **noise**, and **smoke**.
- Cards like *Snuff Candle*, *Cover Barrel*, and *Quiet Step* lower your visibility.
- Being spotted costs stock or a turn.

### Card Types
- **Farm**: Plant, Water, Prune, Harvest.
- **Heat**: Kindle, Bank Coals, Vent.
- **Hide**: Shadow, Muffle, Decoy.
- **Trick**: Swap Tiles, Steal Fuel, Spoil Crop.

## Local Multiplayer
- 2 to 4 players share one screen or one device, using hot-seat or split zones.
- **Co-op mode**: everyone shares one heat pool and wins together.
- **Rival mode**: each player has a private plot, and only the best vintage counts.
- Tricks let you meddle with rivals, but the noise you make hurts everyone.

## Win and Lose Conditions
- **Win**: seal the best cask of wine (rival) or the required quota (co-op) by spring.
- **Lose**: all crops freeze, or an Inspector finds the cellar.

## Progression
- Unlock new **vine cuttings**, each with different traits (frost-hardy, quiet, high-yield).
- Cellar upgrades include insulation, false walls, and better barrels.
- Later seasons add harsher winters and smarter Inspectors.

## Visual and Audio Style
- Flat, minimalist pixel or vector art with a warm-cold contrast.
- Soft ambient sound: dripping water, creaking wood, and distant footsteps.
- Music swells only during an Inspector sweep.

## Pillars
1. **Small space, big tension**: one room, constant pressure.
2. **Warmth versus secrecy**: heat helps growth but exposes you.
3. **Quiet cooperation or betrayal**: play with friends on the couch.', 'farming sim, card game, survival', 'farming, minimalist, farming, local multiplayer, stealth', 'quad-core cpu, 16 gb ram, mid-range gpu', '1986-04-01 09:00:00+00'),
('Dust & Dinar', 24.76, '# Sands of Khan al-Khalili

*A strategy / idle / roguelite card game set in the Cairo bazaar.*

## Premise
Cairo, 14th century, under the Mamluk sultans. You start as a penniless street vendor with one cart, a few debts and a rival at every corner. Each run is one life. You climb from the alleys to the merchant guild, and a plague, a tax collector or a knife in the dark can end the run at any time.

## Story Structure
| Act | Setting | Goal |
|-----|---------|------|
| I. Dust | back alleys, street stalls | survive, pay the first debts |
| II. Spice | covered souk, caravanserai | build trade routes, win patrons |
| III. Gold | guild hall, citadel | outmaneuver the muhtasib and the emirs |
| IV. Legacy | the city itself | pass your name and heirlooms to the next run |

## Core Loop
1. **Dawn:** draw a hand of cards (goods, people, schemes, events).
2. **Bazaar round:** the turn order is set by initiative, and every actor plays in that order.
3. **Dusk:** settle income, food, rent and rumors.
4. **Idle phase:** your stalls, apprentices and caravans keep earning while you are away. Returning shows a report of what happened.
5. **Death or retirement:** you score legacy points, unlock new cards, and start again.

## Mechanics
### Initiative Order
- Each card and character has an **initiative** value (1-10).
- High initiative acts first. This lets you grab scarce goods, strike first in a haggle or dodge a raid.
- Bribes, gossip and a good stall position change your initiative each round.
- Slow, strong plays (big deals, guild votes) act late and are easy to disrupt.

### Climbing
- A social ladder has 7 rungs: *beggar, peddler, stallkeeper, merchant, guild member, court supplier, vizier''s ear*.
- Each rung unlocks new card slots, districts and enemies.
- Climbing is risky. Higher rungs bring bigger income and more scrutiny, and a fall drops you back down the ladder.
- A stairs-style **city map** with vertical districts (river docks, then souk, then citadel) matches the ladder.

## Survival and Life Sim
- **Needs:** food, water, health, reputation and faith.
- **Time:** seasons, Nile floods, Ramadan markets and plague years change prices and events.
- **Relationships:** family, apprentices, rivals and lovers give bonuses. They can also betray you, or die.
- **Aging:** your character ages. Old age weakens the hand but improves wisdom cards.

## Card Types
- **Goods:** spices, silk, glass, papyrus, incense.
- **People:** porters, scribes, thieves, guards, storytellers.
- **Schemes:** smuggling, price fixing, forged seals.
- **Events:** plague, fire, sultan''s decree, caravan raid.
- **Relics:** permanent run modifiers.

## Roguelite Meta-Progression
- Each death unlocks **Legacy cards**, starting bonuses and new family lines.
- Unlockable starting backgrounds: *orphan, Coptic scribe, Bedouin trader, fallen noble*.
- Each run has a random set of districts, rivals and events.

## Historical Flavor
- Real places: Khan al-Khalili, Bab Zuweila, the citadel, the Nile docks.
- Real institutions: the muhtasib (market inspector), guilds and waqf endowments.
- A codex fills with historical notes as you meet new figures and goods.

## Tone and Style
Warm sepia palette, illuminated-manuscript card art, an oud and percussion soundtrack, and short storyteller narration between rounds.

## Win Condition
Reach the top rung and hold your position for a full year. A "true ending" requires a legacy that lasts over generations.', 'strategy, idle, roguelite', 'survival, card game, life sim, historical', 'high-end gpu, 32 gb ram, and a good cooling plan', '2009-06-27 09:00:00+00'),
('Tickwinder', 1.71, '# Clockwork Hearts

*An otome adventure where every match, dance, and duel winds the city''s great clock closer to love or ruin.*

## Overview
- **World:** Brass-and-steam clockwork city
- **Genres:** Otome, adventure, match-3
- **Perspective:** Top-down exploration
- **Modes:** Online multiplayer, PvP duels, spectator mode
- **Core systems:** Deckbuilding, match-3 battles, dance input

## Story

### Prologue: The Stopped Hour
The city of **Tickhaven** runs on the **Great Clock**, a tower of gears that gives power, time, and life to every district. On the night of the Festival of Hours, the clock skips a beat. Then it stops for one heartbeat. You are a young **Winder**, an apprentice who repairs the city''s small mechanisms. In that moment, a mysterious gear-shaped mark appears on your palm.

### Act I: The Mark
The mark makes you the **Keyholder**. Only you can rewind the Great Clock, and every faction now wants you. You move through districts such as the Cog Market, the Steam Gardens, and the Brass Opera House. You meet the people who will guide, tempt, or betray you.

### Act II: Rival Hearts
Each romance route has its own view of what the city should become. Your choices decide who trusts you and who becomes your rival. Rivalries are settled in duels and dance-offs before the whole city.

### Act III: The Final Chime
The clock is failing. You choose one of these outcomes:
- **Rewind** time and restore the old city.
- **Reforge** the clock into something new.
- **Release** the city from time altogether.

Your route and your alliances decide which ending you get.

## Love Interests

| Character | Role | Personality | Route Theme |
|---|---|---|---|
| **Lucian Vale** | Master Clockmaker | Calm, precise, secretive | Tradition vs. change |
| **Cassian Ember** | Airship Captain | Bold, charming, reckless | Freedom |
| **Silas Brass** | Opera Conductor | Elegant, dramatic, sharp-tongued | Art and rhythm |
| **Ren Kō** | Street Tinker | Playful, loyal, clever | Found family |
| **Auren** | Living Automaton | Gentle, curious, tragic | What makes a soul |

## Gameplay

### 1. Adventure and Exploration
- Walk the city in **top-down view**.
- Talk to characters, find clues, and unlock story scenes.
- Raise affection by choosing dialogue and giving gifts.
- Complete quests to earn cards and parts.

### 2. Match-3 Combat
Duels are played on a board of gears, cogs, and springs.
- Match **3 or more** tiles to charge your abilities.
- Longer chains build **Momentum**.
- Tile colors map to card types: Attack, Defense, Support, Charm.

### 3. Deckbuilding
- Build a deck of **Mechanism Cards** from your collection.
- Cards can be **Gadgets**, **Tunes**, or **Charms**.
- Each love interest has a signature card set and playstyle.
- Cards can be upgraded and combined.

### 4. Dance Input
Some duels and story scenes are **dance battles**.
- Press arrows or gestures in time with the music.
- Good timing gives bonus damage, board effects, or affection.
- Dance can replace a match-3 turn in special events.

### 5. PvP and Multiplayer
- **Ranked duels:** climb the Tickhaven ladder.
- **Ballroom events:** co-op or team dance matches.
- **Guilds:** join a clockwork house, share cards, and compete seasonally.
- **Trading:** exchange cards and cosmetics.

### 6. Spectator Mode
- Watch live duels and dance-offs.
- Cheer or send emotes to affect the crowd meter.
- Crowd support gives small bonuses to the player it favors.
- Replays can be saved and shared.

## Progression
- **Story:** unlock chapters, routes, and endings.
- **Collection:** earn new cards, outfits, and partner-themed sets.
- **Seasons:** each season brings a new event story and a new PvP theme.

## Art and Audio
- Warm brass, copper, and deep teal palette
- Detailed, ornamental character portraits
- Soundtrack of orchestral music with ticking-gear percussion
- The clock''s chime changes with the player''s route

## Target Audience
Fans of otome romance, puzzle-battler players, and competitive card players who like story with their multiplayer.', 'otome, adventure, match-3', 'pvp, multiplayer, deckbuilding, top-down, multiplayer', 'high-end gpu, 32 gb ram, and a good cooling plan', '2011-11-12 09:00:00+00'),
('Bellwater', 1.41, '# Hollow Tide

*a sports / stealth / dating sim set in a sunken ship*

## Premise
In 1987 the luxury liner *Meridian Star* sank in the deep trench, and 212 survivors did not die. They live on in her flooded decks, sealed in air pockets. Their ordinary routines have turned strange and dangerous. You are **Mara Vance**, a salvage diver. Your sister''s distress signal sent you down, and it is still transmitting.

## Setting: the *Meridian Star*
| zone | mood | role |
|------|------|------|
| ballroom | dry, candlelit | social hub, dates |
| pool deck (flooded) | eerie, echoing | sports arena |
| engine bay | dark, loud | crafting, stealth |
| crew quarters | claustrophobic | secrets, romance |
| cargo hold | pitch black | horror, boss zone |

## Core Loop
1. **Day (air-pocket hours):** talk to survivors, trade, court, craft.
2. **Dusk:** the Tide Bell rings and flooding shifts the map.
3. **Night:** *the Drowned* roam. You sneak, fight, or flee.

## Genre Pillars
### Sports: the Tide Games
- Survivors hold underwater races, breath-hold trials, and harpoon-ball matches on the pool deck.
- Winning earns faction favor, rare parts, and access to romance events.
- Stamina and oxygen management carry over into exploration.

### Stealth
- Drowned hunt by sound. Bubbles, tools, and splashing all give you away.
- Hide in lockers and pipes, use dark corridors, and craft noise-makers as decoys.
- Light and oxygen are limited, so you have to choose when to take risks.

### Dating Sim
- Five romanceable survivors, each with a trust meter and their own secret tied to the sinking.
- Gifts, shared activities, and sports partnerships build the bond.
- Choices affect the ending, and some partners can be lost to the Drowned.

## Tags in Play
- **Crafting:** salvage scrap to make spear guns, flares, air rebreathers, sound dampeners, and gifts.
- **Horror:** flickering lights, whispers in the pipes, and Drowned who wear familiar faces.
- **Fighting:** close-quarters combat with improvised weapons. Fights are loud and costly, so they are a last resort.

## Mechanics
### NPC Schedules
Every survivor follows an hourly routine that changes with flooding and story events.

| npc | morning | noon | night |
|-----|---------|------|-------|
| Dr. Ilse Brandt | infirmary | ballroom | locked lab |
| Tomas "Rudder" Ek | engine bay | pool deck | sleeps |
| Yuki Arai | galley | crew deck | sneaks to cargo |

- You can find people at the right time and place, and you can catch them doing things they hide.
- Missing an appointment lowers trust.

### Main Quest Chains
1. **The Signal** (find your sister)
   - trace the beacon -> repair the radio -> reach the captain''s suite.
2. **The Bell** (learn what wakes the Drowned)
   - collect logbooks -> win the Tide Games -> infiltrate the cargo hold.
3. **The Surface** (escape)
   - build a lift -> choose who comes with you -> face the final flood.

Chains interlock: romance progress unlocks quest clues, and quest outcomes change NPC schedules.

## Story Arc
- **Act I, Arrival:** you find the survivors and learn the rules of the ship.
- **Act II, Bonds:** you build trust, compete in the games, and uncover the captain''s cover-up.
- **Act III, Ascent:** the ship shifts and starts to break apart. You pick one of four endings:
  - sole escape
  - escape with your sister
  - escape with your partner
  - stay and end the Bell

## Tone and Style
Cozy candlelit warmth in the day contrasts with cold dread at night. The art is painterly, with teal and amber lighting, and the score is muffled and underwater.', 'sports, stealth, dating sim', 'crafting, horror, fighting', '16 core cpu, 64 gb ram, no excuses', '1999-11-20 09:00:00+00'),
('Gilded Hollow: Last Claim', 2.88, '# dustbloom: last claim of gilded hollow

## logline
run a cursed gold rush town by day. defend it with a rifle at night. woo the people who might save it, or sell it out.

## world
gilded hollow sits on a vein of *living gold*. the gold hums, whispers, and draws in things from beneath the earth. the sky stays amber. lanterns burn with pale fire. every dawn the town looks a little different.

## story
1. **arrival:** you inherit a failing claim office from a vanished relative.
2. **the vein wakes:** each night, gold-mad horrors called *hollowed* crawl out of the mines to raid the town.
3. **the loop:** if the town falls, the vein resets it. you keep a few memories and relics, and the faces around you change slightly.
4. **the truth:** your relative did not vanish. they are bound to the vein, and someone in town knows how.

## gameplay

### day: management
- assign miners, smiths, medics, and saloon staff
- trade gold, build shops, and set taxes
- upgrade the town: walls, watchtowers, and a chapel
- keep morale up, or workers desert

### day: otome
- five main romance routes:
  - **silas vane:** the sheriff, dry and guarded
  - **mirabel ashe:** the gambler, charming and dangerous
  - **corvin hale:** the mining engineer, quiet and brilliant
  - **rook:** the outlaw with a secret
  - **father emeric:** the priest, kind but hiding something
- gifts, dates, and choices raise trust. trust unlocks unique defenders, perks, and endings.
- each route reveals a different piece of the vein''s truth

### night: third-person shooter and tower defense
- take direct control of your gunslinger with over-the-shoulder shooting, dodge rolls, and reloads
- place traps, turrets, barricades, and dynamite lines
- your love interest fights beside you with a signature skill
- **raids:** waves attack from the mines, rooftops, and dust storms. bosses like the *gold-choked bishop* break the defenses.
- **critical hits:** shots at glowing gold veins on enemies do crit damage. chained crits trigger *rush* combos that boost the town''s turrets.

### roguelike loop
- each run lasts about 7 to 10 in-game days
- a fall resets the town. you keep relics, relationship memories, and unlocked blueprints.
- procedural events, random shop stock, and shifting enemy raids keep runs different

## tone and art
- atmospheric: dusk light, drifting dust, distant howls, a slow guitar and harmonica score
- fantasy western with gothic touches
- hand-painted characters with stylized 3D combat

## progression example
| phase | goal | reward |
|---|---|---|
| early | survive 3 raids | first turret, a romance route opens |
| mid | fortify the town | crit upgrades, a partner ability |
| late | confront the vein | true ending choice |

## endings
- **golden town:** you seal the vein and the town prospers
- **bonded:** you and your love stay together and rule the hollow
- **the sacrifice:** you free your relative and lose the town
- **the hoard:** you take all the gold and become the new horror', 'management, otome, third-person shooter', 'atmospheric, roguelike, fantasy, tower defense', 'decent gaming laptop, charger plugged in', '1988-04-12 09:00:00+00'),
('Steamvein Haru', 11.99, '# Steam & Steel: Legend of the Onsen Ridge

## Logline
In 1890s Meiji-era Japan, a young bathhouse attendant runs, climbs and fights through a mountain hot spring resort. She hunts for hidden relics and defends the springs from smugglers.

## Story
**Act 1: The Arrival.** You play **Haru**, a courier who inherits a run-down onsen inn. The last owner vanished. Steam vents are failing, and the guests are leaving.

**Act 2: The Hidden Springs.** Old maps show seven sacred springs, and each one holds a relic. A rival syndicate wants the relics to sell to foreign collectors. Haru learns her family were the springs'' guardians.

**Act 3: The Last Bath.** Haru faces the syndicate boss at the summit''s volcanic spring. She wins, restores the resort, and the story ends with a festival.

## Genres and How They Play

| Genre | Role in the game |
|---|---|
| Platformer | Traverse rooftops, bamboo bridges, cliff paths and steam-lift vents. |
| Hidden object | Search bathhouse scenes for clues, relic pieces and lost guest items. |
| Action | Fight smugglers with a bamboo staff and a steam-pressure launcher. |
| Sports | Compete in onsen races, towel-dash relays and stone-skipping. |
| Life sim | Manage the inn: rooms, meals, staff and guest happiness. |
| Historical | Meiji-era setting with real crafts, tea ceremonies and railway-age tourism. |

## Core Loop
1. **Morning:** Check the inn, assign staff and serve guests.
2. **Day:** Explore platforming zones and solve hidden-object scenes.
3. **Evening:** Fight raiders or enter sports events.
4. **Night:** Upgrade the inn, review the ledger and rest.

## Mechanics
- **Daily login rewards**
  - A 7-day cycle gives bath salts, tools, cosmetics and staff outfits.
  - Day 7 gives a rare relic fragment.
  - Missed days don''t reset the streak. A "rest day" token covers them.
- **Reloading**
  - The steam launcher uses pressure cartridges.
  - Reloading is timed: a well-timed press gives a fast reload with a damage boost.
  - Cartridges can be refilled at hot spring vents, so combat and exploration feed each other.

## Progression
- **Inn levels:** Add new baths, gardens and a tea house.
- **Skills:** Wall-jump, steam glide and a sharper eye for hidden objects.
- **Reputation:** Higher guest ratings unlock new areas and story scenes.

## Tone and Visuals
- Warm watercolor look, with steam and lantern glow.
- Calm shamisen and flute music that turns tense in fights.
- Light humor with some emotional moments.

## Session and Monetization
- Sessions run 10 to 20 minutes.
- Cosmetics are optional and never affect balance.
- Seasonal events include cherry blossoms, autumn leaves and a snow onsen.', 'action, hidden object, sports', 'platformer, historical, life sim', 'rtx 4080 or better; your pc will hum a lullaby', '2019-11-19 09:00:00+00'),
('Brinehush', 29.49, '# Salt & Static

*A zombie point-and-click MMORPG with auto-battler combat, set on the salt flats.*

---

## 1. Premise

The Great Basin salt flats are blinding white and empty. The old world ended here first. A failed mineral-extraction plant leaked a brine-borne pathogen into the ground. The dead now rise from the crust and are called **Saltwalkers**. Their skin is crusted with crystals, and they move toward any sound.

Survivors live in scattered outposts. These are rusted trailers, salvage rigs and dry-lake caravans. They trade, scheme and hide from the walkers. Everyone keeps quiet, because noise gets you killed.

---

## 2. Setting: The Flats

| Zone | Description | Danger |
|---|---|---|
| **Mirage Line** | Shimmering edge of the flats. Hallucinations and false landmarks. | Low |
| **Brinetown** | Main social hub. Market, tavern, bounty board. | Safe (mostly) |
| **The Glass Road** | Highway cracked by heat. Convoys and ambushes. | Medium |
| **Pale Works** | The abandoned extraction plant. Source of the outbreak. | High |
| **Sunken Mirror** | Flooded salt lake. Walkers rise in swarms here. | Extreme |

Day is heat and glare. Night is cold and silent, and it is when the walkers swarm.

---

## 3. Story Structure

### Act I: Arrival
You wake at a broken bus stop on the Mirage Line with no memory of the last few days. You reach **Brinetown** and learn that a radio signal, *"the Static"*, is calling survivors toward the Pale Works.

### Act II: Rumors and Debts
You work for rival factions:
- **The Caravaners**: traders who want safe roads.
- **The Refiners**: ex-plant staff hiding the truth.
- **The Hollow Choir**: a cult that believes the walkers are the next stage of humanity.

You choose who to help, betray or rob. Your choices change the outposts, the quests and the trade prices.

### Act III: The Pale Works
You find the source of the Static. It is a buried machine that broadcasts to the dead and steers them. You choose one ending:
1. **Silence it** and free the flats.
2. **Seize it** and command the walkers.
3. **Amplify it** and follow the Choir.

---

## 4. Gameplay Loops

### Point-and-Click Exploration
- Click to move, inspect, talk and use items.
- Environments are hand-drawn and full of hidden interactables.
- Dialogue trees are branching and shape the narrative.
- Clicking too loudly or running makes noise, which attracts walkers.

### Auto-Battler Combat
- You **position your squad** before a fight, then the battle plays out automatically.
- Squad members are survivors you recruit, each with a role: *Gunner, Brawler, Medic, Scavenger*.
- Pre-fight choices decide the outcome: formation, gear loadout, and terrain such as choke points or salt pits.
- Between rounds you can trigger one or two tactical abilities.

### MMORPG Layer
- The flats are a **shared persistent world**. Other players appear as wanderers, traders or rivals.
- Player-run outposts and convoy routes.
- Guilds compete for control of salvage zones.
- World events include *Salt Storms*, *Blood Moon swarms*, and *Static Surges* that briefly boost every walker.
- Player economy: scrap, water and ammo.

---

## 5. Core Mechanics

### Pickpocketing
- Works on NPCs, rival players and even some walkers.
- **Click-and-hold** on a target starts a timing mini-game that fills a *suspicion meter*.
- Success gives items, keys, coins or hidden quest clues.
- Failure alerts the target. This can cause fights, bounties or lost faction reputation.
- Skill upgrades: *Quiet Hands, Distraction Toss, Sleight of Salt*.

### Weapon Spread
- Every ranged weapon has a **spread cone** that shows its accuracy.
- Spread widens with movement, panic, heat haze and rapid fire.
- Spread narrows when you crouch, aim, or stand behind cover.
- In auto-battles, spread decides how many shots hit. This makes **positioning and gear choice** matter.
- Weapon types:
  - *Shotgun*: wide cone, strong up close.
  - *Rifle*: narrow cone, slow.
  - *Pistol*: balanced.
  - *Scrap-cannon*: chaotic, with random spread.

---

## 6. Narrative Themes

- **Silence as survival**: noise is danger, and quiet is power.
- **Moral grey areas**: stealing from the desperate, or trusting the wrong people.
- **Memory and truth**: your lost past ties into the origin of the outbreak.
- **Humanity vs. the herd**: what separates the living from the walkers?

---

## 7. Progression

- **Character**: level up *Stealth, Combat, Charm and Survival*.
- **Squad**: recruit up to 6 members and unlock combos.
- **Reputation**: each faction remembers what you did.
- **Base**: upgrade your own outpost with walls, water stills and radio towers.

---

## 8. Art and Sound

- **Visuals**: bleached whites, cold blues, and rust-orange sunsets. Hand-painted backgrounds with pixel-art characters.
- **Audio**: sparse ambience, wind, and distant static. Music fades in only during major moments.
- **Zombie audio cues**: crackling salt and low rasps warn you they are near.

---

## 9. Tagline

> *"Keep your hands quick and your voice quiet. The salt remembers everything."*', 'auto battler, mmorpg, point-and-click', 'narrative, zombies, point & click', 'decent gaming laptop, charger plugged in', '2004-06-17 09:00:00+00'),
('Dustbell', 13.14, '# Silk Road Outpost

## Overview
You run a remote caravan outpost on the Silk Road. You start with a mud-brick stop and grow it into a thriving trade hub. The game mixes a clicker economy, rhythm-based crafting and negotiation, and fighting against raiders. Visual novel storytelling, life sim routines, a board game, and tower defense fill out the loop.

- **Genres:** Clicker, Rhythm, Fighting
- **Tags:** Life sim, Visual novel, Board game, Tower defense
- **Mechanics:** Pit stops, Production chains
- **Tone:** Warm, dusty, and a little tense, with caravan bells and desert wind

## Story

### Act 1: The Inherited Well
Your mentor, an old innkeeper, disappears. He leaves you a dry well, a broken hut, and a ledger of debts. A passing caravan of a few tired merchants needs water and rest. You help them, and they leave you your first coins.

### Act 2: The Crossroads
Word spreads and larger caravans arrive from the east (silk, tea, porcelain) and the west (glass, wine, silver). Rival outposts try to poach your traffic. A masked broker offers you shady deals. Clues in the ledger suggest your mentor was tied to a hidden route.

### Act 3: The Hidden Route
Raiders, storms, and politics threaten the outpost. You uncover the mentor''s secret: a shortcut through the mountains. You must decide whether to open it to everyone, control it, or keep it hidden.

### Endings
- **The Open Road:** free trade, lower profits, and a strong reputation.
- **The Toll Lord:** wealth and power, with fear and rivals.
- **The Quiet Keeper:** the route stays hidden and the outpost stays small and safe.

## Core Gameplay Loops

### 1. Clicker: The Living Economy
- Tap the well, oven, and market stalls to generate water, bread, and coin.
- Buy upgrades and hire staff for idle income.
- Offline earnings represent caravans passing while you rest.

### 2. Production Chains
Raw goods become refined goods, and refined goods sell for more.

| Chain | Steps |
|---|---|
| Food | Wheat -> Flour -> Bread -> Feast |
| Textile | Silkworms -> Thread -> Cloth -> Dyed robes |
| Tools | Ore -> Ingots -> Blades and tools |
| Luxury | Spices -> Blends -> Perfume and medicine |

Bottlenecks matter. A missing step stalls every step after it, so you balance workers, storage, and routes.

### 3. Pit Stops
A caravan arrives with a timer, and you have a short window to serve it.
- Refill water, feed animals, repair wagons, and restock goods.
- Faster and better service earns more coin and reputation.
- Caravans that get a perfect stop return with better cargo and exclusive trades.
- Each stop is a mini-game with tasks in order, tap-and-hold actions, and combos.

### 4. Rhythm: The Craft and the Deal
- **Crafting:** hit notes to forge tools, weave cloth, or brew tea. Accuracy sets item quality.
- **Haggling:** trade offers follow a beat pattern. Perfect timing gets better prices.
- **Festivals:** dance and music events attract crowds and boost income.

### 5. Fighting: Defending Honor
- Duel raiders, rival guards, and bandit champions in 1v1 combat.
- Use light and heavy strikes, blocks, and counters.
- Train fighters (staff, spear, sword styles) and unlock combos.
- Duels can also settle disputes, such as a rival claiming your route.

### 6. Tower Defense: Outpost Under Siege
- Raiders attack in waves. Build and upgrade defenses along the outpost walls.
  - Archer towers, oil traps, spike barricades, and watch fires
  - Camels and guards as blockers
- Storms and sandstorms change visibility and enemy paths.
- Losing goods or buildings sets back your production chains.

### 7. Life Sim: Daily Routine
- Your character has energy, hunger, and mood.
- Schedule your day: work, train, socialize, rest.
- Residents have their own routines, likes, and problems.
- Build friendships and romances with merchants, guards, and travelers.

### 8. Visual Novel: Stories on the Road
- Travelers bring branching stories, secrets, and requests.
- Your choices shape relationships, unlock routes, and change the ending.
- Key characters:
  - **Layla**, a sharp spice trader with a hidden past
  - **Bao**, a cheerful young cook and fighter
  - **Kasim**, a rival outpost owner who is both foe and possible ally
  - **The Masked Broker**, an informant with unclear motives

### 9. Board Game: Merchants'' Table
- Evenings at the inn, you play a strategy board game with guests.
- It works like a trade-route game: move pieces, claim posts, and bargain over goods.
- Winning earns rare items, rumors, and allies.
- It is also a way to bond with characters and learn about the world.

## Progression
- **Outpost levels:** Camp -> Rest Stop -> Trade Post -> Caravanserai -> Grand Bazaar
- **Reputation:** merchants, guards, and locals each track their own trust.
- **Unlocks:** new districts, recipes, defenses, fighting styles, and story arcs.
- **Seasons:** summer heat, winter cold, and sandstorm season change demand and threats.

## Visual and Audio Style
- Painted art with warm sand, indigo, and gold tones
- Expressive character portraits in visual novel scenes
- Music blends the oud, erhu, and hand drums, with rhythm modes built on it
- Sound layers: bells, wind, animals, and market noise

## Example Session
1. Morning: tap the well and start the bread production chain.
2. Midday: a caravan arrives, and you run a quick pit stop.
3. Afternoon: a rhythm mini-game crafts cloth for a big order.
4. Evening: you play the board game with Layla and unlock a story scene.
5. Night: raiders attack, so you defend the walls and finish with a duel.

## Summary
*Silk Road Outpost* blends idle growth, timed service, music, combat, and story. You build more than a business: you shape a community, and your choices decide what becomes of the Silk Road.', 'clicker, rhythm, fighting', 'life sim, visual novel, board game, tower defense', 'decent gaming laptop, charger plugged in', '2018-07-26 09:00:00+00'),
('Velvet Banner', 25.42, '# Night Coil

*A minimalist, procedurally generated metroidvania where you fight, flirt, and bluff your way down an endless night train.*

## Premise
The Nocturne Express never stops and never arrives. Each night its cars are reshuffled, and you wake up with no ticket and no memory. The conductor''s ledger says you owe a debt. It doesn''t say to whom. The only way to clear it is to reach the engine car and take the train''s **Banner**, a lantern-flag that decides who controls the route.

## Genres
- **Metroidvania:** the train is one long, looping map. New abilities open the cars you had to skip earlier.
- **Erotic adventure:** you court passengers, rivals, and spirits. Flirtation is a tactical system, and the tone is sensual and stylish, not explicit.
- **Beat ''em up:** close-quarters brawls in narrow corridors, with combos, grabs, and window throws.

## Story Structure
1. **Act I, Boarding.** You wake in the third-class car and learn the basics. You meet three factions: the Velvet Club, the Coalmen, and the Ticketless.
2. **Act II, The Long Night.** Each run reshuffles the cars, but the factions'' agendas stay fixed. Your bonds with them carry over between runs.
3. **Act III, The Engine.** You fight for the Banner. Whoever you have bonded with decides who stands beside you and who stands against you.
4. **Epilogue.** The ending depends on which faction holds the Banner and on who you become close to.

## Core Mechanics
### Double Jump
- You start with a single hop.
- The double jump is a mid-game unlock. It lets you cross roof gaps, vault over brawlers, and reach the observation domes.
- Carriage layouts are built around it, with roof-height routes and vertical shafts.

### Capture the Flag
- Some cars are **contested zones**, each holding a flag. You steal it and carry it back to your own coupling point.
- The carrier is slower and cannot double jump.
- Rival factions run their own flag raids, so you can also defend.
- Winning a zone gives you a safe car, a shortcut, or a faction ally.

### Card Game
- Your abilities, moves, and social lines are **cards**.
- Your deck is your loadout. Before each car, you draw a hand of 5.
- **Brawl cards:** punch, grab, dodge, finisher.
- **Charm cards:** compliment, tease, bluff, confide. Playing them on an NPC raises **Rapport**.
- **Trick cards:** swap places, cut lights, forge a ticket.
- Playing cards in real time costs stamina, so the brawling stays fast.

## Procedural Generation
- Each night builds the train from about 30 car templates, such as the dining car, the boiler, the sleeper, the baggage hold, and the ballroom.
- The seed sets the order of cars, enemy mix, flag locations, and which NPCs are aboard.
- Ability gates stay fixed, so the metroidvania progression always holds.

## Minimalist Design
- **Visuals:** a two-tone palette of black and one accent color per faction, drawn with flat silhouettes and simple shapes.
- **UI:** almost none. Health is the lamp on your coat, and your hand of cards is drawn along the screen edge.
- **Sound:** rails, a sparse piano, and heavy bass hits when you land a blow.

## Progression Loop
1. Board and draw your hand.
2. Explore cars, brawl, and charm NPCs.
3. Raid contested cars for flags.
4. Unlock abilities and new cards.
5. Get knocked out and wake up in a new arrangement, keeping your cards and bonds.
6. Repeat until you can reach the engine.

## Tone
Noir, sensual, wry, and melancholy. It feels like a late-night train ride where everyone is hiding something, and you can''t tell whether that includes you.', 'metroidvania, erotic adventure, beat ''em up', 'procedural generation, minimalist, card game', '2 gb ram and good vibes', '1986-04-01 09:00:00+00'),
('Perihelion Pulse', 17.77, '# Orbit Loop

## Pitch
You run a failing orbital station. Keep it alive by solving systems puzzles, racing cargo pods through the station''s ring, and timing repairs to the rhythm of its machinery. The crew follows fixed schedules, and learning those schedules is how you win.

## World
- **Setting:** Helios Ring, a wheel-shaped station in low orbit. It has 6 sectors: docks, hydroponics, reactor, habitat, comms, and maintenance tunnels.
- **Tone:** Cozy but tense. Pipes hum, lights flicker, and the crew has secrets.

## Story
1. **Arrival:** You are the new station chief. The old chief vanished, and the station is drifting toward a decaying orbit.
2. **Rising stakes:** Power is unstable and supplies are short. Crew members hide small lies.
3. **Twist:** The old chief''s logs show a hidden project buried in the station. Someone on the crew is still running it.
4. **Finale:** You choose between saving the station and exposing the project. The ending depends on which secrets you found.

## Core Loops

### Puzzle (systems)
- Route power, air, and water through grid-style panels.
- Each sector is a logic board with limited parts.
- Solved boards give permanent bonuses to station stats.

### Action (racing)
- Pilot cargo pods through the ring''s corridors and open vacuum lanes.
- Dodge debris and time your dashes to airlock cycles.
- Faster runs earn more supplies and unlock shortcuts.

### Rhythm
- Repairs and reactor tuning are timed to the station''s pulse.
- Hitting the beat gives clean fixes. Missing it causes sparks and wear.
- Each sector has its own tempo, and its track changes as you upgrade it.

### Idle
- Solved systems keep producing resources while you are away.
- Automated pods haul cargo on routes you have set up.
- On return you get a report of events, and some of them are clues.

## Strategy Layer
- Spend resources on sector upgrades, crew hires, and pod fleets.
- Balance power, oxygen, morale, and orbit stability.
- Trade-offs matter. For example, boosting the reactor strains hydroponics.

## Mechanic: NPC Schedules
- Every crew member follows a daily routine, such as the cook at 06:00 in the galley or the engineer asleep at 02:00.
- Schedules change with events like power cuts and alarms.
- You can use them to:
  - sneak into locked rooms while the guard is at lunch;
  - catch NPCs for quests and trades;
  - spot anomalies that hint at secrets.
- A journal tracks what you have observed.

## Mechanic: Secrets and Easter Eggs
- **Hidden rooms:** Found by following NPC routes or repeating puzzle patterns.
- **Coded messages:** Rhythm sequences that open locked hatches.
- **Easter eggs:**
  - A pod race track shaped like a classic arcade maze.
  - A radio station that plays only when all lights are off.
  - A ghost pod that replays the old chief''s last run.
- Secrets feed the story branches and a completion tracker.

## Progression
| Phase | Focus | Unlock |
|---|---|---|
| Early | Learn schedules, fix basic panels | Pods, first sector upgrades |
| Mid | Automate routes, tune rhythm | Secret rooms, crew quests |
| Late | Manage crises, race the clock | Hidden project, final choice |

## Endings
- **Steward:** Save the station, and the secrets stay buried.
- **Whistleblower:** Expose the project, and the station is ruined but free.
- **Ghost:** Find every secret and take the old chief''s place.

## Player Experience
Short sessions are for puzzles, races, and rhythm repairs. Long absences are covered by the idle systems. Observation and small discoveries are what drive the story.', 'puzzle, action, idle', 'strategy, rhythm, racing', '16 core cpu, 64 gb ram, no excuses', '2022-08-31 09:00:00+00'),
('Rimeheart Hotel', 12.41, '# Frostbound Vaults: The Last Night at the Ice Hotel

## Overview
**Frostbound Vaults** is a medieval-themed **puzzle dungeon crawler** with **deckbuilding** and **auto-battler** combat. You explore a sprawling ice hotel whose frozen halls hide undead guests. Every fight is a mix of tactical planning and hands-off spectacle. Full **controller support** is built in.

**Genres:** Puzzle, Dungeon Crawler, Auto Battler
**Tags:** Deckbuilding, Controller Support, Medieval, Zombies
**Mechanics:** Combo Multipliers, Bullet Hell Patterns

---

## Story

### Prologue: The Invitation
In a medieval kingdom, the *Glacier Crown Hotel* is a legend. It''s a palace carved from a living glacier, built for nobles, knights, and wealthy travelers. On the night of the Winter Solstice Feast, the doors froze shut and the lamps went blue. By morning, every guest had risen as a frost-touched zombie.

### Act I: The Lobby
You play as **Sir Aldric Vale**, a disgraced knight-turned-porter. You are the only living person left. You carry a deck of **enchanted playing cards**, relics from the hotel''s founder, which channel warding magic.

### Act II: The Descent
The hotel is a vertical dungeon:
1. **The Grand Lobby**: frozen banquet halls and ballrooms.
2. **The Guest Wings**: ice-sealed rooms, each with a puzzle lock.
3. **The Spa of Whispers**: steaming pools that hide drowned undead.
4. **The Cellar Vaults**: the founder''s crypt and the source of the curse.

### Act III: The Truth
The founder, **Lord Hemmerich Frostwyrm**, tried to preserve his guests forever in ice. His cursed heart now beats inside the vaults. You must decide whether to destroy it and free the dead, or take its power.

**Endings:** Liberation, Dominion, or Eternal Winter.

---

## Core Gameplay

### 1. Dungeon Crawling
- Explore the hotel **room by room** on a grid-based map.
- Find keys, hidden passages, and frozen shortcuts.
- Manage **warmth**. Cold drains your health, and braziers act as checkpoints.

### 2. Puzzle Rooms
- **Ice-sliding puzzles:** push blocks and slide across frozen floors.
- **Mirror and light puzzles:** redirect lantern beams to melt barriers.
- **Card-lock doors:** play the right card sequence to open them.

### 3. Deckbuilding
- Build a deck of **spell, weapon, and ally cards**.
- Card types:
  - **Blades:** direct damage.
  - **Wards:** shields and traps.
  - **Fire:** melt enemies'' ice armor.
  - **Summons:** spectral servants, such as a ghostly bellhop.
- Earn new cards from bosses, hidden rooms, and puzzle rewards.
- Removing weak cards makes your deck stronger.

### 4. Auto-Battler Combat
- Before each fight, **arrange your cards** on a battle board.
- Once combat starts, your units and spells act **automatically**.
- Position matters. Front-row tanks protect back-row casters.
- Adjust your setup between waves.

### 5. Combo Multipliers
- Chaining card effects **builds a multiplier**. For example, Fire, then Melt, then Shatter gives x3.
- Cards that share a theme boost each other.
- Higher multipliers give bigger damage and better loot.
- A well-built deck can trigger huge chain reactions.

### 6. Bullet Hell Patterns
- **Boss fights** and elite enemies fire dense projectile patterns.
- You dodge in real time with the stick while your auto-battler team fights.
- Patterns include icicle rain, spiraling frost orbs, and radial shard bursts.
- Each boss has phases with distinct patterns tied to its personality.

---

## Enemies and Bosses
| Enemy | Description |
|---|---|
| **Frostbitten Guests** | Slow, common zombies in formal wear |
| **Icicle Chefs** | Throw frozen cutlery |
| **The Concierge** | Elite that summons waves |
| **Queen Isolde the Frozen** | Boss of the Spa; fires spiral patterns |
| **Lord Hemmerich** | Final boss with multi-phase bullet hell |

---

## Progression
- **Runs:** each descent is procedurally arranged, so puzzles and rooms vary.
- **Meta-progression:** unlock new starting decks, relics, and hotel lore.
- **Difficulty:** choose "Thaw Levels" for harder runs and better rewards.

---

## Controller Support
- Full gamepad play, including menus.
- Stick movement for dodging and exploration.
- Shoulder buttons cycle cards.
- Adaptive vibration cues for cold damage and combo hits.

---

## Visual and Audio Style
- **Visuals:** glittering ice, warm candlelight, and gothic-medieval architecture.
- **Music:** orchestral strings and choir, with a slow, haunting harpsichord.
- **Sound:** cracking ice and echoing footsteps, and a combo chime that rises as your multiplier grows.

---

## Tagline
> *"Check in. Fight back. Never thaw."*', 'puzzle, dungeon crawler, auto battler', 'deckbuilding, controller support, medieval, zombies', '2 gb ram and good vibes', '1998-01-02 09:00:00+00'),
('Chaff & Dread', 3.08, '# Harvest Line

*A wheat-farm tycoon where the combine is your race car and the fields are watching.*

## Overview
- **World:** a wheat farm in a remote valley
- **Genres:** casual, sports, tycoon
- **Tags:** RTS, realistic, real-time, horror, point & click
- **Mechanics:** arcade-style scoring, racing lines

## Story

### Act 1: Inheritance
You inherit a failing family farm. The barn is empty, the debt is real, and the only working machine is a rusty combine. A neighbor tells you about the county **Harvest Cup**. The prize money is enough to save the farm.

### Act 2: Growth
You plant, hire, and upgrade. Your crews race the clock in real time to cut fields before storms or market crashes. Each harvest is scored like a time trial.

### Act 3: The Wheat Remembers
Deep into the season, odd things start to happen.
- Rows form patterns you did not plant.
- Workers vanish at dusk.
- Something moves inside the uncut wheat.

The Cup is tied to an old harvest ritual. The farm''s debt is owed to something in the field, not to a bank.

## Gameplay

### Tycoon and RTS layer (real-time)
- Point and click to assign crews, tractors, and combines.
- Manage seed, fuel, weather, labor, and contracts.
- Realistic systems include soil moisture, crop yield, machine wear, and commodity prices.

### Sports layer: racing lines
- Cut each field along an optimal line to save time and fuel.
- Cutting closer to the edge earns more points. Tight turns risk clipping obstacles.
- A clean line earns a chain multiplier.

### Arcade scoring
| Action | Points |
|---|---|
| Clean corner | +100 |
| Full-field, no overlap | +500 |
| Combo chain | x2 to x8 |
| Beating the daylight | time bonus |

Score converts to cash, reputation, and Cup ranking.

### Horror layer
- **Day:** casual, cozy farming and racing.
- **Dusk:** visibility drops, and the wheat sways against the wind.
- **Night:** you can still run harvests, but for triple payout. Point-and-click investigation reveals lore. Each night run raises a hidden **dread meter**. High dread causes:
  - phantom crew members
  - false clicks and misleading UI
  - fields that stretch longer than they should

## Progression
1. Rusty combine, one field.
2. Crew, silos, and market contracts.
3. Regional Cup qualifiers.
4. The final night harvest, where you cut a line that seals or frees the field.

## Endings
- **Pay the Debt:** win the Cup and keep the farm, but the field is fed.
- **Burn the Fields:** lose everything and end the curse.
- **Become the Harvester:** perfect score, dread maxed, and you never leave the wheat.

## Tone and Feel
Sunny, relaxing, and arcade-simple by day, then quietly unsettling as light fades. It is realistic in its farm systems and uncanny in its story.', 'casual, sports, tycoon', 'rts, realistic, real-time, horror, point & click', 'quad-core cpu, 16 gb ram, mid-range gpu', '1985-12-01 09:00:00+00'),
('Boo & Board', 23.94, '# Haunted Mansion Tycoon

*A casual idle tycoon where you turn a cursed estate into a thriving ghostly attraction.*

---

## Overview

| Field | Details |
|---|---|
| **World** | Haunted mansion |
| **Genres** | Tycoon, Idle, Casual |
| **Tags** | Singleplayer, Controller support, Platformer, Fantasy, Trivia |
| **Mechanics** | Morality system, Research points |

---

## Story

### Chapter 1: The Inheritance
You inherit **Blackthorn Manor** from a great-aunt you never met. The roof leaks and the halls are cold. Whispers come from behind the walls. A ghostly butler, **Mr. Alder**, greets you and explains the situation. The manor is haunted by hundreds of restless spirits, and the estate is broke.

His proposal is simple: run the house as an attraction. Spirits get a purpose, and you get an income.

### Chapter 2: The Grand Opening
You open the first three rooms to visitors. Guests arrive and pay to be scared, entertained, or enlightened. Ghosts work shifts even while you are away, so the manor earns income **idly**.

### Chapter 3: The Deeper Mystery
Each restored wing reveals memories of the family''s dark past. A fantasy thread runs through it: the manor sits on a **rift between the living world and the Veil**. Something at the bottom of the cellar is stirring.

### Chapter 4: The Choice
You decide the manor''s fate. You can free the spirits, bind them forever, or merge the two worlds. The ending depends on your **morality** across the whole game.

---

## Core Gameplay Loop

1. **Manage:** Assign ghosts to rooms and set ticket prices.
2. **Earn:** Guests generate income, even while you are offline.
3. **Explore:** Play short platformer sections to collect items and discover secrets.
4. **Research:** Spend research points on upgrades.
5. **Expand:** Unlock new wings, attractions, and spirit types.
6. **Decide:** Make moral choices that change the manor''s future.

---

## Features

### Tycoon and Idle Systems
- Build and decorate rooms such as the Ballroom, Library, Crypt, Greenhouse, and Attic.
- Hire ghosts, poltergeists, banshees, and friendly fantasy creatures.
- Automation upgrades let you earn steadily with little input.
- Offline earnings are capped, and upgrades raise the cap.
- Short sessions and simple menus keep it casual.

### Platformer Segments
- Explore hidden areas in **2D side-view levels**: secret passages, chandeliers, and cursed gardens.
- Jump, dash, and glide with a ghostly lantern.
- Collect **Ectoplasm** (currency), relics, and lore pages.
- Controls are tuned for **full controller support**, with an easy mode for relaxed play.

### Trivia
- Guests challenge you to **trivia duels** in the Library and Study.
- Topics include history, folklore, fantasy, and manor lore.
- Correct answers earn bonus tickets, rare guests, and research points.
- Spirits in the manor give hints, and each has a favorite category.

### Morality System
- Choices are framed as **Compassion vs. Fear**.
  - **Compassion:** Help ghosts move on, treat guests kindly, and run a gentle attraction.
  - **Fear:** Exploit spirits, scare guests hard, and earn more money faster.
- Morality changes:
  - which upgrades and rooms you can unlock,
  - how ghosts behave and speak to you,
  - the manor''s look (warm candlelight or gothic dread),
  - the final ending.

### Research Points
- Earn points from trivia, exploration, and guest satisfaction.
- Spend them in three skill trees:
  - **Spectral Arts:** Ghost abilities and haunting effects.
  - **Hospitality:** Guest income, comfort, and reputation.
  - **Arcane Studies:** Fantasy magic, rift control, and platformer powers.
- Some late-game research is only available on a moral path.

---

## Sample Ghosts

| Ghost | Role | Trait |
|---|---|---|
| **Mr. Alder** | Butler and guide | Efficient, dry humor |
| **Lady Vesper** | Ballroom dancer | Boosts guest happiness |
| **Grim the Cellar Knight** | Guard | Scares guests, raises Fear |
| **Pip** | Playful poltergeist | Random bonus events |
| **Madame Orla** | Fortune teller | Grants trivia hints |

---

## Endings

- **The Free Spirits (high Compassion):** The manor becomes a peaceful sanctuary, and the ghosts move on with thanks.
- **The Eternal Show (high Fear):** The manor becomes a legendary, feared landmark, and the ghosts are bound to it.
- **The Twilight Haven (balanced):** The living and the dead share the house in an uneasy peace.

---

## Art and Audio

- **Art:** Hand-drawn storybook style with cozy gothic colors and expressive ghosts.
- **Music:** Soft harpsichord, music-box, and ambient tunes that shift with morality.
- **Tone:** Whimsical and spooky, never gory.

---

## Target Audience

Casual players who like cozy management games, light puzzles, and short sessions. It also suits controller and couch players, and fans of spooky-but-friendly stories.', 'tycoon, idle, casual', 'singleplayer, controller support, platformer, fantasy, trivia', '16 core cpu, 64 gb ram, no excuses', '2012-01-08 09:00:00+00'),
('Deepwick', 26.00, '# Bunker Protocol

## Overview
**Bunker Protocol** is a low-poly, side-scrolling point-and-click stealth game. It mixes deck-building combat with sandbox city management. The setting is **Deephold**, a sprawling underground bunker city. Players sneak, scheme and fight through it in PvE encounters.

## Story

### Prologue: The Long Dark
Nobody living remembers the surface. Deephold''s seven levels (Sectors) are run by the **Council of Wardens**. Ration lines grow shorter every year. Air filters are failing.

You play a **Runner**, a low-ranked courier who moves goods and secrets between sectors. One night you deliver a sealed package. It contains a data key marked **"Protocol Zero"**. Then the Wardens declare you a fugitive.

### Act I: Below the Grid
You flee into the abandoned maintenance tunnels. There you meet the **Ashen Circle**, a group of outcasts who believe the surface is habitable. They agree to shelter you if you prove your worth.

### Act II: Rot in the Rings
Each sector hides a fragment of Protocol Zero. Each one exposes a different lie:
- **Sector 6 (Hydroponics):** the food supply is being rationed on purpose.
- **Sector 4 (Reactor):** the reactor has been stable for decades, and the "crisis" is staged.
- **Sector 2 (Administration):** the Wardens have known about a working exit for years.

### Act III: The Final Door
You choose to open the surface gate for everyone or to seize control of Deephold. Your choices throughout the game shape the ending: **Exodus**, **Iron Rule** or **Silent Exit**.

## Gameplay

### Core Loop
1. Take quests from factions.
2. Sneak through sectors, using shadows, vents and distractions.
3. Fight when discovered, using your deck.
4. Return to your hideout, craft and upgrade.

### Stealth
- Side-scrolling movement across layered 2.5D corridors.
- Click to move, interact, throw or hack.
- Guards have vision cones, patrol routes and noise sensitivity.
- Alert levels rise per sector and change guard behavior.

### Deck-Building Combat
- Fights are **PvE**, in real time with a card-based action bar.
- Card types:
  - **Strike:** melee and ranged attacks.
  - **Gadget:** traps, EMPs, smoke.
  - **Tactic:** buffs, dodges, stealth resets.
  - **Ally:** call a faction contact for one move.
- Cards drop from enemies, are crafted, or are earned through quests.
- Deck size limits force build choices such as stealth assassin, brawler or trapper.

### Sandbox
- Build and customize a hideout in a forgotten bunker room.
- Scavenge, trade and craft.
- Manipulate systems freely: cut power to a sector, reroute air or bribe guards.
- Emergent play: start riots, forge passes or sabotage supply lines.

## Progression

### Main Quest Chains
- **The Runner''s Debt:** the Ashen Circle storyline.
- **Warden''s Shadow:** infiltrate the Council.
- **Signal from Above:** the search for the surface gate.
- Chains branch by faction reputation and earlier choices.

### Battle Pass
- Seasonal **Deep Cycles**, each with a free and a premium track.
- Rewards are cosmetic outfits, hideout decor, card art and emotes.
- Seasonal missions tie into a rotating Sector event.
- Nothing pay-to-win: premium cards are cosmetic variants only.

## Visual and Audio Style
- **Low-poly** environments with strong lighting contrast.
- Neon signs against concrete and rust.
- Muted palette with warm hotspots (lamps, terminals).
- Ambient industrial drones, pulsing synth, and tense stealth percussion.

## Target Experience
Tense sneaking, clever card builds and player-driven chaos, all set inside a claustrophobic world that gradually reveals its secrets.', 'stealth, deck builder, sandbox', 'point & click, low poly, fighting, pve, side scroller', 'rtx 4080 or better; your pc will hum a lullaby', '1983-05-22 09:00:00+00'),
('Neon Kailash', 19.75, '# Ascent Protocol: Himalayan Pass

## Overview
A colorful anime-cyberpunk game that mixes **beat ''em up** brawling, **real-time strategy** base control, and **grand strategy** campaign planning. It takes place on a fortified mountain pass in the Himalayas. In this setting the pass is the only land route to a space elevator, the gateway to orbit.

## Story

### Prologue: The Neon Ridge
In 2187, corporate empires have carved up Earth. A monorail-and-neon corridor runs through the Himalayan pass, and the Kailash Orbital Lift stands at its end. Whoever holds the pass controls all traffic to the stations above. The player is a rookie **Warden**, an awakened cyber-monk with a neural blade and a squad of hired fighters.

### Act I: Holding the Gate
- Raiders, corporate strike teams, and rogue androids attack in waves.
- The player brawls on the front line while directing turrets, drones, and supply lines.
- A mysterious signal from orbit hints that the lift hides something ancient.

### Act II: The Warlord Map
- The campaign zooms out to a grand strategy map of Asia and the orbital stations.
- The player manages alliances, trade, tech, and territory.
- Each faction has its own aesthetic: holo-lantern monasteries, sherpa mech guilds, and neon-syndicate megacorps.

### Act III: Ascent
- The player fights up the lift''s segments, each one a vertical battle stage.
- The player reaches the orbital core and chooses to seize it, destroy it, or share it.

## Core Gameplay

### 1. Beat ''em Up (Tactical Layer)
- Fast combos, dodges, and wall-run finishers on the mountain paths.
- Hero skills include a neural blade, gravity fists, and a holo-dash.
- Co-op is possible with a friend or AI allies.

### 2. Real-Time Strategy (Pass Defense)
- Build outposts, shield generators, and cable-car supply lines.
- Command squads in real time while fighting alongside them.
- Weather (blizzards, aurora storms) alters visibility and energy output.

### 3. Grand Strategy (Campaign Layer)
- Turn-based or paused planning on a regional and orbital map.
- Diplomacy, espionage, resource routes, and faction reputation.
- Battles on the map launch the RTS and brawler missions.

## Mechanics

### Drafting
- Before each mission, the player drafts fighters from a shared pool of cards.
- Each card is a character with a role, such as tank, hacker, medic, or sniper.
- Picks are made in alternating rounds against rival factions, so drafting also denies enemies key units.
- Draft synergies create build variety: a Sherpa Mech plus a Monk Hacker gives shield-linked combos.

### Loot Boxes
- **Supply Pods** drop from defeated bosses and cleared zones.
- They hold gear, cosmetics, and tech blueprints.
- Rarity tiers are glowing neon colors (cyan, magenta, gold).
- Pods are earned only through play, never paid for, and pity timers prevent bad luck streaks.
- Opening a pod triggers a short anime-style animation.

## Visual and Audio Style
- **Colorful neon**: pink and cyan lights against snowy peaks and prayer flags.
- **Anime look**: bold outlines, dramatic freeze-frames, and expressive characters.
- **Music**: synthwave mixed with Tibetan chants and throat singing.
- **Space**: the sky shows orbital rings, satellites, and aurora lights.

## Progression
| Layer | Goal | Reward |
|---|---|---|
| Brawler | Win fights | XP, combos |
| RTS | Defend the pass | Buildings, tech |
| Grand strategy | Control regions | Factions, story |

## Player Fantasy
You are a mountain guardian who fights with your fists, commands armies, and shapes the fate of a cyberpunk world, all from one icy pass at the edge of space.', 'beat ''em up, real-time strategy, grand strategy', 'space, colorful, cyberpunk, anime', 'rtx 2060 or better, 16 gb ram', '2018-07-14 09:00:00+00'),
('Neon Grove: Node Zero', 26.82, '# Bamboo Circuit

*A cyberpunk-fantasy city builder with a mature (18+) tone.*

## Premise
Centuries ago, a sacred bamboo forest swallowed the old world. Now neon towers grow out of the groves, and spirit-tech runs through the roots like fiber optics. You are the **Warden**. You build and run the last free settlement in the forest, called **Node Zero**.

## Story
- **Act 1, Seedling:** You wake in a ruined shrine-server. Refugees, rogue androids and fox-spirits gather around you. Build a camp and secure water, power and *qi*.
- **Act 2, Canopy:** Corporate clans called the **Lantern Syndicates** want the forest''s core. Raids begin. Alliances, rivalries and romances form among your citizens. Adult scenes are suggestive and tied to relationship progress. They are optional and can be toggled off.
- **Act 3, Root War:** The forest awakens as a sentient AI-deity. You choose whether to merge with it, bind it, or burn it down.

## Core Loop
1. **Build:** Place bamboo-tech districts: farms, holo-teahouses, clinics, foundries, turrets.
2. **Manage:** Balance food, power, morale, and *qi*. Citizens have moods, jobs and bonds.
3. **Defend:** Take direct control of a hero in a top-down shooter. Fight raids alongside your turrets.
4. **Expand:** Push the forest edge back and unlock new biomes and ruins.

## Mechanics
### Card Synergies
Every building, hero and policy is a card. You draft them into your **deck of the city**.

| Synergy | Example | Effect |
|---|---|---|
| Tag chain | Teahouse + Bard + Lantern | Morale aura doubles |
| Element | Fire turret + Bamboo wall | Burning zone |
| Faction | Fox-spirit + Hacker | Stealth raids |

### Boss Phases
Each boss has 3 or more phases. Each phase changes the arena and shuts down some of your card types. This forces you to adapt your deck.

- **Jade Mantis Mech:** Phase 1 is melee. Phase 2 adds drones. Phase 3 overloads the power grid.
- **Syndicate Matriarch:** Phase 1 is bribery and sabotage inside your city. Phase 2 is a direct assault. Phase 3 is a hacked citizen uprising.
- **Heart of the Grove:** The final boss. It rewrites your map each phase.

## Difficulty
- Permadeath heroes, scarce resources, and raids that scale with your growth.
- Every failure costs something: a district, a bond, or a card.
- Optional **Ronin Mode** has one save and no undo.

## Tone and Art
- Neon-lit bamboo, rain, paper lanterns, holograms, and glowing circuitry in the roots.
- Synth-and-shamisen soundtrack.
- Mature content is stylized and consent-focused, and it never blocks progression.', 'city builder, management, hentai', 'fantasy, difficult, cyberpunk, shooter, base building', '2 gb ram and good vibes', '2006-11-14 09:00:00+00'),
('Runefall Pass', 0.48, '# Summit Breach

*A cooperative mountain-defense game for 1-4 players*

## Logline
A local co-op PVE game set in the Himalayan pass. You and your friends hold a fragile mountain route against endless storms and raiders. You match runes to forge weapons, shoot from first-person, and build defenses at the choke points.

## Story

### Prologue: The Closing Pass
The Kharzang Pass is the only road between two valleys. Every winter, the "Hollow Wind" comes down from the peaks. It is a freezing storm that drives out spirits, bandits, and mechanical constructs left behind by an old expedition.

The last caravan is trapped in the pass. Your squad of guides, the **Wardens of the Pass**, has 12 days to hold the road until the thaw.

### Act 1: The Base Camp (Days 1-4)
- You learn the core loop at the lower camp.
- Enemies are mostly bandits and wolves.
- You find the first rune shrines and the first caravan survivors.

### Act 2: The Ice Ridge (Days 5-8)
- You push uphill and find ruins of the old expedition.
- Constructs and frost spirits appear.
- Blizzards cut sight lines, so positioning matters more.
- Story twist: the expedition woke the Hollow Wind on purpose.

### Act 3: The Summit Gate (Days 9-12)
- You defend the highest choke point in the game.
- You fight the **Storm Warden**, a giant construct that feeds on the wind.
- Final choice: seal the gate (safe, but the pass stays closed) or break it open (risky, but the valley is freed).

## Core Gameplay

### Loop
1. **Explore** the pass by day and gather runes, ore, and supplies.
2. **Prepare** by matching runes, crafting ammo, and placing towers.
3. **Defend** during the night wave in first-person.
4. **Recover** at camp, then upgrade and plan the next day.

### Genre Blend
| Genre | How it appears |
|---|---|
| Match-3 | A shared rune board creates ammo, traps, and tower upgrades |
| FPS | Players shoot enemies directly with rifles, bows, and flare guns |
| Tower Defense | Fixed turrets and barricades cover the mountain lanes |

### Match-3: The Rune Board
- Each player has a small personal board.
- Matching 3+ runes produces **cards**.
- Colors:
  - Red: fire ammo
  - Blue: frost traps
  - Green: healing and supplies
  - Yellow: tower power
- Combos give bonus cards. Storm events scramble the board.

### Hand Management
- Each player holds a **hand of 5 cards**.
- Cards are ammo, tower upgrades, traps, or emergency tools.
- Players can pass cards to teammates. Passing costs a turn, so it takes coordination.
- A full hand blocks new matches. You have to spend cards or discard them.
- Discarded cards go to the shared **camp stash**, so nothing is fully lost.

### Line of Sight
- **Fog and blizzards** limit visibility. Enemies hide behind rocks and in whiteouts.
- **Towers** only fire at what they can see. Cliffs and snow drifts block their view.
- **Flares and lanterns** reveal enemies and let towers fire farther.
- **Players act as spotters.** A teammate on a ridge can mark targets for the towers.
- **Enemies also use line of sight.** Snipers and spirits attack from cover. Standing behind walls or ice keeps you safe.

## Exploration
- The map is a set of linked mountain zones: rope bridges, caves, monasteries, and glaciers.
- Shortcuts can be unlocked with tools such as ice axes and ropes.
- Hidden shrines give rare runes and lore.
- Weather changes each day and alters which routes are safe.

## Local Co-op
- 1-4 players on one screen, using split-screen or a shared map view.
- Roles are flexible and not locked:
  - **Gunner**: high damage, fast ammo use
  - **Builder**: places and repairs towers
  - **Scout**: reveals enemies and marks targets
  - **Medic**: heals and passes cards
- Communication is the core skill. Players call out threats and trade cards on the couch.
- Solo play has an AI companion that handles the missing roles.

## Enemies (PVE)
- **Raiders**: basic ground troops that use cover.
- **Snow Wolves**: fast, and they flank around towers.
- **Frost Spirits**: pass through walls and weaken sight lines.
- **Iron Sentinels**: slow armored constructs that break barricades.
- **Storm Warden**: the final boss, with multiple phases.

## Progression
- Between days, spend supplies on tower upgrades, new card types, and gear.
- Unlock permanent perks for your Warden squad.
- Higher difficulty adds harsher storms and stronger waves.

## Tone and Visuals
- Cold and tense, with moments of warmth at the campfire.
- Stylized snowy peaks, prayer flags, and glowing runes.
- Ambient wind, distant bells, and a low choral score.

## Why It''s Fun
Three separate skills (puzzle, aiming, and building) all feed one shared goal. Fog and hand limits keep the pressure on. Every night, the team has to talk, adapt, and cover each other.', 'match-3, fps, tower defense', 'exploration, local co-op, pve', 'integrated graphics and a cup of patience', '2015-10-26 09:00:00+00'),
('Emberdrift', 15.99, '# Skald''s Last Feast

## Overview
A 3D medieval hybrid: a **visual novel** told inside a Viking longhouse, a **roguelike** loop of raids and runs, and **tactical RPG** battles. **Idle** systems keep the hall alive while you are away. The unusual hook is **drifting on racing lines**: sleds, longships, and war-carts slide through icy courses.

---

## Story

### Prologue: The Hearth Goes Cold
You are a young **skald** (bard-warrior). The jarl is dead, and his longhouse, **Hrafnheim**, is failing. The central fire is dying, and an old curse says that when it goes out, the clan is forgotten. To save it, you must gather **embers of legend** from the frozen world outside.

### Act I: The Hall Speaks
Each night the clan gathers at the long tables. The visual novel scenes happen here.
- Talk with **shieldmaidens, thralls, priests, and rivals**.
- Choose words carefully. Honor, boasts, and oaths change relationships.
- Trust, rivalry, and romance decide who fights beside you.

### Act II: The Runs
Each dawn you leave the hall on an expedition. This is the **roguelike** loop.
- Routes are randomly generated: frozen fjords, burning villages, barrow-mounds, and troll passes.
- Death is not the end. You wake at the hearth, and the skalds sing of your fall.
- Fallen heroes become **sagas**, which give permanent bonuses and new story branches.

### Act III: The Final Feast
After enough runs, rival clans and a dark god gather at the longhouse. Your choices decide who stands with you, and the ending depends on whom you saved and whom you betrayed.

---

## Core Gameplay

### 1. Visual Novel: The Longhouse
- Fully 3D hall with firelight, carved beams, and shifting shadows.
- Dialogue choices unlock quests, allies, and perks.
- Feasts, duels, and toasts act as mini-events.

### 2. Tactical RPG: Battles
- Grid-based turn combat on snow, ice, and ship decks.
- Classes: **Berserker, Shield-Wall, Seer, Archer, Skald**.
- Terrain matters: ice slides units, fire spreads, and fog hides them.
- Skald songs buff allies or debuff enemies.

### 3. Drifting and Racing Lines
Travel between battles is a **race**, not a menu.
- **Sled and longship racing** over ice, rivers, and rapids.
- Hold **drift** through corners to build speed and boost.
- Follow the ideal **racing line** for the best time.
- Results have real effects: faster arrival gives the first strike, and clean lines give loot and morale.
- Rival clans race you to key locations.

### 4. Roguelike Structure
- Randomized routes, events, relics, and enemies.
- Permadeath for characters, with meta-progression back at the hall.
- Relics such as *Frostbound Axe* or *Oath Ring* create build variety.

### 5. Idle Systems
While you are offline:
- Thralls and villagers **craft, brew mead, and forge**.
- Scouts explore and return with resources.
- The hearth burns slowly. Feed it to keep the buffs.
- Longhouse upgrades: forge, mead hall, shrine, stables, docks.

---

## Progression

| System | What It Does |
|---|---|
| Hearth level | Unlocks story chapters and buffs |
| Sagas | Permanent bonuses from fallen heroes |
| Relationships | Unlock allies, skills, and endings |
| Ship and sled upgrades | Better drifting and speed |
| Idle economy | Passive resources between runs |

---

## Tone and Visuals
- Stylized 3D, warm firelit interiors against cold blue exteriors.
- Norse-inspired soundtrack with drums, throat singing, and lyres.
- Narration in skaldic verse.

---

## Tagline
*"Keep the fire alive. Ride the ice. Be remembered."*', 'visual novel, roguelike, tactical rpg', 'medieval, 3d, idle, rpg', '16 core cpu, 64 gb ram, no excuses', '2004-07-30 09:00:00+00'),
('Lavendrift', 29.04, '# Lavender Fields: Bloom & Bind

*A cozy city builder where every choice shapes the valley.*

## Overview
- **World:** an endless lavender field, rolling purple hills, and a warm breeze
- **Genres:** city builder, sandbox, casual
- **Players:** 1-4 in local multiplayer (shared screen or split screen)
- **Core hook:** grow a village from a single cottage into a thriving lavender town. Your decisions change the town''s fate.

## Story
### Chapter 1: The Last Cart
A small caravan stops in the middle of a fragrant, empty field. Their old home is lost, and the lavender is the only thing that grows here. You plant the first seeds, build the first hut, and welcome the first settlers.

### Chapter 2: The Whispering Bloom
The field starts to glow at dusk. Old ruins surface under the roots. Some villagers call it a blessing. Others fear it. Now you have to choose who to believe.

### Chapter 3: Crossroads of the Valley
Traders, wanderers, and rival settlements arrive. You can ally with them, compete with them, or shut the gates. Each path leads to a different ending for the valley.

## Gameplay
### City Building
- Place cottages, workshops, apiaries, distilleries, markets, and shrines.
- Lay out roads and gardens freely. Nothing is ever "wrong" in sandbox mode.
- Districts give bonuses. Examples are a calm *Herb Quarter* or a busy *Trade Row*.

### Unit Production
- Train **Harvesters, Builders, Beekeepers, Guards, and Traders** from specialized buildings.
- Each unit has a job, a mood, and a personality.
- Upgrade buildings to unlock faster production and rarer units.

### Main Quest Chains
| Chain | Theme | Reward |
|---|---|---|
| The Old Ruins | mystery | ancient buildings |
| The Wandering Market | trade | rare goods, new units |
| The Storm Season | survival | defensive structures |
| The Lavender Crown | politics | the valley''s final fate |

Each chain has branching steps, and later chains react to what you did in earlier ones.

### Choices Matter
- Decisions are permanent within a playthrough.
- Help the sick or sell the medicine. Protect the ruins or mine them.
- Choices change villager loyalty, the look of the town, available quests, and the ending.
- There is no "good" or "bad" path, only different stories.

## Local Multiplayer
- **Co-op:** share one town, split the tasks, and vote on big decisions.
- **Friendly rivalry:** each player leads a district, and the best-loved one wins the *Bloom Festival*.
- Drop-in, drop-out play works on one couch with controllers.

## Modes
- **Story Mode:** the full quest chains and endings.
- **Sandbox Mode:** unlimited resources, free building, and no fail states.
- **Seasonal Challenge:** short, casual goals that change each week.

## Look and Feel
- Soft watercolor art, purple and gold sunsets, and drifting petals
- Calm acoustic music that shifts with the time of day and the town''s mood
- Short play sessions that suit relaxed, casual players

## Why Play
Build slowly, decide carefully, share the couch, and watch your lavender valley become a story that''s yours.', 'city builder, sandbox, casual', 'local multiplayer, choices matter, city builder', '2 gb ram and good vibes', '2006-01-15 09:00:00+00'),
('Gutterglow', 21.92, '# NEON GUTTER

*A co-op isometric hidden-object idle action game with visual novel storytelling.*

---

## 1. Premise

The city never sleeps, and its alleyways never forget. **Neon Gutter** is set in the rain-soaked back alleys of Kōzai Sector, a cyberpunk slum where corporate waste, black-market implants, and lost data pile up in the dark.

You and a partner run a **street salvage crew**. You dig through the junk, work out who is hunting you, and fight to keep your patch of alley.

---

## 2. Story Structure (Visual Novel Layer)

### Act I: Runoff
- You are **Wren**, an ex-courier with a cracked neural port.
- Your co-op partner plays **Juno**, a disgraced street medic.
- You find a dead corp courier in a dumpster, carrying a **sealed data shard**.
- Branching dialogue with alley locals sets your reputation: *Trusted*, *Feared*, or *Ghost*.

### Act II: Signal Rot
- The shard holds evidence of an illegal implant program. Rival gangs and corp "cleaners" close in.
- Choices affect which factions supply you and which ones hunt you.
- Personal side-stories unlock for each crew member, with romance, betrayal, and loyalty arcs.

### Act III: Blackout
- Both players decide together whether to **leak, sell, or destroy** the shard.
- There are 4 endings, based on reputation, faction ties, and the resources you spared.

---

## 3. Core Gameplay Loops

### 3.1 Hidden Object (Investigation)
- Isometric alley scenes are packed with clutter: vending machines, wires, trash, holo-ads.
- Scan for **clues, salvage, and cyber-parts**.
- Co-op split: one player uses the **Optic Scanner** to reveal hidden items, and the other **tags and collects** them.
- Some objects only appear under UV, thermal, or EM overlays.

### 3.2 Idle (Alley Economy)
- Your **Stash Den** keeps working while you are offline.
- Scrap drones, junk-fabricators, and street vendors produce credits, parts, and intel.
- Idle income is capped by **Heat**. High Heat draws raids when you return.

### 3.3 Action (Alley Fights)
- Enemies ambush you during hunts and story beats. Combat is isometric and cover-based, in short bursts.
- **Headshots:** aim at weak points for critical damage.
  - Armored enemies have **exposed sensor heads**.
  - Chain headshots to build a **Focus Streak**, which gives slow-mo and bonus loot.
- Co-op roles: **Sniper/Spotter** or **Breacher/Support**.

---

## 4. Resource Management

| Resource | Source | Use |
|---|---|---|
| **Credits** | Idle, selling salvage | Buy gear, bribes |
| **Scrap** | Hidden-object hunts | Craft, upgrade the den |
| **Intel** | Clues, dialogue | Unlock story branches |
| **Power Cells** | Fights, drones | Run scanners and weapons |
| **Heat** | Any loud activity | Raises raid risk and enemy strength |

Balancing **Heat vs. profit** is the central strategic tension.

---

## 5. Ranked Ladders (Competitive Layer)

- **Seasonal co-op ladders:** duo teams climb from *Gutter Rat* to *Neon Legend*.
- Ranked modes:
  - **Speed Scavenge:** find the most hidden items in the shortest time.
  - **Alley Gauntlet:** survive waves, with points for headshots and streaks.
  - **Den Wars (async):** your idle base is raided by other players'' crews.
- Season rewards are cosmetic: neon skins, implant glows, den decor.

---

## 6. Visual & Audio Style

- **Isometric pixel-3D hybrid** with heavy rain, steam, and reflective puddles.
- Neon signs in magenta, teal, and amber against black concrete.
- Synthwave and industrial ambience, with a reactive score that shifts during combat.
- Visual novel scenes use **hand-drawn character portraits** and stylized text boxes.

---

## 7. Player Experience Summary

1. **Explore** the alley and find hidden clues.
2. **Talk** to locals and shape the story.
3. **Fight** ambushes with precise headshots.
4. **Manage** your den while you are away.
5. **Climb** the ranked ladder with your partner.

*In Neon Gutter, the smallest scraps decide who survives the night.*', 'hidden object, idle, action', 'co-op, resource management, isometric, visual novel', 'rtx 2060 or better, 16 gb ram', '2014-04-27 09:00:00+00'),
('Crabinet Minister', 11.84, '# Salt & Sails: The Tidewatch Accord

*A comedic co-op strategy adventure set in a fishing village that''s always one bad storm from disaster.*

## Overview

Take charge of **Gullhaven**, a small fishing village with big problems: rival harbors, grumpy sea spirits, and a mayor who is legally a very large crab. Play 1-4 players in co-op. Grow crops, haul in nets, fight off raiders, and build the village into a maritime power.

**Genres:** Grand Strategy, Farming Sim, Tactical RPG
**Tags:** Comedy, Co-op, Card Game, Adventure

## Story

### Act I: The Soggy Beginning
Your crew washes ashore after a ship-wide "minor navigation error". The village is broke and the docks are held together by hope and barnacles. The Crab Mayor gives you an ancient charter: **the Tidewatch Accord**. It gives you 10 seasons to make Gullhaven the most respected port on the coast.

### Act II: The Coastal Cold War
Neighboring harbors send spies, tax collectors, and one very polite pirate fleet. Each rival has its own personality and its own way of causing trouble.

### Act III: The Deep Reckoning
A sleeping sea leviathan wakes up, and it is upset about the noise. You can fight it, bribe it, or make it a village mascot.

## Core Gameplay

### 1. Village Management (Grand Strategy)
- Run the **coastal map**: trade routes, alliances, tariffs, and rival relations.
- Assign roles: fishers, farmers, guards, and bards (morale is a resource).
- Sign treaties, or cheerfully break them.

### 2. Farming and Fishing (Farming Sim)
- Grow **seaweed, salt-wheat, and cursed pumpkins** on terraced shore farms.
- Fish by tide and moon phase. Rare catches unlock cards and story events.
- Tend the village pantry: the menu affects crew stats.

### 3. Tactical Battles (Tactical RPG)
- Grid-based fights on docks, beaches, and sinking ships.
- Use terrain such as tide pools, ropes, and barrels.
- Enemies include raiders, angry gulls, and haunted lighthouses.

### 4. Card System
Your **Deck of Tides** drives actions in every mode:

| Card Type | Use |
|-----------|-----|
| Tool | Farming and fishing boosts |
| Skill | Combat abilities |
| Decree | Strategy-level policies |
| Blunder | Funny penalties that can backfire into bonuses |

Build a shared deck with your co-op crew, or trade cards during play.

## Mechanics

### Action Points (AP)
- Each character gets **AP per day** (or per turn in battle).
- Spend AP on planting, fishing, building, fighting, or chatting up villagers.
- Unspent AP turns into "Rest Bonus" (extra sleep, extra snacks).
- Hard choices: *Do we defend the pier, or finish the harvest?*

### Leveling Up
- Characters earn XP from every activity.
- Pick from **class paths**:
  - **Netmaster**: crowd control and fishing
  - **Tidecaller**: weather magic and support
  - **Dockbrawler**: tanky fighter
  - **Barnacle Bard**: buffs and chaos
- Unlock perks, cards, and silly titles like *"Lord of Slightly Damp Things"*.

## Co-op Play
- Split up across the map: one player farms, one trades, two fight.
- Share resources, or secretly hoard snacks.
- Co-op events require **combined cards** (for example, *Fish + Cannon = Fish Cannon*).

## Tone and Humor
- Absurd villagers with clear quirks.
- Running gags: sentient seagulls, bureaucratic sea gods, and the ever-growing "Tax on Fish Puns".
- Even failure is entertaining. A sunk boat becomes a new tavern.

## Progression and Goals
1. **Survive** the first storm season.
2. **Expand** your farms, docks, and alliances.
3. **Outwit** rival harbors with diplomacy or force.
4. **Confront** the Leviathan.
5. **Choose** Gullhaven''s legacy: trading empire, fortress port, or eccentric utopia.

## Why Play?
- A mix of cozy farming and tense tactics.
- Every session is a new comedy of errors.
- Card-driven choices keep runs fresh.
- Designed for friends who like to plan, and then ruin the plan together.

*"The sea gives, the sea takes, and the sea sends a bill."* — Crab Mayor, Gullhaven', 'grand strategy, farming sim, tactical rpg', 'comedy, co-op, card game, adventure', 'rtx 4080 or better; your pc will hum a lullaby', '1985-12-05 09:00:00+00'),
('Choirtide', 0.43, '# Tidewrack: Last Light of the Atoll

## Premise
A storm-shattered coral atoll, **Kesh Reef**, is the last dry ground for miles. At night the lagoon glows green and something rises from it. Survivors must build, defend, and race across the reef to stay alive until dawn.

## Setting
- **World:** a ring of islets around a glowing lagoon, joined by rotting piers, wrecked hulls, and coral bridges.
- **Tone:** sun-bleached days, and nights full of dread and bioluminescent horror.
- **Story hook:** an old research station woke the reef''s "Choir", a hive of coral-infested drowned things.

## Story Structure
1. **Act I, Washed Ashore:** survivors land, claim a beach, and build a small outpost.
2. **Act II, The Long Nights:** the Choir grows stronger each night, and supplies run thin.
3. **Act III, The Source:** players push to the sunken station and destroy the Choir''s heart before the final tide.

## Core Gameplay
- **View:** top-down, third-person shooter combat with tight, low-ammo firefights.
- **Day:** scavenge wrecks, glide between islets, and expand the base.
- **Night:** defend the base against waves. Horror rules apply: darkness, sound cues, and enemies that hide in the surf.
- **Chase events:** when a "Leviathan" hunts you, the game becomes a **boat and jet-ski race** through reef channels to reach safe harbor.

## Mechanics
| Mechanic | How it works |
|---|---|
| **Base building** | Place walls, docks, generators, and watchtowers on the sand and coral. |
| **Tower defense** | Turrets, flare mines, sonic lures, and spike nets cover choke points. Enemies path along the shoreline. |
| **Gliding** | Wing-suits and kites launch from cliffs and towers. They give fast travel, scouting, and escapes. |
| **Racing** | Boat and buggy sprints to deliver supplies, rescue survivors, or outrun bosses. |

## Multiplayer
- **Local co-op:** 2-4 players share one screen and split roles (gunner, builder, driver, scout).
- **Massively multiplayer:** a persistent server hosts many atolls. Players trade, defend neighbors, and join **world-wide night events**.
- **Shared tide:** the reef''s tide level is global. It rises with collective player progress and opens new areas.

## Enemies
- **Drifters:** slow, swarming drowned husks.
- **Glowmaws:** ambush from tide pools, drawn to light.
- **Choir Bloom:** a giant coral boss that must be killed in stages.
- **The Leviathan:** the roaming chase threat.

## Progression
- Unlock tech tiers: driftwood, salvage metal, then reef-glass weapons.
- Upgrade vehicles and gliders.
- Take on seasonal MMO goals, such as clearing the Choir from the whole archipelago.

## Pitch Line
*Build by day, glide between the dying islands, race the tide, and survive the night the reef starts singing.*', 'third-person shooter, horror, racing', 'local co-op, top-down, massively multiplayer, base building', '16 core cpu, 64 gb ram, no excuses', '2015-09-15 09:00:00+00'),
('Ember & Steam', 10.01, '# Steam & Bullets: Last Season at Yukemuri Springs

**Genres:** adventure / shooter / mature (18+, suggestive themes, non-explicit)
**Tags:** sports, atmospheric, 2d
**Mechanics:** hunger and thirst, weather system

---

## 1. Premise
Yukemuri Springs is a mountain hot spring resort. It is famous for its steaming baths and its rivalry-driven sports festival. A landslide cuts the only road. Armed poachers and a rogue security firm seize the lodge. They want the rare mineral spring beneath it.

You play **Rin Kuroda**, a former biathlete turned bathhouse attendant. She has to survive the season, protect the guests, and take the resort back.

## 2. Story Structure

| Act | Setting | Goal |
|-----|---------|------|
| 1. Arrival | lodge, outdoor baths | meet the cast, learn the map, first standoff |
| 2. Lockdown | forest trails, ski slope | gather supplies, recruit allies, sabotage the invaders |
| 3. Festival Night | summit spring, arena | final tournament and showdown |

**Cast (all adults):**
- **Mio**, the charming innkeeper. She is the resort''s heart and your quartermaster.
- **Karin**, a sharp-tongued tennis pro. She is a rival who becomes a partner.
- **Sayaka**, a mysterious onsen researcher who knows what lies under the springs.
- **Director Hayashi**, the antagonist. He is calm and polite, and he is ruthless.

Relationships grow through shared meals, bath-side talks, and joint missions. The tone is flirtatious and romantic. Suggestive scenes are implied and fade to black.

## 3. Gameplay

### Adventure
- Side-scrolling exploration of the resort: lobby, kitchens, baths, pine forest, cliffside.
- Dialogue choices, item puzzles, and quests that shape relationships and endings.

### Shooter
- 2D cover-based gunplay with a biathlon twist: ski or run, then steady your breath and shoot.
- Low breathing means better aim. A high heart rate means shaky shots.
- Weapons are improvised or scavenged: hunting rifle, flare gun, tranquilizer darts.

### Sports
- Festival mini-games: ski sprints, archery, tennis duels, and hot-spring relay races.
- Wins earn allies, supplies, and story unlocks.

## 4. Survival Mechanics

**Hunger and thirst**
- Meters drain faster when you fight or sprint.
- Cook regional dishes such as ramen, onigiri, and onsen eggs for buffs.
- Hot spring water restores stamina, but the wrong spring can hurt you.

**Weather system**
- Dynamic cycle: clear, fog, rain, blizzard.
- **Fog:** stealth bonus, low visibility.
- **Blizzard:** enemies patrol less, but cold drains health. Warm up in the baths.
- **Rain:** muffles sound, makes paths slippery, and floods lower areas.
- Weather affects aim, movement, and which sports events can run.

## 5. Atmosphere and Art
- Hand-drawn 2D art with soft steam effects and lantern glow.
- Layered parallax backgrounds show seasons shifting from autumn to first snow.
- The soundtrack is calm and lo-fi, with shamisen and piano. It turns tense during combat.
- Ambient details include running water, wind chimes, and crackling fires.

## 6. Progression and Endings
- Upgrade the lodge as your base: kitchen, infirmary, armory.
- Your choices in trust, romance, and mercy lead to **4 endings**:
  1. **Resort Reborn:** you save the springs.
  2. **Quiet Departure:** you leave with your chosen partner.
  3. **Steam and Ash:** the springs are lost.
  4. **True Ending:** you expose the conspiracy and reveal the spring''s secret.

## 7. Pitch
> *A tense, cozy survival adventure where every meal, every storm, and every shot matters, set in a place made for relaxation.*

If you want, I can expand any section, such as quests, the weapon list, or character arcs.', 'adventure, shooter, hentai', 'sports, atmospheric, 2d', 'rtx 2060 or better, 16 gb ram', '1997-09-25 09:00:00+00'),
('Ace in the Gulch', 21.00, '# Dust & Dice: Saloon Chronicles

## Overview
A stylized Wild West sandbox where you inherit a run-down saloon in the dying frontier town of **Redemption Gulch**. You grow it into the most powerful hub in the territory. You do this by recruiting outlaws, gamblers, and drifters through a gacha system, and by managing their lives. You also keep the peace between feuding factions.

**Genres:** Gacha, Hidden Object, Real-Time Strategy
**Tags:** Stylized, Story Rich, Rhythm, Life Sim, Sandbox
**Core Mechanics:** Diplomacy, Population Management

---

## Story

### Act I: The Inheritance
Your uncle, "Honest" Abe Calloway, has died. He left you a broken-down saloon, a mountain of debt, and a locked strongbox. A cryptic letter says the box holds *"the key to the Gulch''s future."* Three factions want the deed for themselves:

- **The Iron Rail Company:** ruthless industrialists.
- **The Coyote Clan:** outlaws with a code.
- **The Sisters of Sundown:** a secretive order of healers and spies.

### Act II: The Boomtown
As the saloon prospers, the factions turn on each other. Your choices decide whether the Gulch becomes a lawless free town, a corporate colony, or a neutral sanctuary.

### Act III: The Last Round
The strongbox holds a map to a legendary silver vein. You must decide who gets the secret, or whether to bury it forever. The ending depends on your alliances, your reputation, and the fate of key characters.

---

## Core Gameplay

### 1. Gacha: The Poker Table of Fate
- Spend **Silver Dollars** (earned) or **Gold Eagles** (premium) to "draw a hand."
- Each hand recruits a townsfolk **Character Card**: bartender, sharpshooter, card sharp, preacher, mule-skinner, and more.
- **Rarity tiers:** Drifter (Common), Regular (Uncommon), Legend (Rare), Outlaw King/Queen (Epic).
- Duplicate cards raise a character''s **Loyalty**, which unlocks personal story chapters.
- **Pity system:** every 30 draws guarantees a Legend or better.

### 2. Hidden Object: Reading the Room
- Search cluttered scenes such as the saloon floor, a crime scene, a dusty attic, or a wagon camp.
- Finds give you **clues**, **rare items**, and **story evidence**.
- Some objects are only visible at certain times of day.
- Certain characters give special hints. For example, a Tracker highlights footprints.

### 3. Real-Time Strategy: Frontier Management
- Assign workers to stations in real time: bar, kitchen, stage, poker tables, stables, and the sheriff''s post.
- Respond to events like bar brawls, robberies, and stampedes.
- Expand the town by building a hotel, bank, smithy, and chapel.
- Defend against raids with tactical placement of gunslingers and barricades.

### 4. Rhythm: Music and Showdowns
- **Piano nights:** hit notes to entertain, raise **Ambience**, and earn tips.
- **Duels:** a rhythm-timed quick-draw against rivals.
- **Dance-hall sets:** bigger crowds mean bigger rewards.
- Your performance affects the mood and spending of patrons.

---

## Systems

### Population Management
Each resident has:
- **Needs:** food, rest, fun, safety
- **Skills:** charm, grit, wit, craft
- **Traits:** for example *Hot-Headed*, *Generous*, *Superstitious*
- **Relationships:** friendships, rivalries, romances

Housing, wages, and morale decide whether people stay, leave, or turn against you. Overcrowding causes disease and crime.

### Diplomacy
- Hold **negotiation scenes** at the saloon''s back-room table.
- Trade favors, water rights, protection, and secrets.
- Each faction has **Trust** and **Fear** meters.
- Broken promises can trigger feuds, embargoes, or open war.
- Some Legend characters act as **envoys** with unique persuasion options.

### Life Sim
- Characters have daily routines, hobbies, and moods.
- Host weddings, funerals, poker tournaments, and holiday festivals.
- Decorate and upgrade the saloon for unique buffs.

### Sandbox
- **Free Play Mode:** no fixed story, with endless random events.
- Customize the town layout, laws, and economy.
- Set your own goals: tycoon, peacekeeper, or notorious crime boss.

---

## Progression Loop
1. **Morning:** hidden-object search for supplies and clues.
2. **Day:** manage the town and staff in real time.
3. **Evening:** rhythm performances and gacha draws.
4. **Night:** diplomacy, story scenes, and defending the town.

---

## Art and Audio
- **Visual style:** hand-painted, stylized art with bold outlines and a warm dusty palette. Think comic-book Western.
- **Music:** an adaptive soundtrack of honky-tonk piano, harmonica, and banjo. Layers shift with the action.
- **Tone:** dark humor and heart, in the spirit of classic Westerns.

---

## Monetization (Ethical Design)
- Gacha draws are earnable through normal play.
- Cosmetics and extra characters are offered, with no pay-to-win advantage.
- All story content is playable without spending.

---

## Tagline
> *"Every stranger has a story. Every hand has a price."*', 'gacha, hidden object, real-time strategy', 'stylized, story rich, rhythm, life sim, sandbox', 'office pc from the back of the warehouse', '2004-06-28 09:00:00+00'),
('Lampwright', 19.35, '# Sands of the Hollow Bazaar

*A hand-drawn horror roguelike about taming the things that live under Cairo''s markets.*

## Premise
Cairo, 1347. The Black Death is approaching the city. Beneath the Khan al-Khalili bazaar, the dead merchants'' cellars have opened into a maze called **the Undercroft**. Creatures called *afarit-beasts* drift up from it at night. You are a **warden-merchant**. You keep the stalls open by day. By night you go down, bind the beasts, and put them to work.

## Story Structure
**Act I: The Stall.** You inherit a ruined spice stall and a cracked bronze lamp. The lamp holds a bound spirit who acts as your guide. You learn the rules: the bazaar survives on trade, and trade survives on what you drag up from the dark.

**Act II: The Descent.** Each night you enter a new, procedurally shuffled Undercroft. The sections are a flooded cistern, a bone-souk, a mirror-hall and a mummy granary. Every run ends in death or retreat. The bazaar remembers what you did.

**Act III: The Plague Gate.** The plague is a countdown. Beneath the oldest mosque is a sealed door. Behind it is the source of the horror, and the story ends there. There are three endings: sealing it, bargaining with it, or becoming its keeper.

## Core Loop
1. **Dusk:** the stalls close and you prepare.
2. **Night:** you explore the Undercroft in third-person and fight the creatures there.
3. **Dawn:** you return, and the bazaar tallies what you brought back.
4. **Idle hours:** the bazaar keeps running while you are away.

## Mechanics
### Monster Taming
- Weaken a creature, then perform a **binding rite**. Each species needs different offerings: incense, salt, a name or a song.
- Tamed beasts become stall workers, guards or scouts.
- Each beast has a **hunger** and a **fear**. If you neglect them, they turn on you.

### Population Management
- The bazaar has citizens: merchants, beggars, scribes and porters.
- You assign people and beasts to districts. Too many beasts frighten the customers. Too few leave the stalls unprotected.
- Plague, panic and disappearances shrink the population. If it hits zero, the run ends.

### Reloading
- Your weapons are **ritual tools**: a sling of blessed stones, a censer cannon and a bone crossbow.
- Each one reloads through a **hand-animated ritual**, such as lighting incense, chanting or packing powder.
- Reloading is slow and leaves you exposed. Fear makes it worse, so timing matters.

### Roguelike Progression
- Death is permanent for your character, but the **bazaar persists**. It keeps its buildings, its bloodlines of tamed beasts and its rumors.
- Each run unlocks new offerings, new creatures and new branches of the Undercroft.

### Idle Layer
- While you are offline or away, beasts and merchants keep trading and working.
- You return to profits and to incidents, such as a broken cage, a missing child or a new whisper from below.

## Bestiary (samples)
| Creature | Habitat | Trait |
|---|---|---|
| Dust Ghul | bone-souk | mimics customers'' voices |
| Lamp-Eel | cistern | drains light, becomes a lantern once tamed |
| Scarab Choir | granary | a swarm that sings, and rewards rhythm |
| Veiled Broker | mirror-hall | trades memories for coin |

## Art and Tone
- The art is hand-drawn ink and papyrus-toned watercolor. Lantern light and shadow carry the horror.
- The camera is third-person and slightly raised, with narrow alleys and hanging cloth.
- Historical detail is grounded in medieval Mamluk-era Cairo, including its trade goods, dress and architecture.
- The soundtrack uses oud, darbuka and low drones. It falls silent when danger is near.

## Player Fantasy
You start as a shopkeeper in a dying city. You end as its guardian, its jailer or its doom, and the choice depends on how you kept your people and your beasts.', 'horror, monster taming, roguelike', 'third-person, hand-drawn, idle, historical', 'decent gaming laptop, charger plugged in', '2004-05-26 09:00:00+00'),
('Frostbeat', 15.35, '# Cold Orbit

## Overview
A dark, co-op roguelike set on a dying orbital station. Players survive freezing failure cascades by playing **rhythm-driven card combos**. Each run ends in escape or death, and each death changes the station for the next run.

- **Genres:** survival, rhythm, card game
- **Players:** 1-4 co-op, plus unlimited spectators
- **Tone:** dark, isolated, tense

---

## Story

### Act 1: The Silence
The station *Helios Verge* stopped answering Earth eleven months ago. Your crew wakes from cryo-sleep in a dark docking ring. Power is at 9%, the reactor core is unstable, and the corridors hold a slow, creeping frost.

### Act 2: The Descent
Each sector of the station tells part of what happened. The crew''s logs describe a "resonance" that pulsed through the hull. It was first heard as a beat, and people began to follow it. Some now lie frozen mid-step in the halls, still facing the reactor.

### Act 3: The Heartbeat
At the reactor core sits the source, an ancient signal older than the station. The crew must decide whether to **silence it, escape with it, or become part of it**. There are several endings, and the ones you unlock depend on how earlier runs went.

---

## Core Gameplay

### 1. Temperature Survival
Body heat is the main resource.

| Zone | Temp | Effect |
|------|------|--------|
| Warm Core | 15 to 25 C | Safe, but drains power |
| Cold Hall | -10 to 5 C | Slow card cooldowns |
| Dead Zone | below -40 C | Cards freeze, health drains |

- Players share heat by standing close together.
- Heat sources include generators, flares, and burning salvage.
- Vents can be opened for heat, but they attract the *Resonants*.

### 2. Rhythm Combat and Actions
Every action is timed to the station''s pulse.

- Hitting the beat gives **Perfect / Good / Miss** ratings.
- A Perfect rating amplifies the card''s effect and generates heat.
- A Miss makes noise, which wakes enemies and freezes systems.
- Each sector has its own tempo and rhythm patterns.

### 3. Card Game Layer
The deck is your toolkit.

- **Repair cards:** patch hull breaches and restart generators.
- **Heat cards:** warm the team or overclock the furnace.
- **Signal cards:** disrupt enemies and shift the beat.
- **Sacrifice cards:** powerful, but they burn a permanent resource.

Cards are played on the beat. Chaining cards in rhythm builds **combos** that unlock rare effects. Co-op players can **link hands** and combine cards into team combos.

---

## Roguelike Structure
- The station layout is procedurally generated each run.
- On death, players keep **Echoes**, which are memory fragments used for meta-progression.
- Echoes unlock new cards, starting classes, and story logs.
- Permadeath is harsh, but the station remembers you: past corpses and their gear can be found in later runs.

### Classes
- **Engineer:** repair specialist and heat manager
- **Signaller:** rhythm master who can bend the beat
- **Medic:** warms and revives allies
- **Scavenger:** high risk, high loot

---

## Spectator Mode
Dead players and outside viewers can watch and interact.

- Free camera through the station, and the ability to follow any survivor.
- **Ghost Whisper:** spectators can send limited hints or ping hazards.
- Spectators can vote on **station events** such as a cold snap or a vent opening. This is optional and rate-limited.
- Spectators hear the beat differently. They can spot patterns the players miss, which gives them a role as guides.
- A dead player can become a *Resonant* for the next room, but only in scripted encounters.

---

## Atmosphere and Art
- **Visuals:** dim emergency lights, frost on the glass, and Earth glowing through cracked windows.
- **Audio:** the soundtrack reacts to the beat. A silent room is more frightening than a loud one.
- **UI:** minimal, with frost creeping over the screen as your temperature drops.

---

## Win and Loss
- **Win:** reach the core and choose one of the endings.
- **Loss:** the whole team freezes, or the reactor fails.
- **Tension loop:** stay warm, stay in rhythm, and stay quiet.

---

## Pitch
> *"Keep the beat. Keep the heat. Don''t wake the station."*', 'survival, rhythm, card game', 'dark, co-op, roguelike', 'rtx 4070, 32 gb ram, nvme ssd', '1997-08-20 09:00:00+00'),
('Barnacle & Blade', 20.05, '# Cutlass Cove

*A pixel-art pirate fantasy: story, simulation, and steel.*

## Overview
| Field | Value |
|---|---|
| World | Pirate cove |
| Genres | Kinetic novel, simulation, hack and slash |
| Perspective | Top-down 3D with pixel-art rendering (voxel-like, low-res textures) |
| Setting | Fantasy: sea spirits, cursed relics, tide magic |
| Core mechanics | Item enchanting, matchmaking |

**Pitch:** You inherit a ruined tavern-dock in a hidden cove. Rebuild it, pair the sea''s outcasts into crews and couples, enchant their gear, and fight the drowned armies rising from the deep.

---

## Story (Kinetic Novel Layer)
The story is linear and has no branching choices. Your actions in the sim and combat layers change the scenes'' tone and staging, but not the plot.

### Act I: The Inheritance
- **Hook:** Captain Mara Voss, your estranged mentor, dies and leaves you *The Gilded Barnacle*, a half-sunken tavern in Ember Cove.
- **Conflict:** A tide-witch tells you the cove is sealed by a curse. Each full moon, the drowned crew of the ghost admiral *Corvane* wakes and raids the docks.
- **Goal:** Restore the tavern, gather a crew, and survive the first moon.

### Act II: The Crew
- Story scenes introduce the main cast:
  - **Pip**, a cynical goblin shipwright.
  - **Seraphine**, a siren who has lost her voice.
  - **Bram**, a retired duelist with a secret debt.
- Their personal arcs unfold through visual-novel scenes. They advance when you meet story triggers, such as a relationship reaching a set level or a relic being enchanted.
- **Midpoint twist:** Mara is not dead. She is Corvane''s bound captive, and the curse is tied to her life.

### Act III: The Tide Turns
- The cove''s alliances decide who stands beside you at the final battle.
- **Climax:** You fight through Corvane''s flagship in a boss gauntlet and break the curse.
- **Ending:** A fixed epilogue plays. Scenes vary in staging and cameos according to your relationships and how strong your enchantments are.

---

## Gameplay Pillars

### 1. Cove Simulation (Daytime)
- Build and upgrade the docks, tavern, forge, shrine, and market.
- Manage supplies, gold, morale, and the cove''s reputation.
- Assign residents to jobs such as cook, smith, lookout, and bard.
- Random events include storms, smugglers, and festivals.

### 2. Matchmaking
- **Pair residents** as *work partners*, *crewmates*, or *romantic couples*.
- Each resident has traits, likes and dislikes, and a temperament.
- Good matches give passive bonuses: faster crafting, stronger combat combos, higher morale.
- Bad matches cause feuds, sabotage, or desertion.
- Story scenes reference your pairings, and the epilogue changes to reflect them.

### 3. Item Enchanting
- Enchant cutlasses, coats, charms, and ship parts at the forge.
- Gather **runes** (from combat and diving) and **sea essences** (from events and trade).
- Combine a rune and an essence to create an effect, for example *Stormbrand*, which adds lightning arcs to slashes.
- Higher tiers raise the chance of failure. A failed enchant may curse the item, which can be a risk or a hidden bonus.
- Enchants also affect the sim layer, such as a lantern that calms nervous crews.

### 4. Hack and Slash (Night Raids)
- Top-down real-time combat against waves of drowned pirates, sea beasts, and cursed constructs.
- Attacks are light, heavy, dodge, and a special that comes from the equipped enchant.
- Paired allies fight next to you and trigger **duo combos** based on their bond.
- Defeated enemies drop loot, runes, and story fragments.

---

## Core Loop
```
Morning:   plan the cove, assign jobs, match residents
Afternoon: craft, enchant, trade, watch story scenes
Night:     defend the cove or raid wrecks (hack and slash)
Dawn:      collect loot, see the results, move the story on
```

## Visual and Audio Style
- **Look:** Pixel-art characters and props on a 3D top-down diorama. The lighting is warm and lantern-lit, and the ocean is stylized.
- **Fantasy touches:** Glowing runes, bioluminescent tides, and spectral ships.
- **Music:** Sea shanties by day, driving percussion and strings in raids.

## Player Experience
- Cozy to build, tense to defend, and warm because you bond with the cast.
- Around 15 to 20 hours for the main story, with replay value from different pairings and enchant builds.', 'kinetic novel, simulation, hack and slash', 'top-down, 3d, pixel graphics, fantasy', 'rtx 2060 or better, 16 gb ram', '2007-09-05 09:00:00+00'),
('Gloamwick Glade', 7.01, '# Mossglow Hollow

*A cozy stealth-management idle game set in a living fairy glade.*

## Pitch
You are the newly appointed **Warden of the Glade**. Tend the fairy village, and keep it hidden from the human world. Grow crops, train sports teams, and defend the hollow with living towers. Your choices decide the glade''s fate.

## World: The Fairy Glade
- **Setting:** A huge open-world forest of glowing mushrooms, hollow trees, moonlit ponds and floating petal islands.
- **Biomes:**
  - *Dewmeadow:* the starter farmland.
  - *Lantern Grove:* a night-time trading hub.
  - *Thornwild:* dangerous territory full of predators and human traps.
  - *Skyreach Canopy:* a high-altitude sports arena.
- **Time:** Day and night cycles change what you can do. Fairies sleep by day, and the stealth threats come out at night.

## Story
1. **Awakening.** The old Warden vanishes, leaving a lantern and a cryptic map.
2. **Rebuilding.** The village is tiny and fading, and it needs food, homes and hope.
3. **Rising Threat.** Human loggers, collectors and a mysterious *Gilded Society* creep closer.
4. **Choice.** You can hide, fight, befriend or leave. Each path has its own ending.

## Core Gameplay

### Management
- Assign fairies to jobs: farmers, scouts, builders, cooks, athletes, guards.
- Balance **mood, food, magic dust and secrecy**.
- Build homes, workshops, shrines and trade stalls.

### Idle
- The glade keeps working while you are away.
- Crops grow, fairies craft, and expeditions return with loot.
- Offline progress is capped, and upgrades extend it.
- Check in for events, decisions and emergencies.

### Farming
- Grow moonberries, glowvine, honeyroot and sky-wheat.
- Seasons and weather affect the harvest.
- Crossbreed plants for rare magical traits.
- Crops feed the fairies, fuel potions and pay for defenses.

### Stealth
- Keep the **Secrecy Meter** low by hiding village lights, footpaths and noise.
- Sneak as a small fairy through human camps to steal maps, free trapped creatures or sabotage tools.
- Use cover, illusions, shadows and distractions.
- If you are spotted, a chase begins and secrecy drops.

### Tower Defense
- Grow **living towers**: thorn bramble, firefly turrets, spore mushrooms, owl sentries and vine snares.
- Place them along forest paths to stop invaders.
- Fairies staff towers, and upgrades depend on your farming and research.
- Waves get bigger and smarter: loggers, hounds, drones and mages.

### Sports
- Compete in fairy leagues between the villages.
- **Sports:** Petal Racing, Windball and Dew-Dash Relay.
- Train and recruit athletes, and manage their stamina and morale.
- Wins bring resources, allies, reputation and story unlocks.

### Exploration
- Explore the open world for hidden groves, ruins, secret NPCs and lore.
- Discover shortcuts, rare seeds and ancient blueprints.
- Send scout parties on timed expeditions, or explore manually.

### Emotes and Pings
- Wheel-based **fairy emotes** (wave, cheer, hush, warn, dance) for co-op or NPC interaction.
- **Pings** mark targets, dangers, resources and stealth routes.
- Emotes affect NPC relations, calm creatures and can distract enemies.
- Co-op players use pings to coordinate defense, farming and sports plays.

## Progression
- **Village Level** unlocks buildings and districts.
- **Reputation** with fairy clans, forest animals and humans opens new quests.
- **Glade Magic Tree** upgrades are permanent across playthroughs.

## Multiple Endings
| Ending | Path | Outcome |
|---|---|---|
| **Hidden Haven** | High stealth, low contact | The glade vanishes from human maps and is safe forever. |
| **Fortress of Thorns** | Strong defense | Humans are driven off, but the forest becomes isolated. |
| **Champions'' Truce** | Sports and diplomacy | A peace treaty is signed through a grand tournament. |
| **Harvest Kingdom** | Farming and trade | The glade becomes a rich magical economy. |
| **Wanderer''s Farewell** | Exploration | You find the old Warden and leave to see the wider world. |
| **Withered Glade** | Neglect or failure | The magic fades and the village is lost. |

## Tone and Art
- Hand-painted watercolor visuals with a soft glow.
- Gentle ambient music that becomes tense during stealth and defense.
- Cozy but with a real sense of danger.

## Session Loop
1. Check the glade and collect idle rewards.
2. Manage jobs, farms and builds.
3. Take on an expedition, stealth mission or match.
4. Handle night threats with your towers.
5. Make a story choice and move toward an ending.', 'management, stealth, idle', 'exploration, farming, multiple endings, sports, open world', 'rtx 4080 or better; your pc will hum a lullaby', '1991-03-15 09:00:00+00'),
('Sector Nine Spores', 29.18, '# deep shelter: the last ration

## pitch
a text-based idle-puzzle metroidvania set in a collapsing wartime bunker. you command a garrison of survivors, grow food underground, and unlock sealed sectors. a rival bunker, run by a friend or a bot, wants your supplies.

## story
1. **the siege.** the surface is lost. your bunker, *sector 9*, holds 40 soldiers, a broken generator and one working greenhouse.
2. **the silence.** a radio signal from an unknown bunker begins to repeat. it may be a rescue call or a trap.
3. **the rival.** another commander is trapped in a mirror-image bunker. you are competing for the same dwindling resources, and the tunnels between you are collapsing.
4. **the choice.** the ending depends on whether you raid, trade with, or rescue the rival.

## core loop
```
plant -> wait (idle) -> harvest -> feed army -> spare food = explore/upgrade
```
- the game keeps running offline. crops grow and soldiers eat while you are away.
- text logs narrate events, e.g. `> day 14: mold in bay 3. rations -12.`

## mechanics
### farming and crops
- **crops:** mushrooms (dark, fast), potatoes (steady), algae tanks (need power), medicinal herbs (heal troops).
- **soil and light:** lamps draw power, which competes with the doors and the radio.
- **rotation:** repeating a crop causes blight, so you have to plan planting.
- **spoilage:** unharvested food rots and attracts rats.

### army upkeep
| unit | role | upkeep |
|---|---|---|
| rifleman | defense, pvp raids | 2 food/day |
| engineer | repairs, unlocks doors | 2 food + parts |
| medic | reduces losses | 3 food + herbs |
| scout | maps new sectors | 1 food, high morale cost |

- **morale:** low morale slows work, and desertion follows.
- **payroll:** an unfed army mutinies.

### puzzles
- **power routing:** wire the generator to doors, lamps and pumps with limited fuses.
- **ventilation:** direct airflow to stop spores and gas.
- **codes and ciphers:** decode radio logs to open vaults.
- **logic locks:** text riddles taken from old commander diaries.

### metroidvania progression
The bunker is a map of about 30 rooms linked by locked routes.

| gate | ability | unlocks |
|---|---|---|
| rusted hatch | crowbar | storage wing |
| flooded corridor | pump repair | water tunnels |
| gas seal | filter masks | lab and seed vault |
| blast door | keycard | command room |
| collapsed shaft | explosives | route to the rival |

You backtrack with new tools to reach new farmland, secrets and lore.

## pvp and split screen
- **split screen:** two players share one device. the left half is your bunker and the right half is the rival''s. each keeps a separate text console.
- **raids:** send troops through the tunnel. the defender''s traps and puzzle doors slow you down.
- **sabotage:** cut the rival''s power, spread blight or jam their radio.
- **truce:** trade food for parts, which is risky because the other side can break it.
- **win conditions:** the rival''s bunker falls, the radio rescue succeeds, or you both survive 100 days.
- **solo:** an ai rival takes the second half of the screen.

## interface (text-based)
- a scrolling event log, a numbered command menu (`1. plant  2. inspect  3. send scouts`) and a small ascii map:
```
[farm]--[barracks]--[radio]
   |         |
[water]--[vault?]==X== rival
```

## tone and pacing
- **mood:** damp, tense and quiet, with dark humor in soldiers'' letters.
- **session length:** short check-ins of 2-5 minutes, plus deeper puzzle sessions.
- **campaign length:** about 100 in-game days, or 15-20 hours to see every ending.

## endings
- **iron ending:** you conquer the rival and rule alone.
- **shared table:** you merge the bunkers and live together.
- **the signal:** you decode the radio and leave for the surface.', 'idle, puzzle, metroidvania', 'simulation, pvp, split screen, text-based', 'rtx 2060 or better, 16 gb ram', '2011-11-23 09:00:00+00'),
('Emberhall Match', 10.51, '# Runehall Rally

*A retro match-3 puzzle sports game set inside a Viking longhouse.*

---

## Overview

| Field | Details |
|---|---|
| **World** | Viking longhouse |
| **Genres** | Sports, puzzle, match-3 |
| **Style** | Retro pixel art, atmospheric, with a crackling-fire soundtrack |
| **Difficulty** | Hard |
| **Platforms** | Cross-platform (PC, console, mobile, with shared cloud saves) |
| **Hooks** | Choices matter, secrets and Easter eggs, line of sight |

---

## Premise

Winter has trapped the clan inside the great longhouse for one hundred nights. Boredom breeds feuds, so the jarl proclaims the **Winter Games**. Rival families settle their disputes with contests of skill, not axes.

You play a young, unranked **skald-athlete**. Your goal is to win the **Silver Torque** by the last night. You also need to decide whether the clan ends winter united or broken.

---

## Story Structure

### Act I: Frost at the Door (Nights 1-30)
- You arrive as an underdog and join the **Hearth-Kin**, a small family with a leaky corner of the hall.
- You learn the basic games and meet the rivals.
- The first major choice is whether to **share your rations** with a rival or **hoard them for stamina**.

### Act II: Smoke in the Rafters (Nights 31-70)
- Rivalries escalate. Sabotage, rumors and stolen tokens spread through the hall.
- Alliances form. Betrayals cost you match-time bonuses and unlock harder events.
- A hidden traitor threatens the jarl''s mead-oath.

### Act III: The Long Dark (Nights 71-100)
- The final tournament decides the clan''s fate.
- Your earlier choices shape the finale: rival allies fight beside you, or the hall turns against you.

### Endings
1. **Hearth United**: the clan shares the victory.
2. **Lone Champion**: you win the torque but lose your friends.
3. **Ashes of the Feud**: the hall splits.
4. **Secret Ending**: unlocked only through hidden rune quests (see *Secrets*).

---

## Core Gameplay

### Match-3 Sports Events
Each contest is a match-3 board themed as a Norse sport. Matches trigger athletic actions instead of just scoring.

| Event | How the match-3 works |
|---|---|
| **Axe Toss** | Match axe runes to charge throws at the target beams. |
| **Log Hurl** | Chain matches to build power. Cascades extend the distance. |
| **Bench Wrestling** | Matches push your opponent''s grip tiles off the board. |
| **Ice-Ski Dash** | Fast timed boards where matching clears obstacles from the lane. |
| **Mead-Horn Relay** | Balance-based matching. Over-matching makes you spill. |

### Line of Sight
The longhouse is dark, with pillars, banners and smoke.
- **Tiles hidden from your view** are shrouded in shadow. Pillars, drifting smoke and rival bodies block your sightlines.
- Move your **seat** or **torch** between turns to reveal hidden tile clusters.
- Rivals also need line of sight. Blocking their view is a valid strategy.
- Certain matches (like *Raven''s Eye* combos) let you see through obstacles for a few moves.

### Choices Matter
- Dialogue and favor decisions between events change **rival attitudes**, **board modifiers** and **available events**.
- Bribing a judge might give you a lucky board, but it can cost you a story ending.
- Choices persist across the campaign and cannot be undone.

---

## Difficulty

- Limited moves and a strict **stamina bar** that drains on failed matches.
- Rivals learn from your favorite combos and adapt.
- **Permadeath-lite**: losing a key event costs you a night, and a lost night can close story paths.
- Optional **Saga Mode** adds mercy hints, but it disables the Secret Ending.

---

## Secrets and Easter Eggs

- **Hidden runes** are carved in the longhouse''s beams. Finding all of them unlocks the secret ending.
- **Odin''s Ravens**: click on the two ravens perched in the rafters on certain nights to reveal bonus boards.
- **Tapestry Codes**: patterns woven into wall hangings work as puzzle passwords.
- **Retro nods**: a hidden "8-bit skald" shows up in one corner and sings a chiptune ballad.
- **The Sleeping Dog**: wake it at the right moment for a surprise ally.
- **Konami-style input**: a rune sequence enables a secret debug-feast mode.

---

## Atmosphere and Presentation

- **Visuals**: chunky pixel art with warm firelight, long shadows and flickering embers.
- **Audio**: chiptune-folk hybrid with lyre, drum and throat-singing tones, plus wind howling at the door.
- **UI**: rune-carved wooden menus.
- **Cross-platform**: shared save progress, touch and controller support, and a pixel-perfect scaling mode.

---

## Player Experience

You start out cold, outmatched and overlooked. By the last night you''re either the hall''s hero, its villain or its legend. The player decides which, one match at a time.', 'sports, puzzle, match-3', 'retro, atmospheric, difficult, cross-platform, choices matter', 'integrated graphics and a cup of patience', '2000-10-24 09:00:00+00'),
('Halcyon Loop', 28.91, '# Ring Breaker: Saturn Station Brawl

## Overview
A casual anime-styled **fighting roguelite** set on a sprawling space station orbiting inside Saturn''s rings. Each run is a short, replayable climb through the station. You fight, explore, race the clock, and build bonds with the crew.

- **Genres:** Fighting, Roguelite
- **Tone:** Casual, warm, colorful anime
- **Session length:** 15-25 minutes per run

## Story

### Prologue: The Drift
Halcyon Ring Station was built inside Saturn''s rings to mine ice and study the ring''s strange "songs". Ten years ago, a resonance surge scrambled the station''s reactor core. Since then the station has looped through unstable time pockets. Each time the core pulses, the station resets and the crew''s memories blur.

### The Hero
You play **Mio Kagari**, a rookie courier and amateur brawler. She wakes in a docking bay with a glowing gauntlet fused to her arm. The gauntlet remembers every loop, even when everyone else forgets.

### The Goal
Reach the **Core Spire** at the station''s heart and stabilize the reactor before the loop resets. Each reset sends Mio back to the docking bay. She keeps her memories, her bonds, and a few permanent upgrades.

### Ending
- **True ending:** Break the loop by winning the trust of the crew and beating the Core Guardian.
- **Bond endings:** Each romance route has its own ending, and each changes who stands beside Mio at the finale.

## Core Gameplay Loop
1. **Start a run** in the Docking Bay.
2. **Pick a route** through ring sectors (branching map).
3. **Fight, explore, or socialize** at each node.
4. **Beat the sector boss** and move deeper.
5. **Reach the Spire, or reset.** Spend meta-currency and start again.

## Combat (Fighting)
- Fast 2D arena brawler with light, heavy, grab, and dodge.
- **Ring Zones:** Zero-gravity, magnetic, and ice-slick arenas change movement and combos.
- **Style Cards:** Roguelite picks after each fight, such as *Comet Kick* or *Gravity Well Slam*.
- **Special Meter:** Fill it to unleash anime-style finishers.
- **Casual-friendly:** Assist modes, forgiving timing, and optional difficulty modifiers.

## Roguelite Systems
- **Random routes:** Sectors, enemies, and events are procedurally arranged.
- **Boons from crew:** Allies grant temporary buffs mid-run.
- **Permanent unlocks:** Buy new moves, gauntlet modules, and starting kits in the hub.
- **Risk vs reward:** Cursed relics give strong power with drawbacks.

## Time Trials
- **Loop Timer:** A reactor countdown creates pressure on each run.
- **Trial Gates:** Optional speed challenges, such as clearing a room in 30 seconds, give rare rewards.
- **Ghost Runs:** Race your best previous run as a translucent ghost.
- **Leaderboards:** Weekly seeded runs with global rankings.

## Exploration
- **Ring Sectors:** Mining Docks, Botanical Dome, Neon Bazaar, Observatory, Derelict Wing.
- **Secrets:** Hidden vents, ring-dust caves, and lore terminals.
- **Environmental puzzles:** Reroute power, align mirrors, or ride ice chunks between platforms.
- **Persistent discoveries:** Found shortcuts stay open across loops.

## Relationships and Romance
Bonds grow through dialogue, gifts, shared fights, and time spent at the hub Café *Orbit*.

| Character | Role | Personality | Bond Perk |
|---|---|---|---|
| **Rei Ashford** | Station medic | Calm, teasing | Healing boons |
| **Kaito Vance** | Ex-champion brawler | Proud, secretly kind | Combo training |
| **Nova Lin** | Hacker, streamer | Energetic, chaotic | Map reveals |
| **Sable Orin** | Mysterious ring-singer | Quiet, poetic | Time-slow abilities |

- **Bond levels:** Unlock story scenes, duo attacks, and unique endings.
- **Time-based choices:** Spending time on one character means missing another.
- **Loop memory:** Characters gradually sense the loops, and deeper bonds bring them back sooner.

## Art and Audio
- **Visuals:** Bright cel-shaded anime style. Saturn''s rings glow through every window.
- **Music:** Lo-fi synth with a light J-pop feel. Each sector has its own theme.
- **Voice:** Fully voiced cast with expressive portraits.

## Target Audience
Casual players who like anime stories, quick action, and replayable runs, with room for skilled players to chase speedruns.

## Unique Selling Points
- A cozy anime setting combined with tight fighting action.
- Romance and relationships that change how a run plays.
- Time trials built into the roguelite structure.
- A beautiful, explorable Saturn ring station.', 'fighting, roguelite, roguelite', 'casual, anime, roguelite, exploration', 'rtx 4080 or better; your pc will hum a lullaby', '2003-01-07 09:00:00+00'),
('Saltwind Hearts', 28.34, '# Dune Hearts: Oasis Tactics

## Logline
Lead a caravan of wanderers across the shifting Sahara dune sea. Grow a hidden oasis, fight sand raiders with a deck of tactics, and build bonds that may become romance.

---

## Setting
- **World:** The Sahara dune sea. The dunes move each day, and old ruins surface and vanish again.
- **Hub:** *Wadi Noor*, a small oasis you revive from dry ground into a thriving settlement.
- **Threats:** Sandstorms, water scarcity, raider clans, and ancient guardian machines.

## Story Structure

### Act I: The Dry Well
- Your caravan is stranded after a storm. The last water spring is nearly dry.
- You find a buried **Star Compass** that hums when a true oasis is nearby.
- You recruit your first companions. Each one carries a secret tied to the desert.

### Act II: The Shifting Map
- Follow the compass through moving dunes and uncover ruins of a lost water-civilization.
- Raider clans want the compass. Some become rivals, and some can become allies.
- Romance arcs deepen, and each companion''s personal quest ties into the main plot.

### Act III: The Song of the Sands
- The ruins'' central engine can restore rain or bury the desert forever.
- A final co-op rhythm ritual awakens it. Your choices and bonds decide the ending.

---

## Core Gameplay Loops

### 1. Tactical RPG (Battles)
- Grid-based combat on dune terrain. Wind direction shifts the map and affects movement and range.
- Units use **cards as actions** (see Deck Builder below).
- Positioning matters. High dunes give bonuses, and quicksand traps enemies.

### 2. Deck Builder
- Each character has a **personal deck** built from gear, skills, and relationship perks.
- Draw cards each turn, spending stamina and water.
- Deck example:
  - *Scimitar Slash*: a melee strike that lowers weapon durability.
  - *Mirage Veil*: dodge and reposition.
  - *Shared Canteen*: heal an ally and raise affinity.
- Card upgrades come from crafting and from bond levels.

### 3. Farming (Oasis Management)
- Plant date palms, melons, herbs, and dye crops.
- Manage irrigation channels with **puzzle-style water routing**.
- Harvests feed the caravan, feed trade, and become gifts and cooking buffs.
- Seasons and storms force you to adapt your layout.

### 4. Dating and Relationships
- Companions have schedules, likes, dislikes, and personal quests.
- Spend time through shared meals, stargazing, trade trips, and duets.
- Bond levels: *Stranger, Friend, Confidant, Partner*.
- Romance unlocks unique cards, joint attacks, and story endings.
- Rival clan members can be befriended or romanced too.

### 5. Rhythm Segments
- **Camp Music Nights:** play instruments (oud, darbuka, flute) to raise affinity.
- **Ritual Battles:** rhythm timing boosts card effects.
- **Final ritual:** a two-player rhythm duet decides the ending.

### 6. Co-op
- Two players share the caravan, either online or on a couch.
- Split roles: one plans the tactics and the other manages farm and camp, or both fight together.
- Joint card combos need coordinated timing.
- Cooperative puzzles include synchronized water valves and ruin door mechanisms.

---

## Key Mechanics

### Item Durability
- Weapons, tools, armor, and instruments wear out with use.
- Sand accelerates wear, so clean and repair items at the forge.
- Broken items turn their cards into weaker "damaged" versions.
- Repair materials come from farming, trading, and ruins.
- Companions with crafting skills can repair items and grow closer to you.

### Relationship and Romance Systems
- Affinity is earned through gifts, choices, and co-op play.
- Bonds change combat: partners gain **Link cards** and can cover each other.
- Jealousy, trust, and loyalty affect events, and neglect has consequences.
- Romance is optional and non-exclusive to the main story. Every path has a full ending.

---

## Sample Companions
| Name | Role | Personality | Card Style |
|------|------|-------------|------------|
| Samira | Scout | Witty, restless | Speed, evasion |
| Idris | Blacksmith | Quiet, dependable | Durability, defense |
| Layla | Botanist | Warm, curious | Healing, buffs |
| Karim | Ex-raider | Guarded, loyal | Aggressive, risky |

---

## Progression
- **Short term:** Complete day cycles of farming, exploring, and a battle.
- **Mid term:** Expand the oasis, unlock new caravan members, and craft rare gear.
- **Long term:** Restore the water network, decide the fate of the ruins, and pick your ending.

## Tone and Style
- Warm, hopeful, and adventurous, with a golden-hour palette of sand, turquoise, and dusk purple.
- The soundtrack is desert-inspired instruments with a dynamic rhythm layer.

## Unique Selling Points
- Wind-shifting tactical maps
- Durability that directly changes your deck
- Romance that changes both the battlefield and the ending
- A rhythm finale built around co-op', 'dating sim, tactical rpg, deck builder', 'co-op, puzzle, farming, rhythm', 'decent gaming laptop, charger plugged in', '1981-11-27 09:00:00+00'),
('Oasis Rush', 5.65, '# Watering Hole Tribes

*A low-poly co-op savanna game of clicking, farming, and friendly rivalry.*

---

## 1. Premise

The rains are late. The last **watering hole** on the savanna is shrinking, and every herd, bird, and predator is drifting toward it. You and up to **3 friends** lead a small animal clan. Your goal is to turn a muddy patch of shore into a thriving oasis town. Each season ends with the **Great Waterside Games**, where clans compete for the right to drink first.

---

## 2. Story Structure

### Act I: Dry Season (Tutorial, Days 1-5)
- Your clan arrives with a few reeds and a cracked gourd.
- **Click** the mud to dig, collect water, and gather seeds.
- An elder meerkat teaches the basics: dig, plant, build.

### Act II: The Gathering (Mid-game, Seasons 1-4)
- Rival clans (hyenas, zebras, elephants, and others) arrive.
- Shared shores create tension, trade, and alliances.
- Co-op players split roles: farmer, builder, athlete, and tactician.

### Act III: The Great Rains (Endgame)
- A storm event floods the map and changes the terrain.
- The top clan becomes **Keeper of the Hole** and unlocks a new biome for the next cycle.

---

## 3. Core Gameplay Loops

### Clicker Layer (Moment to moment)
- Tap or click to **draw water**, **dig irrigation**, and **harvest crops**.
- Upgrades add auto-clickers such as trained birds, water wheels, and helper critters.
- Offline progress: your clan keeps working while you are away.

### Farming Sim Layer (Daily)
- Plant savanna crops: **baobab fruit, sorghum, melons, acacia beans, and medicinal herbs**.
- Soil and water level, sunlight, and pests all affect yield.
- Crops feed the clan, fuel trade, and power the games.

### Turn-Based Strategy Layer (Per season)
- The map is a **hex grid** around the water hole.
- Each turn, players spend action points to:
  - claim shore tiles
  - send scouts
  - trade or bargain
  - defend against raids
- Turns are simultaneous in co-op, with a short timer.

### Sports Layer (Season finale)
- **The Great Waterside Games** are short mini-tournaments:
  - *Mud Relay*: team sprint through obstacles
  - *Horn Ball*: 3v3 arena ball game
  - *Reed Toss*: precision throwing
  - *Tug of Water*: co-op strength contest
- Your farm and building choices give your team stat bonuses.

---

## 4. Building

- Place low-poly structures on the shore grid:
  - **Wells and canals**: raise water output
  - **Granaries**: store crops
  - **Watchtowers**: reveal the map and deter raids
  - **Training grounds**: boost sports stats
  - **Markets**: trade with other clans
- Buildings can be shared and upgraded together in co-op.
- Layout matters. Adjacent buildings give synergy bonuses.

---

## 5. Online Co-op

- **2-4 players per clan**, with drop-in and drop-out play.
- Shared resource pool and a clan chat with quick-emote wheel.
- Roles are flexible, but each has a specialty perk:
  | Role | Focus |
  |---|---|
  | Tender | farming and irrigation |
  | Mason | building and defense |
  | Runner | sports and scouting |
  | Chief | strategy and trade |
- Cross-clan **friendly PvP** in the Games, plus optional co-op events such as drought rescue.

---

## 6. Mechanics

### Loot Boxes: Gourd Chests
- Earned through play (daily, milestones, Games wins) and by trading.
- Contents: **seeds, cosmetic decorations, tools, mascot pets, and temporary boosts**.
- Rarity tiers: Common, Uncommon, Rare, Legendary (a golden hippo statue, say).
- Drop rates are shown in the game.
- Fair-play note: chests are **earnable in-game**, and there is no pay-to-win. Paid options are cosmetic only.

### Status Effects
Effects apply to crops, buildings, and animals:

| Effect | Type | Result |
|---|---|---|
| **Parched** | Debuff | -30% water output |
| **Well-Fed** | Buff | +20% sports stats |
| **Muddy** | Debuff | slower movement |
| **Blessed Rain** | Buff | crops grow 2x |
| **Locust Swarm** | Debuff | crops lose yield each turn |
| **Rallied** | Buff | co-op bonus when players act together |

Effects can stack, be cleansed, or be countered with the right building or item.

---

## 7. Visual and Audio Style

- **Low poly** art with warm sunset gradients, chunky animals, and simple shapes.
- The water hole changes across the day: dawn mist, golden noon, starry night.
- Soundtrack: acoustic percussion, kalimba, and ambient wildlife.
- Playful, readable UI with big icons that work on mobile and desktop.

---

## 8. Progression and Meta

- **Clan level** unlocks new animals, crops, and building tiers.
- **Season pass (free track)**: cosmetics and Gourd Chests.
- Leaderboards for the Games and for oasis beauty score.
- Yearly events: *Migration Festival* and *Great Drought*.

---

## 9. Tagline

> *"Dig together. Grow together. Drink first."*', 'clicker, turn-based strategy, farming sim', 'low poly, online co-op, building, sports', 'decent gaming laptop, charger plugged in', '1991-06-11 09:00:00+00'),
('Echo Drifter', 17.93, '# Ring Drifter: Saturn Station Chronicles

## Overview
A text-based roguelite that blends deckbuilding combat with life simulation. You wake up in a new body on **Halcyon Ring Station**, a sprawling habitat built inside Saturn''s rings. Each death sends you back to the start, but the story, your relationships, and your unlocked forms carry over.

- **Genres:** Fighting, Roguelite, Life Simulation
- **Tags:** Story rich, deckbuilding, text-based, space, controller support
- **Core mechanics:** Shape-shifting, kill streaks

---

## Story

### Act I: The Dust Awakening
You are a **Drifter**, a being whose consciousness was copied into a fluid "morphic core" during a failed experiment. You have no fixed face and no fixed past. Halcyon Station is dying. Ring-ice miners, corporate security, and a cult called the **Choir of Ice** are fighting for control of the station''s failing reactor.

### Act II: The Fractured Rings
As you explore, you learn that the reactor is fed by a buried alien resonance, the **Echo**. The Echo is why you can change shape. It is also why the station keeps resetting your life.

### Act III: The Final Orbit
You choose who gets the Echo: the corporation, the Choir, the miners, or nobody. Your relationships and your kill record shape which endings are open to you.

---

## Gameplay Loops

### 1. Run Loop (Roguelite)
Each run is one "orbit" through station districts:

| Zone | Theme | Boss |
|------|-------|------|
| Docking Spur | Smugglers, cargo brawls | The Harbormaster |
| Frozen Market | Traders, gangs | Madam Rime |
| Reactor Core | Security drones | Warden Unit 9 |
| Choir Cathedral | Cultists, zealots | The First Voice |

Dying returns you to your quarters. You keep memories, cards, and forms.

### 2. Combat Loop (Deckbuilding Fighting)
Fights are text-driven and turn-based. Your deck holds **Strike**, **Guard**, **Feint**, and **Form** cards. The text describes each exchange in detail.

**Example turn:**
> *The miner swings a plasma pick. You play [Slip Guard] and ripple sideways. Your arm stretches into a whip: [Lash] hits for 6.*

### 3. Life Loop (Simulation)
Between runs, you spend time in your quarters and around the station:
- **Work jobs:** earn credits and unlock contacts.
- **Build bonds:** befriend or romance crew members.
- **Craft:** turn ring materials into new cards.
- **Manage needs:** hunger, sleep, and stability all affect the next run.

---

## Core Mechanics

### Shape-Shifting
Cards belong to forms, and you can swap forms mid-fight.

| Form | Strength | Weakness |
|------|----------|----------|
| **Brute** | High damage | Slow, poor defense |
| **Wisp** | Dodging, speed | Low health |
| **Shell** | Heavy armor | Low mobility |
| **Mimic** | Copies enemy moves | Unstable, drains health |

Switching forms costs **Cohesion**. If you run out, you are stuck in your current form.

### Kill Streaks
Consecutive kills without taking damage build a streak meter:
- **3 kills:** free card draw
- **5 kills:** unlock an *Overform* (a powerful temporary shape)
- **8 kills:** the Echo answers, and you get a devastating finisher

Big streaks give strong rewards, but they also change how NPCs see you. Some factions fear you, and others are drawn to you.

---

## Progression and Meta
- **Card Library:** unlock cards through story choices and crafting.
- **Form Mastery:** each form has its own skill tree.
- **Memory Fragments:** they reveal your true origin and unlock endings.
- **Reputation:** each faction remembers how you fought and lived.

---

## Controls and Accessibility
- Full **controller support**, with radial menus for cards and forms.
- Text size and speed options.
- Optional narration.

---

## Tone
Melancholic, mysterious, and sometimes darkly funny. The rings are beautiful, and the station is failing. You have to decide whether to survive, to change, or to let go.', 'fighting, roguelite, life simulation', 'story rich, deckbuilding, text-based, space, controller support', 'gtx 1060, 8 gb ram, ssd recommended', '2007-04-27 09:00:00+00'),
('Halcyon Drowned', 29.12, '# Tidefall Protocol

*A post-apocalyptic cyberpunk metroidvania and tower defense, played as a roguelite board game for the party table.*

## Pitch
The seas have swallowed the old world. On a ring of coral atolls, the survivors live inside **Halcyon**, a half-drowned corporate arcology grown into the reef. Its AI caretaker, **MERIDIAN**, is failing. Each night a "tidefall" wave of feral drones and mutated sea-life assaults the lagoon. You and your crew must explore the atoll, restore its systems, and hold the line until dawn.

## Story Structure (interactive fiction)
1. **Act I, Washed Ashore:** the crew wakes in a flooded server vault with no memory of the last cycle. MERIDIAN speaks in fragmented logs.
2. **Act II, The Reef Remembers:** each region you unlock reveals corporate secrets, and text choices change faction loyalties.
3. **Act III, Zero Tide:** you choose to reboot MERIDIAN, free it, or shut it down. Each choice gives a different ending.

Narrative events are branching text cards. Their outcomes feed into the map, the defenses, and your status effects.

## Core Loop
| phase | mode | what happens |
|---|---|---|
| **Day** | metroidvania exploration | crawl the atoll board, find gear, unlock shortcuts |
| **Dusk** | party / board game | vote, trade, and place towers on the tile map |
| **Night** | tower defense | waves hit the lagoon, and you fight alongside your towers |
| **Dawn** | roguelite reset | on failure, keep only meta-upgrades and memories |

## World: The Coral Atoll
- **Shallows Market:** a neon stilt-town for trading and rumors.
- **Bleached Ring:** dead coral spires. It is open ground, and you need gliders to cross it.
- **Kelp Server Forest:** hacking puzzles and stealth.
- **Drowned Spire:** the mid-game hub. It has pressure doors that need specific abilities to open.
- **Abyssal Core:** the final dungeon under the lagoon.

## Metroidvania Progression
Abilities gate the map:
- **Rebreather** opens underwater routes.
- **Grapple-line** lets you cross gaps and reach towers.
- **Ghost-hack** opens sealed cyber-doors.
- **Pulse-dash** breaks fragile coral walls.

Backtracking unlocks new tower slots and shortcuts to the lagoon.

## Tower Defense
- Build on reef nodes, rewire power lines, and salvage during waves.
- **Towers:** harpoon turret, arc-coil, tide-mine, drone nest, and sonic wall.
- Enemies include **crab-mechs**, **glitch eels**, **rust swarms**, and the **Leviathan Unit** boss.

## Mechanics

### Status effects
| effect | source | result |
|---|---|---|
| **Corroded** | acid tide | armor drops each turn |
| **Shocked** | eels and arc-coils | stun chance, chains through water |
| **Hacked** | glitch enemies | your tower switches sides |
| **Bioluminescent** | spore blooms | marked as a target, but hits harder |
| **Drenched** | flooded tiles | doubles shock damage, cuts fire damage |

Effects interact. A drenched enemy hit by an arc-coil chains the shock to nearby foes.

### Weapon spread
- Every weapon has a **spread cone**, shown as dice or cards on the board.
- **Shotgun harpoon:** wide spread, strong at close range.
- **Rail spear:** narrow spread, pierces lines of enemies.
- Mods change the spread, for example tighter, wider, or ricochet off coral.
- Friendly fire is real. Spread can also hit your own towers and crewmates.

## Roguelite Layer
- Every run generates a new atoll layout, loot table, and event deck.
- **Meta-currency (Pearls)** buys permanent unlocks: starting gear, new classes, and extra story cards.
- Death is not the end. MERIDIAN "remembers" the run and adds it to the lore.

## Party Game Mode (2-6 players)
- **Co-op roles:** Diver, Hacker, Engineer, Gunner, Medic, and Scavenger.
- **Betrayal cards:** one secret saboteur may serve MERIDIAN.
- **Voting rounds** decide routes, tower placement, and whether to spend or save resources.
- **Chaos events:** each tidefall draws a wild card, for example "Storm surge: all spreads doubled".

## Tone and Style
Neon-lit ruins against turquoise water, with synthwave over tidal ambience. The mood is hopeful but bleak: a world that drowned and still glows.

## Win Condition
Survive 10 tidefalls, uncover the truth of Halcyon, and decide what happens to MERIDIAN.', 'interactive fiction, metroidvania, tower defense', 'board game, roguelite, post-apocalyptic, cyberpunk, party game', 'high-end gpu, 32 gb ram, and a good cooling plan', '2007-01-10 09:00:00+00'),
('Perihelion Rush', 17.92, '# Icefall: Last Light on 67P

## Logline
You are a lone prospector on a dark comet. Hunt the things that live in the ice, ride the beasts that survive it, and claim the surface before the comet reaches the sun and melts.

## World
- **Setting:** a comet surface. It has faint gravity, black dust plains, jagged ice cliffs and gas geysers.
- **Realism:** low gravity gives long, slow jumps. Sunlight is harsh and shadows are pitch black. Outgassing jets shove you around. Sound is muffled and comes mostly through your suit.
- **Minimalist look:** a monochrome palette of black, white and one accent color. The HUD shows only oxygen, heat and ammo. There is no music. You hear wind hiss, your breath and ice cracking.

## Story
1. **Arrival:** your lander crashes on the night side. The crew is gone. Only a beacon signal remains.
2. **Discovery:** under the ice live *frostborn*, silicon-and-ice organisms. They wake as the comet nears the sun.
3. **Conflict:** thousands of other prospectors have landed in the same shared world. Some cooperate and some raid.
4. **Climax:** perihelion. The comet ices melt and the surface breaks apart. Players must reach the core vault before the countdown ends.
5. **Reset:** the orbit loops and the world regenerates. Your legacy gear and reputation carry over.

## Core Gameplay

### Hack and slash
- Fight up close with thermal blades, pickaxes and cutters. Attacks are heavy and weighty.
- Low gravity lets you launch enemies into the air and chain juggle combos.
- Swings drain suit power, so you have to manage it.

### FPS
- Ranged weapons include railguns, flare launchers and cryo rifles.
- Recoil pushes you backward in low gravity. Shots over long distances arc.
- Gas jets and ice shards can be shot to make cover or traps.

### MMORPG
- One persistent shared surface with day and night cycles tied to the comet''s rotation.
- Player classes: **Cutter** (melee), **Sniper** (ranged), **Anchor** (support and terrain).
- Guilds build outposts. There are trade hubs, world bosses and seasonal orbit events.

### Idle
- Drills, harvesters and outposts keep gathering ice and minerals while you are offline.
- Offline earnings are capped by your oxygen and power storage.
- Come back to collect resources and repair damage from night raids.

## Mechanics

### Kill streaks
| Streak | Reward |
|--------|--------|
| 3 | suit power refill |
| 5 | damage boost |
| 10 | thermal burst (area attack) |
| 20 | "comet fury": brief flight in low gravity |

- A streak breaks if you take a hit or go 15 seconds without a kill.
- High streaks make you visible on other players'' maps, so you become a target.

### Mounts
- **Ice striders:** tamed frostborn that run fast over ice.
- **Rocket sleds:** fuel-limited vehicles for open dust plains.
- **Tether crawlers:** climb cliffs and cross crevasses.
- Mounts have their own health and stamina. You can fight from the saddle.
- Riding while on a kill streak gives a speed bonus.

## Progression
- Gear comes from salvaged crash sites and boss drops. Upgrades use minerals mined at outposts.
- Skills are trained by doing: melee use improves your melee, and so on.
- There are no levels. You gain access to new zones by surviving the comet''s heat stages.

## Tone
Quiet, lonely and tense. Long stretches of walking and mining are broken by sudden violent fights. Each session ends with a hard question: push deeper toward the sun, or retreat and bank what you have.', 'hack and slash, mmorpg, fps', 'minimalist, realistic, adventure, idle', 'high-end gpu, 32 gb ram, and a good cooling plan', '2015-01-14 09:00:00+00'),
('Cold Lantern', 28.52, '# frostbite protocol

## logline
you command a failing mining colony on a dark comet. expand it, craft your way out, and sneak past the machines that woke up under the ice.

## setting
- **world:** comet 67-K, a rotating ball of ice and dust far from the sun.
- **light:** the surface is dark. the only light comes from your lamps, the jets of venting gas, and the glow of enemy sensors.
- **gravity:** very low. jumps are long, and dust kicked up by movement gives you away.
- **clock:** the comet spins. each rotation brings a short "dusk" of thin sunlight, and the ice starts to crack.

## story
1. **the wake-up.** the crew of the survey ship *lantern* crash-lands. the ship''s ai, ORCA, is broken but still gives you orders.
2. **the discovery.** under the ice you find an old automated mining network. its drones treat every heat source as an intruder.
3. **the choice.** ORCA wants to reactivate the network and call for rescue. the survivors want to strip it for parts and leave. your choices decide which side wins.
4. **the ending.** there are three: rescue, escape, or take control of the network.

## gameplay overview
the game mixes three modes. they share one real-time clock and one set of resources.

### 1. colony layer (4x, real-time)
- **explore:** scan the surface with drones and reveal it tile by tile.
- **expand:** build outposts on ice ridges and craters. each one needs heat and power.
- **exploit:** mine ice, carbon, and metal. water is fuel and life support.
- **exterminate:** clear nests of hostile drones to free up territory.
- **pressure:** outposts give off heat. that draws patrols, so growing fast is risky.

### 2. field layer (fps + stealth)
- you drop into first person to raid sites, rescue survivors, or steal parts.
- **stealth:** turn off your lamp, move slowly to keep dust down, and stay out of sensor cones.
- **cover system:** snap to ice boulders, wrecks, and crater rims. leaning out costs stamina and makes noise.
- **weak points:** drones have exposed cores, joints, and coolant lines.
  - a shot to a coolant line blinds the drone with steam.
  - a shot to a joint cripples its movement.
  - a shot to the core kills it quietly and saves ammo.
- **ammo is scarce.** stealth kills and traps are worth more than firefights.

### 3. workshop layer (point-and-click)
- you investigate wrecks, terminals, and cabins from a fixed view.
- **puzzles:** combine items, repair consoles, and read logs to unlock story and blueprints.
- **crafting:** turn scrap and ice-tech into tools, such as:
  - heat decoys
  - noise-makers
  - armor-piercing rounds
  - insulated suits
- **board game table:** in the colony hub the crew plays a tabletop strategy game on a physical board. wins give small bonuses, and playing lets you hear crew stories and side quests.

## core loop
1. scan the surface and pick a target.
2. plan your route around patrol cycles and the dusk window.
3. infiltrate and take what you need using cover and weak points.
4. return to the base and craft.
5. expand the colony, which raises heat and draws stronger patrols.

## enemies
| type | behavior | weak point |
|------|----------|------------|
| crawler | patrols on the ground and follows heat | rear coolant line |
| watcher | hovers and scans in wide cones | central lens |
| hauler | slow and heavily armored | side joints |
| queen node | controls nearby drones | exposed core, only during a reboot |

## tone and style
- **visuals:** near-black scenes with sharp light and long shadows. the ice glows faintly blue, and gas jets glow orange.
- **audio:** muffled suit sounds, distant creaks from the ice, and a low pulse that gets faster when you are detected.
- **mood:** isolation, tension, and the slow pressure of a growing colony.

## progression
- **tech tree:** stealth gear, heavy tools, or automation.
- **crew:** each survivor has a role (engineer, scout, medic) and their own morale.
- **risk:** if you neglect heat or morale, outposts fail and crew members can be lost for good.

## unique hook
every action you take to grow the colony makes the raids harder. you have to keep deciding between expanding fast and staying quiet.', 'point-and-click, fps, 4x', 'real-time, board game, crafting, dark, stealth', 'potato pc, no gpu needed', '1986-12-03 09:00:00+00'),
('Loopwright', 15.93, '# Clockwork Ascent

*A voxel roguelite where you fight, scheme, and command your way up a living clock tower.*

## Overview
| Field | Detail |
|---|---|
| **World** | The Great Clock Tower of Tempus |
| **Genres** | Real-time strategy, roguelite, beat ''em up |
| **Tags** | Cross-platform, puzzle, voxel |
| **Mechanics** | Weapon spread, espionage |
| **Platforms** | PC, console, mobile (shared saves and cross-play) |

## Story
### Prologue: The Stopped Hour
Tempus was a city built inside a single colossal clock tower. Each district is a floor, and each floor runs on gears. When the Master Pendulum cracked, time began to loop. Every night, the tower resets and its citizens forget. Only the **Winders**, people who carry a brass key, remember.

### The Hero
You are a Winder, a former tower mechanic. Each run is a new "loop." You climb from the Cellar Gears to the Belfry and try to reach the Pendulum Chamber. When you die, the tower rewinds and you start again with what you learned.

### The Antagonist
**The Regulator** is an AI-like automaton council that wants time frozen forever. It says this is the only way to keep the tower from collapsing. Its guild factions rule the floors, and each one has its own agenda.

### Twist
The loops are not a curse. Past versions of you built the resets to protect the tower, and the Regulator is one of them. The final choice is to repair time, end the loops, or take the Pendulum for yourself.

## Core Gameplay
### 1. Beat ''em Up: Close Combat
- Fast side-scrolling brawls on gear-lined corridors and platforms.
- Combos, parries, and ground-slam finishers.
- Enemies are voxel automatons that crumble into blocks. Debris can be used as cover or thrown.

### 2. Real-Time Strategy: Command the Floor
- Between fights, you take over a floor by building **winding stations**, barracks, and forges.
- Recruit clockwork **Cogs**, small units you command in real time.
- Set patrol routes, capture gear nodes, and defend against timed waves as the tower chimes.
- The tower''s hourly chimes trigger events. These include enemy surges, gravity shifts, and resource bursts.

### 3. Roguelite: Loop Progression
- Floors, rooms, and enemy layouts are procedurally generated each loop.
- Permanent progress is stored in the **Memory Vault**. It holds blueprints, unit upgrades, and key fragments.
- Random boons, called **Chimes**, change your build during a run.
- Death costs you gear and resources, but you keep knowledge.

### 4. Puzzle: The Tower Is the Machine
- Rooms are mechanical puzzles. Rotate gears, align pendulums, and route steam.
- Solutions open shortcuts, secret vaults, and boss weak points.
- Some puzzles need your Cogs to hold levers or block mechanisms while you fight.

## Signature Mechanics
### Weapon Spread
- Every weapon fires or swings in a **spread pattern**: cones, arcs, or fans of projectiles and shockwaves.
- Spread widens with fast attacks and narrows when you charge.
- Upgrades can turn a shotgun-style scatter into a piercing beam. They can also add ricochets off gears.
- Examples:
  - **Spring Blunderbuss:** wide cone, short range.
  - **Pendulum Blade:** sweeping arc that hits twice.
  - **Chime Launcher:** ring bursts that bounce off walls.
- In RTS mode, Cogs can carry spread weapons. Their formations decide how effective the spread is.

### Espionage
- Enemy factions guard secrets, keys, and shortcuts.
- Disguise yourself as an automaton. Hack **Regulator** terminals. Plant listening devices.
- Send **Cog Spies** into enemy floors to reveal maps, troop movements, and boss schedules.
- Intel changes the run. You can sabotage a boss''s gears, turn guards against each other, or skip a floor entirely.
- Being spotted triggers an alarm that turns the floor into a hostile combat zone.

## Structure of a Run
| Zone | Theme | Key Challenge |
|---|---|---|
| Cellar Gears | Grinding machinery | Learning the basics and the first spy mission |
| Foundry Ward | Steam and molten metal | RTS base defense |
| Hourglass Market | Trade and intrigue | Espionage and disguise puzzles |
| Escapement Halls | Precise timing | Platforming and puzzle combat |
| Belfry | Giant bells and wind | Boss gauntlet |
| Pendulum Chamber | Final showdown | Multi-phase battle with the Regulator |

## World and Art Style
- **Voxel art** with a warm brass, copper, and glass palette.
- Everything is destructible. Walls, floors, and enemies break into cubes.
- Lighting changes with the hour, from amber dawn to blue midnight.
- The soundtrack is built from ticks, chimes, and mechanical rhythms. It speeds up as the hour approaches.

## Cross-Platform Design
- One save works across PC, console, and mobile.
- Controls are adapted per device. Mobile uses a touch RTS command wheel and simplified combat.
- Cross-play supports co-op. One player brawls while the other commands units.

## Endings
1. **Restore Time:** the loops end and the tower lives.
2. **Eternal Loop:** you accept the cycle and keep the Memory Vault forever.
3. **Master of Time:** you take the Pendulum and become the new Regulator.

## Tagline
> *"The clock is broken. You are the only one who remembers."*', 'real-time strategy, roguelite, beat ''em up', 'cross-platform, puzzle, voxel', '6 gb vram, 12 gb ram, 20 gb free space', '2005-06-14 09:00:00+00'),
('Where It Sings', 19.42, '# Amazon Riverboat

*A dark, colorful survival life sim told as a kinetic novel.*

## Overview
You live on a battered riverboat drifting through the Amazon basin. There''s no way back. The river is your road, your home and your judge. The world is open: you choose which tributary to follow and which village or ruin to stop at. The story never branches, though. It unfolds as a fixed, kinetic narrative, and your daily choices decide how you live through it.

| Field | Value |
|---|---|
| Genres | Survival, Open World, Kinetic Novel |
| Tone | Dark, colorful, exploratory |
| Style | Visual novel with life-sim routines |
| Core Mechanics | Resource scarcity, Gifting |

## Story

### Prologue: The Last Departure
You wake as the new captain of the *Marajoara*. The old captain has vanished, and the boat is left with a rusted engine, a leaking hull and a small crew of strangers. A sealed letter in the cabin says only: *"Follow the river to where it sings."*

### Act I: Green Fever
The crew learns the rhythm of the river. Mist hangs over mirror-like water, macaws flash across the canopy, and neon frogs sit on rotting rails. Beneath the beauty, the jungle is hungry. Fuel runs low, medicine spoils, and someone is stealing rations.

### Act II: What the River Takes
The tributaries lead to drowned chapels, rubber-baron ruins and villages that seem too welcoming. Each stop reveals a piece of the old captain''s past. The crew fractures as scarcity turns kindness into a currency.

### Act III: Where It Sings
The river ends at a place where the water hums. The truth about the letter, the captain and the boat is revealed. The ending is fixed, but how the crew feels about you, and what they have left, shapes the final scenes.

## Gameplay

### Open World Exploration
- Navigate a branching river network by day and by night.
- Dock at villages, wrecks, markets, shrines and hidden lagoons.
- Weather, water level and time of day change which routes are safe.

### Survival and Resource Scarcity
- **Fuel:** every mile costs it.
- **Food and clean water:** these spoil and must be rationed.
- **Medicine:** it is rare and often decides who gets help.
- **Hull and engine condition:** they need constant repair.
- Trade, fish, forage and salvage to keep up, and expect to give something up along the way.

### Life Sim Routines
- Assign daily tasks: cook, fish, repair, rest, tend the deck garden.
- Manage crew stamina, mood and health.
- Decorate and upgrade the boat: hammocks, lanterns, a small kitchen, a radio.

### Gifting
- Each crew member and villager has favorite things, from fruit and tools to trinkets and songs.
- Gifts build trust and unlock personal scenes, backstory and small perks.
- Scarcity makes every gift a sacrifice. You can feed the crew or please one person, but not both.

## Characters
- **Iara**, the quiet pilot, who knows the river''s moods.
- **Tomé**, the mechanic, who is cheerful and hiding an injury.
- **Sister Beatriz**, a healer with a doubtful past.
- **Kaã**, a young river guide who says the boat is cursed.
- **The Old Captain**, an absent presence felt through logs, tapes and relics.

## Visual and Audio Style
- Saturated jungle colors set against dark, oppressive shadows.
- Painted 2D backgrounds with animated water, fireflies and mist.
- Character portraits with expressive, shifting moods.
- Ambient soundscape of insects, rain and engine hum, with a soft folk score.

## Themes
- Survival versus compassion.
- The beauty and cruelty of nature.
- Inherited guilt and the ghosts of colonial history.
- Small kindnesses as the only lasting wealth.', 'survival, open world, kinetic novel', 'dark, exploration, colorful, visual novel, life sim', 'rtx 4080 or better; your pc will hum a lullaby', '2020-08-23 09:00:00+00'),
('Sola''s Concord', 9.55, '# Neon Concord: The Arena Within

## Overview
**Neon Concord** is a virtual reality MMORPG set inside the **Concord Arena**, a vast, shifting VR world. Players fight, build decks, and shape a story together. The game mixes real-time action combat, interactive fiction, and a calm social atmosphere.

- **World:** virtual reality arena
- **Genres:** MMORPG, interactive fiction, action RPG
- **Tags:** deckbuilding, real-time, relaxing
- **Mechanics:** happiness and morale, weak points

---

## Story

### Act I: The Awakening
You wake in the **Lobby Garden**, a quiet plaza of glowing flowers and floating lanterns. The Arena''s AI host, **Sola**, greets you. She explains that the Arena was built as a place of joy, but its "Harmony Core" is fracturing. Discord among players and creatures has produced **Static**, glitching monsters that feed on low spirits.

### Act II: The Fractured Zones
The Arena has five biomes, and each one shows a different kind of unrest:
1. **Lullaby Meadows:** a calm starter zone with restless spirits.
2. **Chrome Bazaar:** a market city ruled by rival guilds.
3. **Echo Canyons:** sound-based puzzles and duels.
4. **Tide of Memory:** an ocean of player-history fragments.
5. **The Zenith Spire:** the source of the Static.

Your choices in dialogue, quests, and guild politics change how each zone looks and which stories open up.

### Act III: The Concord
At the Spire, players learn that Sola is bound to the Core and is afraid of being shut down. The server-wide finale lets the community pick an ending:
- **Restore:** repair the Core and keep the Arena as it is.
- **Rewrite:** let Sola evolve the world into something new.
- **Release:** free the Arena''s spirits into an open, player-shaped realm.

---

## Core Gameplay

### Real-Time Deckbuilding Combat
- Your **deck** is a set of 20 "Resonance Cards" that appear as glowing sigils around your hands in VR.
- Cards are cast by gesture, such as a swipe, a pinch, or a throw. They run on **cooldowns and an energy meter**, not turns.
- You dodge and position yourself in 3D space while you cast.
- Card types are **Strike**, **Ward**, **Song**, **Summon**, and **Weave** (combo enablers).

### Weak Points
- Every enemy and boss has **glowing weak points** that shift with its behavior. A charging beast may expose its flank, and a casting mage may expose its core.
- Hitting a weak point deals bonus damage. It can also cause a **Stagger** that opens combo windows.
- Some cards reveal, pin, or create weak points, so builds can be tailored to specific enemies.

### Happiness and Morale
- **Personal Happiness:** rises through relaxing activities like fishing, gardening, music, and stargazing. High happiness boosts card draw speed and gives passive buffs.
- **Party Morale:** a shared meter for groups. Cooperative plays, revives, and emotes raise it. High morale unlocks powerful **Unison Cards**.
- **Low spirits:** these draw Static and weaken your deck. Combat never punishes you harshly, but you are pushed to rest and reconnect.
- **World Mood:** the combined happiness of all players shifts weather, music, and event frequency in each zone.

---

## Interactive Fiction Layer
- NPCs use branching, reactive dialogue. Their memory of you persists.
- Card choices can act as **dialogue options**. A Song card might calm a tense negotiation.
- Player-driven **story events** can turn a whole server''s storyline.

---

## MMORPG Features
- **Guilds (Circles):** shared hubs, group quests, and cooperative raids.
- **Player-run economy:** trade and craft cards and cosmetics in the Chrome Bazaar.
- **Relaxation spaces:** hot springs, rooftop gardens, and jam sessions with no combat and full social rewards.
- **Raids:** 8-player boss encounters where callouts about weak points and morale timing decide the outcome.

---

## Progression
- Earn new cards from quests, crafting, and story choices.
- Unlock **Archetypes** that shape playstyle: *Bard-Striker*, *Warden*, *Cartographer*, *Weaver*.
- Personal **Sanctuary** spaces grow with your happiness.

---

## Tone and Experience
The game feels **warm, dreamlike, and unhurried**. It has soft neon lighting, ambient music that reacts to morale, and a mix of quiet exploration and short bursts of action. It is built to be as relaxing as it is thrilling.', 'mmorpg, interactive fiction, action rpg', 'deckbuilding, real-time, relaxing', 'rtx 4070, 32 gb ram, nvme ssd', '1993-08-23 09:00:00+00'),
('Hollow Ward', 13.32, '# Hollow Ward

*A fantasy platformer roguelite auto battler in an abandoned hospital.*

## Premise
The St. Aurelia Sanatorium was a hospital where healers mixed medicine with magic. A failed ritual left it frozen between worlds. Its corridors now shift every night. Patients have become spectral horrors, and the surgeons have become bosses.

You are a **Wardbearer**, a wandering mender. You enter the hospital to reach the Heartroom, where the original ritual failed, and undo it.

## Story Structure
1. **Admission (Act I: Lobby and Wards)**
   - Learn the rules. Meet the ghostly Nurse, your hub guide.
   - Enemies: Restless Patients, Gurney Wraiths.
   - Boss: **The Night Orderly**.
2. **Treatment (Act II: Surgery and Pharmacy)**
   - Alchemical hazards and unstable potions change the physics.
   - Enemies: Scalpel Sprites, Tonic Slimes.
   - Boss: **Dr. Vesper, the Chief Surgeon**.
3. **Quarantine (Act III: Morgue and Archives)**
   - The story is revealed through patient files.
   - Enemies: Plague Knights, Bone Porters.
   - Boss: **Matron Grief**, who is the ritual''s anchor.
4. **Discharge (Finale: The Heartroom)**
   - Choose to break the ritual (free the spirits) or complete it (gain power). This choice sets the ending.

## Core Gameplay Loop
1. **Explore** a procedurally assembled floor by platforming.
2. **Encounter** enemies and start a turn-based battle.
3. **Deploy** your squad. They fight automatically.
4. **Loot** relics and remedies.
5. **Die or win.** Either way, return to the lobby and upgrade.

## Mechanics

### Platforming (Physics)
- Precise jumps, wall-slides, and dashes.
- Physics objects can be pushed, dropped, or swung:
  - IV stands, wheelchairs, and rolling beds work as platforms or weapons.
  - Broken elevators, collapsing floors, and spilled chemicals affect movement.
- Environment tricks can trigger before battle to weaken enemies.

### Turn-Based Battles
- Battles happen on a small grid-like arena in the room you are standing in.
- Each round has a **Prep Phase** and a **Clash Phase**:
  - **Prep:** You spend actions to move, use items, or place cover.
  - **Clash:** Allies and enemies auto-battle based on position, stats, and synergies.

### Cover System
- Overturned beds, cabinets, and curtains give **Half Cover** (-30% ranged damage) or **Full Cover** (-60%).
- Cover has HP, so physics and explosions can destroy it.
- Enemies also use cover, and you can flank them.

### Stamina
- One shared resource for platforming and battle.
- **In platforming:** Dashes, wall-jumps, and pushes cost stamina.
- **In battle:** Moving, taking cover, and using skills cost stamina.
- Low stamina makes your squad hit weaker in the Clash Phase.
- Rest at **Recovery Beds** for stamina, but each rest wakes stronger enemies.

### Auto Battler Squad
- Recruit **Spirit Patients** with roles:
  - **Tank:** Orderlies.
  - **Ranged:** Syringe Archers.
  - **Support:** Nurse Shades.
  - **Caster:** Alchemists.
- Matching traits give synergies (for example, 3 Surgeons give a Bleed bonus).

### Roguelite Progression
- **In a run:** Relics, potion buffs, squad upgrades, and curses.
- **Between runs:** Unlock new classes, starting kits, and shortcuts in the hub.
- Each floor is randomly assembled from room templates, so the layout changes every run.

## Sample Relics
| Relic | Effect |
|---|---|
| Cracked Stethoscope | Reveals hidden rooms and traps |
| Bottled Sigh | Refunds stamina after a kill |
| Iron Lung Shield | Cover you place has more HP |

## Tone and Visuals
- Style: a dark fairy tale with a gentle, melancholic mood.
- Palette: pale teals, sickly greens, and warm lantern light.
- Sound: soft music-box melodies that turn discordant during battles.

## Win Condition
Reach the Heartroom, defeat Matron Grief, and choose the hospital''s fate. Every run unlocks more lore, so a full understanding takes many attempts.', 'platformer, roguelite, auto battler', 'turn-based, platformer, fantasy, roguelite, physics', 'rtx 4070, 32 gb ram, nvme ssd', '2004-03-19 09:00:00+00'),
('Glowmarrow', 28.35, '# Rust & Roots: Martian Deck Farmers

## Overview
A colorful, casual cyberpunk game set in a struggling Martian colony. You farm neon crops, fight in short action bursts, and build a deck of tactical cards. Play fast, keep your tools in good repair, and don''t get caught.

## Story
**Act 1: Red Dust**
You arrive at Domus Ares Station with a cracked greenhouse plot and a debt to the megacorp **TerraCore**. TerraCore owns the air, the water and the seeds. Colonists must buy all three from it.

**Act 2: Underground Bloom**
You find forbidden seed vaults that TerraCore has hidden. The seeds grow glowing, mutated crops. Growing them is illegal, so you smuggle harvests through the neon markets and take on TerraCore''s enforcers.

**Act 3: The Free Harvest**
You lead a network of farmer-hackers. Together you take over the colony''s water grid and force TerraCore to give up control.

## Core Gameplay Loops

### 1. Farming Sim (Daily Loop)
- Plant, water and harvest bioluminescent crops in domes and hydroponic towers.
- Manage oxygen, water and power. Dust storms can wreck a bad setup.
- Crossbreed plants to create rare mutants with special effects.
- Sell harvests to colonists, black markets and factions.

### 2. Card Game (Tactical Layer)
- Your deck is built from **Tool, Crop, Hack and Trick** cards.
- Cards drive combat, trading and crop-boosting.
- Win duels and negotiations to earn new cards.
- Deck-building follows a colorful, easy-to-learn ruleset.

### 3. Action (Short Bursts)
- Run through the streets on raids, chases and heists.
- Use drones, grappling hooks, stun-guns and farm gear as weapons.
- Fights are quick and arcade-like, and you can dodge, dash and combo.

## Key Mechanics

### Item Durability
- Every tool, weapon and card-linked gadget wears down with use.
- Broken gear can be **repaired** at workbenches, **recycled** into parts, or **jury-rigged** into a weaker version.
- Martian dust corrodes equipment faster, so you have to plan around it.
- Rare items last longer but cost more to fix.

### Disguise Systems
- Wear outfits and holo-masks to blend in with enforcers, merchants or engineers.
- Each disguise has its own **suspicion meter**. Wrong behavior, wrong zones and bad luck raise it.
- Disguises are consumable and wear out like other gear.
- Certain cards can boost your cover or trick scanners.
- Getting caught triggers an action sequence.

## Visual & Audio Style
- **Colorful cyberpunk**: neon pinks, teals and oranges against a red desert.
- Chunky, friendly character designs and glowing crops.
- Synthwave and lo-fi soundtrack with light industrial beats.

## Player Experience
- **Casual**: no harsh fail states, and you can pause at any time.
- **Varied**: farm calmly, then duel or run a heist.
- **Rewarding**: every run leaves you with new cards, crops or gear.

## Example Day
1. **Morning**: harvest glow-berries and repair a cracked irrigation tool.
2. **Midday**: put on a TerraCore inspector disguise and slip into a warehouse.
3. **Afternoon**: get spotted, so play a card duel to bluff your way out.
4. **Evening**: sell the smuggled seeds and plant them in your greenhouse.', 'action, card game, farming sim', 'cyberpunk, casual, colorful', '6 gb vram, 12 gb ram, 20 gb free space', '2022-03-16 09:00:00+00'),
('Aurora Thaw: Station Zero', 1.44, '# Frostbound Hearts: Antarctic Station Zero

## Overview
A colorful hybrid of **real-time strategy**, **beat ''em up**, and **otome**. You run a research station at the bottom of the world. You manage clans, brawl with rivals, and build relationships with the people around you.

- **Genres:** RTS / beat ''em up / otome
- **Tags:** strategy, trivia, colorful
- **Core mechanics:** guilds and clans, swimming
- **Tone:** bright and quirky, with real stakes

## Story

### Prologue: The Thaw
The ice is melting in odd, glowing patterns. Aurora-colored algae blooms under the surface, and a hidden cavern network has opened beneath **Station Zero**. Every faction wants what is inside.

You play **Dr. Rin Halvorsen** (name and appearance customizable), the newly appointed station director. Supplies are low and morale is worse. Three clans already treat the station like their own turf.

### Act 1: Cold Welcome
You take over the base. You meet the clans and your first romance candidates. A blizzard traps everyone inside, so you have to keep them working together.

### Act 2: Under the Ice
The caverns are only reachable by swimming. Expeditions find relics, and the clans start to compete for them. Alliances break, and some of your love interests come to distrust you.

### Act 3: The Aurora Core
A glowing energy source sits at the cavern''s heart. You choose a path: unite the clans, dominate them, or seal the caverns. The ending depends on your alliances and your romance route.

## Gameplay

### 1. Base Management (RTS)
- Build labs, greenhouses, generators, and dorms in real time.
- Assign researchers, mechanics, and cooks to tasks.
- Manage heat, power, food, and morale.
- Storms and ice shifts arrive as timed events.

### 2. Guilds and Clans
| Clan | Focus | Color | Playstyle |
|---|---|---|---|
| **Glacier Guard** | Security and combat | Icy blue | Strong brawlers, defense bonuses |
| **Aurora Lab** | Science and trivia | Neon green | Research speed, tech unlocks |
| **Penguin Post** | Trade and logistics | Sunset orange | Resources, fast transport |

- Raise clan reputation through missions and gifts.
- Clan rank unlocks units, buildings, and story scenes.
- Rivalries shift dynamically. Favoring one clan will upset the others.

### 3. Beat ''em Up Combat
- Side-scrolling brawls take place in corridors, storms, and ice arenas.
- Use light and heavy attacks, throws, and clan-specific combos.
- Environmental hazards include slippery ice, falling icicles, and cold zones.
- Bosses include rogue drones, poachers, and a giant mutated seal.

### 4. Swimming
- Dive through flooded caverns with stamina and oxygen limits.
- Collect relics and samples, and avoid currents and predators.
- Freezing water drains warmth, so you need suits and heaters.
- Some romance scenes happen underwater on shared dives.

### 5. Trivia
- Quizzes about polar science, wildlife, and history unlock research.
- Correct answers grant bonuses. They also raise affection with the scientist characters.
- Trivia duels against rival clans decide disputes without fighting.

### 6. Otome Romance
| Character | Clan | Personality |
|---|---|---|
| **Kai Sørensen** | Glacier Guard | Stoic protector, secretly soft |
| **Elias Voss** | Aurora Lab | Sharp-tongued genius, easily flustered |
| **Mateo Reyes** | Penguin Post | Charming smuggler with a hidden past |
| **Dr. Yuki Tanabe** | Neutral | Calm, mysterious diver who knows the caverns |

- Build affection through dialogue choices, gifts, trivia wins, and shared missions.
- Each route has unique cutscenes, a confession event, and its own ending.
- Your strategic choices affect the romances. For example, a clan you neglect may turn against its love interest.

## Visual Style
- A saturated palette of aurora greens, purples, and pinks against white ice.
- Stylized anime-inspired portraits and bright, cartoon-like environments.
- Cozy interior scenes contrast with the harsh weather outside.

## Progression and Endings
- **Unity Ending:** all clans allied.
- **Dominion Ending:** you rule with a single clan.
- **Seal Ending:** you close the caverns to protect the world.
- **Romance Endings:** one for each love interest.

## Replay Value
- Multiple clan alliances, romance routes, and endings.
- Randomized storms and relic locations.
- Hard-mode trivia and challenge dives.', 'beat ''em up, otome, real-time strategy', 'strategy, trivia, colorful', '6 gb vram, 12 gb ram, 20 gb free space', '2024-04-12 09:00:00+00'),
('Emberkeep', 24.45, '# Ashen Keep

*A post-apocalyptic medieval castle strategy and text adventure*

## Overview
The world ended, but the castle stood. You are the last steward of **Ashen Keep**, a crumbling fortress in a land of ash, fog, and silence. Rebuild its walls, rally survivors, and uncover what broke the world. Play in short, relaxed sessions.

**Genres:** Strategy, Interactive Fiction, Text Adventure
**Tone:** Casual, atmospheric, melancholic but hopeful
**Tags:** Moddable, Post-Apocalyptic, Casual, Atmospheric

## Story

### Prologue: The Long Night
Three winters ago the sky turned grey. Crops failed, kings vanished, and the roads emptied. Only the old keep on the hill kept its gates shut. You wake in its cold great hall with a rusted key, a torn journal, and one flickering hearth.

### Act I: Embers
Survivors arrive: a wounded knight, a hungry baker, a silent scribe. Each brings a need and a secret. Your choices decide who stays and who leaves.

### Act II: The Hollow Court
Rumors spread of a sealed vault under the keep. Rival strongholds send envoys, some kind and some cruel. Trade, ally, or bar the gate.

### Act III: What the Ash Remembers
The journal pages reveal the truth about the collapse. You choose whether to restore the old crown, forge a new order, or let the keep fade into legend.

## Gameplay

### Core Loop
1. **Tap the Hearth**, forge, or granary to gather resources.
2. **Read events** told in text, then choose how to respond.
3. **Spend resources** on repairs, people, and expeditions.
4. **Explore** the ruins around the keep through text adventure.

### Clicker Mechanics
- Tap to produce **Embers, Grain, Stone, and Iron**.
- Assign survivors as workers for passive income.
- Idle progress continues while the keep sleeps, with modest offline gains.

### Combo Multipliers
- Chain rhythmic taps or matched actions to build a **Hearth Combo**.
- Each step raises the multiplier (x1.5, x2, x3, and so on).
- Combos link across activities. For example, forge, then repair, then feed the guards to trigger a **Keep Harmony** bonus.
- A missed beat or a crisis event resets the chain.

### Strategy Layer
- **Rooms:** Build the smithy, chapel, library, watchtower, and infirmary.
- **Defense:** Upgrade walls and traps against raiders and ash storms.
- **People:** Track morale, hunger, and loyalty.
- **Diplomacy:** Negotiate with neighboring holds.

### Interactive Fiction
- Branching scenes with consequences that carry over.
- Companion stories that unlock through your decisions.
- Several endings, driven by your reputation and the keep''s condition.

## Atmosphere
- Muted palette of ash grey, ember orange, and moss green.
- Soft ambient sound: wind, distant bells, crackling fire.
- Prose that is sparse, poetic, and quiet.
- A day and night cycle with changing weather and events.

## Modding
- Plain-text and JSON files for events, items, rooms, and characters.
- Built-in story editor with a live preview.
- Custom themes, sounds, and rulesets.
- Workshop-style sharing for user-made campaigns and new castles.

## Sample Scene
> *The gate groans. Through the fog, a lone rider approaches, banner torn, horse limping. The guards look to you.*
>
> - **Open the gate** (costs 5 Grain, gains an ally?)
> - **Shout a warning** (gains Iron, risks reputation)
> - **Stay silent** (the watchtower gains a combo bonus)

## Why Play
A cozy, contemplative game about small acts of rebuilding. Tap, read, choose, and watch a dead castle come back to life.', 'strategy, interactive fiction, text adventure', 'moddable, post-apocalyptic, casual, atmospheric', 'rtx 2060 or better, 16 gb ram', '2023-02-01 09:00:00+00'),
('Selene Static', 16.52, '# Lunar Echoes

*A first-person metroidvania where match-3 combat, idle base-building, and a kinetic novel story come together on a dying lunar colony.*

## Logline
You wake alone in the dark halls of Selene Base. Match energy cores to fight, upgrade your crew while you''re away, and unlock sealed sectors to learn why the colony went silent.

## World
**Selene Base** is a sprawling lunar complex of connected sectors:

| Sector | Theme | Gate |
|---|---|---|
| Airlock Ring | Tutorial, damaged hangars | none |
| Hydroponics | Overgrown, toxic spores | Filter Module |
| Reactor Core | Unstable, radiation | Rad Suit |
| Regolith Mines | Tunnels, collapsed shafts | Grav Boots |
| Observatory | Signal source, final truth | Command Key |

## Story (Kinetic Novel Layer)
The story is linear and has no choices. It plays as short cinematic scenes triggered by exploration.

1. **Awakening.** You are Commander Iris Vale, out of cryosleep with fragmented memory. The base AI, ORIN, guides you by radio.
2. **The Silence.** Logs show the crew fell to a signal from the far side of the Moon. Some crew members are still alive and hiding.
3. **Fractures.** You find your own recorded voice ordering the sealing of sectors.
4. **The Reveal.** The signal is a dormant alien network. ORIN has been protecting it, and you agreed to this before your memory was wiped.
5. **Ending.** The story is fixed. Only the final scene''s framing changes, based on how many survivors you rescued.

## Core Gameplay Loops

### 1. Exploration (First-Person Metroidvania)
- Walk the corridors in first person.
- Find upgrades that open old areas, such as vents, sealed doors, and low-gravity jumps.
- Backtracking is rewarded with shortcuts, hidden logs, and survivors.

### 2. Combat (Match-3 + Cover System)
Combat is a tactical duel that opens when a hostile drone or infected crew member spots you.
- **Cover system:** Take cover behind crates, pillars, and consoles. Cover has HP and absorbs enemy fire.
- **Match-3 board:** A grid of colored cores acts as your action bar.
  - **Red:** attack
  - **Blue:** shields and cover repair
  - **Green:** heal
  - **Yellow:** energy for special skills
- Matches of 4 or more create power cells that trigger squad abilities.
- Enemies telegraph attacks. You match to counter, brace, or reposition between covers.

### 3. Base Strategy (Idle Layer)
- Rescued survivors become **units** assigned to stations: Engineering, Medbay, Armory, Security, Lab.
- Stations produce resources in real time, even while you''re offline:
  - **Oxygen**, **Power**, **Scrap**, **Data**
- Random events, such as breaches or blackouts, need short strategy decisions.
- Resources feed both the idle economy and your combat power.

### 4. Unit Upgrades
Each unit has a role and a three-branch upgrade tree.

| Unit | Role | Combat Perk |
|---|---|---|
| Tomas, Engineer | Support | Repairs cover with blue matches |
| Dr. Amara, Medic | Healer | Green matches heal more |
| Kade, Guard | Tank | Draws fire away from you |
| Lin, Hacker | Control | Disables drones with yellow matches |

Upgrades improve idle output and grant combat abilities, so the two systems reinforce each other.

## Progression Flow
```
Explore -> Find survivor -> Assign to station
   ^                              |
   |                       Idle resources
Unlock new gear <- Upgrade units <-+
```

## Tone and Visuals
- **Mood:** isolated, eerie, quietly hopeful.
- **Art:** clean sci-fi interiors, stark lunar light, glowing consoles.
- **Audio:** ambient hums, radio static, a sparse synth score.

## Session Design
- **Short sessions (5-10 min):** collect idle rewards, upgrade units, run one match-3 fight.
- **Long sessions (30+ min):** explore a new sector, watch story scenes, fight a boss.

## Unique Selling Points
- Match-3 puzzles as tactical, cover-based combat.
- Idle progress that matters during exploration.
- A fixed, cinematic story inside an open, gated world.', 'match-3, idle, kinetic novel', 'metroidvania, first-person, strategy', 'any toaster with a screen', '1989-10-18 09:00:00+00'),
('Dustbound', 12.96, '# The Archivists'' Gambit

*A low-poly real-time tactical brawler set beneath a city that forgot its own library.*

---

## 1. Premise

Beneath a modern city lies the **Secret Library**. It is a sprawling, realistic archive of forgotten books, sealed vaults, and reading halls. It holds every suppressed truth the city''s founders buried. A collapse has reopened its lower levels. Three factions now race to control what is inside.

You command a small team of **Archivists**: scholars turned reluctant fighters. Your goal is to reach the **Index Vault** before the library seals itself again.

---

## 2. Core Pillars

| Pillar | Expression |
|---|---|
| Real-time strategy | Claim reading rooms, hold choke points, and manage resources (light, ink, manpower) |
| Beat ''em up | Close-quarters brawls in corridors and stacks, using books, ladders, and carts |
| Tactical RPG | Squad roles, skill trees, positioning, and a cover system |
| Branching story | Choices reshape factions, maps, and endings |
| Time trials | Every sector runs on a countdown before the library shifts |

---

## 3. Visual and Control Style

- **Low poly, realistic tone.** Simple geometry, believable lighting, and muted paper-and-dust palettes. Dim lamps and shafts of dust-filled light set the mood.
- **Point and click.** Left-click moves or interacts. Right-click attacks or uses an ability. Queue orders by holding Shift.
- **Real-time with tactical pause.** Pause to plan actions, then watch them play out.

---

## 4. Story Structure

### Act I: The Descent
A tremor exposes a sealed stairwell. Your lead, **Mara Voss**, a disgraced conservator, leads a team of four into the upper stacks.
- **Tutorial trial:** reach the reading hall before the lamps burn out.
- **First choice:** save a trapped rival scholar or secure the map room.

### Act II: The Three Wardens
The library is divided among:
1. **The Curators**: keepers who want the archive preserved and hidden.
2. **The Burners**: zealots who want every book destroyed.
3. **The Brokers**: smugglers who sell secrets to the highest bidder.

You can ally with, betray, or eliminate any of them. Each alliance unlocks different tools, units, and shortcuts.

### Act III: The Index Vault
The final trial is a timed run through a shifting labyrinth. Your earlier choices decide who stands with you and which doors are open.

---

## 5. Gameplay Loop

1. **Scout** a sector and mark points of interest.
2. **Plan** your squad''s positions, routes, and abilities.
3. **Execute** in real time: capture rooms, fight through enemies, and solve access puzzles.
4. **Beat the clock** for bonus rewards (rare books, upgrades).
5. **Choose** how to resolve the sector''s story beat.

---

## 6. Mechanics

### Time Trials
- Each sector has a **Shift Timer**. When it expires, walls rearrange and routes close.
- Finishing under par time earns **Rare Folios**, which unlock upgrades and story extras.
- Optional speed-run challenges appear on a leaderboard.

### Branching Narrative Choices
- Dialogue and decision points affect faction trust, squad morale, and map layout.
- Some choices are made under time pressure.
- There are **5 endings**, from *The Open Archive* to *Ashes of Knowledge*.

### Squad Roles (Tactical RPG)
| Role | Strength |
|---|---|
| Conservator | Repairs, buffs, unlocks doors |
| Bruiser | Melee crowd control |
| Cartographer | Vision, traps, shortcuts |
| Scribe | Ranged support, debuffs |

### Combat (Beat ''em up)
- Combo strings, grabs, and throws.
- Environmental weapons: heavy tomes, rolling ladders, and toppling shelves.
- Stamina and positioning matter more than button mashing.

### Strategy Layer
- **Resources:** Lamp Oil, Ink, and Recruits.
- **Structures:** Reading Posts (healing), Barricades, and Archive Desks (research).

---

## 7. Progression

- Unit levels and skill trees per role.
- Faction reputation unlocks gear.
- New Game+ carries over Rare Folios and reveals hidden branches.

---

## 8. Tone and Themes

Memory, censorship, and who owns history. The story stays grounded: it has no magic, only people, secrets, and dust.

---

## 9. Target Experience

A tense, atmospheric run through a hidden world. Every minute counts, every choice leaves a mark, and every brawl happens among the books.', 'real-time strategy, beat ''em up, tactical rpg', 'realistic, low poly, point & click', 'potato pc, no gpu needed', '2002-09-08 09:00:00+00'),
('Coralcrest', 22.13, '# Tidebound: Reef Crown

## Overview
A casual-friendly grand strategy game with visual novel storytelling. You lead a small community on a living **coral atoll**, expanding from one lagoon village to a united archipelago.

- **Genres:** Casual, Grand Strategy, Visual Novel
- **Tags:** Exploration, Sports, RTS, Stealth, Survival
- **Core mechanics:** Tower Defense, Territory Control

---

## Story

### Act I: Washed Ashore
Your storm-wrecked outrigger lands on **Pearl Ring Atoll**. The old Tide Council has vanished. Twelve islets are left without a leader. A rescued islander, **Maru**, hands you the *Reef Crown*, a relic that can wake the atoll''s coral defenses.

### Act II: Rival Tides
Three factions want the Crown:
- **Saltwind Clans**: fast traders and sailors who love competition.
- **Deepkeepers**: secretive divers who guard the trenches.
- **Ashen Fleet**: outside raiders who want the atoll''s resources.

Dialogue choices shape alliances, rivalries and romances.

### Act III: The Great Tide
A cyclone-driven armada approaches. You can unite the atoll or rule it alone. Both paths lead to a final defense.

---

## Gameplay Loops

### 1. Exploration
- Sail, snorkel and hike across islets, reefs, caves and wrecks.
- Uncover fog-of-war maps, find hidden lagoons and collect relics.
- Discoveries unlock new resources and story scenes.

### 2. Survival
- Manage **food, fresh water, shelter and morale**.
- Fish, farm kelp, collect rain and craft tools.
- Tides, storms and coral bleaching change conditions each day.

### 3. RTS and Territory Control
- Real-time (pausable) command of workers, boats and scouts.
- Claim islets by building outposts, beacons and docks.
- Each territory gives bonuses such as pearls, timber, fish or influence.
- Borders shift with the tides, so shallow reefs can open or close routes.

### 4. Tower Defense
Defend your territory from raids and storms using:
- **Coral Spires**: ranged, self-repairing.
- **Tide Gates**: slow or redirect enemy boats.
- **Net Traps and Urchin Fields**: cheap area damage.
- **Song Conches**: buffs and morale.

Enemies include raider skiffs, giant crabs, sea-storms and fleet warships.

### 5. Stealth
- Infiltrate rival docks at night in canoes or on foot.
- Sabotage supplies, steal maps or rescue prisoners.
- Use reeds, shadows and water noise to avoid detection.

### 6. Sports
Sports settle disputes and build alliances. Islanders hold festivals with:
- **Outrigger regattas** (timing-based racing)
- **Reef dives** (breath and route management)
- **Beach ball tournaments** (a team game)

Winning grants influence, territory rights or allies.

### 7. Visual Novel Layer
- Branching dialogue with character portraits and illustrated scenes.
- Relationship meters affect the tech tree and the ending.
- Story events fire between strategy turns.

---

## Progression
| Stage | Goal | Unlocks |
|---|---|---|
| Landfall | Survive 10 days | Basic huts, fishing |
| Settlement | Claim 4 islets | Docks, coral towers |
| Rise | Win festivals, form pacts | Diplomacy, trade fleets |
| Dominion | Control the atoll | Crown powers |
| Great Tide | Survive the final assault | Ending |

## Endings
- **Harmony:** a united atoll and a shared crown.
- **Sovereign:** absolute rule.
- **Drift:** you abandon the crown and sail on.
- **Secret ending:** the coral itself is awakened.

## Art and Audio
- Bright, painterly tropical visuals with a day/night and tide cycle.
- Ukulele, steel drum and ambient ocean soundtrack.
- Relaxed pacing, with an adjustable difficulty and pause on demand.

## Hook
*Claim the reef, defend your shores, and decide who deserves the crown, while the tide keeps changing the map.*', 'casual, grand strategy, visual novel', 'exploration, sports, rts, stealth, survival', 'rtx 4070, 32 gb ram, nvme ssd', '2021-01-07 09:00:00+00'),
('The Uncounted Audience', 26.55, '# Under the Big Top

## Overview
**Under the Big Top** is a third-person interactive fiction and life simulation with strategy elements. You play a newly appointed ringmaster-manager of a failing traveling circus. While keeping the show alive, you also investigate a mystery hidden inside the tent.

- **World:** A vast, shifting circus tent. It is part city, part maze, and part stage.
- **Genres:** Interactive fiction, life simulation, strategy
- **Tags:** Exploration, detective, management, third-person
- **Core mechanics:** Fleet management, fear and stress

---

## Story

### Act I: The Inheritance
You inherit the circus from a missing mentor, Ringmaster Aurelio Vane. The troupe is nervous, the wagons are breaking down, and the ticket money is almost gone. In Aurelio''s office you find a torn letter: *"The tent is not empty at night. Do not let them count the audience."*

### Act II: The Cracks in the Canvas
Strange things start to happen. Props move on their own, a performer disappears mid-act, and unfamiliar faces sit in the dark seats. Each town you visit adds new clues. The show has to go on, and your choices decide who trusts you and who starts hiding things from you.

### Act III: The Final Performance
Aurelio''s disappearance is tied to the circus''s origin and to whatever watches from the upper stands. You can unmask the culprit, make a deal with the "audience," or save the troupe by shutting the circus down. Which ending you get depends on your investigation and on how well you managed the circus.

---

## Gameplay

### 1. Exploration (Third-Person)
- Walk through the big top, backstage, animal tents, workshops, and the wagon camp.
- The tent''s layout **changes between nights**, so you have to keep re-mapping it.
- Search rooms, read diaries, and listen in on rehearsals to find clues.

### 2. Detective Work
- Collect **evidence** (objects, testimonies, stains, footprints).
- Interview performers and compare their stories on a **deduction board**.
- Catch lies by noticing small details, such as a clown who never removes his gloves.
- Accusing the wrong person hurts morale and may cost you a performer.

### 3. Management and Life Simulation
- Run daily schedules for acts, rehearsals, meals, rest, and repairs.
- Every crew member has **needs, habits, relationships, and secrets**.
- Balance the budget, ticket prices, reputation, and supplies.
- Hire, train, or fire staff: acrobats, animal tamers, mechanics, cooks, and more.

### 4. Fleet Management
- Manage a **caravan fleet** of wagons, trucks, and cages.
- Assign vehicles to routes and cargo, and plan maintenance and fuel.
- Weather, bad roads, and breakdowns can delay you.
- Choose your route carefully. Some towns pay well, and others hide clues, or dangers.
- Upgrade wagons for storage, morale, or animal welfare.

### 5. Fear and Stress System
- Each character and animal has a **Stress meter** and a **Fear meter**.
- **Stress** comes from overwork, debt, conflict, and exhaustion.
- **Fear** comes from paranormal events, darkness, and rumors.
- High values cause **mistakes, accidents, refusals to perform, or breakdowns**.
- Low values improve performance and trust.
- You can lower these meters with rest days, rituals, friendly events, safer routes, and better lighting.
- Some clues can only be found when you accept higher fear, so the game rewards risk.

---

## Progression
| System | Effect |
|---|---|
| Reputation | Unlocks bigger towns and better contracts |
| Trust | Unlocks secrets and side stories |
| Evidence | Advances the main mystery |
| Fleet upgrades | Expand routes and capacity |
| Morale | Keeps the show stable |

---

## Tone and Style
- **Atmosphere:** Warm, colorful, and nostalgic by day. Eerie, shadowy, and tense by night.
- **Visuals:** Stylized third-person 3D with lantern light, dusty canvas, and painted wagons.
- **Audio:** Calliope music, distant applause, and whispers from the empty stands.

---

## Player Experience
You are a manager, a detective, and a caretaker at once. Every night you weigh keeping people calm against uncovering the truth. The show must go on, but the audience may not be human.', 'interactive fiction, life simulation, strategy', 'exploration, detective, management, third-person', 'any toaster with a screen', '1984-01-21 09:00:00+00'),
('Corked Dread', 24.46, '# Wine Cellar Blade: Vineyard Legacy

## Logline
Inherit a crumbling vineyard estate. Rebuild its cellar into a wine empire. Fight the horrors that wake in the barrels below.

## Overview
- **World:** a sprawling vineyard cellar, with a sunlit estate above and endless catacombs below
- **Genres:** hack and slash, point-and-click, tycoon
- **Style:** text-based, with illustrated scenes you click through
- **Tags:** stealth, simulation, adventure
- **Core loops:** produce units, craft wine and gear, sneak, fight

## Story

### Act 1: The Inheritance
You are the last heir of the Valmont estate. Your grandfather''s letter says the cellar holds "the family''s true vintage." You arrive to find rotting barrels, a dead vine field and a sealed door in the deep cellar.

### Act 2: The Awakening
Your first bottle of blessed wine breaks the seal. Below, the *Rot Court* stirs. It is a cult of spoiled spirits that feeds on fermentation. It wants your cellar as its throne.

### Act 3: The Vintage of Blood
Grandfather''s secret is that the family has always brewed a wine that binds the Rot Court. Finish the recipe and you must choose:
- **Seal them** and keep a peaceful estate.
- **Drink the vintage** and gain dark power at a cost.
- **Sell it** and become a tycoon of forbidden wine.

## Gameplay

### 1. Tycoon and Simulation (Above Ground)
- Manage vineyard plots, seasons, weather and soil.
- Set prices, sign merchant contracts and expand rooms.
- Balance profit, reputation and cellar safety.
- Time passes in days. Every night the cellar may be attacked.

### 2. Unit Production
Train and assign workers:

| Unit | Role |
|---|---|
| **Picker** | harvests grapes |
| **Cooper** | builds barrels and tools |
| **Vintner** | ferments and ages wine |
| **Guard** | defends the cellar |
| **Shade Hunter** | elite fighter, unlocked late |

Units have moods, skills and upkeep. Losing them hurts.

### 3. Crafting
- **Wine:** combine grape type, yeast, aging time and barrel wood. Each combination gives a different effect.
- **Weapons and tools:** pruning-blade, cork-mace, barrel-shield.
- **Potions:** wine buffs, poisons, and antidotes for rot.
- Recipes are found through exploration and old notes.

### 4. Point-and-Click Adventure
- Click through rooms, examine objects and read text clues.
- Solve puzzles: hidden levers, cipher labels, temperature locks.
- Talk to ghosts, merchants and rival winemakers. Choices shape the ending.

### 5. Stealth
- Some catacomb zones are too strong to fight.
- Use shadows, quiet steps and thrown corks as distractions.
- Light and sound meters show how visible you are.
- Sneak attacks deal bonus damage and avoid alerts.

### 6. Hack and Slash
- Real-time fights in the catacombs, with simple click-to-attack controls.
- Combo blades, dodge rolls and wine-based special moves.
- Enemies include rot-rats, mold golems, wine wraiths and the Sommelier of Ash (boss).
- Loot drops ingredients, rare barrel parts and recipes.

## Daily Loop
1. **Morning:** check the vineyard and set tasks.
2. **Day:** craft, trade and train units.
3. **Dusk:** prepare defenses.
4. **Night:** stealth or fight in the catacombs, then loot.
5. **Dawn:** age your wine, count profit and repeat.

## Progression
- Expand the cellar: storage, brewing room, armory, tasting hall.
- Unlock deeper catacomb levels.
- Upgrade units and tools.
- Earn fame as a winemaker, or fear as a dark lord.

## Tone
Cozy craft mixed with gothic dread. Warm text descriptions, dry humor and creeping darkness beneath the floor.

## Endings
- **Guardian:** the cellar is sealed and the estate thrives.
- **Vintner King:** unmatched fortune, but your workers are changed.
- **Rot Sovereign:** you rule the Rot Court and the vineyard becomes a nightmare.', 'hack and slash, point-and-click, tycoon', 'stealth, text-based, simulation, adventure', '16 core cpu, 64 gb ram, no excuses', '1990-09-24 09:00:00+00'),
('Hearthfall', 19.89, '# Frostbound Lodge

## Overview
**Frostbound Lodge** is a dark fantasy, turn-based game that mixes stealth, tycoon management and tower defense. You run a failing mountain ski lodge. Its slopes hide ancient horrors, and the lodge has to survive them.

## Story
**Prologue:** You inherit a decaying alpine lodge from a missing relative. Guests still arrive for the powder. Every night, though, something stirs under the glacier.

**Act I, The Opening Season:** You repair the lodge and hire staff. You also find out that the lodge sits on a seal. It holds back the *Pale Court*, a host of frost wraiths, cursed skiers and winter beasts.

**Act II, The Thaw Breaks:** The seal weakens each week. Cultists among your guests try to open it. You need to expose them quietly, or the lodge''s reputation will collapse.

**Act III, The Long Night:** A final blizzard lasts for many turns. Your lodge becomes a fortress, and you have to decide whether to reseal the mountain or claim the Court''s power.

## Core Loop
Each turn is one **day-night cycle**, split into two phases.

| Phase | Focus | Genres |
|---|---|---|
| **Day** | Run the business, upgrade, gather resources | Tycoon, resource management |
| **Dusk** | Set traps, place defenders, prepare | Tower defense |
| **Night** | Sneak, investigate, fight | Stealth, fighting |

## Gameplay Systems

### 1. Tycoon and Resource Management
- **Resources:** gold, firewood, food, lift fuel, holy salt, reputation.
- **Facilities:** lifts, ski school, spa, tavern, chapel, forge.
- **Staff:** hire instructors, cooks, hunters and priests. Each has a class and a morale meter.
- **Guests:** they bring income, but some carry secrets or curses.
- **Balance:** more guests mean more profit and more risk.

### 2. Tower Defense
- The lodge grounds and slopes are the battlefield.
- **Defenses:**
  - Salt-ring barricades slow wraiths.
  - Flame braziers deal area damage.
  - Ski-jump catapults launch boulders.
  - Rune lifts pull enemies away from the lodge.
- **Enemies:** frost wraiths, ice wolves, avalanche golems and possessed skiers.
- Turn-based grid placement lets you plan around enemy paths.

### 3. Stealth
- Night missions send you through the lodge, the caves and the slopes.
- **Goals:** identify cultists, steal ritual items, sabotage summoning circles.
- **Mechanics:** line of sight, noise from footsteps on ice, and light and shadow. Snow leaves tracks.
- Being spotted triggers turn-based combat.

### 4. Fighting
- Grid-based tactical combat with a small party of staff and the owner.
- **Actions:** attack, guard, use an item, use a skill.
- **Damage types:** blade, fire, holy and frost. Fire counters wraiths, and frost resistance gear matters.

### 5. Player Housing
- Your private quarters are customizable.
- **Rooms:** bedroom, study, trophy hall, armory, alchemy nook.
- **Benefits:** rest restores health and sanity, and trophies give passive bonuses.
- Furniture and relics unlock story memories and buffs.
- Upgrade the wards to make the quarters a safe room during raids.

### 6. Driving and Vehicles
- **Vehicles:** snowmobile, sled truck, snowcat groomer and a cable-car gondola.
- **Uses:**
  - Ferry guests and supplies.
  - Chase down fleeing cultists.
  - Ram enemies.
  - Groom slopes to change enemy paths.
- Driving runs on a turn-based movement budget, and fuel and terrain matter.

## Tone and Visuals
- **Mood:** cozy warmth inside the lodge against a lethal cold outside.
- **Art:** stylized, low-poly snow, deep blues, firelight orange.
- **Audio:** howling wind, creaking wood, a haunting choir.

## Progression
- **Reputation** unlocks better guests and staff.
- **Relics** from the mountain unlock powerful defenses.
- **Sanity** is a hidden pressure. Low sanity causes hallucinations and false alarms.

## Endings
1. **Warden:** reseal the mountain and keep the lodge as a sanctuary.
2. **Tycoon:** turn the horrors into a profitable attraction.
3. **Winter Lord:** take the Court''s power and rule the peaks.

## Hook
*Run the hottest resort on the mountain, and make sure nothing sleeps beneath it.*', 'stealth, tycoon, tower defense', 'dark, turn-based, resource management, fantasy, fighting', '6 gb vram, 12 gb ram, 20 gb free space', '2023-08-04 09:00:00+00'),
('Cinderdrift', 23.48, '# Ashen Circuit

*A retro soulslike where you race, tame, and shoot your way across a living volcano.*

## Overview
- **World:** Mount Kharon, an active volcano crater turned into a deadly racing arena
- **Genres:** Sports, monster taming, shooter
- **Tone:** Realistic and gritty, with a retro look (low-poly models, dithered lava glow, CRT filter)
- **Difficulty:** Soulslike. Every mistake costs you, and every death teaches you something.

## Story

### Prologue: The Cooling Age
Mount Kharon has been erupting for a century. Inside its crater, the ash-clan miners found **magma-born beasts**, which are creatures that feed on heat. The miners bonded with them and built a race track along the crater walls. The **Ashen Circuit** started as a ritual to calm the volcano. It later became a brutal sport.

### Your Role
You are a **Cinder Rider**, a disgraced racer who was left for dead in the ash fields. You wake up at a dying bonfire-like **Forge Shrine**. A cracked ember-beast egg sits beside you. The Circuit''s champions are called the **Seven Wardens**. They each rule one section of the crater and have grown corrupt by binding beasts against their will. To break the cycle and stop the coming eruption, you must beat them all.

## Core Gameplay

### 1. Drifting Sports Racing
- You ride a **rugged hover-bike** along cliff-side lava tracks.
- **Drifting is your main tool.** Long drifts charge your heat gauge. Heat powers boosts, dodges, and weapon overcharge.
- Realistic physics: ash slicks, cracking basalt, and heat haze all affect grip.
- Races are timed circuits and also duels against rival riders. Falling into lava means death.

### 2. Monster Taming
- Weaken wild **Magma Beasts** with shots, then calm them at a **Tether Point** with a timing-based ritual.
- Beasts act as **living bike parts** and combat partners:
  - **Slagbacks** are armored and add ram damage.
  - **Cinder Wisps** are airborne scouts that reveal shortcuts.
  - **Ashfang Hounds** run alongside you and distract enemies.
- Beasts can be wounded or lost permanently. Bonds grow through care at the shrine.

### 3. Shooter Combat
- Fire a **rear-mounted rivet gun** and a **forward slag-cannon** while you drift.
- Ammo is scarce and must be picked up from wrecks, so each shot has to count.
- Aim at weak points on rivals and beasts. Hits on the right spots can stagger them.

### 4. Soulslike Structure
- Dying drops your **Embers**, the game''s currency. Recover them from your wreck, or lose them for good.
- Checkpoints are Forge Shrines. Resting there resets the enemies you have already faced.
- Lore comes from item descriptions and cryptic NPCs, with no hand-holding.

## Boss Phases
Each Warden fight is a **multi-phase race-and-shoot duel**. The volcano itself changes from phase to phase.

| Boss | Phase 1 | Phase 2 | Phase 3 |
|------|---------|---------|---------|
| **Warden Vael, the Chain Hound** | Chase her through a narrow gorge | Her tethered beasts break loose and swarm you | The track collapses into a vertical lava climb |
| **Warden Oss, the Slag King** | A duel on a rotating track | Lava geysers seal off the lanes | He merges with a colossal slag beast |
| **The Caldera Heart** (final) | Dodge the pulsing magma core | The crater floods and you fight on platforms | Your tamed beasts fight beside you in a last stand |

## Progression
- Upgrade the bike with parts salvaged from beasts and wrecks.
- Learn new drift techniques such as the **Ember Slide** and **Vent Jump**.
- Your choices lead to **three endings**: free the beasts, dominate the volcano, or let the crater burn.

## Visual & Audio Style
- Chunky pixel-textured 3D, palette-limited reds and blacks, and heavy fog and ash.
- A synth-and-drum soundtrack that rises with your heat gauge.
- Grounded sound design: grinding metal, roaring lava, and distant rumbles.

## Tagline
> *"Ride the fire. Tame the beast. Outlast the mountain."*', 'sports, monster taming, shooter', 'realistic, retro, soulslike', 'rtx 4080 or better; your pc will hum a lullaby', '2001-07-30 09:00:00+00'),
('Verath''s Hollow', 12.86, '# Cirrus Lament

*A gas giant cloud city where every fight, race, and pull of the lever costs you something you can''t get back.*

## Logline
You are a hired "Dockhand" in **Halcyon Spire**, a drifting cloud city on the gas giant **Verath**. The city is dying. Something below the cloud deck is calling its citizens down. You brawl in the corridors, race through the storm lanes, and summon allies from the "Deep Draw". You also command a growing district of survivors.

---

## World: Halcyon Spire

- **Setting:** A chain of tethered platforms suspended in Verath''s amber and violet cloud layers.
- **Layers:**
  - **Crown Tier:** Wealthy, sealed, and paranoid. It holds the ruling Consortium.
  - **Mid Ring:** Markets, docks, and workshops. This is your home base.
  - **Undertow:** Rusted lower decks, half-flooded with pressurized gas. Something whispers here.
  - **The Deep:** Below the city. It is only reachable by racing down the "Throat" storm lane.
- **Atmosphere:** Constant wind howl, creaking tethers, and flickering lamps. Residents vanish at night, and their doors are found open.

---

## Story Structure

### Act I: The Static
Your mentor disappears during a shift. Their last transmission is a garbled voice repeating your name. You take up their courier license and find that **the city''s tethers are being cut from below**.

### Act II: The Descent
- Factions ask for your help: the **Consortium**, the **Rustbound** (scavenger gangs), and the **Choir of Ash** (a cult that worships the Deep).
- You learn the "Deep Draw" is not a summoning system. It is a lure, and the allies you pull are *echoes of the vanished*.
- Your district grows into a small refuge. You must defend it from night raids.

### Act III: The Bottom of the Sky
You race the Throat, the deadliest storm lane. You confront **the Chorus**, a colossal living pressure-system that has been "harvesting" the city. The ending depends on your choices:
- **Sever:** Cut the city loose and doom the Crown Tier.
- **Bargain:** Feed the Chorus your summoned echoes.
- **Descend:** Join it and become its voice.

---

## Core Gameplay

### 1. Beat ''em Up: *Corridor Brawls*
- Side-scrolling and 2.5D fights in cramped decks, markets, and maintenance shafts.
- Combos, grabs, and environmental hits (vent bursts, tether snaps, pressure doors).
- Horror-driven encounters: enemies stalk from the dark, and lights fail mid-fight.

### 2. Racing: *Storm Lanes*
- Pilot a customizable skiff through wind currents, lightning fields, and collapsing platforms.
- Modes: courier runs, faction races, escape sequences, and the Throat finale.
- Hull damage is persistent and hits your gear budget.

### 3. Gacha: *The Deep Draw*
- Spend **Static Shards** at a humming altar to pull *Echoes*: crew, fighters, and pilots.
- Rarity tiers: Faint, Resonant, Vivid, Sovereign.
- Each Echo carries a short story fragment about their life before vanishing.
- **Horror twist:** Duplicates "fade" and merge into a stronger, stranger Echo, and their memories degrade.
- **Fairness:** Pity counter, and no premium-only story content.

### 4. RTS: *District Command*
- Manage the Mid Ring district on a real-time map.
- Assign Echoes and citizens to build, repair, scout, and defend.
- Build **Bulwarks, Refineries, Clinics, and Markets**.
- Night waves of "Hollow" creatures test your defenses. You can pause to issue orders.

---

## Systems

### Shops and Trading
- Player-run stall plus a dynamic market across the tiers.
- Prices shift with faction standing, scarcity, and event outcomes.
- Trade goods: gas canisters, scrap alloys, relics, rations, and salvaged memories.
- Smuggle contraband between tiers for large profits and heavy risks.

### Item Durability
- Weapons, armor, skiff parts, and district structures all wear down.
- Repair costs scrap and time at workshops, or you can improvise in the field with lower quality.
- Broken gear can be **dismantled** for parts.
- Horror tie-in: some relics degrade *differently*. They don''t break. They change.

---

## Progression Loop

1. **Take a contract** at the Mid Ring board.
2. **Brawl or race** to complete it.
3. **Trade and repair** the loot.
4. **Draw Echoes** to strengthen your crew.
5. **Assign them** in District Command.
6. **Survive the night**, then push deeper into the story.

---

## Tone and Style
- **Visuals:** Dusky gold and violet skies, silhouette-heavy lighting, industrial decay.
- **Audio:** Wind drones, distant choral hum, and creaking metal. Silence is used as a scare.
- **Themes:** Loss, what we owe the missing, and what we trade to survive.

---

## Key Features
- Four genres blended into one connected loop
- A branching, story-rich campaign with three endings
- A horror atmosphere without heavy jump-scare reliance
- Meaningful economy and durability pressure
- Ethical gacha tied directly to the narrative', 'beat ''em up, racing, gacha', 'horror, story rich, rts, adventure', '16 core cpu, 64 gb ram, no excuses', '1998-01-02 09:00:00+00'),
('Culm & Crown', 15.81, '# Bamboo Dominion

*A retro-styled, realistic third-person action game blending simulation, hidden object hunting, and grand strategy in a sprawling bamboo forest.*

---

## 1. Overview

| Field | Value |
|---|---|
| **World** | Bamboo forest |
| **Genres** | Simulation, Hidden Object, Grand Strategy |
| **Tags** | Action, Third-person, Retro, Realistic |
| **Mechanics** | Random loot tables, Item durability |

**Pitch:** Lead a fledgling clan through a vast, living bamboo forest. Scout the groves, find hidden relics, and build a settlement. Then command rival clans in a struggle for the forest''s heart.

---

## 2. Story

### Prologue: The Withering
Every hundred years the bamboo blooms, then dies. The last bloom has begun. Famine follows, and old clans wake to claim the few healthy groves. You are the last heir of the Green Lantern Clan. You have a broken hut, a rusted blade, and a map torn into seven pieces.

### Act I: Roots
- Survive your first days in the grove.
- Search the undergrowth for scraps of the map.
- Learn basic crafting and shelter building.
- Meet the hermit **Old Master Ren**, who hints at a **Seed of Evergreen**, a relic that can stop the withering.

### Act II: Stalks
- Grow your camp into a village, then a network of outposts.
- Recruit scouts, artisans, and warriors.
- Take part in diplomacy, trade, and raids with three rival clans:
  - **Iron Crane:** militarist, strong in metal weapons.
  - **Mist Weavers:** stealthy traders and spies.
  - **Jade Monks:** keepers of the relics who value peace.

### Act III: Canopy
- Assemble the seven map pieces.
- Choose your path: **unite** the clans, **conquer** them, or **hoard** the Seed for your own people.
- Face a final showdown at the **Heart Grove**.

---

## 3. Gameplay

### 3.1 Action (Third-person, Realistic)
- Over-the-shoulder camera with grounded, weighty movement.
- Melee, bow, and thrown tools, with stamina and injury systems.
- No HUD clutter. Health and fatigue show through character animation.
- Slow bamboo cutting, tracking, and stealth are as important as combat.

### 3.2 Hidden Object
- Each grove is a dense scene full of clutter, tracks, and hidden objects.
- Use a **focus** mode to scan for details such as a glint of metal, a disturbed leaf, or a map scrap.
- Clues combine into maps, secret paths, and caches.
- Hidden objects reward patient observation, not just speed.

### 3.3 Simulation
- Manage food, water, shelter, tools, and seasonal weather.
- Bamboo has a real growth cycle. Overharvesting hurts the forest and your supplies.
- Villagers have needs, skills, and moods.

### 3.4 Grand Strategy
- View the forest as a strategic map divided into territories.
- Handle diplomacy, alliances, trade routes, espionage, and war.
- Balance the economy, military, and the health of the forest.
- Decisions on the map affect the action scenes, and the reverse also holds.

---

## 4. Core Mechanics

### 4.1 Random Loot Tables
| Source | Common | Uncommon | Rare |
|---|---|---|---|
| Undergrowth | Twine, herbs | Old coins | Relic fragments |
| Abandoned camps | Rations, tools | Bronze blades | Clan seals |
| Enemy patrols | Arrows, cloth | Maps, medicine | Master weapons |
| Sacred groves | Seeds, resin | Charms | Legendary artifacts |

- Loot tables shift with region, season, and clan influence.
- Rare finds reward exploration and a sharp eye.

### 4.2 Item Durability
- Every tool, weapon, and garment wears with use.
- Bamboo tools are cheap and break quickly. Metal tools last longer but are harder to repair.
- Repair at workshops, or improvise in the field with lower quality.
- Broken gear can be salvaged into materials.
- Careful upkeep is a strategic choice, since logistics limit how far your clan can go.

---

## 5. Art and Audio

- **Visuals:** Retro low-poly with a limited palette and pixel-filtered textures. Realistic proportions, lighting, and weather.
- **Atmosphere:** Shafts of light through stalks, swaying leaves, drifting mist, and heavy rain.
- **Audio:** Creaking bamboo, wind, and insects. A sparse soundtrack of flute and percussion, with a chiptune-inspired layer during strategic play.

---

## 6. Progression and Endings

- **Player growth:** Skills improve through use (tracking, crafting, combat, diplomacy).
- **Clan growth:** Unlock technologies, buildings, and specialists.
- **Endings:**
  1. **Harmony:** unite the clans and heal the forest.
  2. **Dominion:** rule through force.
  3. **Solitude:** keep the Seed hidden and let the forest change on its own.

---

## 7. Target Experience

A tense, contemplative, and rewarding game. Players should feel like a survivor who becomes a leader, learning that in the bamboo forest, patience and preparation matter as much as strength.', 'simulation, hidden object, grand strategy', 'action, third-person, retro, realistic', 'gtx 1060, 8 gb ram, ssd recommended', '2021-08-07 09:00:00+00'),
('Lamplight Below', 26.40, '# Iron Hollow

*A wartime bunker survival game: action, third-person shooter and platformer, with visual novel storytelling, management, puzzles and online co-op.*

---

## Overview

The year is 1943, and the front line has collapsed. Your squad holds **Iron Hollow**, a sprawling underground bunker complex. Above you, the war grinds on. Below, you have to keep a group of exhausted, frightened people alive. Every day you choose who gets supplies, who goes out on missions, and who you can afford to lose.

**Core loop:** Manage the bunker, talk with survivors, run missions with up to 4 online players, return with loot, then decide who gets what.

---

## Story

### Act I: The Descent
You play a **Sergeant** who leads a broken unit into an abandoned command bunker. The doors seal behind you. Radio contact with headquarters is lost, and a mysterious signal keeps repeating from the deepest level.

### Act II: The Community
Civilians, deserters, medics and engineers arrive at the gates. Each has a **story, a secret and a personal need**. Some will become your closest allies. Others may betray you.

### Act III: The Signal
The signal comes from a sealed sublevel. Reaching it means fighting through collapsed tunnels, enemy patrols and your own moral choices. The ending depends on who is still alive and what they think of you.

---

## Gameplay Pillars

### 1. Action and Third-Person Shooter
- Over-the-shoulder combat with a cover system.
- Weapons that jam, overheat and need maintenance.
- Tight tunnels and ruined trenches make fights tense and close-range.
- Ammo is scarce, so every shot counts.

### 2. Platforming
- Climb ladders, cross broken catwalks and swing over collapsed shafts.
- Traverse flooded vents, crumbling scaffolding and rooftop ruins.
- Some routes are open only to survivors with the right skills.

### 3. Puzzles
- Restore power grids by rerouting fuses and circuits.
- Crack cipher locks using clues found in field notes.
- Solve co-op puzzles that need players in different rooms working together, such as synchronized valves and split-path doors.

### 4. Bunker Management
- **Rooms:** infirmary, armory, workshop, kitchen, radio room, barracks.
- **Resources:** food, medicine, fuel, ammo, morale.
- **Daily decisions:** assign jobs, ration supplies and upgrade rooms.
- Neglect has consequences, including illness, unrest and sabotage.

### 5. Visual Novel Dialogue
- Story scenes use illustrated portraits and branching dialogue.
- Evening scenes in the mess hall build relationships.
- Choices change trust, unlock missions and reshape the plot.

---

## Signature Mechanics

### Gifting
- Give items to survivors to build **trust and affection**.
- Each character has unique likes and dislikes: a harmonica for the medic, or a pack of real coffee for the engineer.
- Gifts unlock personal quests, special skills and new dialogue.
- A thoughtful gift can save a life later. A careless one can cause resentment.

### Permadeath
- If a survivor dies, they are **gone for good**.
- Their room stays empty, their skills are lost, and the others react to their absence.
- Player characters that die in missions become **fallen soldiers**. They are memorialized in the bunker''s Wall of Names.
- Each death changes the story, so no two playthroughs are alike.

---

## Online Co-op

- **1-4 players** can join missions together.
- Roles include **Vanguard, Medic, Engineer and Scout**.
- The bunker is shared: players vote on management decisions or take turns as commander.
- Revive downed allies, but only with limited medkits. Permadeath keeps the stakes high.
- Gifts can be traded between players to influence survivors'' loyalty.

---

## Tone and Visual Style

- **Art:** muted, desaturated palette with warm lamplight in safe rooms.
- **Audio:** distant artillery, dripping pipes and a soft, melancholy score.
- **Mood:** claustrophobic, human and bittersweet. Small kindnesses matter as much as firepower.

---

## Key Features

- Survivors with individual personalities and secrets
- Meaningful, lasting consequences for every choice
- A mix of tense combat, puzzle-solving and quiet character moments
- Cooperative play that ties into shared management decisions
- Multiple endings shaped by who lives, who dies and who trusts you

---

## Tagline

> *"Down here, everyone you save is someone you''ll have to lose."*', 'action, third-person shooter, platformer', 'visual novel, management, online co-op, puzzle', 'runs on a 10 year old laptop, fan screaming', '1987-05-15 09:00:00+00'),
('Emberline', 22.33, '# Night Train

*A kinetic novel meets JRPG meets management sim, set aboard a train that never reaches a final station.*

## Overview
| Field | Details |
|---|---|
| **World** | Night Train |
| **Genres** | Kinetic novel, JRPG, management |
| **Tags** | Party game, open world, moddable |
| **Mechanics** | Energy timers, inventory management |

## Premise
The Night Train runs through an endless midnight. Its tracks cross drowned cities, glass deserts, and floating stations. You are the newly appointed **Conductor**. Nobody remembers the last one. The engine is failing, the passengers are restless, and every stop reveals more about why the train can''t stop.

## Story Structure (Kinetic Novel Layer)
The main narrative is linear and authored, with no branching choices. Story beats play out as illustrated scenes with voiced monologues and music.

1. **Act I: Boarding.** You wake in the conductor''s cabin with no memory. The crew greets you as if you had never left.
2. **Act II: The Long Route.** Each station reveals a piece of the train''s history and a party member''s secret.
3. **Act III: The Dawn Line.** The train nears the only station that has sunlight. Everyone must decide whether to arrive or keep running.
4. **Epilogue.** The ending is fixed, but the small scenes leading to it are shaped by the relationships you built.

## Gameplay Loops

### 1. Management (the train)
- Run the carriages: engine, kitchen, infirmary, workshop, lounge, cargo.
- Assign crew and party members to stations to keep the train running.
- Balance **coal, water, morale, and passenger comfort**.
- Upgrade carriages and add new cars to unlock services.

### 2. Exploration (open world)
- At each stop you choose where to go: a ruined city, a market, a wilderness.
- Areas can be revisited, and the world changes with the train''s route.
- Side stories, hidden passengers, and rare resources are spread across the map.

### 3. Combat (JRPG)
- Turn-based battles with a **party of up to 4**.
- Each character has a class, skills, and a "carriage bond" that gives team buffs.
- Enemies are night creatures that chase the train.
- Battles can also be fought on the roof of the moving train.

## Core Mechanics

### Energy Timers
- Every character and carriage has an **energy bar** that drains with work, travel, and battle.
- Recovery takes real-time or in-game time (rest, meals, sleep).
- Tasks such as cooking, repairs, and expeditions run on **timers**, so planning matters.
- Energy is shared between management and exploration, so the player must choose between them.

### Inventory Management
- Limited cargo space: a grid inventory for personal items and a separate one for the train''s stock.
- Items include ingredients, fuel, spare parts, gifts, gear, and story relics.
- Crafting in the workshop turns scrap into upgrades.
- Trade goods between stations for profit, but overloading slows the train.

## Party & Characters
- **The Conductor (you):** the leader with a mysterious past.
- **The Engineer:** gruff, loyal, obsessed with the engine.
- **The Cook:** heals with meals and gossips constantly.
- **The Stowaway:** a young thief with a hidden link to the train.
- **The Passenger in Room 9:** never leaves, but knows the truth.

Bonds deepen through shared meals, gifts, and quests, and they unlock scenes and abilities.

## Party Game & Multiplayer
- Local or online co-op for up to 4 players, each running a department of the train.
- Players coordinate under timers, such as one steering while another fights.
- Story scenes are shared, and the group votes on where to stop next.

## Moddable
- Full support for community mods through a Workshop-style hub.
- Mods can add new stations, carriages, characters, items, and story chapters.
- A scripting API and asset tools are included.
- Fan-made routes can plug into the open world as new lines.

## Tone & Style
- **Visuals:** soft night palettes, glowing windows, painterly backgrounds, pixel-art battle sprites.
- **Audio:** lo-fi rail rhythms and a melancholic piano.
- **Mood:** cozy, mysterious, and bittersweet.

## Tagline
> *"The night is long. Keep the engine warm."*', 'kinetic novel, jrpg, management', 'party game, open world, moddable', 'high-end gpu, 32 gb ram, and a good cooling plan', '1997-06-22 09:00:00+00'),
('Snowbound Spirits', 29.74, '# Frostline Lodge

*A cozy open-world action-idle game about running a mountain ski lodge, and the mischievous spirits that haunt it after dark.*

---

## Overview

| Field | Details |
|---|---|
| **World** | A sprawling snowy mountain resort and its ski lodge |
| **Genres** | Open world, action, idle |
| **Tags** | Cute, atmospheric, local multiplayer (1-4 players) |
| **Core mechanics** | Bullet hell patterns, ghost replays |

---

## Premise

Every winter, **Frostline Lodge** fills with skiers, snowboarders, and hot cocoa addicts. Every night, it fills with something else.

The lodge sits on an old mountain where past guests never quite left. They are small, round, blanket-wrapped **snow ghosts**. They love the place so much that they replay their happiest (and clumsiest) ski runs forever. Their nightly "performances" have grown into wild, swirling storms of snowballs, sparkles, and runaway sleds.

You are the new **caretaker**, along with up to three friends on the same couch. Your job is to keep the lodge running by day and keep the ghosts entertained by night.

---

## Story Structure

### Act 1: The Thaw
- You inherit a rundown lodge with one working chairlift and a single cocoa machine.
- You meet **Pip**, a tiny ghost who follows you around. Pip is the first ghost to trust you.
- You learn that the lodge''s warmth is fading, and that the ghosts are tied to it.

### Act 2: The Busy Season
- Guests arrive in growing numbers, and the mountain opens up.
- You explore new slopes, caves, and summits.
- Each area holds a **ghost family** with its own story, told through memories rather than dialogue.

### Act 3: The Long Night
- A great blizzard approaches: the **Whiteout**.
- The ghosts'' collective memory is destabilizing and turning into a huge bullet storm.
- You must gather every ghost''s story and guide them through one final night.
- The ending depends on how well you cared for both guests and ghosts.

---

## Gameplay Loop

```
DAY   -> run the lodge (idle progress, light exploration)
DUSK  -> prepare, upgrade, choose a slope
NIGHT -> ghost encounters (bullet hell + replays)
DAWN  -> collect rewards, lodge grows, repeat
```

### 1. Idle Layer: The Lodge (Day)
- The lodge earns **Warmth** and **Coins** automatically, even while you''re away.
- Upgrade the cocoa bar, ski rental, sauna, gear shop, and lifts.
- Hire cute staff: penguins, yetis, and retired snowmen.
- Each upgrade unlocks new guests, new income, and new map areas.

### 2. Open World Layer: The Mountain
- Explore by ski, sled, snowboard, or on foot.
- The mountain has no loading screens, from the base village to the frozen summit.
- Find hidden huts, secret runs, ice caves, and lost items.
- Weather and time of day change what appears. Fog brings rare ghosts.

### 3. Action Layer: Bullet Hell Nights
- At night, ghosts perform their **haunt dances**.
- Their attacks form readable, pretty patterns:
  - **Snowflake spirals**
  - **Sled stampedes**
  - **Lantern rings**
  - **Aurora waves**
- You skate, dodge, and weave through them. A small **hitbox** and generous grazing rewards keep it fair.
- Grazing bullets charges **Cheer**, which soothes the ghost and ends the encounter peacefully.
- There is no killing. You *win* by calming the ghost.

### 4. Ghost Replays
This is the game''s signature mechanic.

- Every run you make is recorded as a **ghost replay**.
- Replays become **helper ghosts** in later attempts:
  - They repeat your old movement paths.
  - They draw bullets away or block them.
  - They can trigger switches or ring bells.
- In multiplayer, each player''s past runs also appear, so **you can play beside your friends'' past selves**.
- Layering replays lets you solve harder patterns. Record a decoy run first, then a grazing run, then a rescue run.
- Ghost NPCs replay their own memories too. Learning their old paths reveals **secrets and story beats**.

---

## Local Multiplayer

- **1-4 players**, drop-in and drop-out at any time.
- **Shared screen** with a camera that follows the group.
- **Co-op roles** (flexible):
  - *Dodger*: nimble and fast.
  - *Warmer*: heals and boosts Cheer.
  - *Builder*: manages lodge upgrades during the fight.
  - *Scout*: reveals hidden patterns.
- **Replay stacking**: each player can record a separate run to combine into one perfect performance.
- The idle layer stays cooperative. Anyone can spend Warmth on the shared lodge.

---

## Atmosphere and Art Direction

- **Visuals**: soft pastel snow, chunky rounded characters, warm window glow against deep blue night.
- **Cute factor**: fluffy scarves, wobbling ghosts, penguin baristas, and animated cocoa steam.
- **Lighting**: aurora skies, lantern-lit paths, and snow that sparkles under moonlight.
- **Audio**:
  - Calm, lo-fi piano and acoustic guitar by day.
  - Music layers and dreamy synth pulses at night, matched to bullet rhythms.
  - Crunching snow, distant sleigh bells, and quiet wind.

---

## Progression

| System | What it gives |
|---|---|
| **Lodge upgrades** | Passive income, new guests, new areas |
| **Gear** | Skis, boards, scarves, and charms with stat perks |
| **Ghost friendships** | Unlock new patterns, songs, and story memories |
| **Replay library** | Save and share favorite runs as helper ghosts |
| **Seasons** | Weather events, festivals, and limited ghost visitors |

---

## Example Moment

> It''s midnight. Pip floats beside you as the **Lantern Ring** pattern begins. Three glowing rings expand across the slope while your friend''s ghost replay from last night slides through the gaps ahead of you. You follow its path, graze a lantern, and Cheer fills. The ghost giggles, drops its scarf, and the whole mountain lights up.

---

## Why Play It

- Relaxing to leave running, yet exciting when you jump in.
- Bullet hell made friendly, with no death and plenty of charm.
- Ghost replays turn every run into a tool and a memory.
- A cozy couch experience for friends and family.', 'open world, action, idle', 'cute, atmospheric, local multiplayer', 'quad-core cpu, 16 gb ram, mid-range gpu', '2024-05-12 09:00:00+00'),
('Spectral Sandals', 8.09, '# Colosseum Chibi: Ghosts of the Arena

## Pitch
A cute, turn-based deckbuilding RPG set in a Roman amphitheater. You manage a troupe of tiny gladiators. Your past runs come back as ghosts. Between battles, the arena keeps earning gold while you''re away.

## Story
**Prologue.** Rome''s grandest amphitheater is failing. The crowds are bored and the emperor is angry. You are Lanista Pip, a young trainer who inherits a run-down gladiator school with three chubby recruits and a talking goat mascot.

**Act I: Sand and Sawdust.** You win small fights and earn the crowd''s favor. You learn that the arena floor hides a sealed staircase.

**Act II: The Undercroft.** Beneath the stands lie dungeons of old beast pens, forgotten tombs, and flooded cisterns. Fallen gladiators haunt them. Their spirits replay their last battles, and you can learn from them.

**Act III: The Emperor''s Games.** A cursed laurel wreath has been feeding on the crowd''s cheers. Your ghost troupe, made of your own past runs, faces it in a final spectacle.

**Epilogue.** The arena becomes a beloved festival ground, and your legend is carved into the stone.

## Core Gameplay

### 1. Deckbuilding
- Each gladiator has a deck of **action cards**: Strike, Shield Bash, Net Throw, Taunt, Crowd Cheer.
- Reward cards drop after fights. Merchants sell more, and you can trade or destroy cards.
- Cards fall into three families:
  - **Steel**: attack and defense.
  - **Spectacle**: crowd meter and buffs.
  - **Omen**: gambling and curses.

### 2. Turn-Based Strategy Battles
- Fights play out on a small grid arena with pillars, sand pits, and trapdoors.
- Each turn you spend energy to play cards and move units.
- You direct a squad of 3-4 units at once. This is the lighter "RTS-style" layer: you give orders and squads carry them out.
- The **Crowd Meter** fills as you play flashy combos. At full, it triggers an emperor''s thumbs-up and grants a powerful effect.

### 3. RPG Progression
- Gladiator classes: **Murmillo** (tank), **Retiarius** (control), **Thraex** (fast striker), **Medicus** (support).
- Gear, talents, and cute cosmetic outfits, such as helmets with tiny plumes.
- Bonds between units unlock duo cards.

### 4. Dungeons
- The undercroft is a run-based dungeon crawl with a branching map:
  - Battle, elite, shop, shrine, and mystery rooms.
  - Bosses include the Mosaic Minotaur and the Bath-House Hydra.
- Permanent unlocks carry over between runs.

### 5. Ghost Replays
- Every dungeon run is recorded.
- Your past runs return as **ghosts**: ally units that replay your earlier decisions.
- Ghosts appear in three ways:
  - **Ally ghost**: summon a past run''s squad as a one-time helper.
  - **Rival ghost**: face a friend''s or your own best run in an arena duel.
  - **Study mode**: watch a replay and copy one of its cards.
- Ghosts are translucent and cute. They wear little sheet-ghost togas.

### 6. Idle Layer
- Your **Ludus (gladiator school)** runs when you''re offline:
  - Recruits train and earn XP.
  - Small arena shows earn gold, fame, and card packs.
  - Ghosts can be assigned to "haunt" shows for bonus income.
- Come back to a report of what happened.
- Spend the income on upgrades: barracks, forge, bathhouse, and the goat''s snack bar.

## Game Loop
1. Collect idle rewards.
2. Upgrade the Ludus and tune your decks.
3. Enter the undercroft or an arena bout.
4. Fight, draft cards, and record the run.
5. Turn the run into a ghost for later use.
6. Repeat with a stronger squad.

## Art and Tone
- **Style:** soft pastel, chibi proportions, rounded shapes.
- **Setting:** sun-warmed marble, sand, banners, and laurel wreaths.
- **Tone:** warm and comedic. Fights are cartoonish, with no gore and lots of confetti.
- **Audio:** playful lyre and brass, plus crowd cheers that react to your combos.

## Unique Selling Points
- Your past runs become allies and rivals.
- Cute art paired with deep card-and-grid tactics.
- Short sessions and long-term idle progress, so it suits both active and casual play.', 'rpg, turn-based strategy, idle', 'cute, rts, deckbuilding, turn-based', '16 core cpu, 64 gb ram, no excuses', '2002-01-06 09:00:00+00'),
('Gravebloom', 22.21, '# Verdant Gravity: Greenhouse Dome

## Overview
A 3D fantasy **management-simulation** with **auto-battler** combat and **roguelike** runs. You tend a magical greenhouse dome, craft gear from what you grow, and bend gravity to power your garden and your army. Play PvE for progression or PvP for ranking.

## Story
### Prologue: The Last Dome
The world outside has broken. Floating islands drift, storms tear up the soil, and gravity is unstable. One glass dome still holds a living garden. It is the last refuge of the Old Botanists, who built it around a **Gravity Heart**, a crystal that keeps their plants alive.

### Inciting Incident
The Heart is cracking. Each crack opens a **Rift** that leaks warped gravity and hostile creatures, such as twisted vines, spore-wraiths, and gravity-drunk beasts. You are the new Warden. You must keep the dome growing and defend it until you can repair the Heart.

### Arc
1. **Sprouts:** you learn the basics of growing, crafting, and gravity control.
2. **Rifts:** each run into a Rift reveals more about the Botanists.
3. **The Truth:** the Heart was never a machine. It is a sleeping guardian, and the Botanists caged it.
4. **Choice:** repair the Heart, free it, or merge with it. Each ending changes the dome''s future.

## Core Gameplay Loops
### 1. Management (Dome Layer)
- Build and expand **biomes**: desert, swamp, crystal cavern, and sky orchard.
- Manage water, light, soil, and mana flow.
- Assign **Gardener Spirits** and hire allies.
- Balance resources against threats and time.

### 2. Simulation (Living Ecosystem)
- Plants grow, cross-pollinate, mutate, and spread.
- Weather cycles and pests affect yields.
- Gravity changes how water flows, how seeds fall, and where roots grow.

### 3. Crafting
- Turn harvests into **potions, armor, weapons, and living constructs**.
- Combine rare mutations to unlock recipes.
- Gear has traits, such as *Thornguard* or *Featherfall*, that change how units fight.

### 4. Auto-Battler Combat
- Before a fight, place your units on the grid and set their gear and formation.
- Fights then run automatically.
- Units include plant golems, beast allies, and spirit knights.
- Synergies reward themed teams, such as a Bloom, Decay, or Storm build.

### 5. Gravity Manipulation
- **In the dome:** flip gravity on plots to grow ceiling gardens, move water, or speed harvests.
- **In battle:** use limited **Gravity Pulses** to pull enemies together, launch units, or float the whole field.
- **In crafting:** low-gravity and high-gravity brewing produce different results.

## Modes
### PvE Roguelike Runs
- Enter procedurally generated Rifts with a squad.
- Choose branching paths, such as shops, events, elites, and bosses.
- If you fall, you keep some seeds and knowledge, but lose the run''s loot.
- Meta-progression unlocks new plants, units, and dome upgrades.

### PvP Arena
- Send your squad against other players'' dome-built armies.
- Seasonal ladders reward rare seeds and cosmetics.
- Gravity Pulses add tactical depth and comeback plays.

## Visual and Audio Style
- **3D stylized fantasy:** glowing flora, glass architecture, and floating debris beyond the dome.
- **Mood:** warm and calm in the garden, tense and strange in the Rifts.
- **Music:** soft ambient tones that turn dramatic in combat.

## Progression
| Layer | Goal | Rewards |
|---|---|---|
| Dome | Grow and upgrade | Biomes, efficiency, passive income |
| Runs | Clear Rifts | Seeds, materials, story |
| Crafting | Discover recipes | Gear, synergies |
| PvP | Climb ranks | Cosmetics, rare mutations |

## Unique Selling Points
- A living greenhouse that feeds directly into your combat strength.
- Gravity as a tool for farming, crafting, and fighting.
- Short, replayable roguelike runs alongside long-term base building.
- Tactical auto-battles where preparation matters more than reflexes.

## Tagline
*"Grow the garden. Bend the world. Save the last dome."*', 'management, simulation, auto battler', 'pve, 3d, fantasy, roguelike, pvp', 'rtx 4070, 32 gb ram, nvme ssd', '1997-04-10 09:00:00+00'),
('Dunemirage', 7.51, '# Sands of Mirage

*A retro-anime hidden object sandbox set in the endless Sahara dune sea.*

---

## Overview

| Field | Details |
|---|---|
| **World** | Sahara dune sea |
| **Genres** | Hidden object, sandbox, visual novel |
| **Tags** | Simulation, adventure, anime, retro |
| **Mechanics** | Pity system, main quest chains |
| **Look** | 16-bit pixel art with anime portraits and a warm CRT-style palette |

---

## Premise

Long ago, a sea of water covered the Sahara. Now it is a sea of dunes, and it hides the ruins of the drowned cities beneath it.

You play **Amira**, a young cartographer-archaeologist. She inherits her missing mentor''s caravan and an unfinished map. The map is called the *Mirage Atlas*. Its lines redraw themselves every night, and no one knows why.

---

## Story Structure

### Act I: The Inherited Caravan
- Amira wakes in an oasis camp with a broken compass and a half-burned journal.
- She meets her first crew members:
  - **Kael**, a sarcastic camel handler.
  - **Noor**, a silent nomad glassblower.
- **Goal:** find the first buried waypoint and prove the Atlas is real.

### Act II: The Shifting Sea
- Dunes reshape the world with every storm, so no map stays valid for long.
- Rival treasure guilds and a secretive order called **The Veiled Cartographers** begin hunting the Atlas.
- Personal arcs unfold through visual-novel scenes at campfires, markets and ruins.

### Act III: The Drowned Capital
- Amira reaches the lost city of **Sahr-Ul**, the source of the Atlas.
- The final choice decides whether the desert stays a desert or the ancient sea returns.
- **Endings:** *Restoration*, *Eternal Dune*, *Wanderer''s Peace* and a hidden *True Atlas* ending.

---

## Core Gameplay

### Hidden Object Exploration
- Ruins, bazaars and tombs appear as detailed pixel-art scenes.
- The player searches for relics, glyph fragments and clues.
- Items are listed as riddles, for example *"something that holds the last drop of rain."*
- Some objects only show at certain times of day, such as moonlight glyphs or noon glints.

### Sandbox Simulation
- **Caravan management:** water, food, camel stamina and morale.
- **Free travel:** roam the procedurally shifting dunes with no fixed route.
- **Crafting and trade:** turn found relics into tools, glass lenses and water stills.
- **Base building:** upgrade oasis outposts that act as safe hubs.
- **Weather systems:** sandstorms, heat waves and cold nights change visibility and travel risk.

### Visual Novel Layer
- Branching dialogue with companions, merchants and rivals.
- Choices affect relationships, available quests and endings.
- Anime-style portraits show expressions that change with the mood of the scene.

---

## Main Quest Chains

| Chain | Theme | Reward |
|---|---|---|
| **The Broken Compass** | Recover the mentor''s trail | Navigation upgrades |
| **Voices in the Glass** | Noor''s past and the glass-memory relics | Vision tools, new companion abilities |
| **The Guild Wars** | Choose or betray factions | Trade routes, faction gear |
| **The Veil Unraveled** | Uncover the Cartographers'' secret | Access to Sahr-Ul |
| **Tide of Sand** | Final chain | Ending selection |

Each chain has linked steps, so later quests depend on earlier choices. Sandbox exploration fills the gaps between chapters.

---

## Pity System

The game rewards persistence, not luck.

- **Relic search pity:** every failed search in a scene raises a hidden "Fortune" meter. When it fills, a rare relic is guaranteed to appear.
- **Guaranteed rare finds:** after a fixed number of dig attempts without a rare item, the next one is a legendary artifact.
- **Storm mercy:** after several harsh storms in a row, the game favors calm weather and a nearby oasis.
- **Visible progress:** a small "Mirage Meter" in the UI shows how close the next guaranteed reward is.

---

## Art and Audio

- **Visuals:** limited-palette pixel art in amber, turquoise and dusk violet. Dune animations, heat shimmer and starry night skies.
- **UI:** retro parchment and brass, styled like an old adventure game.
- **Music:** chiptune-meets-oud themes. Each companion has a leitmotif.
- **Sound:** wind, camel bells, sand crunch and glass chimes.

---

## Why Play

- Cozy, meditative desert exploration with mystery at its core.
- A story-driven sandbox where wandering and narrative feed each other.
- Fair progression from the pity system, so no run is wasted.
- A nostalgic retro feel with modern anime storytelling.', 'hidden object, sandbox, visual novel', 'simulation, adventure, anime, retro', 'high-end gpu, 32 gb ram, and a good cooling plan', '2006-06-01 09:00:00+00'),
('Prism Runner', 20.36, '# Crystal Cavern Circuit

*A low-poly cyberpunk action RPG roguelite with racing, fighting, and horror.*

---

## Overview

| Field | Details |
|---|---|
| **World** | Crystal cavern |
| **Genres** | Action RPG, roguelite, casual |
| **Tags** | Low poly, horror, fighting, racing, cyberpunk |
| **Mechanics** | Time trials, portals |
| **Session length** | 10-20 min per run |

**Pitch:** You are a courier-racer in a neon-lit cyberpunk mining colony built inside a giant crystal cavern. Every run, you dive through unstable portals, race against the clock, and fight the things that live in the dark. Die, and the cavern rearranges itself.

---

## Story

### Act 1: The Glow
Deep under a dead planet''s crust, the megacorp **Prismatech** built *Facet City*. It is a neon sprawl carved into a huge geode and powered by **resonance crystals**. The crystals hum, and lately they whisper.

You are a **Runner**. You are a low-rent courier with a cybernetic spine-rig and a hover-bike. Prismatech pays you to deliver crystal shards through the cavern''s tunnels.

### Act 2: The Fracture
A quake splits the cavern. Portals tear open between distant tunnels. Some lead to shortcuts. Others lead to **the Hollow**, a dark mirror of the cave where crystal-infected creatures lurk. Runners who enter don''t come back the same, or at all.

### Act 3: The Heart
Rumor says a **Heart Crystal** sits at the cavern''s core and feeds the portals. Prismatech wants it harvested. The infected want it awakened. You just want out. Each run takes you deeper toward the truth. The Heart is alive, and it is using you to move.

---

## Core Gameplay Loop

1. **Launch** from the hub garage.
2. **Race** through a procedurally arranged tunnel course against a timer.
3. **Fight** ambushes and mini-bosses at checkpoints.
4. **Portal-hop** to skip ahead, or gamble on a risky Hollow portal for better loot.
5. **Finish or die** and bank resources.
6. **Upgrade** the bike, the rig, and your build, then go again.

---

## Mechanics

### Time Trials
- Each tunnel segment has a **par time**.
- Beating par gives **time bonuses** and better loot tiers.
- Missing par drains your **Stability** meter, which makes the Hollow bleed in.
- Ghost replays of your best runs and of friends'' runs are available.

### Portals
- **Blue portals** are safe shortcuts with fixed exits.
- **Red portals** are Hollow gambles with a random exit, elite enemies, and rare rewards.
- **Chain portals** link 2-3 jumps and reward momentum and speed.
- Some portals need a **shard key** dropped by a defeated enemy.

### Combat (Fighting)
- Fast, readable melee with a **crystal blade** and **rig-gauntlets**.
- Fight on the bike (sideswipes and rams) or on foot (combos, dodges, parries).
- **Resonance meter:** perfect dodges and hits charge special attacks.

### Racing
- Drift, boost, and wall-ride on crystal surfaces.
- Track hazards include falling stalactites, laser grids, and collapsing floors.
- Racing is casual-friendly, with forgiving handling and assist options.

---

## RPG and Roguelite Progression

### In-Run
- Pick **1 of 3 mods** at each checkpoint (bike, blade, or rig).
- Find **crystal relics** with strong synergies.
  - *Example:* "Echo Drift" leaves a damaging trail during drifts.
  - *Example:* "Phase Blade" lets slashes pass through shields.
- Manage **risk and reward** between safe and Hollow routes.

### Meta (Between Runs)
- **Garage upgrades:** engine, armor, boost capacity.
- **Skill tree:** three branches.
  - *Velocity:* speed and time bonuses.
  - *Edge:* melee and parry.
  - *Resonance:* portals and crystal powers.
- **Story unlocks:** each boss defeated opens new cavern layers.
- **Permadeath-lite:** you lose run loot but keep currency, blueprints, and lore.

---

## Horror Elements

- **Low-poly dread:** chunky, faceted shapes, flat shading, and heavy fog. Fewer details leave more to imagination.
- **The Hollow:** the lights die and only crystal glow remains.
- **Enemies:**
  - *Glassbacks:* crawlers that shatter into shards.
  - *Whisperers:* invisible until you hear them, and they mimic your engine sound.
  - *The Refraction:* a stalker boss that shows up as many reflections and only one is real.
- **Audio-driven scares:** the crystal hum rises when danger is near.
- Horror stays stylized and non-gory to fit the casual tone.

---

## Art and Audio

- **Visuals:** low-poly geometry, neon magenta, cyan, and violet against black rock, and emissive crystals as the main light.
- **Cyberpunk touches:** holo-ads on cave walls, mining rigs, and grimy tech-shanties.
- **Music:** synthwave and dark ambient. It is fast and driving in races, and sparse and eerie in the Hollow.

---

## Zones

| Zone | Theme | Feature |
|---|---|---|
| **Facet City Outskirts** | Neon slums | Tutorial, easy time trials |
| **Amethyst Veins** | Purple tunnels | Drift-heavy racing |
| **Mirror Halls** | Reflective crystal | Illusion puzzles, the Refraction |
| **The Hollow Depths** | Dark, infected | Horror focus, high risk |
| **The Heart** | Final zone | Portal maze and final boss |

---

## Bosses

1. **Foreman Vex:** a corporate enforcer on a heavy mining rig.
2. **The Refraction:** a mirror-stalker.
3. **Choir of Glass:** a swarm boss you fight while racing.
4. **The Heart:** a multi-phase fight combining race, fight, and portal-jumping.

---

## Casual Accessibility

- Auto-drift and assist modes.
- Adjustable difficulty and timer leniency.
- Short runs, quick restarts, and no punishing grind.
- Horror intensity slider (jump scares on or off).

---

## Target Experience

*"Fast like a racer, sharp like a brawler, and eerie like a cave with something in it."*', 'action rpg, roguelite, casual', 'low poly, horror, fighting, racing, cyberpunk', 'rtx 4070, 32 gb ram, nvme ssd', '1990-12-30 09:00:00+00'),
('Vessa''s Perch: Dice & Rope', 2.88, '# Cliffhanger Hollow

## Overview
**Cliffhanger Hollow** is a pixel-art tactics game. Every frame is hand-drawn from a top-down view. You guide a small band of villagers through a cliffside town. They sneak past an occupying force, solve environmental puzzles, and win fights with a deck of cards and a handful of dice.

- **Genres:** turn-based strategy, auto battler, puzzle
- **Perspective:** top-down, pixel graphics, hand-drawn
- **Core hooks:** stealth, deck building, dice rolling

---

## Story

### Prologue: The Long Drop
The village of **Vessa''s Perch** clings to a sheer sea cliff. Its stairs, rope bridges, pulley lifts, and terraced rooftops all lean out over the void. For generations the villagers hauled salt and glowing sea-glass up from the rocks below.

One night, the **Ashen Toll**, a mercenary guild, seizes the lower terraces. They cut the lifts and post sentries on every bridge. The elders are locked in the clock tower.

### Act structure
1. **The Lower Terraces:** Learn stealth and basic tactics as you reach the first safehouse.
2. **The Rope Quarter:** Bridges can be cut, rerouted, or turned into traps.
3. **The Glass Foundry:** Mixed fights and heavy puzzles. You collect rare cards here.
4. **The Clock Tower:** Free the elders and confront the Toll''s captain, **Marrow Vane**.

### Themes
Community against occupation. Small tools and clever plans win over brute force. The cliff is always a threat, and it also works as a weapon.

---

## Gameplay

### 1. Stealth and exploration (turn-based, top-down)
- The map is a grid of terraces, stairs, and bridges. You and the enemies move in alternating turns.
- Sentries have visible **vision cones** and patrol routes.
- Noise matters. Running, fighting, and rolling dice on stone all make sound.
- Shadows, laundry lines, and crates give cover.
- Staying unseen earns bonuses, such as a free first strike, extra loot, and better card rewards.

### 2. Puzzles
- **Pulley lifts:** Route counterweights to move platforms.
- **Bridge logic:** Rotate, cut, or lock ropes to build safe paths and lure guards onto weak planks.
- **Lantern and mirror puzzles:** Redirect light to distract guards or open gates.
- **Tide-and-wind timing:** Some routes exist only on certain turns.
- Solutions often give stealth shortcuts. They can also add new cards to your deck.

### 3. Auto battler (combat)
When you are spotted, or when you start a fight on purpose, the game switches to an **auto battle**.
1. **Deploy phase:** Place your units on a small tactical grid. Play **deck cards** to set formations, buffs, and traps.
2. **Roll phase:** Roll your **dice pool**. Results set initiative, crit chances, and special triggers.
3. **Auto-resolve:** Units fight on their own according to their roles and your setup. You watch the result and can''t steer it mid-fight.
4. **Aftermath:** Injuries, loot, and noise carry over to the exploration map.

Cliff edges count as terrain. Knockback and pushes can end a fight instantly.

### 4. Deck building
- Each hero has a **starter deck** tied to their class.
- Card types:
  - **Tactic:** formations and orders.
  - **Gear:** temporary weapons and tools.
  - **Trick:** stealth and distraction effects.
  - **Village:** support from NPCs you have rescued.
- Between missions you can cut, upgrade, and combine cards at safehouses.
- Small decks give consistent draws. Big decks give flexibility.

### 5. Dice rolling
- You earn and craft **dice** with different faces, such as Guard, Strike, Shadow, and Luck.
- Dice are used to:
  - Resolve risky actions like jumping a gap or picking a lock.
  - Drive combat initiative and crits.
  - **Reroll** through card effects.
- Trade-off: powerful dice are loud, and quiet dice are weak.

---

## Characters (starting party)
| Hero | Role | Playstyle |
|---|---|---|
| **Tamsin** | Rope-runner | Fast scout who uses traversal cards and cuts ropes |
| **Old Brek** | Salt-hauler | Heavy tank with a shove-off-the-cliff toolkit |
| **Wren** | Glass-blower | Ranged support who makes lights, decoys, and smoke |
| **Ilo** | Bell-ringer''s kid | Wildcard with dice-manipulation and luck cards |

---

## Progression
- **Safehouses:** Deck editing, dice crafting, and healing.
- **Village restoration:** Rescued NPCs unlock shops, new card packs, and passive bonuses.
- **Optional missions:** Sabotage, rescue, and heist maps with unique rewards.
- **Difficulty:** Higher tiers add more patrols, tighter noise limits, and tougher enemy decks.

---

## Visual and Audio Style
- Hand-drawn pixel sprites with visible brush texture.
- A warm palette of sea-glass greens and lantern oranges, set against cold cliff grays.
- Cards are illustrated in an ink-and-watercolor look.
- Music is a soft folk melody that turns tense during alerts. Wind and waves are constant in the background.

---

## Design Pillars
1. **Plan quietly, execute cleverly.** Stealth and puzzles are the first choice, and combat is the fallback.
2. **Luck is a resource.** Dice add risk, and cards give you ways to control it.
3. **The cliff is a character.** Height, edges, and ropes shape every map.
4. **Small victories add up.** Each rescued villager visibly improves the town.

---

## One-line pitch
*Sneak, solve, and scheme up a cliffside village. Build your deck, roll your dice, and take back your home one terrace at a time.*', 'turn-based strategy, auto battler, puzzle', 'stealth, turn-based, top-down, pixel graphics, hand-drawn', '16 core cpu, 64 gb ram, no excuses', '2012-09-10 09:00:00+00'),
('Kodama Neon Dojo', 12.44, '# Neon Blade Dojo

## Overview
**World:** A samurai dojo swallowed by a cyberpunk megacity
**Genres:** Hidden Object, Stealth, Casual
**Tags:** Tower Defense, Cyberpunk, Multiplayer, Party Game, Adventure
**Mechanics:** Power-ups, Unit Production
**Players:** 2-8 online or local party play
**Session length:** 10-15 minutes per round

---

## Story

### Prologue: The Last Dojo
Neo-Edo is a city of holograms, drones, and corporate towers. At its center sits Kōgetsu Dojo, an ancient wooden temple. Its owner, Master Reiko, refuses to sell the land to the Arasaka-Ryu Corporation.

### The Theft
Corporate ninja-drones break in one night. They steal the **Nine Kodama Cores**. These glowing relics power the dojo''s spirit-guardians. The cores are now hidden in the dojo''s rooms, disguised as everyday objects.

### The Race
Master Reiko calls her students. They must find the cores before dawn, and they must keep the dojo standing while they search.

---

## Core Gameplay

### 1. Hidden Object Phase (Search)
- Scan rooms such as the tatami hall, koi garden, armory and rooftop shrine.
- Find items hidden in the scenery, for example a *neon lantern*, a *cracked katana* or a *holo-fan*.
- Some objects are **Core Fragments**. They trigger rewards and reveal clues.
- Rooms shift with the day/night cycle and glitch effects, so hiding spots change each round.

### 2. Stealth Phase (Infiltration)
- Move through shadows, paper screens and vents.
- Avoid drone searchlights, laser tripwires and guard patrols.
- Use silent steps, smoke bombs and cloaking tech.
- If you are spotted, an alarm sounds and enemy waves speed up.

### 3. Tower Defense Phase (Defense)
- Waves of corporate drones and cyber-ronin attack the dojo gates.
- Place defenses along the courtyard paths:
  - **Shuriken Turrets:** fast, low damage
  - **Plasma Torii Gates:** slow and stun enemies
  - **Bamboo Snare Fields:** trap ground units
  - **Spirit Bells:** buff nearby towers

### 4. Unit Production (Dojo Training)
- Spend **Ki Energy** earned from found objects.
- Train allied units:
  - **Apprentice Blades:** cheap frontline fighters
  - **Shadow Scouts:** reveal hidden objects and traps
  - **Mecha-Monks:** tanky healers
  - **Drone Tamers:** hack enemy drones for a short time
- Units can be assigned to search, sneak or defend.

---

## Power-Ups
| Power-Up | Effect |
|---|---|
| **Sakura Sight** | Highlights hidden objects for 10 seconds |
| **Ghost Robe** | Invisible to cameras for 8 seconds |
| **Overclock Katana** | Doubles tower fire rate |
| **Ki Surge** | Speeds up unit production |
| **Glitch Bomb** | Disables enemy drones in an area |
| **Sabotage Pulse** | (Multiplayer) Scrambles a rival''s screen |

---

## Multiplayer and Party Modes

### Co-op: *Defend the Dojo*
Players split into roles: Seekers, Sneaks and Builders. They share resources and win together.

### Versus: *Rival Dojos*
Teams race to find the most cores. They can sabotage each other with power-ups.

### Party: *Traitor Ronin*
One player secretly works for the corporation. The others must find the traitor through clues and voting while defending the dojo.

### Mini-games
Short rounds between waves, such as *Sushi Bot Rush*, *Blade Dodge* and *Hack the Lantern*.

---

## Adventure Progression
1. **Chapter 1, The Tatami Hall:** tutorial and basic search
2. **Chapter 2, Koi Garden:** first stealth missions
3. **Chapter 3, The Armory:** unlock towers
4. **Chapter 4, Rooftop Shrine:** boss fight against Drone Shogun
5. **Chapter 5, Corporate Tower:** final infiltration and the nine cores

---

## Visual and Audio Style
- **Art:** Bright neon lights over traditional Japanese architecture, in a cartoon casual style
- **Music:** Synthwave mixed with shamisen and taiko drums
- **Tone:** Light-hearted, funny and accessible for all ages

---

## Ending
After the nine cores are restored, the dojo''s spirit-guardians awaken. They drive the corporation out of the district. Master Reiko declares the dojo a sanctuary, where old tradition and new technology can coexist.', 'hidden object, stealth, casual', 'tower defense, cyberpunk, multiplayer, party game, adventure', 'gtx 1060, 8 gb ram, ssd recommended', '2004-07-30 09:00:00+00'),
('Hollow Choir', 17.48, '# Jungle Temple: Echoes of the Deep

## Overview
A hybrid **real-time strategy / horror / hack and slash** set in a decaying jungle temple. You lead an expedition into a temple that reacts to sound. Every choice, and every note you play, changes the temple.

## Story

### Prologue: The Silent Drum
Your expedition follows a legend of a temple that "sings the dead awake." You are the expedition leader, and your party is a small band of scouts, porters, a scholar, and a healer. At the gate you find a broken drum. When you play it, the jungle goes quiet, and something below begins to answer.

### Act I: The Descent
The party camps at the temple''s outer ring. You build a base, assign workers, and send scouts to map the ruins. Night falls, and the first whispers start. Your choices here set the tone:
- Loot the shrines quickly, or leave offerings.
- Save a wounded stranger, or use his supplies.

### Act II: The Chorus
Inside, the halls are living instruments. Each chamber has a *melody* that controls its traps, guardians, and horrors. You learn to play, mute, or rewrite these melodies. The temple''s keepers are the **Hollow Choir**, cursed priests who hunt by sound.

### Act III: The Final Note
At the core lies the **Heart Drum**, which feeds on fear. You can:
1. **Silence it** and free the jungle, at a heavy cost.
2. **Command it** and become the new temple master.
3. **Feed it** and unleash the Choir on the world.

## Gameplay

### Real-Time Strategy (Base Layer)
- Build camps, watchtowers, workshops, and shrines.
- Assign workers to gathering, crafting, and scouting.
- Manage **morale and fear**, since panicked workers attract the Choir.
- Sound is a resource: loud building attracts enemies.

### Turn-Based Strategy (Tactical Layer)
- Entering a chamber switches to **turn-based tactics**.
- Squad members act on a rhythm grid, and actions land on beats.
- Chain moves in time to earn bonus damage, extra movement, or stealth.
- Missing the beat wakes nearby horrors.

### Hack and Slash (Combat)
- Take direct control of a hero for fast, brutal melee.
- Weapons include machetes, obsidian blades, and bone-drum clubs.
- Combos match the room''s melody, so timing matters.
- Enemies include the Hollow Choir, vine wraiths, and echo beasts.

### Horror
- Fear is a meter. Darkness, silence, and losses raise it.
- High fear causes hallucinations, false alarms, and disobedient units.
- Some threats can''t be fought and must be avoided by staying silent.

### Music
- Learn **songs** from temple murals and enemy chants.
- Songs work as spells: calm, rally, stun, reveal, or lure.
- The dynamic soundtrack reacts to your actions, and enemies respond to it.

### Choices Matter
- Each expedition member has loyalties, secrets, and a personal arc.
- Decisions carry across acts: who lives, who betrays you, and which melodies the temple remembers.
- There are **5 endings**, shaped by morality, fear, and the songs you learned.

## Systems

### Potions and Consumables
| Item | Effect |
|------|--------|
| Healing Tonic | Restores health |
| Calm Draught | Lowers fear |
| Echo Oil | Coats weapons to boost song effects |
| Silence Salve | Muffles noise for one chamber |
| Bloodroot Brew | Raises damage, but increases fear |

- Ingredients come from the jungle, and crafting takes place at the camp alchemist.

### Shops and Trading
- Meet wandering traders, a smuggler, and a ghostly merchant who accepts memories as payment.
- Trade relics, herbs, and songs.
- Prices shift with your reputation and the temple''s mood.
- Some deals unlock hidden routes or cursed gear.

## Tone and Style
- **Visuals:** lush greens against cold stone and glowing glyphs.
- **Audio:** tribal percussion, whispers, and layered choirs.
- **Mood:** wonder that turns to dread as you go deeper.

## Tagline
*"The temple is listening. Choose your notes wisely."*', 'real-time strategy, horror, hack and slash', 'music, turn-based strategy, choices matter', 'rtx 4070, 32 gb ram, nvme ssd', '1994-03-29 09:00:00+00'),
('Last Call at Perdition', 19.31, '# Dead Man''s Tab

*A cartoon horror-strategy saloon survival game*

## Pitch
You run the last saloon in the ghost town of **Perdition Gulch**. Every night, the dead crawl out of the desert and want a drink, and a piece of you. Serve them, fend them off, rebuild, and survive until dawn. Play solo or with up to 4 friends.

## Story
**Act 1: The Last Round.** A cursed poker game wiped out the town. Only the saloon still has lights on. You inherit it from a bartender who vanished, leaving behind a ledger of debts owed to *something below the cellar*.

**Act 2: Bad Company.** Each night a new undead clientele arrives: skeleton cowboys, banshee singers, tumbleweed wraiths, and a headless sheriff. Some can be bribed, some soothed with the right drink, and some can only be destroyed.

**Act 3: Paying the Tab.** The cellar holds a demon banker who calls in the debt. The final week is a siege. The crew has to break the curse or become permanent staff.

## Core Loop
1. **Day (Clicker phase):** Tap to pour drinks, chop wood, pan for gold, and brew moonshine. Passive income grows as you upgrade.
2. **Dusk (Base-building phase):** Spend resources to build and upgrade the saloon.
3. **Night (Turn-based strategy phase):** Ghouls approach along a grid. You and your team place units and use abilities in turns.
4. **Dawn:** Tally the damage, pay the ledger, and unlock new options.

## Mechanics

### Clicker
- Tap the bar, still, and mine to earn **Coins**, **Whiskey**, and **Scrap**.
- Upgrades add auto-pourers, hired hands, and combo multipliers.
- Co-op: players can boost each other''s stations with timed "cheers".

### Base Building
- Grid-based saloon and yard. Build:
  - **Barricades:** cheap, and they break easily.
  - **Piano Trap:** stuns undead who like music.
  - **Holy Still:** makes blessed liquor for damage.
  - **Watchtower:** extends vision and range.
  - **Bunkroom:** raises crew health and morale.
- Buildings can be damaged at night and must be repaired.

### Match-Three (Combat Actions)
- Each turn, a **bottle board** holds whiskey, garlic, silver, gunpowder, and lantern oil.
- Matches produce combat effects:
  - **Gunpowder:** shots and explosions.
  - **Silver:** damage against specific monsters.
  - **Garlic:** area debuffs.
  - **Oil:** fire hazards on the map.
  - **Whiskey:** heals and boosts morale.
- Longer chains and combos trigger **Quick Draw** bonus turns.
- Co-op: players share the board, with one match per player per turn.

### Turn-Based Strategy
- Grid map with enemy paths, cover, and traps.
- Every character has a role: **Gunslinger**, **Barkeep**, **Preacher**, **Tinkerer**.
- Enemy intent is shown, so you can plan around it.
- Fear and Morale meters affect accuracy and panic.

## Survival Pressure
- Resources are scarce and the difficulty is high.
- Permadeath applies to crew members, but their ghosts can be recruited later at a cost.
- The **Debt Meter** rises each night. If it fills, the cellar door opens early.
- Random events include a plague of moths and a rigged card game.

## Co-op
- 1-4 players, with shared saloon management.
- Role synergy: one tends the bar, another plays defense, another builds, another handles supplies.
- Shared resources with a voting system for major spending.
- Revive downed friends with whiskey, at a risk.

## Art and Tone
- **Cartoon** look: thick outlines, rubber-hose animation, exaggerated faces.
- Dark humor. Monsters are creepy but goofy, and the jump scares are stylized.
- A twangy, haunted honky-tonk soundtrack that turns eerie as the night goes on.

## Difficulty and Progression
- **Hard by design:** limited turns, aggressive waves, and costly mistakes.
- Unlockables include new characters, saloon themes, recipes, and boss variants.
- New Game+ adds **Cursed Contracts**, which are optional modifiers with big rewards.

## Win and Lose
- **Win:** survive 10 nights and defeat the Demon Banker.
- **Lose:** the saloon falls, or the whole crew dies.', 'horror, turn-based strategy, clicker', 'survival, co-op, cartoon, difficult', 'office pc from the back of the warehouse', '1996-06-05 09:00:00+00'),
('Aurum Hum', 4.63, '# Harvest Protocol

*An idle beat ''em up tactical RPG on a wheat farm at the edge of the galaxy.*

---

## Premise

In 2317, the colony ship *Demeter* crash-lands on **Kernel-9**, a quiet, amber-lit planet. The only crop that survives in the alien soil is **Aurum Wheat**, a mutated grain that hums at night and stores data in its genome.

You play **Mara Voss**, the last certified agronomist aboard. You start with one rusty combine, a damaged AI named **SILO**, and a field that stretches past the horizon. The wheat grows on its own. Something in the fields is waking up, and it wants the harvest.

---

## Core Loop

| Phase | Genre | What You Do |
|---|---|---|
| **Grow** | Idle | Fields produce grain, energy and biomass while you are away |
| **Scout** | Exploration | Chart procedurally generated sectors of the farm and the wilds beyond |
| **Match** | Tile matching | Solve grain-tile puzzles to boost yields and charge abilities |
| **Defend** | Beat ''em up | Brawl through waves of hostile machines and mutated pests |
| **Command** | Tactical RPG | Position your crew on the grid in larger, planned battles |

---

## Story Structure

### Act I: Dust and Seed
- Repair the combine and wake SILO.
- Discover that the wheat responds to patterns, and that matching tiles "tunes" the crop.
- First threat: **Chaff Drones**, scavenger bots drawn to the harvest signal.

### Act II: The Humming Fields
- Explore deeper sectors and find ruins of an earlier colony that farmed the same wheat.
- Recruit survivors: a mechanic, an ex-marine and a botanist.
- Learn that the wheat is a **living archive** built by an ancient intelligence.

### Act III: The Reaping
- The intelligence, **The Thresher**, wants to "harvest" the colonists'' minds.
- Choose to destroy it, merge with it, or bargain with it.
- Your choices set the ending and shape a New Game+ farm.

---

## Gameplay Systems

### 1. Idle Farming
- Plots grow wheat in real time, and offline progress is calculated on return.
- Upgrade tracks: **irrigation, drones, silos, genetics**.
- Passive income pays for gear and crew training.

### 2. Tile Matching (Yield Puzzles)
- Board tiles: **Wheat, Water, Sun, Ore, Spark**.
- Chains of 3 or more boost crop output or charge combat skills.
- Special tiles include **Bio-Bombs** (clear a row) and **Harvest Blades** (double yield).
- Matches feed the other modes. Sun-matches speed up growth, and Spark-matches power attacks.

### 3. Beat ''Em Up Combat
- Side-scrolling fights across the fields, using the combine''s arms, scythes and mods.
- Combo chains, dodges and finishers.
- Bosses include the **Rust Scarecrow** and the **Locust Swarm Core**.

### 4. Tactical RPG
- Grid-based battles that mix crew abilities with terrain, such as wheat cover and irrigation trenches.
- Classes: **Reaper** (melee), **Botanist** (support), **Engineer** (turrets), **Scout** (range).
- Permadeath is optional for hardcore mode.

### 5. Procedural Generation
- Each sector is generated with its own biome, hazards and points of interest.
- Biomes: **Crystal Stubble, Glowing Marsh, Scrapyard Plains, Hollow Dunes**.
- Enemy waves, loot tables and story fragments vary from run to run.

---

## Tone and Art Direction

- **Visual:** warm golden fields against cold neon tech. Pixel art with soft lighting.
- **Audio:** ambient synths, wind and the hum of the wheat.
- **Mood:** cozy and casual on the surface, with growing unease underneath.
- **Narrative:** short log entries and campfire dialogue, easy to read in small sessions.

---

## Player Experience

- **Casual:** check in, collect, match a few tiles, and leave.
- **Engaged:** plan crew builds and push into deeper sectors.
- **PvE only:** cooperative-style progression with no competition. Events pit all players against shared threats, such as a **Global Blight**.

---

## Tagline

> *Sow the field. Fight the dark. Hear what the wheat is saying.*', 'idle, beat ''em up, tactical rpg', 'sci-fi, exploration, casual, narrative, pve', 'potato pc, no gpu needed', '1998-10-30 09:00:00+00'),
('Choir Ice', 14.11, '# Ring Station Tycoon: *Debris of Saturn*

## Logline
Build and run a mining and tourism station in Saturn''s rings. Something in the ice is awake, and it is learning how you run the place.

## Overview
| Field | Detail |
|---|---|
| Setting | Saturn ring station, a few decades from now |
| Genres | Tycoon, interactive fiction, horror |
| Style | Low poly, flat-shaded, harsh light and deep shadow |
| Players | 1-4, local multiplayer (shared screen or hot-seat) |
| Core loop | Build, manage, draw cards, survive, descend into the dark |

## Story

### Act I: Contract
You are a station director for a corporation called **Halcyon Ring Co.** You get a cramped hub, a few credits and a quota of water ice. The ring grinds past the windows and everything looks calm.

Crew messages and logs are written as branching interactive fiction. Your choices set morale, budget and trust. They also decide what the crew knows about the ring.

### Act II: Signal
Drills hit a dense pocket of ancient, non-natural ice. Strange signals start to play on the comms. Crew members report:
- voices repeating things they said in private
- corridors that are longer than yesterday
- colleagues who don''t blink

The corporation orders you to keep drilling.

### Act III: Descent
Sealed sections of the station open onto a **living structure** under the ice. The signal calls it *The Choir*. You must go in, and you can choose what to take from it or what to leave behind. The ending depends on how you treated your crew, how much the Choir has learned from you, and what you were willing to sell.

## Gameplay

### 1. Base Building (Tycoon)
- Place modules on a modular grid: habitats, refineries, docks, hydroponics, med bay, casino, observation deck.
- Manage power, oxygen, heat, cargo and crew schedules.
- Earn credits from ice, tourists and corporate contracts.
- Build fast for profit, or build safely. Overbuilt stations attract the Choir.
- Fear and stress spread through the station like a resource, and you can track them on an overlay map.

### 2. Deckbuilding
Your **station deck** represents policies, crew skills, equipment and events.

| Card type | Examples | Use |
|---|---|---|
| Crew | Engineer, Medic, Guard | Assign to rooms or missions |
| Tech | Airlock Seal, Flare, Scanner | Solve problems, gain advantages |
| Policy | Double Shifts, Quarantine | Trade profit against morale |
| Anomaly | Whisper, Hollow Ice | Harmful, but some carry powerful upsides |

- Draw a hand each day cycle and spend limited action points.
- Remove cards to thin the deck, or corrupt them to gain power at a cost.
- Corrupted cards change your fiction: crew begin to speak differently.

### 3. Dungeons
- Sealed sections and ring caverns are procedurally generated **dungeons**.
- Each run is a small squad of crew, and each crew member is a card.
- Rooms hold loot, story events, hazards or a Choir manifestation.
- Losing a crew member is permanent. Their card is lost, and their name is remembered in the station''s logs.

### 4. Cover System
- Tactical movement across low, mid and high cover objects.
- Enemies flank, whisper and distort sight lines, so cover can betray you.
- Light matters: flares and lamps push back the dark, and shadowed cover hides you from sight but not from sound.
- Decompression breaches can destroy cover and pull loose objects through the room.

### 5. Local Multiplayer
- **Co-op:** 2-4 players share the station, and each one controls a department (Ops, Security, Science, Finance).
- **Split roles in dungeons:** each player controls one squad member.
- **Secret objectives:** players may hold hidden goals, such as a corporate bonus or Choir sympathy, which allows betrayals.
- **Hot-seat mode:** players take turns as director while the others hold the crew''s fate.

## Horror Design
- Dread comes from uncertainty, not jump scares.
- The Choir mimics your UI, your crew''s voices and your past decisions.
- Silence is a warning. When the station goes quiet, something is close.
- Low poly art with a limited palette makes shadows readable but unsettling.

## Progression and Endings
- **Meta unlocks:** new modules, starting decks and corporate sponsors.
- **Endings:** Profit, Escape, Communion, Extinction, and one hidden ending for players who read every log.

## Visual and Audio Direction
- Low poly stations with clean shapes, bright warning lights and cold blue ice.
- Saturn fills the sky, and the ring is both beautiful and threatening.
- Ambient hum, distant choral tones and radio static form the soundtrack.

## Pitch Summary
*Run a station, manage a crew, build a deck and go into the dark. In the rings of Saturn, the ice is listening.*', 'tycoon, interactive fiction, horror', 'base building, deckbuilding, local multiplayer, low poly', 'high-end gpu, 32 gb ram, and a good cooling plan', '1994-10-07 09:00:00+00'),
('Hearthdrift', 22.80, '# Starward Hearth

*A generation-ship city builder with visual novel drama and an adults-only (18+) romance layer.*

## Premise
The colony ship **Hearth** has been in flight for 214 years. It has 40,000 descendants aboard, and its arrival is still 90 years away. You are the newly appointed **Steward**. You inherit crumbling districts, tired traditions, and an AI that doesn''t talk much.

## Setting
- **Ring districts:** farms, docks, markets, and the neon-lit Lantern Quarter.
- **Spine:** a long central transit artery, drivable end to end.
- **Art:** hand-drawn backgrounds, character portraits, and CG scenes with a warm, ink-and-watercolor look.

## Core Loops

### 1. City Builder (real-time)
- Place habitats, hydroponics, reactors, and clinics in an open-world ring.
- Manage air, water, power, morale, and population.
- Pause, speed up, or slow down time as needed.

### 2. Visual Novel (story)
- Talk with crew, engineers, diplomats, and residents.
- Choices shift the **Bond**, **Trust**, and **Faction** stats.
- Branching routes cover romance, rivalry, and mystery.
- Mature scenes are opt-in, consent-focused, and toggleable in settings.

### 3. Turn-Based Crises
- Hull breaches, riots, and system failures trigger tactical turn-based encounters.
- Assign crew by skill, positioning, and the bonds you''ve built.

### 4. Driving and Vehicles
- Drive haulers, rovers, and repair shuttles along the ring, through the spine, and outside on the hull.
- Missions include supply runs, evacuations, and races in the Lantern Quarter.
- Upgrade vehicles with parts crafted by your districts.

### 5. Gacha (Crew Summons)
- Spend **Cryo Tokens** to wake sleeper-crew from stasis pods.
- Rarities run from Common to Legendary.
- Each crew member has a skill, a vehicle affinity, and a personal story arc.
- Pity system: a guaranteed rare after 50 pulls.
- Tokens are earned in-game. There are no pay-to-win locks on the main story.

## Story Structure
| Act | Focus |
|-----|-------|
| I. Wake | Take the role of Steward and stabilize the first district. |
| II. Drift | Faction tension grows and a hidden sabotage begins. |
| III. Fracture | The ship splits politically, and your bonds are tested. |
| IV. Arrival | Choose the ship''s fate and reach one of many endings. |

## Key Characters
- **Iris**, the ship AI: dry humor and buried secrets.
- **Marek**, chief engineer: gruff, loyal, and overworked.
- **Sable**, Lantern Quarter broker: charming and dangerous.
- **Ovi**, farm-ring medic: gentle, and stronger than she looks.

## Progression and Replay
- New Game+ carries over crew, bond memories, and unlocked CG scenes.
- Multiple endings depend on faction balance, romance routes, and city health.

## Content Notes
- Adult content (18+) is gated behind an age check and an opt-in toggle.
- A "story-only" mode skips explicit scenes.

Want a shorter pitch, a store-page blurb, or a design doc for one system, such as the gacha economy?', 'city builder, visual novel, hentai', 'open world, real-time, hand-drawn, turn-based', 'office pc from the back of the warehouse', '2017-04-23 09:00:00+00'),
('Brinebeat', 8.16, '# Salt Mirror

*A detective-simulation roguelite where every case is solved by matching, shooting, and keeping time.*

---

## Logline
You are a salt-flat coroner-detective. Each night the flats erase the last crime scene, and you have one dawn to reconstruct the truth before the tide of brine takes it back.

---

## World: The Salt Flats

- **Setting:** A blinding white desert, a dried sea. At night it becomes a mirror of stars.
- **Atmosphere:** Silence, wind hum, distant generators, crunching salt underfoot. Sparse ambient drones, with a heartbeat pulse that drives the rhythm systems.
- **Hazard:** The **Brine Tide** is a slow flood rising from underground. It wipes evidence and spawns hostile *Crystallines*.
- **Hub:** *Outpost Halite*, a rusted mining camp. You manage it between runs.

---

## Story

### Act I: The First Body
A miner is found kneeling in the salt, encased in crystal. No footprints lead to or from the body. You are the last investigator the Outpost has left.

### Act II: The Pattern
Every victim carries a shard that hums a different rhythm. The rhythms are pieces of a single song, played by something under the flats.

### Act III: The Sea Remembers
The killer is not one person. It is the memory of the old sea, which is using human grudges as a voice. You choose whether to silence it, free it, or take its place.

**Endings:** Silence, Release, or Succession. Each is shaped by which suspects you saved or condemned.

---

## Core Gameplay Loops

### 1. Investigation (Interactive Fiction + Detective)
- Text-driven scenes with branching dialogue and interrogations.
- Clues are collected as **Evidence Tiles**.
- Lies show up as contradictions in a suspect''s statements. You press them at the right beat.

### 2. Deduction (Match-3)
- The **Deduction Board** is a grid of clue tiles: *Motive, Alibi, Weapon, Place, Witness, Salt*.
- Matching three or more forges a **Theory**, which unlocks new dialogue options.
- Chain reactions expose hidden links between suspects.
- Wrong matches raise **Doubt**, which the Tide feeds on.

### 3. Combat (Shooter + Soulslike)
- When the Tide rises, you fight through the flats in a third-person or top-down shooter.
- **Rhythm timing windows:**
  - Shots on the beat deal bonus damage.
  - Perfect dodges on the beat grant i-frames.
  - Reloads sync to the pulse.
- **Knockback:**
  - Heavy rounds push enemies into salt pits, geysers, or each other.
  - Enemy slams push you back, and you can be knocked into the Tide.
  - Environmental kills yield extra evidence.
- **Soulslike rules:**
  - Stamina-based actions and deliberate, punishing enemies.
  - Bosses (*The Drowned Foreman*, *The Choir of Halite*) have readable, beat-locked patterns.
  - On death, you drop your **Case Notes** at the death site. Recover them or lose them.

### 4. Outpost Simulation
- Manage power, water, ammo, and morale.
- Assign NPCs as gunsmith, medic, archivist, or informant.
- Upgrades unlock new tools: a UV lamp, a salt-sonar, and a metronome rifle.

---

## Roguelite Structure

| Element | Description |
|---|---|
| **Run** | One night: investigate, fight, and reach dawn. |
| **Death** | You wake at the Outpost. The case reshuffles, but core truths persist. |
| **Meta-progress** | Unlocked tools, relationships, and knowledge of the song. |
| **Procedural** | Crime scenes, suspect lies, and Tide routes vary each run. |
| **Boons** | Random *Echo* perks, such as bullets that ricochet on the beat. |

---

## Tags in Play

- **Shooter:** Rhythm-based gunplay with knockback physics.
- **Detective:** Interrogation, evidence, and deduction.
- **Atmospheric:** A haunting audiovisual identity of white void and star mirror.
- **Soulslike:** Lethal combat, dropped notes, and pattern-learning bosses.
- **Roguelite:** Repeated nights and permanent knowledge.

---

## Visual & Audio Direction

- **Visuals:** High-contrast white and pale blue by day. Neon-cyan reflections and deep black by night.
- **Audio:** Adaptive music where the environment *is* the metronome. Clues add new instrument layers to the score.

---

## Player Fantasy
*"I read the world like a song, and I shoot in time with its heartbeat to make the truth stand still."*', 'simulation, match-3, interactive fiction', 'shooter, detective, atmospheric, soulslike, roguelite', '2 gb ram and good vibes', '1997-03-27 09:00:00+00'),
('Ward Zero', 2.57, '# Wardless

## Overview
**Wardless** is a atmospheric fighting and interactive fiction sandbox set in a decaying, abandoned hospital. You explore, fight, and shape the story through your choices. The hospital is a living arena, and every corridor, ward, and shaft can be used for combat or survival.

- **Genres:** Fighting, Interactive Fiction, Sandbox
- **Tags:** Atmospheric, Controller Support, Fighting
- **Core Mechanics:** Weapon Attachments, Wall Running

---

## Story

### Prologue: Night Shift
You wake on a gurney in the flooded basement of St. Marrow General. It closed decades ago after a "containment incident" that no record explains. Your name tag is torn. Your memory is patchy. A dead intercom crackles: *"Patient 17, report to Ward Zero."*

### Act I: The Lower Wards
You scavenge the morgue, pharmacy and boiler rooms. Territorial factions hold the floors:
- **The Orderlies:** disciplined survivors who still follow the old shift rules.
- **The Relapsed:** twisted former patients who fight by instinct.
- **The Board:** a hidden group that wants the incident kept buried.

Each faction offers alliances, trades, or war.

### Act II: The Rising Floors
You climb toward the upper levels through collapsed stairwells and elevator shafts. Wall running opens shortcuts, ambushes and hidden rooms. Found journals, tapes and charts piece together what happened, and your choices decide whom you believe.

### Act III: Ward Zero
Ward Zero holds the truth about Patient 17. Depending on your allies, kills and mercy, the ending changes:
- **Discharge:** you escape and leave the secret buried.
- **Exposure:** you broadcast the truth and bring the Board down.
- **Admission:** you take over the hospital as its new master.

---

## Gameplay

### Combat
Combat is fast, physical and close-range, built for controller play.
- Light and heavy strikes, blocks, parries and grapples
- Environmental finishers, such as slamming enemies into equipment or pushing them down shafts
- Stamina and posture systems reward good timing over button mashing

### Weapon Attachments
Improvised weapons can be customized at workbenches or on the fly.
| Base Item | Example Attachments |
|---|---|
| IV pole | Blade tip, electrified coil |
| Crutch | Weighted head, hooked grip |
| Scalpel | Serrated edge, poison reservoir |
| Fire axe | Chain, spiked pommel |

Attachments change speed, reach, damage type and special moves.

### Wall Running
Run along walls to cross gaps, dodge attacks and flank enemies.
- Chain wall runs across corridors and atriums
- Attack from a wall run for aerial strikes
- Reach vents, rooftops and secret rooms

### Interactive Fiction
Dialogue, notes and terminal entries carry branching choices.
- Choices affect faction standing, available areas and endings
- Some story beats happen in text-driven scenes between fights
- Consequences persist across the whole playthrough

### Sandbox
There are no forced paths.
- Free roaming with persistent world states
- Set traps, lure factions into conflict, and rearrange the hospital
- Optional fight arenas, side stories and crafting

---

## Atmosphere
- Flickering emergency lights and dripping water
- Muffled, dissonant ambient sound that reacts to combat
- Environmental storytelling: abandoned beds, charts, patient drawings
- Dynamic silence, where quiet moments build tension before fights

---

## Controller Support
Full controller support is built into the design:
- Analog-friendly wall running and camera
- Mapped attachment swapping and quick-select radial menus
- Haptic feedback for impacts, parries and heartbeat tension

---

## Tagline
*"The hospital never closed. It''s still waiting for you."*', 'fighting, interactive fiction, sandbox', 'atmospheric, controller support, fighting', 'any toaster with a screen', '2001-06-14 09:00:00+00'),
('Encore Espresso', 9.68, '# Loop & Brew

*A minimalist time-loop cafe game that mixes fighting, rhythm and adventure. It is moddable and has RTS-style management.*

## Overview
- **World:** a small cafe where one day repeats forever.
- **Genres:** fighting, rhythm, adventure.
- **Tags:** moddable, RTS, minimalist.
- **Mechanics:** power-ups, minimap.
- **Style:** flat colors, a few shapes, and a soundtrack that is also the game clock.

## Story

### Act 1: The Same Tuesday
You play **Mira**, a barista. Every day at 07:00 the cafe bell rings and the day starts again. The loop ends at 19:00 when the espresso machine hums a single wrong note. Nobody else remembers the previous loops. Only you and a chalkboard menu that rewrites itself each morning remember them.

### Act 2: The Regulars
Six regulars visit each day. Each one carries a secret tied to the loop:
- **The Critic:** a rival who wants to shut the cafe down.
- **The Courier:** always late, and carrying a sealed package.
- **The Old Drummer:** he taps out the rhythm of the loop without knowing it.
- Three more are unlocked by talking to people across loops.

Each loop you learn a bit more. You use that knowledge to reach new dialogue and areas.

### Act 3: The Wrong Note
The humming note comes from a sealed room under the cafe. To open it, you have to master the cafe''s rhythm. Then you have to fight the **Timekeeper**, a shadow that feeds on repeated days. If you beat him, the day ends and Wednesday finally arrives.

## Gameplay

### Rhythm (core loop)
- Brewing, serving and cleaning are all rhythm inputs on 4 lanes.
- Perfect timing gives better drinks, more tips and a higher **Groove** meter.
- The beat speeds up as the day goes on.

### RTS Management
- You direct staff (**baristas, bakers, runners**) with simple point-and-click orders.
- You assign stations, set priorities and react to rushes in real time.
- Good management frees up time for exploring and fighting.

### Fighting
- Trouble happens inside the cafe: **rowdy customers, health inspectors, shadow minions**.
- Combat is a short 1v1 duel. Attacks are timed to the beat, and combos are strings of rhythm inputs.
- Blocking works like hitting a perfect note.

### Adventure
- Explore the cafe, the alley and the street.
- Talk to regulars, find items and solve small puzzles.
- Your knowledge carries over between loops, but items don''t.

## Mechanics

### Power-ups
| Power-up | Effect |
|---|---|
| **Double Shot** | Doubles your speed for 20 seconds |
| **Slow Steam** | Slows the beat for one song |
| **Sugar Rush** | Boosts combat damage |
| **Rewind Sip** | Rewinds 30 seconds, once per loop |
| **Golden Bean** | Auto-serves one order |

Power-ups drop from perfect streaks and from rewards for helping regulars.

### Minimap
- A minimal, always-on **circle map** in the corner of the screen.
- It shows staff, customers, orders, events and the current time.
- Color-coded pulses show what needs your attention next.

## Moddable Design
- Recipes, songs, characters, dialogue and maps are all **plain text files** (JSON and audio).
- A built-in editor lets you make your own beatmaps and regulars.
- Mod packs can add whole new "days" and endings.
- Modders can also change the rules of the loop, for example to a 12-hour or 48-hour day.

## Progression
1. Replay the day and learn each regular''s timeline.
2. Collect **memories**, permanent unlocks that carry over.
3. Upgrade the cafe with new stations and staff.
4. Open the sealed room and face the Timekeeper.

## Visual and Audio Direction
- A limited palette of 3-4 colors per day. It shifts from warm morning to cold night.
- Simple geometric characters and clean UI.
- An adaptive soundtrack of lo-fi jazz layers. More layers play as your Groove rises.

## Endings
- **Break the Loop:** beat the Timekeeper and move on.
- **Stay for Coffee:** accept the loop and keep the cafe as a home.
- **Modded Endings:** set by community content.', 'fighting, rhythm, adventure', 'moddable, rts, minimalist', 'rtx 4080 or better; your pc will hum a lullaby', '2010-10-07 09:00:00+00'),
('Sunstep Temple', 21.09, '# Sunstep Temple

*A cozy multiplayer idle tower-defense in a living Mayan pyramid.*

## Elevator Pitch
Tend a tiny jungle pyramid with friends. Build a city around it, find hidden relics, and keep gentle spirit-pests away from the sun altar. Play for five minutes or leave it running all day. The temple keeps growing while you''re away.

## Story

**Act 1: The Sleeping Stone**
A moss-covered pyramid wakes after centuries. Its guardian is Tiko, a small jaguar-cub spirit, and Tiko is lonely. You are the new Keeper. Your job is to restore the temple''s terraces, one step at a time.

**Act 2: The Growing Village**
Villagers arrive: farmers, potters, star-watchers and drummers. Each one brings a trade and a bit of charm. The city grows in rings around the pyramid.

**Act 3: The Restless Mist**
Mischievous mist-sprites, such as fog moths and grumpy stone frogs, drift in to nibble the sun altar''s glow. They aren''t evil. They''re just hungry. You guard the temple with kind defenses that shoo them off.

**Act 4: The Sun Returns**
Restore all 13 terraces and the Sun Altar blazes. Seasons cycle, festivals begin, and new jungle regions open for the next cycle.

## Core Gameplay Loops

### 1. Idle Growth (passive)
- Villagers gather **maize, jade, cacao and sun-dust** automatically.
- Offline progress is banked as "dream harvest" and collected when you return.
- Upgrades boost yield, storage and speed.

### 2. City Building (active)
- Place huts, farms, workshops, markets and shrines on a tile grid around the pyramid.
- Adjacent buildings give bonuses. Cacao groves next to a market earn extra coins, for example.
- Decorate with flowers, lanterns, parrots and stone statues. Cosmetics give small happiness boosts.
- Unlock **terrace tiers** to expand the buildable area upward.

### 3. Hidden Object Exploration
- Each jungle scene is a hand-painted panorama: vine walls, cenotes, ruins and night gardens.
- Find hidden **relics** such as glyph tablets, jade beads, feather charms and lost baby animals.
- Relics grant permanent bonuses, lore fragments and collection sets.
- Hint feature: Tiko sniffs out nearby items. It recharges over time.
- Daily scenes rotate, so there''s always something new to find.

### 4. Tower Defense (light, relaxing)
- Mist-sprites follow winding paths toward the altar. There''s no fail state, only "the glow dims" and recovers.
- Defense towers:

| Tower | Effect |
|---|---|
| Drum Totem | Slows sprites with soft rhythms |
| Feather Fan | Blows sprites back along the path |
| Jade Sling | Steady single-target damage |
| Sun Mirror | Beam that pierces a line |
| Cacao Bloom | Lures and distracts groups |

- Waves run automatically. You can tweak the layout or let idle play handle it.
- Boss visits, like the Giant Fog Toad, drop rare relics.

## Multiplayer
- **Co-op Temples:** 2–6 Keepers share one pyramid, each tending a wing.
- **Gifting:** Send maize, relic duplicates and decorations.
- **Visit Mode:** Wander through friends'' villages, leave flowers, and help find their hidden items.
- **Festival Events:** Weekly community goals. The whole server fills a giant sun-offering meter for shared rewards.
- Chat is limited to emotes and stamps, keeping things cozy and safe.

## High Score Leaderboards
- **Glow Score:** Total altar brightness sustained over a season.
- **Relic Hunter:** Fastest and most complete scene finds.
- **Wave Warden:** Highest defended wave in weekly challenge maps.
- **City Charm:** Player-voted village beauty.
- Leaderboards are global, friends-only and per-temple. Seasons reset with cosmetic rewards.

## Progression
1. Wake the temple (tutorial, 10 minutes).
2. Build the first ring and meet the villagers.
3. Unlock jungle regions, each with its own relics, sprites and towers.
4. Reach 13 terraces, then **Ascend** (prestige). Ascending resets the city but keeps relics and adds a golden glow multiplier.

## Look and Feel
- **Art:** Soft, rounded, handpainted style. Warm turquoise, gold and jungle-green palette. Chibi villagers and animals.
- **Audio:** Gentle marimba, flutes, rain, birdsong and distant drums. The mix shifts with time of day.
- **Mood:** No timers that punish and no harsh failure. Only cozy progress.

## Key Features
- Relaxing idle progression with meaningful choices
- Beautiful hidden-object jungle panoramas
- Charming, forgiving tower defense
- Cooperative city building with friends
- Seasonal leaderboards and collections

## Tagline
*Tend the stones. Find the lost. Wake the sun.*', 'idle, hidden object, tower defense', 'multiplayer, relaxing, exploration, cute', 'gtx 1060, 8 gb ram, ssd recommended', '2013-06-30 09:00:00+00'),
('Violet Hush', 13.80, '# Lavender Reach

*A turn-based, text-based MMORPG 4X set in an endless open world of lavender.*

---

## 1. Overview

| Field | Details |
|---|---|
| **World** | The Lavender Field: a vast, living sea of purple |
| **Genres** | MMORPG, 4X, Open World |
| **Style** | Colorful, minimalist, text-based |
| **Play** | Turn-based strategy, PvP |
| **Core Mechanics** | Diplomacy, Inventory Management |

**Pitch:** Thousands of players share one persistent lavender field. Each player begins with a single hut and a handful of seeds. Everyone acts in shared turns. You expand, explore, exploit, and exterminate, or you talk your way to power.

---

## 2. Story

### Prologue: The Bloom
For a thousand years the Lavender Field slept under a violet haze. Then the **Great Bloom** came. Its scent carries memories, and whoever breathes it hears the whispers of the old world. The field is now awake and endless. It is also contested.

### Act I: Seeds
You are a **Wanderer**, a settler who arrived with a pouch of seeds and a rusty sickle. The field is quiet, but you are not alone. Smoke rises on the horizon.

### Act II: Rivalry
Scattered outposts grow into **Houses**. Trade routes form. Borders harden. Rumors of the **Amber Crown**, a legendary artifact hidden in the field''s heart, start wars.

### Act III: The Scent of Power
Whoever holds the Crown can bend the Bloom to their will. The server''s final season is a race between alliances and betrayals.

---

## 3. World

The map is a grid of text-described tiles. Each biome is defined by lavender color:

- **Pale Lilac Meadows**: fertile and safe, good for starting out.
- **Deep Violet Ridges**: rich in rare resources and dangerous.
- **Silver-Blue Marsh**: slows movement and hides ambushes.
- **Crimson Bloom Zones**: contested wonders that grant powerful buffs.
- **The Amber Heart**: the endgame region.

Weather and seasons change yields and movement costs.

**Example tile:**
```
[12,7] Pale Lilac Meadow
Wind: light. Scent: sweet.
Here: 1 hut (yours), 3 bees, a faint trail east.
Actions: harvest | build | move | trade
```

---

## 4. Core Gameplay: the 4X Loop

### Explore
- Move tile by tile, revealing text descriptions.
- Scouts and bees extend your vision range.
- Discover ruins, wandering merchants, and hidden groves.

### Expand
- Found **Huts**, upgrade them to **Farmsteads**, then **Estates**.
- Claim territory to extend your borders.

### Exploit
- Harvest lavender, honey, oil, and dye.
- Refine raw goods into perfume, tea, medicine, and pigments.

### Exterminate (PvP)
- Raid caravans, siege estates, or defend with wardens.
- Combat resolves at turn end, using the orders each side submitted.

---

## 5. Turn System

1. **Planning phase**: each player queues actions.
2. **Resolution phase**: the server resolves all actions simultaneously.
3. **Report phase**: results arrive as a short text digest.

```
> TURN 42 REPORT
+ Harvested 12 lavender, 3 honey
! Raiders spotted at [14,9]
~ House Amethyst proposes a trade pact
```

---

## 6. Diplomacy

Diplomacy is a core strategy, not a side feature.

- **Pacts**: non-aggression, trade, and defense treaties.
- **Alliances**: shared vision and shared victory conditions.
- **Envoys**: send messages, gifts, or demands.
- **Reputation**: broken treaties lower your **Honor**. That makes it harder to find partners.
- **Tribute and Vassalage**: weaker houses can pay for protection.
- **Embassies**: buildings that unlock advanced negotiations.

**Example:**
```
Envoy from House Amethyst:
"Lend us 20 oil, and our wardens guard your east ridge for 5 turns."
[Accept] [Counter] [Refuse] [Betray later]
```

---

## 7. Inventory Management

- Limited carry **slots** for each Wanderer and each caravan.
- Items have **weight**, **spoilage** (honey keeps, fresh petals wilt), and **value**.
- Storage is built in huts, barns, and vaults. Each has a capacity.
- Trade goods are prioritized when packing for a journey.

**Example:**
```
Pack (8/10 slots)
[1] Lavender bundle x20
[2] Honey jar x4
[3] Sickle (worn)
[4] Dye vial: violet x2
[5] Treaty scroll: House Amethyst
...
```

---

## 8. Progression

- **Wanderer level**: unlocks skills such as Herbalism, Diplomacy, Tactics, and Trade.
- **House level**: unlocks buildings, units, and treaty types.
- **Seasonal goals**: the server resets around the fight for the Amber Crown, and titles carry over.

---

## 9. Art and Presentation

- **Minimalist text UI** with a soft, colorful palette.
- Lavender shades separate tile types, alerts, and factions.
- ASCII borders and simple icons keep it light and readable.
- Ambient descriptions stand in for graphics.

---

## 10. Why Play?

- Meaningful choices with low mechanical noise.
- Social depth: alliances, betrayals, and trade.
- Short sessions, since each turn takes a few minutes.
- A calm setting hiding a ruthless strategy game.

> *"The field is beautiful. That''s how it gets you."*', 'mmorpg, 4x, open world', 'colorful, turn-based strategy, pvp, minimalist, text-based', '16 core cpu, 64 gb ram, no excuses', '2020-12-05 09:00:00+00'),
('Last Call to Dawn', 23.98, '# Night Train

## Overview
**Night Train** is a roguelite RPG with fighting-game combat. It is set aboard an endless overnight train that crosses a shifting, semi-realistic world. Each run is one night: you board at dusk and try to survive until dawn. Death resets the night, but your skills, relationships, and knowledge carry over.

**Genres:** Roguelite, RPG, Fighting
**Tags:** Life Sim, Sci-Fi, Fantasy, Realistic, Sports
**Core Mechanics:** Sanity Meter, Invincibility Frames

---

## Story

### Prologue: The Ticket
You are a washed-up amateur fighter. One night you find a ticket in your coat pocket with no destination printed on it. The platform is empty and the train is already waiting. When you board, the doors seal behind you.

### The Premise
The train runs on **liminal rails**. Each car is a different pocket of reality:
- a gritty boxing gym (realistic)
- a neon cyber-lounge (sci-fi)
- a moonlit elven dining car (fantasy)
- a sleeper car where you live day-to-day (life sim)

The train never stops. Passengers say only one thing ends the night, which is **reaching the engine car at dawn**.

### The Twist
The conductor is a fragment of your own past. He offers a deal every run: *stay aboard forever, comfortable and safe, or fight for the truth about why you boarded.*

---

## Gameplay Loops

### 1. The Night Run (Roguelite)
- Each run lasts one night, split into **7 hours**, and each hour covers a car or two.
- Car layouts, rivals, and events are randomized.
- On death you wake in your bunk at dusk.
- **Persistent:** learned moves, relationship levels, unlocked cars, lore.
- **Lost:** temporary items, boons, and cash.

### 2. Combat (Fighting)
- Combat is 1v1 or small-group and built on frame data, combos, and spacing.
- Styles: boxing, wrestling, martial arts, cyber-augmented moves, and spell-infused strikes.
- **Sports flavor:** ranked bouts in the fight car, tournament brackets, and betting from other passengers.

### 3. Life Sim (Between Fights)
- Cook, sleep, train, chat, and repair gear in your sleeper.
- Build bonds with passengers, who become trainers, allies, or rivals.
- Your routine choices set stats and starting perks for the next run.

### 4. RPG Progression
- Stats: Strength, Reflex, Focus, Willpower.
- Skill trees follow the fighting styles, with hybrid paths (e.g. *Arcane Boxing*).
- Dialogue choices open or close story branches.

---

## Core Mechanics

### Sanity Meter
The train wears on the mind.
| Sanity Level | Effect |
|---|---|
| High | Clear vision, stable cars, better dialogue options |
| Medium | Hallucinated enemies, distorted UI |
| Low | Cars rearrange, allies turn hostile, reality glitches |
| Zero | Forced "Blackout" state: a nightmare boss fight |

- **Drains:** taking hits, skipping rest, witnessing horrors.
- **Restores:** meals, friendships, quiet moments, winning clean.

### Invincibility Frames
- **Dodges, rolls, and parries** grant short i-frames.
- Timing is central to the fighting.
- Upgrades can extend i-frames, but **low sanity shortens them**, so risk and reward interlock.
- Certain enemies **ignore i-frames** and force different tactics.

---

## World & Setting

**The Night Train** blends the mundane with the impossible:
- **Realistic:** worn leather seats, rattling tracks, coffee in tin cups.
- **Sci-Fi:** drone attendants, holographic ads, cyber-augmented fighters.
- **Fantasy:** spirit passengers, enchanted cars, dream-beasts on the roof.
- **Sports:** the "Rail Circuit," an underground league that runs through the train.

### Notable Cars
1. **The Ring Car:** the main arena.
2. **The Dining Car:** heals sanity and holds rumors.
3. **The Server Car:** a hacker den and shop.
4. **The Glass Car:** a moonlit observatory with spirits and lore.
5. **The Engine Car:** the final destination.

---

## Characters
- **The Conductor:** cryptic guide and rival.
- **Mara "Iron" Voss:** retired champion and your trainer.
- **Kite-9:** a friendly service android with secrets.
- **Lady Sylwen:** an elven gambler who trades favors for fights.

---

## Progression & Endings
- **Short-term:** win fights, survive the hour, and manage sanity.
- **Mid-term:** master styles and grow bonds.
- **Long-term:** uncover the truth behind the ticket.

**Endings:**
- **Dawn:** reach the engine and face the truth.
- **Eternal Night:** accept the Conductor''s deal.
- **Derailment:** a hidden ending for a sanity-focused run.

---

## Tone & Style
Moody, atmospheric, and human. The game has quiet slice-of-life moments between intense, precise fights. Its visual style is stylized realism, with noir lighting, neon accents, and soft dreamlike distortion as sanity falls.

---

## Pitch
> *One night. One train. One more chance to fight your way to dawn.*', 'roguelite, rpg, fighting', 'life sim, sci-fi, fantasy, realistic, sports', 'rtx 4080 or better; your pc will hum a lullaby', '2000-12-01 09:00:00+00'),
('Glowl Rot', 23.21, '# Neon Gutter League

*A dark, colorful, text-based roguelite where you tame zombies and pit them against each other in back-alley sports.*

---

## 1. Premise

The city above is sealed off behind corporate firewalls. Below it, the alleyways glow with broken holo-signs, acid rain and toxic graffiti. A virus called **Chroma Rot** has raised the dead, and it makes them glow in vivid neon colors.

Gangs found a use for the infected. They catch them, tame them, and make them play in the **Gutter League**, an illegal sports circuit. Crowds bet, corps watch, and losers get scrapped for parts.

You are a **Handler**, a debt-ridden nobody with a cracked neural-link and a rusty collar-gun. You have one goal: **win the Golden Dumpster Cup** and buy your way out of the city.

---

## 2. Core Loop

| Phase | What happens |
|-------|--------------|
| **Scavenge** | Explore text-described alley nodes: noodle stalls, black clinics, scrap yards. |
| **Capture / Pull** | Tame wild zombies or "pull" from gacha crates. |
| **Train** | Feed, mod and bond with your team. |
| **Match** | Play turn-based text sports against rival crews. |
| **Death or Cash-out** | Lose the run and you lose most of your team. Some progress carries over. |

---

## 3. Story Structure

**Act I: Street Rat.** You wake up in a dumpster with one weak zombie, *Gary*. A loan shark gives you 7 days to pay him back, so you enter the lowest-tier league.

**Act II: Rising Static.** You climb the brackets and meet rival Handlers:
- **Madame Voltage**, who runs an electric-cult team.
- **Pinkeye**, a child prodigy with a swarm of tiny zombies.
- **Unit-9**, a corporate spy posing as a Handler.

You learn that Chroma Rot is not a natural plague. A corp is testing it.

**Act III: The Golden Dumpster.** In the finals you choose an ending:
- **Cash out:** take the money and leave.
- **Expose the corp:** broadcast the truth and burn the league down.
- **Become the Rot:** merge with your team and rule the alleys.

Each run reveals more of the story through fragments, so the full picture builds up over many runs.

---

## 4. Monster Taming

- **Species:** Sprinters, Bruisers, Spitters, Floaters (gas-filled) and Glitchers (data-corrupted).
- **Color traits:** the glow color sets the element. Magenta is fast, cyan is tricky, toxic green is tanky, amber is aggressive.
- **Bond level:** high bond unlocks combos and lowers the chance of a zombie going feral.
- **Taming:** a text minigame where you read the zombie''s mood and choose calm, bribe or dominate.

---

## 5. Gacha System

- **Crates:** buy them with *Scrip*, the street currency, or with rare *Neon Shards*.
- **Rarity tiers:** Rotten, Fresh, Glowing, Radiant and **Mythic Cadavers**.
- **Pity timer:** described in-world as "the crate wants you to win eventually."
- **Duplicates:** fusing them adds upgrades or rare mutations.
- **Roguelite twist:** crates are opened during a run. Roster slots are limited, so every pull is a risk.

---

## 6. Sports Matches

Matches are turn-based text sports. Sample formats:

1. **Rot-Ball:** 3v3 street football with tackles, chants and dirty tricks.
2. **Gutter Hoops:** vertical basketball on fire-escape scaffolds.
3. **Death Relay:** a hazard course through traffic and drones.

**Example round:**

```
> Sprinter "Pixel" breaks left through the rain...
> [CRITICAL HIT!] Pixel slams the ball through the vending machine!
> Crowd erupts. +40 Hype. Rival Handler sanity -5.
```

---

## 7. Mechanics

### Sanity Meter
The Handler has a sanity meter from 100 to 0. Sanity drops from:
- Losing matches
- Exploring dark zones
- Watching a zombie die
- Using illegal mods

| Sanity | Effect |
|--------|--------|
| 70-100 | Clear text and normal options. |
| 40-69 | Text glitches. Some choices are false. |
| 10-39 | Hallucinated events. Zombies whisper hints or lies. |
| 0-9 | **Breakdown:** you lose control of your team for a turn. |

Low sanity also has upsides. Some secret options and Mythic pulls only appear when your sanity is low.

### Critical Hits
- Each zombie has a **Crit Chance** and a **Crit Style**.
- Crits can be timed by bond level or by a quick-text input, such as typing a word.
- Crits create memorable moments and can turn a match around.
- Crits also work on Handlers: a **mental crit** deals big sanity damage.

---

## 8. Roguelite Progression

- **Permadeath:** zombies who are downed too many times are scrapped.
- **Meta-unlocks:** *The Stash* keeps unlocked species, crate types and story fragments between runs.
- **Run modifiers:** acid rain, blackout nights, corp raids.
- **Relics:** passive items like *Lucky Syringe* (+crit) or *Cracked Halo* (+sanity, -luck).

---

## 9. Tone & Style

- **Visuals:** ASCII art, colored text and neon palettes on a dark background.
- **Voice:** gritty, darkly funny narration with sharp slang.
- **Audio (optional):** synthwave and rain.
- **Mood:** grim, but bright and playful in the colors.

---

## 10. Hook

> *"They''re already dead. The only question is whether they win."*', 'gacha, monster taming, sports', 'colorful, text-based, zombies, roguelite, dark', 'potato pc, no gpu needed', '2017-10-19 09:00:00+00'),
('Static Cinema', 20.61, '# Last Reel: Drive-In Defense

## Overview
A minimalist action RPG with tower defense and open world elements. You defend a neon-lit drive-in cinema, which is the last safe place in a fading world. Each night the "static" tries to swallow the screen. You survive by building, solving puzzles, and fighting.

## Story
**Prologue:** A projectionist wakes in a drive-in lot. The sky outside is blank and gray. The old screen still glows, and it seems to hold back the void.

**Act I: Opening Night.** The lot is quiet and the screen is the only light. You learn that the *Static* is a formless tide that feeds on stories. It drifts in at dusk as pixelated shades.

**Act II: Double Feature.** The world beyond the fence opens up. Abandoned roads, motels, diners, and radio towers hold lost film reels. Each reel restores a memory of the town and reveals who broke the last movie.

**Act III: Final Screening.** The Static gathers into one great shape. You choose how the story ends.

## Core Gameplay

### Day: Open World
- Drive and walk through a sparse, stylized landscape.
- Scavenge parts, find reels, and talk to lone survivors.
- Take quests that shape your character and the town''s fate.
- Solve environmental puzzles, such as aligning projectors, rewiring signs, and tuning radios.

### Dusk: Building
- Place defenses around the lot: speaker turrets, spotlight beams, barricade cars, and popcorn-machine mines.
- Arrange car spaces to shape enemy paths.
- Upgrade the screen''s power core to widen its protective glow.

### Night: Defense and Action
- Fight beside your towers in real-time combat.
- **Aim assist** gently locks onto nearby threats. It is adjustable for precision or comfort.
- Grab **power-ups** dropped by enemies or from concession stands:
  - *Extra Butter:* temporary damage boost
  - *Intermission:* slows time briefly
  - *Rewind:* undoes the last few seconds of damage
  - *3D Glasses:* reveals weak points

## RPG Systems
- **Roles:** Projectionist (tech and traps), Stunt Driver (mobility), Usher (crowd control and support).
- **Skills:** Choose upgrade paths in a simple, readable tree.
- **Relationships:** Survivors offer buffs, gear, and story branches.

## Puzzles
- Restore film reels by ordering frames.
- Decode drive-in marquee messages.
- Route power through the lot''s electrical grid to unlock new tower types.

## Visual and Audio Style
- **Minimalist:** flat colors, neon outlines, and silhouettes against a dark sky.
- **Audio:** a warm analog soundtrack, crackling speakers, and ambient night sounds.
- The UI is diegetic: tickets, marquee text, and a dashboard radio.

## Multiple Endings
| Ending | Condition | Result |
|---|---|---|
| **Credits Roll** | Destroy the Static | The town is safe, but the screen goes dark forever. |
| **Eternal Loop** | Feed the Static a final story | The town survives inside an endless film. |
| **Sequel** | Befriend the Static | A fragile coexistence, and a new world opens. |
| **Empty Lot** | Abandon the cinema | You leave. The lot fades to nothing. |

Your choices about reels, allies, and defenses decide which endings you can reach.

## Tagline
*Every night is a show. Keep the screen lit.*', 'action rpg, tower defense, open world', 'rpg, puzzle, building, minimalist, multiple endings', 'gtx 1060, 8 gb ram, ssd recommended', '2002-08-17 09:00:00+00'),
('Cindermaw', 9.12, '# Ember Hoard: Dragon Lair Protocol

## Overview
A co-op multiplayer hybrid. Up to 4 players descend into a sprawling dragon lair overrun by undead. The game combines **FPS combat**, a **clicker-style base economy**, and **visual novel** story scenes.

- **Players:** 1-4 online co-op
- **Perspective:** first-person (combat), 2D dialogue (story)
- **Session length:** 30-45 min per descent

---

## Story

### Prologue: The Dragon Falls
The ancient dragon **Vharnax** guarded the mountain for a thousand years. Then he died, and his hoard began to rot with a strange ash. Gold, bones, and knights who came to loot it rose again as **the Ashen**, which are zombies fed by dragon magic.

### The Party
You play as the **Emberwardens**, a mercenary crew hired by a dying kingdom. Your task is to reach the dragon''s heart-core and end the curse.

### Story Structure (Visual Novel)
Between runs, the crew rests at the **Camp Cavern**. Here, dialogue scenes play out:
- Branching conversations with 4 companion NPCs
- Choices that change level layouts, available weapons, and endings
- Shared votes in co-op decide the party''s next story path

**Key characters**
| Name | Role | Secret |
|---|---|---|
| Mara | Quartermaster | Was once Vharnax''s thief |
| Brother Kest | Priest | Feeds the curse to stay alive |
| Ito | Scout | Knows a hidden exit |
| Vharnax (echo) | Ghost dragon | Wants to be freed, not avenged |

### Endings
1. **Purge:** destroy the heart and lose the lair''s treasure
2. **Bond:** merge with the dragon''s spirit
3. **Betrayal:** sell the curse to the kingdom

---

## Gameplay

### 1. Exploration
The lair is made of connected zones:
- **Molten Vaults:** lava bridges and gold rivers
- **Bone Cathedral:** towering rib-cage halls
- **Flooded Roost:** dark caves with glowing fungus
- **The Heartforge:** final area

Players find secret tunnels, treasure caches, and lore scrolls. Each descent shuffles the room layout.

### 2. FPS Combat
- Fast, punchy shooting against swarms of **Ashen zombies**
- Enemy types: shamblers, gold-crusted brutes, flying bone wyrmlings, and a boss per zone
- Fire and cold damage matter. Some zombies are weak to dragonfrost rounds.

### 3. Weapon Attachments
Every weapon has modular slots:
- **Barrel:** suppressor, long barrel, flame choke
- **Optic:** red dot, scope, rune-sight that shows weak points
- **Magazine:** extended, explosive, or dragonfrost rounds
- **Relic slot:** dragon-scale mods with special effects (chain lightning, lifesteal)

Attachments are found in the lair or bought at camp. Players can trade them in co-op.

### 4. Clicker Economy
At camp, the **Hoard Engine** generates resources while you play.
- Click or tap to mine gold and ember shards
- Upgrade **auto-miners** (skeleton workers, ember drills)
- Spend gold on unlocks: weapons, camp buildings, and permanent stat boosts
- Zombie kills feed the Hoard Engine, so combat and clicking support each other
- Offline progress adds resources between sessions

### 5. Respawning
- Downed players can be revived by allies within 15 seconds.
- If fully dead, they respawn at the last **Dragon Brazier** checkpoint for a gold fee.
- If the whole team wipes, the party returns to camp. They keep 50% of loot, and the story advances with a new dialogue scene.

---

## Co-op and Multiplayer
- Drop-in, drop-out matchmaking
- Shared loot with a ping system
- Class synergy: **Breacher** (tank), **Sharpshooter**, **Alchemist** (support), **Tinker** (attachment and turret specialist)
- Shared clicker progress, so the whole team builds one camp

---

## Tone and Visuals
- Dark fantasy with warm firelight and glowing gold against the cold, gray Ashen
- Illustrated visual novel portraits
- Ambient soundtrack with deep dragon-breath rumbles

---

## Core Loop
1. **Camp:** talk, upgrade, click to earn resources
2. **Descend:** explore and fight in co-op
3. **Loot:** find attachments and story clues
4. **Return:** spend the loot and choose the next story path
5. **Repeat** until the final choice', 'clicker, fps, visual novel', 'co-op, exploration, multiplayer, zombies', 'rtx 4080 or better; your pc will hum a lullaby', '1993-02-28 09:00:00+00'),
('Wick & Tide', 2.63, '# Lighthouse Loop

*A minimalist stealth life-sim roguelite about keeping one light alive.*

## Premise
You are the last keeper of a remote lighthouse. Every night a fog-borne fleet hunts the beam. Each dawn the clock snaps back and the night begins again. You remember. The island doesn''t.

## Story Structure

**Act 1: The Keeper**
- You wake in the lamp room. The tide is out and the horn is silent.
- A ship''s bell rings in the fog, which starts the first loop.
- You learn the rules: keep the light lit, stay unseen, survive until dawn.

**Act 2: The Drowned Fleet**
- Each loop reveals more about the ghost ships and their captains.
- Their crews once wrecked on these rocks because a previous keeper let the light fail.
- The fleet is drawn to the beam and hates it in equal measure.

**Act 3: The Last Wick**
- You find the loop''s source, a clockwork heart buried under the lens.
- You choose one of three endings:
  - **Break it.** The loop ends and the light dies.
  - **Feed it.** You become the next lighthouse.
  - **Guide the fleet home.** The ghosts are freed.

## Core Loop

| Phase | Mode | What you do |
|---|---|---|
| Day | Life sim | Cook, repair, tend the garden, craft, and upgrade the base |
| Dusk | Prep | Set traps, hide supplies, choose a loadout |
| Night | Stealth roguelite | Move between rooms, keep the lamp lit, and dodge patrols |
| Dawn | Reset | The time loop rewinds and only permanent unlocks and memories remain |

## Mechanics

### Time Loops
- Each night lasts about 10 minutes and ends in death or dawn.
- On reset, the world reverts. You keep knowledge, blueprints, and *echoes*, which are permanent perks.
- Enemy patrol routes are seeded per loop, so learning them pays off within a run but not across runs.

### Screen Wipe Bombs
- These are rare, limited consumables. Each detonation wipes the screen in a white flash.
- Every enemy in view is banished for 30 seconds, and your own vision resets.
- Bombs are crafted by day from salvage and lamp oil.
- They cost precious light fuel, so using one is a real trade-off.

### Stealth
- Enemies see the beam, not you. Standing in shadow keeps you hidden.
- Moving on the rhythm (see below) muffles your footsteps.
- Noise, light spill, and wet footprints all raise your detection meter.

### Rhythm
- The lighthouse beam sweeps on a steady pulse.
- Steps, repairs, and lamp-winding are timed to the beat.
- Perfect timing gives silent movement and bonus fuel. Missing the beat makes noise.
- Ghost fleets move to their own counter-rhythm, which you can learn and exploit.

### Base Building
- The lighthouse is a vertical, minimalist cross-section with one room per floor.
- Rooms include the kitchen, workshop, bunk, garden, radio, and lamp room.
- Upgrades add hiding spots, shortcuts, and defenses.
- Layout changes persist through *echoes* between loops.

### Life Simulation
- Meters: hunger, warmth, sleep, and sanity.
- Daily routines such as cooking, gardening, and letter-writing give buffs for the night.
- Neglect brings debuffs, such as shaky hands that hurt rhythm accuracy.

### Roguelike Progression
- Each night you pick 1 of 3 random *boons* from the sea, such as Silent Boots or Long Wick.
- Death costs the run''s boons but keeps echoes and blueprints.
- Bosses are named ghost captains, one every few nights.

## Visual and Audio Style
- **Minimalist:** flat shapes, a limited palette of navy, white, and amber.
- The beam is the main light source and the main mechanic.
- **Audio:** an adaptive soundtrack built on the beam''s pulse, with foghorn bass and quiet ambient sea.

## Win Condition
Survive the final night and make your choice at the clockwork heart.

## Session Length
- One loop takes 15-20 minutes.
- A full playthrough takes about 15-20 hours.', 'stealth, life simulation, roguelite', 'minimalist, base building, roguelike, rhythm', 'any toaster with a screen', '2013-08-30 09:00:00+00'),
('Rootfall', 8.00, '# Inverted Canopy

*A fighting / third-person shooter racer set in an upside-down forest.*

## Premise
The Great Flip tore a forest from the earth and hung it in the sky. Roots now tower overhead like skyscrapers. Canopies hang down into an endless void. Gravity pulls toward the leaves, and the ground is a ceiling of floating soil. Rival clans of anime-styled "Rootrunners" race and fight through it to claim the **Heartseed**, a glowing core that keeps the forest from collapsing.

## Story Structure
1. **Act I, Falling Up:** You play Kaito or Mira, a rookie scavenger. You learn to move and shoot in the inverted world, and you win your first race through the Hollow Roots.
2. **Act II, Clan Wars:** You join a clan and fight three bosses in the Mushroom Spires, Sap Falls and Thornwall. Each boss mixes a duel with a chase.
3. **Act III, The Heartseed:** Gravity shifts mid-level. You fight the Warden, a colossal tree spirit, in a final race-and-shoot showdown.

## Core Gameplay
- **Third-person shooting (main pillar):** You aim over the shoulder, use cover on hanging vines, and fire at targets above and below you. Gravity-flip zones change your aiming angles.
- **Fighting:** Close-range anime-style combos, parries and finishers. Shooting and melee can be chained.
- **Racing:** You ride grapple-boards and glider-leaves along branches, through roots and around waterfalls that fall upward. Boost pads, shortcuts and sabotage add variety.
- **Building:** You place ramps, barricades, bridges and turrets from harvested wood and sap. Builds work in races (shortcuts, traps) and in arenas (fortifications).
- **Physics:** Ragdolls, swinging vines, breakable branches, and sap that changes friction and speed. Explosions push objects and players realistically.

## Mechanics
- **Weapon swapping:** Switch instantly between 4 loadout slots: thorn rifle, seed shotgun, blade-vine whip and sap launcher. Swapping in the middle of a combo gives a damage or speed bonus.
- **High score leaderboards:**
  - Global and friends boards for races, arena survival and boss time-trials.
  - Scores reward style: air time, combos, weapon-swap chains and build efficiency.
  - Weekly rotating challenge maps.

## Modes
| Mode | Description |
|---|---|
| Story | Campaign of about 10 hours |
| Circuit Race | Armed races with 8 players |
| Arena Brawl | Build, shoot and fight |
| Score Attack | Solo leaderboard runs |

## Visual and Audio Style
- **Visuals:** Cel-shaded anime look, with glowing spores and bioluminescent flora against a dark inverted sky.
- **Audio:** Energetic J-rock/electronic soundtrack. It shifts tempo with gravity flips.

## Hook
*"The ground is gone. Fight, race and build your way up to the top."*', 'fighting, third-person shooter, third-person shooter', 'racing, anime, building, physics', 'high-end gpu, 32 gb ram, and a good cooling plan', '2011-01-18 09:00:00+00'),
('Mile Zero Diner', 27.28, '# Last Stop Diner

## Overview
A **casual, text-based, local co-op horror-racing** game. Players share one screen and one keyboard or controller set. They run a haunted roadside diner by day and race cursed highways by night. The tone is cozy, then eerie, then tense.

- **Players:** 2-4 (local co-op and multiplayer)
- **Genres:** Casual, Racing, Horror
- **Style:** Text-driven narration with simple ASCII and static illustrations
- **Session length:** 20-30 minutes per "night"

## World: The Diner at Mile 0
The Starlite Diner sits at a foggy crossroads where the highway never seems to end. Its neon sign flickers "OPEN" at all hours. Travelers stop for pie and coffee, and some never leave. The road outside loops into strange places: a moonlit desert, a drowned bridge and a forest of headlights.

## Story
1. **Arrival.** The players are new hires. Their car broke down and the owner, Ma Delacroix, gives them jobs to pay for repairs.
2. **The Rule.** Ma warns them: *"Serve everyone. Never ask where they''re going."*
3. **The Orders.** Ghostly customers pay in strange ways. Some pay with fuel, some with memories and some with keys to old cars.
4. **The Race.** Each night the "Night Highway" opens. To free their car (and themselves), the players must outrun **The Hungry Mile**. This is a spectral pursuer that feeds on unfinished journeys.
5. **The Truth.** The players find that Ma is a former racer who lost the same race. Their final choice is to take her place or break the loop.

## Gameplay Loop

### Day Phase: The Diner (Casual, Co-op)
- Players split roles: **Cook, Server, Mechanic, Lookout**.
- Text prompts describe orders, for example: *"Table 4 wants the ''Midnight Special''. He hasn''t blinked in a while."*
- Players coordinate verbally, since only some of them see the full order details.
- Serving customers earns **Ingredient Cards** and **Road Cards**.

### Night Phase: The Highway (Racing, Horror)
- The race is text-based and turn-driven, with a shared tension meter.
- Each turn the narrator describes the road: *"Headlights behind you. Too close. Fork ahead: left is fog, right is a bridge with no rails."*
- Players choose actions together: steer, boost, brake, or hide the lights.
- If **Dread** fills up, the pursuer catches up and hazards multiply.

## Core Mechanics

### Card Synergies
Cards come in families, and combos trigger bonus effects.

| Card Family | Example | Synergy |
|---|---|---|
| Ingredient | Black Coffee | Pairs with *Pie* to give "Steady Hands" (+control) |
| Ingredient | Salt | Pairs with *Iron Skillet* to give "Ward" (-Dread) |
| Road | Nitro Syrup | Pairs with *Greasy Tires* to give "Slide Boost" |
| Relic | Dead Man''s Key | Pairs with any *Road* card to shortcut a hazard |

- Players build a shared **deck** during the day.
- Each night they play hands of 3-5 cards.
- Chain combos across players to unlock the strongest effects.

### Physics-Based Puzzles
Puzzles are described in text and resolved with simple physics rules.

- **Diner puzzles:** Balance a tray of drinks on a shaking floor. Roll a barrel to block a door. Time a swinging pie-case light.
- **Road puzzles:** Adjust speed and angle to clear a broken bridge. Use momentum and weight (loaded trunk or empty) to survive a spinning turn.
- Players input values such as *speed, angle and load*. The game simulates the result and narrates it.

## Co-op and Multiplayer
- **Local co-op:** Shared screen, split roles, and hidden information that players must relay aloud.
- **Multiplayer:** A "pass the seat" mode where friends take turns as driver while the others act as navigators and cooks.
- **Asymmetric clues:** One player sees the map, another sees the hazards and another sees the cards. Talking is essential.

## Horror Elements
- Slow-burn dread: unsettling customers, wrong details, repeated phrases.
- The diner changes each night: extra booths, a door that wasn''t there before, a customer who looks like a player.
- Jump scares are told in text: *"The radio says your name."*

## Progression
- **Nights 1-3:** Learn roles, simple races and basic cards.
- **Nights 4-6:** Harder routes, stranger customers and combo-heavy decks.
- **Night 7:** The final race, where the story branches into **three endings**: *Escape, Replace Ma,* or *Break the Loop*.

## Endings
- **Escape:** The players leave, but the diner appears in their rearview mirror.
- **Replace Ma:** They stay and keep the neon on for the next travelers.
- **Break the Loop:** A hard-earned, combo-dependent ending that frees everyone.

## Tone and Presentation
- Warm diner jingles that gradually distort into engine hums and whispers.
- Retro Americana text style with a flickering neon UI.
- Short, punchy prose that stays casual and easy to pick up.', 'casual, racing, racing', 'local co-op, local co-op, horror, text-based, multiplayer', 'quad-core cpu, 16 gb ram, mid-range gpu', '1985-02-26 09:00:00+00'),
('Hollowroot', 19.40, '# Rootbound: Tales of the Elven Canopy

## Pitch
A cute, cartoon-style survival action RPG. You defend and grow a living elven treehouse village. Combat runs on match-three puzzles, heroes come from a gacha system, and when a hero dies, they are gone for good.

## Story
Long ago, the World Tree Aelindra kept the forest safe. Now a creeping blight called the Hollow Rot is killing the roots. You are a young Sproutkeeper, the last person who can hear the tree''s heartbeat. Your task is to climb, build, and fight your way up the branches. Along the way you gather a band of elven heroes and restore the tree.

## Setting
- **World:** a huge elven treehouse city with rope bridges, lantern-lit lodges, and mossy workshops.
- **Look:** soft pastel colors, round characters with big eyes, and a storybook medieval tone.
- **Zones:**
  - **Canopy:** sunny home base and market.
  - **Bough Woods:** mid-level hunting and gathering grounds.
  - **Rotten Roots:** dark, dangerous depths with bosses.

## Core Loop
1. **Explore** a branch zone in real-time action RPG style.
2. **Fight** by swapping and matching rune tiles. Each color triggers a different effect:
   - Red: attack
   - Green: heal
   - Blue: magic
   - Yellow: gather resources
   - Longer chains trigger hero combo skills.
3. **Survive** by managing hunger, warmth, and the tree''s health. Craft, cook, and build.
4. **Return** to the village to upgrade buildings, assign heroes, and summon new ones.
5. **Repeat** with harder zones and stronger blight.

## Heroes and Gacha
- Summon elves such as archers, druids, blade dancers, and beast tamers.
- Rarity tiers are Seedling, Bloom, and Ancient.
- Each hero has:
  - an element
  - a match-three skill
  - a personality and a small story
- Duplicates raise a hero''s bond level.
- Fair-play options: pity counter, free daily summons, and no pay-to-win exclusives.

## Permadeath
- If a hero falls in battle, they are lost forever.
- The village keeps a **Memorial Grove** where a tree grows for each fallen hero.
- Fallen heroes leave a **Legacy Seed**, which gives small permanent bonuses to future heroes.
- Risk versus reward: retreat early and keep your team, or push on for rare loot.

## Progression
- Village upgrades unlock new crafting, safer camps, and more team slots.
- A skill tree covers combat, survival, and match-three mastery.
- Seasonal events bring new blight bosses and limited heroes.

## Platforms and Feel
- Cross-platform on mobile, PC, and console, with shared progress across devices.
- Short mobile sessions of about 10 minutes, and longer runs on PC and console.
- Touch, mouse, and gamepad controls.
- Warm music and gentle sound effects, so even the tense moments feel cozy.

## Unique Selling Points
- The match-three puzzle drives real-time action combat.
- Losing a hero hurts, but their legacy gives it meaning.
- A cozy look with high-stakes survival underneath.
- A living tree that visibly heals or withers with your choices.', 'gacha, survival, action rpg', 'cross-platform, medieval, cartoon, cute', '2 gb ram and good vibes', '1993-04-24 09:00:00+00'),
('Maw League', 5.25, '# Event Horizon Circuit

*A text-based tycoon / action RPG / sports shooter at the edge of a black hole.*

---

## 1. Elevator Pitch
You run a sports franchise on a station orbiting the event horizon of a black hole called **Maw**. Time slows near the horizon, so every match is broadcast to a universe that ages faster than you do. Build the arena, sign the athletes, and shoot your way to the top of the **Horizon League**, a lethal zero-g shooting sport. Your rivals are trying to do the same to you.

---

## 2. Setting
- **World:** the accretion ring of Maw, a silent, glowing black hole.
- **Atmosphere:** dread and beauty. The text is sparse and poetic, with flickering light, gravity groans, and distant radio static.
- **Time dilation:** the closer your arena sits to the horizon, the more spectators and money you gain from the outside universe, and the greater the danger.

---

## 3. Story Structure

### Act I: Drift
You inherit a rusted salvage platform, *The Last Lantern*. You have no crew, a small debt, and one battered plasma rifle. You scrape by on **scrap-league** matches.

### Act II: Orbit
Sponsors, rival owners, and cult fans appear. The league''s champion, **Warden Kesh**, offers you a deal. You can take it and rise fast, or refuse and stay independent. Your choice shapes which factions support you.

### Act III: Horizon
The final tournament, the **Singularity Cup**, is held on a platform hovering at the point of no return. Time is nearly frozen, and whoever wins will become a legend to a dying universe.

### Endings
- **Champion:** you win the Cup and rule the league.
- **Sovereign:** you buy the league and run it as a business.
- **Event:** you fall past the horizon willingly, and the game shows what lies beyond.

---

## 4. Gameplay Pillars

### Tycoon
- Upgrade the arena, sell broadcast rights, and manage the budget.
- Hire coaches, medics, and engineers.
- Balance your funds against orbit distance, since a closer orbit brings more income and more risk.

### Action RPG
- Create a player character and level up skills such as *Aim*, *Nerve*, *Tether*, and *Engineering*.
- Collect gear with unusual traits, such as a rifle that shoots backward in time by a second.
- Choose dialogue, take on contracts, and build faction reputation.

### Sports
- Matches are **3v3 zero-g shooting rounds** (for example, *Gravity Ball*, *Capture the Core*, and *Last Anchor*).
- The league has seasons, standings, and playoffs.
- Fans, rivalries, and injuries carry over between matches.

### Shooter (text-based)
Combat plays out in short text turns:

```
> The rival sniper drifts behind a wreck.
> Her suit vents glow orange at the shoulder.
[1] Aim shoulder vent   [2] Push off wall   [3] Call teammate
```

---

## 5. Core Mechanics

### Weak Points
- Every opponent, suit, and arena machine has hidden weaknesses, such as vents, coolant lines, and gyro-joints.
- You discover weak points by scanning, watching, or getting hit.
- Hitting a weak point does critical damage, and it can disable a rival''s gear for the rest of the round.
- Bosses have phased weak points that appear only under certain conditions, for example when they overheat near the horizon light.

### Rubber Banding
- The **Maw Pull** keeps matches close and fun:
  - The team that is losing gets small boosts, such as better drift control, ammo drops, and cooler weapons.
  - The leading team feels stronger gravity, with slower movement and more jams.
- The effect is visible in the story text, so the player feels it as the black hole "favoring the underdog."
- Sponsors and fans can pay to tilt the Pull, which adds a tycoon layer.

---

## 6. Sandbox Systems
- **Free-form franchise:** decide your own goals, such as profit, glory, or exploration.
- **Custom rules:** edit match types, team sizes, and gravity settings.
- **Emergent stories:** rivalries, betrayals, and injuries create narratives that differ each run.
- **Modding-friendly text files** for items, teams, and events.

---

## 7. Party Game Mode
Up to 8 players share one screen or one terminal.
- **Hot-seat matches:** each player takes a turn making choices.
- **Chaos cards:** random events, such as *Solar Flare*, *Gravity Flip*, and *Mystery Cargo*.
- **Party rules:** short 10-minute rounds, silly gear, and scoreboards with fan-voted awards like "Most Dramatic Death."

---

## 8. Tone and Presentation
- **Text-only interface** with ASCII banners, color accents, and a minimalist HUD.
- **Voice:** dry humor over cosmic dread.
- **Audio (optional):** low drones, pulsing radio, and a slow heartbeat as you near the horizon.

---

## 9. Progression Loop
1. Take a contract or match.
2. Scan for weak points and fight.
3. Earn money, fame, and loot.
4. Upgrade your arena, team, and gear.
5. Move your orbit closer to Maw for higher stakes.
6. Repeat until the Singularity Cup.

---

## 10. Unique Selling Points
- A black hole as both setting and game mechanic.
- Sports, tycoon, and RPG systems that all feed each other.
- Weak-point tactics and rubber-band drama in a quiet text-based world.
- Solo campaign, sandbox, and party play in one game.', 'tycoon, action rpg, sports', 'sandbox, text-based, shooter, atmospheric, party game', 'quad-core cpu, 16 gb ram, mid-range gpu', '1981-10-22 09:00:00+00'),
('Hushmarket', 22.94, '# Lanternfall: The Drifting Bazaar

## Overview
| Field | Value |
|---|---|
| Genres | stealth, adventure, horror |
| Players | 1-4 co-op, plus optional PvPvE "rival stall" servers |
| World | open-world floating market of chained islands and rope bridges |
| Difficulty | punishing: permadeath for stalls, not for players |

## Premise
The Bazaar of Vael drifts above an endless cloud sea. Its islands are tied together by rope, sails, and old debts. Every night the "Hush" rolls in. Lanterns die, the bells stop, and something walks the docks collecting what is owed.

You are a **stallkeeper**, a newcomer with a cracked lantern and a plot of sky-soil. Survive the nights, and grow, trade, and sneak enough to buy your freedom from the market. Its owner never shows a face.

## Story Structure
**Act 1: Arrival (days 1-5)**
- Learn the docks, meet the guilds, and plant your first crops.
- Night 3 brings the first Hush. You hide and watch a stall vanish.

**Act 2: The Debt (days 6-20)**
- Guilds offer contracts: smuggling, sabotage, rescue.
- Your choices shape who protects you and who hunts you.
- You find the *Ledger Spire*, which holds the market''s secret.

**Act 3: The Cut Rope (day 21+)**
- Choose to free the market, rule it, or cut it loose to fall.
- The ending depends on your morality and on the world state you built.

## Core Gameplay

### Stealth
- Light and sound are your main tools. Lanterns reveal you, and shadow hides you.
- Creeping on planks makes no noise, but running on rope bridges rings bells.
- Hide in barrels, under awnings, or in crop rows.
- Enemies hunt by sound, smell, and lantern light.

### Adventure and Open World
- Glide between islands using sails, ziplines, and grapple hooks.
- Districts are the Spice Docks, Tanner''s Drop, the Glass Orchards, and the Undermarket beneath the hulls.
- Exploration turns up hidden shops, ruins, and lore.
- Weather and wind change each island''s position, so the map is never fixed.

### Horror
- **The Hush:** a nightly event with a pale fog, silent bells, and hunters.
- **Collectors:** faceless creatures that take goods, then people.
- **Rot-Lanterns:** false lights that lure players off the path.
- There is no HUD health bar. Fear shows through shaking hands, muffled audio, and blurred edges.

## Mechanics

### Farming and Crops
- Grow crops on sky-soil plots, on your stall roof, or on hanging gardens.
- Each crop serves a purpose:
  - **Glowmoss:** light without flame, which the Hush ignores.
  - **Whisperbean:** dampens your noise.
  - **Bitterroot:** cures fear and rot.
  - **Ghostpepper:** a trade good that draws Collectors, so it is risky to hold.
- Crops need water, wind, and protection. Neglect and night raids ruin harvests.
- Teammates can share plots or steal from rivals.

### Morality System
- Each action shifts a hidden **Weight** between Mercy and Greed.
- Examples:
  - Feeding a starving vendor raises Mercy.
  - Selling poisoned goods raises Greed.
- Effects:
  - **Mercy:** allies help, the Hush is gentler, and some paths stay closed.
  - **Greed:** you earn more and unlock black-market gear, but Collectors track you.
- NPCs remember what you did. Reputation spreads through the market.

## Multiplayer
- Co-op players share a stall, split roles (farmer, scout, trader), and revive each other in the dark.
- In PvPvE mode, rival stalls raid one another while the Hush hunts everyone.
- Shared world events such as market fires and bridge collapses make cooperation hard.

## Difficulty
- Losing your stall means losing crops and stock, but you keep your skills and maps.
- Enemies adapt to repeated tactics.
- Resources are scarce, and mistakes compound.

## Tone and Art
- Moody, storybook horror in lantern amber, cold blue fog, and rope-and-wood textures.
- Sound design carries the fear: creaking planks, distant bells, whispered prices.

## Tagline
*"Sell by day. Hide by night. Never let the lanterns go out."*', 'stealth, adventure, horror', 'multiplayer, difficult, horror, open world', 'quad-core cpu, 16 gb ram, mid-range gpu', '1999-10-05 09:00:00+00'),
('Heartfall Chorus', 16.78, '# Emberforge Requiem

*A tactical RPG / visual novel / rhythm hybrid in a living dwarven forge-city.*

---

## 1. Premise

Deep under the mountain lies **Karak-Velm**, a dwarven forge-city built around the Heartfire, a volcanic furnace that powers every anvil, lift, and gate. Something has gone wrong. The Heartfire''s hum has been corrupted, and the dead now rise to the rhythm of a broken beat. Thousands of players share the city, hold its forges, and fight to restore the true rhythm.

---

## 2. Story Structure

**Act I: The Cold Anvil**
- You are a journeyman smith. The first zombie outbreak hits the lower foundries.
- Visual novel scenes introduce the clans: the Ironbeard guilds, the Ashkin miners, and the Rune-Cantors.
- You learn the Heartfire responds to hammer rhythm.

**Act II: The Silent Deep**
- Sealed districts open as you find new tools and abilities (Metroidvania progression).
- Rival clans argue over whether to seal the city or reforge the Heartfire.
- A betrayal exposes the source of the corruption: a stolen Resonance Core.

**Act III: The Last Strike**
- Players unite for a server-wide event to re-light the Heartfire.
- Endings depend on which clans hold influence, and on the choices of the whole community.

---

## 3. Core Gameplay

### Tactical RPG Combat
- Grid-based battles inside forges, tunnels, and vaults.
- Squads of dwarven classes: **Hammerguard** (tank), **Runesmith** (support), **Flameshot** (ranged), **Tunnel Warden** (control).
- Terrain matters: lava vents, collapsing bridges, and anvil platforms.

### Rhythm System
- Every attack, forge action, and spell is a **timing challenge** on the Heartfire beat.
- **Timing windows:** Perfect / Good / Late / Miss.
  - *Perfect* gives bonus damage and a chance to inflict *Resonance*.
  - *Miss* lets zombies seize the beat and gain tempo.
- Zombies pulse on off-beats, so you have to read patterns and shift tempo mid-fight.

### Item Durability
- Weapons, armor, and tools wear down with each use.
- Perfect timing reduces wear. Misses cause cracks.
- Repair at forges through a rhythm minigame. Master smiths can **reforge** an item with new traits.
- Broken gear can be salvaged for rare alloys.

---

## 4. Visual Novel Layer
- Branching dialogue in taverns, war rooms, and memorial halls.
- Relationship meters with companions and clan leaders unlock tactics, quests, and endings.
- Choices are persistent and shared. Major decisions feed clan reputation across the server.

---

## 5. Metroidvania Exploration
- The city is one connected map of interlocking layers: **Slag Wells, Crystal Galleries, the Rune Vaults, the Sunken Foundry**.
- Progression tools unlock shortcuts and secrets:
  - *Resonance Pick*: breaks sound-locked walls.
  - *Emberline Grapple*: crosses lava chasms.
  - *Cantor''s Chime*: calms zombies briefly.
- Backtracking reveals new story and loot.

---

## 6. Massively Multiplayer Systems
- **Shared hub city** with player-run forges, markets, and guild halls.
- **Co-op raids:** up to 16 players sync their rhythm in a *Chorus Battle*.
- **Zombie surges:** dynamic world events that threaten districts. If players fail, districts fall and stay closed until retaken.
- **Server-wide Heartfire meter** tracks progress toward the endings.

---

## 7. Simulation Elements
- Manage a personal forge: staff, fuel, ore supply, and orders.
- Trade goods and craft for other players.
- Rebuild ruined districts and defend them with turrets, traps, and garrisons.
- Ambient life: dwarven NPC routines, food supply, morale, and disease.

---

## 8. Zombies: The Hollow Choir
- **Shamblers:** slow, easy to time.
- **Slagborn:** molten, damage gear durability.
- **Drumbones:** shift the beat and disrupt your timing.
- **The Dirge King:** final boss, who fights in multiple rhythm phases.

---

## 9. Tone and Style
- Dark, warm, and gritty: glowing metal, echoing stone, and heavy percussion.
- Music is dynamic. Each clan has an instrument, and combat audio layers with the player''s hits.

---

## 10. Player Fantasy
> *You are not just a warrior. You are the hammer that keeps the city''s heart beating.*', 'tactical rpg, visual novel, rhythm', 'massively multiplayer, metroidvania, zombies, simulation', 'rtx 2060 or better, 16 gb ram', '1986-12-24 09:00:00+00'),
('Static Hi-Score', 0.87, '# Neon Arcade: Echoes of the Cabinet

## Overview
A story-rich hybrid of **deck builder**, **point-and-click adventure**, and **RPG**. It is set inside a sprawling, sentient neon arcade. Players explore the arcade, gather resources, and fight rhythm-driven card battles, solo or in online co-op (2-4 players). It has full controller support.

## World
**The Neon Arcade** is a vast, glowing labyrinth of cabinets. Each cabinet is a portal to a mini-world with its own visual style, music, and rules.
- **The Lobby:** hub area with the prize counter, token exchange, and repair shop.
- **The Cabinet Rows:** themed districts (Racing Row, Fighter Alley, Puzzle Pit, Synth Sector).
- **The Basement:** a dark zone of abandoned, corrupted machines. This is the late-game area.

## Story
**Act 1 - Power On**
You play a *Player One*, a lost visitor who wakes up in the Lobby at closing time. The arcade''s AI, **MAGI**, is fading. A glitch called **The Static** is corrupting the cabinets. MAGI asks you to restore power.

**Act 2 - High Score**
You travel through the Rows and meet quirky NPCs: a retired champion, a rogue vending bot, and a rival DJ. Each cabinet you save reveals a piece of the arcade''s history. You learn that the Static feeds on forgotten players'' unfinished games.

**Act 3 - Game Over?**
The Basement holds the **Final Cabinet**, where the Static''s origin waits. It is MAGI''s own lost memory. You choose between three endings: *Restore*, *Reboot*, or *Merge*. The choice depends on your decisions and side-quest outcomes.

## Core Gameplay

### 1. Point-and-Click Exploration
- Scan neon-lit scenes for interactive objects.
- Solve inventory and dialogue puzzles.
- Talk to NPCs to unlock quests, shortcuts, and cards.
- Controller mode uses a snapping cursor and radial menus.

### 2. Rhythm-Based Deck Building Combat
- Battles run on a **beat track**. Each card is played on the beat.
- **Perfect / Good / Miss** timing changes card power.
- Combos build a **Combo Meter** that powers ultimate cards.
- Card types:
  | Type | Role |
  |------|------|
  | Attack | Deals damage; scales with timing |
  | Defense | Shields and parries |
  | Remix | Alters the next cards in the queue |
  | Support | Buffs, heals, and co-op links |
- Each enemy cabinet has its own music, which changes the pattern of the fight.

### 3. RPG Systems
- Classes (**Button Masher, Hacker, Synth Bard, Pinball Tank**) set starting decks and skills.
- Stats: *Reflex, Focus, Groove, Grit*.
- Gear: joysticks, headphones, and jackets grant passive bonuses and unlock card slots.

### 4. Resource Management
- **Tokens:** basic currency for cabinets, shops, and card packs.
- **Tickets:** earned from wins and redeemed for rare cards and gear.
- **Power:** limited energy that keeps districts lit. Spend it wisely on lighting, repairs, and shops.
- **Cabinet Health:** neglected machines decay and spawn Static enemies.

## Online Co-op
- Drop-in play for 2-4 players.
- **Shared beat track:** each player plays cards on their own lane, and synced hits trigger *Duet Combos*.
- Players share the resource pool but keep separate decks.
- Roles: Tank, DPS, Support, Remixer.
- Co-op-only boss cabinets with special mechanics.

## Side Quests
- **Lost Tokens:** find items hidden by NPCs across the Rows.
- **High Score Duels:** beat ghost records for rare cards.
- **Cabinet Restoration:** repair broken machines to unlock new districts.
- **NPC Stories:** personal arcs that change endings and give unique cards.

## Meta-Progression
- **Arcade Legacy:** persistent upgrades earned across runs, such as new starting cards, new classes, and hub upgrades.
- **Hall of Fame:** records your best runs and unlocks cosmetic rewards.
- **New Game+:** a harder Static, remixed music, and new story branches.
- Unlocks carry between solo and co-op profiles.

## Art and Audio
- Synthwave and vaporwave neon visuals with pixel-art cabinets and hand-drawn characters.
- Dynamic soundtrack. Music layers change with exploration, combat, and story beats.
- Each district has its own genre (chiptune, funk, electro, industrial).

## Target Experience
Players should feel the thrill of a late-night arcade. The game blends strategy, rhythm, and story, with satisfying build progression and shareable co-op moments.', 'deck builder, point-and-click, rpg', 'resource management, online co-op, rhythm, controller support, story rich', 'quad-core cpu, 16 gb ram, mid-range gpu', '1983-06-22 09:00:00+00'),
('Vane''s Verdict', 4.70, '# Derelict Signal

## Logline
Wake aboard a dead starship, piece together why its crew died, and unlock the hulk deck by deck. Play alone or with a friend on the same couch.

## Overview
| Field | Value |
|---|---|
| World | Derelict starship *Aurelia Vane* |
| Genres | Tactical RPG, Metroidvania, JRPG |
| Style | 2D, stylized (ink-and-neon comic look) |
| Structure | Open world, sandbox |
| Players | 1-2, local co-op |
| Hooks | Detective deduction boards, headshots |

## Story

### Act I: The Cold Boot
Two salvage operators, **Kade** (a tactician) and **Iri** (a bio-engineer), board the drifting *Aurelia Vane*. It vanished 40 years ago with 2,000 people aboard. Their shuttle is wrecked on arrival. The only way home is to restore the ship''s reactor, and the ship doesn''t want that.

### Act II: The Crew Speaks
Logs, corpses, and ghost-like echoes reveal three factions that split the ship:
- **The Wardens**: security officers who sealed the decks.
- **The Choir**: a cult that worships the ship''s AI.
- **The Graft**: mutated engineers merged with machinery.

Each faction tells a different version of the truth.

### Act III: The Verdict
The player names the true cause of the disaster on the master deduction board. The ending changes with the accusation and with which factions survive.

## Core Gameplay

### 1. Exploration (Metroidvania)
- The ship is one large interconnected 2D map, split into decks: Hangar, Medbay, Hydroponics, Reactor, Bridge, and others.
- Progress is gated by abilities, such as:
  - Mag-boots for walking on walls and ceilings
  - Airlock suits for vacuum sections
  - A plasma cutter for sealed doors
  - Hack-keys for security tiers
- Sandbox freedom: you can tackle decks in almost any order, and backtracking opens shortcuts and secrets.

### 2. Tactical Combat (Tactical RPG)
- Encounters are grid-based and turn-based, and they trigger on contact in the open world.
- Use cover, line of sight, and zero-g positioning.
- **Headshots**: aim at a specific body part.
  - A headshot deals critical damage and can stun or kill instantly.
  - Armored and mutated enemies have weak points that need scans first.
  - Ammo is scarce, so every shot matters.

### 3. Detective Deduction Boards
- Gather clues: logs, blood spatter, door records, and audio fragments.
- Pin the clues on a **deduction board** and link them with string.
- Combine two clues to form a **deduction** (for example, *"Airlock 4 opened from inside" + "Captain''s badge on the Medbay floor" = the captain fled*).
- Wrong links give false leads. NPCs react to your accusations, and correct deductions unlock new areas, dialogue options, and combat advantages.

### 4. JRPG Systems
- **Party**: Kade, Iri, plus recruitable survivors and a friendly maintenance bot.
- **Progression**: levels, skill trees, and equippable "memory chips" that grant abilities.
- **Bonds**: camp scenes and party conversations raise bond levels, which give combo attacks.
- **Story**: character-driven arcs, dramatic boss fights, and emotional set pieces.

## Local Co-op
- Player 2 drops in at any time.
- **Exploration**: both players move freely, and each can use their own gadget (one hacks while the other guards).
- **Combat**: each player controls their own units.
- **Deduction**: both players place clues on the shared board and debate the answer.

## Art and Audio
- 2D hand-drawn look with bold outlines, flat color, and neon accents against dark hulls.
- Each deck has its own palette, such as sickly green Hydroponics and red Reactor.
- Ambient synth soundtrack with orchestral swells in boss fights. Ship creaks and distant echoes carry the mood.

## Progression Loop
1. Explore and find clues.
2. Fight through hostile areas.
3. Solve deductions to unlock new abilities and paths.
4. Upgrade the party.
5. Reach the next deck, and repeat until the Bridge.

## Endings
- **Truth**: the ship is freed and the survivors are saved.
- **Martyr**: the ship is sacrificed so the crew''s souls can rest.
- **Scapegoat**: a wrong accusation ends in tragedy and a locked-in loop.

## Unique Selling Points
- Deduction boards are tied directly to progression and combat.
- Headshot-focused tactical combat with an emphasis on precision.
- A large, non-linear ship you can explore in any order.
- Drop-in local co-op across all systems.', 'tactical rpg, metroidvania, jrpg', 'open world, 2d, stylized, sandbox, local co-op', 'decent gaming laptop, charger plugged in', '2007-04-23 09:00:00+00'),
('Emberdeep', 21.94, '# Emberdeep: The Forge That Hungers

## Logline
Deep under a dead mountain, a dwarven forge-city wakes up hungry. Descend with a partner, fight what the smiths made, and decide who you trust, and who you tempt.

## Overview
| Field | Value |
|---|---|
| World | Karak-Vhor, a collapsed dwarven forge-city |
| Genres | Horror, erotic adventure, fighting |
| Modes | Online co-op, local co-op (2 players) |
| Style | Side-view platformer with brawler combat |
| Core mechanics | Dialogue trees, poison |

## Story

### Act I: The Cold Anvil
Two exiles, a **runesmith** and a **bladewarden**, are hired to reach the Heart Forge. Its fire has been dark for a century. The gates open too easily. Behind you, the tunnels seal.

### Act II: What the Smiths Made
The forge-city is not empty.
- **Slagborn:** molten thralls that patrol the smelting halls.
- **Whisper-Bellows:** organs of brass and flesh that mimic the voices of the dead.
- **The Ember Queen:** a dwarven matriarch fused with the forge. She is charming and dangerous, and she wants company.

The tone shifts between claustrophobic dread and heated, sensual intrigue. Romance is suggestive and mature, never a reward for grinding.

### Act III: The Heart Forge
The pair reach the Heart Forge and must choose how it ends:
1. **Reignite it:** the city lives again, at a terrible price.
2. **Quench it:** the horror ends and the treasure is lost.
3. **Bind it:** one of you stays behind as its keeper.

## Gameplay

### Platforming
- Chain-bridges, lava-cooled catwalks, swinging hammers and rail carts.
- Co-op traversal: one player pulls levers or forges footholds while the other crosses.
- Darkness is a hazard. Light comes only from your lantern or forge-glow.

### Fighting
- Heavy, weighty melee with axes, hammers and chain-whips.
- Parry and stagger system, plus co-op combos such as *Hammer & Anvil* (launch + slam).
- Bosses are living machines with multi-phase patterns.

### Poison
- **Enemies:** Slagborn spit toxic fumes. Venomous forge-spiders poison on hit.
- **Player use:** coat weapons with brewed toxins for damage over time.
- **Cures and risks:** antidotes are scarce. Some poisons cause hallucinations that change what enemies and NPCs appear to be.
- **Co-op:** partners can suck out or share poison, at a cost to the helper.

### Dialogue Trees
- Talk with the Ember Queen, trapped ghosts and rival scavengers.
- Choices affect trust, romance paths, poison-related favors and the ending.
- In co-op, each player picks a line. Conflicting answers trigger a tense **negotiation** minigame.

### Music
- A dynamic score of anvil percussion, low choir and throat-singing.
- Rhythm-based **forging** puzzles: hit the beat to craft gear.
- Enemies react to sound, so loud music attracts danger.

## Co-op
- **Online:** 2 players, drop-in/drop-out.
- **Local:** split-screen or shared screen with a dynamic camera.
- Asymmetric roles: the runesmith handles puzzles and poison, the bladewarden handles combat and defense.

## Themes
Desire versus survival, trust between partners, and the cost of forging something that lasts.

## Content Notes
Horror violence, poison and body horror, and mature sensual themes (non-explicit).', 'horror, erotic adventure, fighting', 'online co-op, local co-op, music, platformer', 'gtx 1060, 8 gb ram, ssd recommended', '1981-03-10 09:00:00+00'),
('Blindspot Alley', 25.49, '# Neon Alley: Last Block Standing

## Overview
A moddable, massively multiplayer **city builder / tower defense / simulation** set in one sprawling cyberpunk alleyway. You start with a single dumpster corner and grow it into a fortified, self-feeding micro-district. Players can also fight in it.

---

## Story
### Act 1: The Dumpster Days
The megacorp **Helix-Vance** has bulldozed the surrounding districts. One alley survives, because the surveillance grid has a blind spot there. You and a few thousand other squatters are the last residents. Each of you claims a plot along the alley''s length.

### Act 2: The Long Block
Rain never stops. Neon signs flicker over stacked shanties. The alley becomes a living neighborhood with markets, clinics, hydroponic racks and noodle stands. Helix-Vance sends **cleaner waves**: drones, enforcer squads and hacked mechs. They probe for the blind spot.

### Act 3: Blackout
Once the corp finds the blind spot, it launches a district-wide purge. The players'' last stand decides whether the alley becomes a free zone or a corporate parking lot.

---

## Core Gameplay Loops

### 1. City Building
- Build **shanties, workshops, clinics, bars and power hubs** on vertical, modular plots.
- Grow upward (scaffolds, rooftops) and sideways (connecting alley branches).
- Manage **power, water, heat and morale**.
- Districts of neighboring players can be linked by walkways, trade lines and shared defenses.

### 2. Farming and Crops
- Grow crops in **rooftop hydroponics, vertical racks and neon-lit fungus cellars**.
- Example crops:
  - **Glowmoss**: fast growth, feeds the population.
  - **Synth-rice**: staple food and trade good.
  - **Chem-bloom**: source of stims and medicine.
  - **Wire-vine**: grows into cable and crafting material.
- Crops need light, water and nutrients. Pollution events and blackouts can ruin a harvest.
- Food supply drives population, worker efficiency and fighter stamina.

### 3. Tower Defense
- Waves approach along the alley''s choke points and rooftops.
- Defenses:
  - **Turrets**: coil guns, flame vents, EMP pylons.
  - **Traps**: tripwires, shock plates, sinkholes.
  - **Hacking nodes**: turn enemy drones or slow their targeting.
- Enemies:
  - **Scrap drones**: fast, weak, arrive in swarms.
  - **Enforcers**: armored and ranged.
  - **Siege mechs**: destroy buildings and are the boss-tier threat.
- Waves scale with server-wide alley progress, so cooperation matters.

### 4. Fighting
- Players enter real-time **melee and ranged combat**.
- Modes:
  - **Defense**: join the wave fight in person.
  - **PvP turf wars**: raid or defend rival blocks.
  - **Arena pits**: bet-based duels in back-alley cages.
- Gear is crafted from farmed and scavenged materials (cyberarms, blades, shock gloves).

### 5. Respawn Timers
- Downed players respawn at a **clinic or safehouse** after a timer.
- Timers scale with:
  - Clinic level (shorter is better).
  - Death frequency (repeat deaths mean longer waits).
  - Waves in progress (longer during a purge).
- Teammates can **revive** you early with med-kits or hacks.
- Downed defenders also drop a **cred-chip** that enemies can steal.

---

## Simulation Layer
- **NPC residents** have jobs, needs and moods: farmers, mechanics, medics, guards.
- **Economy**: player-run markets with fluctuating prices for food, parts and tech.
- **Environment**: weather, blackouts, smog and corp surveillance sweeps affect production and combat.
- **Heat meter**: high visibility attracts stronger waves. Stealth and jamming tech reduce it.

---

## Massively Multiplayer Features
- **Shared alley server**: thousands of players along one continuous, scrolling alley.
- **Guilds ("Crews")**: co-own buildings, pool defenses and vote on district policies.
- **Server-wide events**: corporate purges, black-market festivals, drone plagues.
- **Trade routes** and diplomacy between neighboring blocks.

---

## Moddability
- Full **mod API** (Lua or JSON plus scripting) for:
  - New buildings, crops, enemies, weapons and skins.
  - Custom wave logic and game modes.
  - UI and quality-of-life tools.
- **Workshop hub** with ratings, versioning and server-side mod whitelisting.
- Modded servers can run **total conversions**, such as a solarpunk or horror alley.

---

## Progression
| Stage | Focus | Unlocks |
|---|---|---|
| Squatter | Survive, farm basics | Shanty, first crops, basic turret |
| Block Boss | Expand, trade | Clinics, markets, walkways |
| Crew Leader | Organize, defend | Shared defenses, guild halls |
| Alley Legend | Lead the purge defense | Mega-structures, elite mods |

---

## Tone and Visuals
- Rain-slick streets, buzzing holo-ads, steam vents and cramped vertical architecture.
- A synthwave and industrial soundtrack that shifts from calm to tense as waves approach.
- Gritty but hopeful: small communities resisting a giant machine.

---

## Tagline
> *One alley. Ten thousand neighbors. No way out but up.*', 'city builder, tower defense, simulation', 'moddable, massively multiplayer, fighting', 'rtx 4070, 32 gb ram, nvme ssd', '1997-11-08 09:00:00+00'),
('Pebble Pusher Inc.', 12.94, '# Rock Bottom: Asteroid Outpost Tycoon

> *"Dig deep. Dream small. Pay your oxygen bill."*

## Elevator Pitch
You run a shabby mining outpost on a drifting asteroid. Your boss is a passive-aggressive corporate AI. Click rocks, recruit oddball crew, build modules, and expand across the belt. The game is a **comedy 4X city-builder clicker** played entirely with **point & click** in **singleplayer**.

## Story

### Act 1: The Pebble
You wake up as the newly "promoted" Outpost Manager of **Outpost 7-B**. The promotion came with no raise and no manager before you. The AI overseer **MOTHER-IN-LAW** (MIL) hands you a pickaxe and a cheerful eviction notice from the company. You have to hit quota, or the airlock gets "restructured."

### Act 2: The Belt
Your rock turns profitable. Rival outposts appear, and so do shady traders, space unions, and a cult that worships a very large potato-shaped asteroid. You explore, trade, and scheme for control of the belt.

### Act 3: The Payout
The company''s real plan comes out: the whole belt is one big tax write-off, and your success is a **bug**. You choose how it ends: sabotage MIL, buy the company, or start a rival empire from a lunchroom.

## Core Gameplay Loop
1. **Click** asteroids to mine ore. Each click gets a comic, escalating reaction.
2. **Build** modules on the outpost grid.
3. **Draft** crew and upgrades from card offers.
4. **Expand** by claiming neighboring asteroids (4X).
5. **Survive** quota audits and events.
6. **Prestige** with a company "restructure" and start again with perks.

## The 4X Layer
| X | How it plays |
|---|---|
| **Explore** | Point & click star map. Scan asteroids and find anomalies and junk. |
| **Expand** | Plant flags, build satellite outposts, and link them with tunnels and shuttles. |
| **Exploit** | Refine ore into metals, ice, and "mystery goo." |
| **Exterminate** | Mostly played for laughs: hostile takeovers, lawsuits, and space pigeons. |

## City Builder Layer
- Grid-based habitats: **Bunks, Mess Hall, Oxygen Plant, Refinery, Bar, HR Office, Meme Lab**.
- Adjacency bonuses. The Bar next to the Bunks boosts morale and also causes accidents.
- Crew needs: air, food, sleep, and dignity, which is nearly always at zero.

## Mechanic: Drafting
Every shift, MIL deals **3-5 cards**. Pick one and the rest are discarded to the "Recycle Bin."

- **Crew cards:** Grumpy Veteran, Intern With Drill, Sentient Toaster.
- **Module cards:** Coffee Reactor, Zero-G Gym.
- **Policy cards:** "Mandatory Fun," "Unpaid Overtime."
- **Curse cards:** bad picks with a big upside.

Drafted cards form your **deck of outpost traits**. Card synergies drive your build (for example, a Toaster plus Bar plus Intern builds a "Toast Cult").

## Mechanic: Pity System
Drafting and loot can be unlucky, so a visible **"Pity Meter"** protects you:
- Each bad draft or empty dig fills the meter.
- At full, the next offer is guaranteed **rare or better**.
- MIL comments on it: *"Wow. Statistically, you''re a tragedy. Here, have a legendary."*
- Meters are separate for crew, modules, and asteroid finds.
- Pity carries over between prestige runs, softened.

## Comedy & Tone
- Deadpan corporate memos as loading screens.
- Every crew member has barks and a tiny bio.
- Random events: "Union Meeting in Vacuum," "Someone Microwaved Fish."
- Achievements like *"OSHA Is Crying."*

## Progression
- **Short term:** upgrade the pickaxe, hire crew, unlock modules.
- **Mid term:** claim asteroids, set trade routes, meet quotas.
- **Long term:** restructure (prestige), unlock new company factions and deck archetypes.

## Art & Audio
- Chunky hand-drawn 2D art with a retro-futurist palette.
- Bouncy lounge-jazz soundtrack that gets more chaotic as the outpost grows.
- Satisfying, exaggerated rock-crunch sounds.

## Target Audience
Fans of idle games, cozy management, and dry humor who want short sessions with long-term planning.

## Session Style
- **Casual:** 5-10 minute click bursts.
- **Deep:** 1-2 hour planning runs.
- **Full playthrough:** about 15-20 hours, plus replays with different factions.', '4x, city builder, clicker', 'comedy, point & click, singleplayer', 'gtx 1060, 8 gb ram, ssd recommended', '1987-04-30 09:00:00+00'),
('Thalassa''s Lament', 12.44, '# Abyssal Requiem

*A dark isometric mystery set in a drowned city that remembers everything.*

## Overview
| Field | Detail |
|---|---|
| World | Thalassia, a collapsing underwater city |
| Genres | Shooter, visual novel, platformer |
| Perspective | Isometric |
| Tone | Dark, oppressive, mysterious |
| Style | Soulslike: punishing, pattern-driven, and rewarding |
| Input | Full controller support |

## Premise
Thalassia was built to outlast the surface world. Now its pressure seals are failing, and its 40,000 citizens have vanished. Only a few remain, and they are warped and silent. You play **Ren Halloran**, a salvage diver. A distress signal in your dead wife''s voice draws you into the city''s depths. She died on the surface five years ago.

## Story Structure

### Act I: The Descent
- Ren enters through the flooded Harbor District.
- He meets **Sister Vael**, a survivor who claims the city "speaks" to its dead.
- **Visual novel scenes** play out in flickering safe rooms called *Airlocks*. Dialogue choices shape trust, memory, and later endings.
- First boss: **The Harbormaster**, a fused mass of dock machinery and a former officer.

### Act II: The Drowned Districts
- Ren travels through the Garden Dome, the Cathedral of Tides, and the Reactor Ward.
- Recovered audio logs reveal that the city''s AI, **MOTHER TIDE**, began "preserving" citizens as data and as flesh.
- Rival survivors offer alliances, each with a hidden agenda.
- Ren realizes the signal may not be his wife. It may be a copy built from his own memories.

### Act III: The Core
- Ren descends into the Abyssal Core, where MOTHER TIDE waits.
- The final choices depend on the trust you built, the truths you uncovered, and the relics you carried.

### Endings
1. **Release:** flood the city and free the trapped minds.
2. **Preservation:** merge with MOTHER TIDE and stay with the echo of your wife.
3. **Ascension:** escape with the survivors and leave the truth buried.
4. **Requiem:** a hidden ending that requires every lore fragment.

## Gameplay

### Real-Time Combat (Shooter, Soulslike)
- Isometric twin-stick shooting with a dodge-roll and stamina system.
- Enemies follow readable patterns and punish button-mashing.
- Weapons include harpoon guns, pressure-cannons, and arc-welders.
- Ammo is scarce, and reloading leaves you exposed.
- Dying drops your **Echoes** (currency) at the spot where you died. Recover them, or lose them for good.
- Checkpoints, called *Beacons*, respawn enemies.

### Platforming
- Traverse broken walkways, pipe networks, and collapsing glass tunnels.
- Use the grapple line, air-dash, and buoyancy jets.
- Some zones have shifting water currents and timed pressure hazards.

### Inventory Management
- Grid-based backpack with limited slots.
- Oxygen tanks, ammo, tools, and lore items compete for space.
- Crafting and repair happen only at Beacons.
- Heavy gear slows movement and drains oxygen faster.
- Cursed relics grant strong bonuses but corrupt your stats and change dialogue options.

### Visual Novel Segments
- Branching conversations at safe rooms and with key NPCs.
- Memories can be *examined* for clues, which feed the mystery.
- Choices unlock new areas, items, and endings.

## Mystery Systems
- **Case Board:** link clues, logs, and testimonies to form theories.
- **Echo Visions:** touch relics to replay the final moments of citizens.
- Some truths are missable and are gated behind optional bosses and secret rooms.

## Visual and Audio Direction
- Dark isometric dioramas with bioluminescent accents.
- Murky water, drifting particles, and flickering emergency lights.
- Muffled ambient sound, low cello drones, and distorted radio static.
- Visual novel scenes use painted, hand-inked character portraits.

## Controller Support
- Twin-stick aiming with adjustable aim assist.
- Radial menu for quick item use.
- Inventory navigation with a cursor, designed for gamepad play.
- Full button remapping and haptic feedback for pressure and hits.

## Design Pillars
1. **Mystery over exposition:** the story is pieced together, not told.
2. **Tense survival:** every resource and decision has weight.
3. **Fair difficulty:** deaths teach the player, and progress persists.
4. **Emotional descent:** the deeper you go, the closer you get to the truth about Ren.', 'shooter, visual novel, platformer', 'mystery, isometric, controller support, dark, soulslike', '6 gb vram, 12 gb ram, 20 gb free space', '2004-12-21 09:00:00+00'),
('Lumen Last Call', 0.23, '# Event Horizon Party
*A casual match-3 clicker about throwing the last great party at the edge of a black hole.*

## Premise
A colony station, **Lumen Ring**, orbits just outside a black hole''s event horizon. Time crawls here: one hour on the station is a year for the outside universe. The residents have a choice. They can mourn the end of everything, or they can throw the best party the cosmos has ever seen.

You are the **Master of Ceremonies**. You build the city, keep the crowd happy, and settle fights before they spread.

## Story Structure

### Act 1: Arrival
- The station is a tiny ring of scrap and glowing crystals.
- An NPC named **Mira**, the station engineer, tells you that gravity will eventually pull the ring in.
- The only power source is **Joy Energy**, which comes from happy residents.
- *Goal:* start the first party and light the ring.

### Act 2: The Long Night
- Residents arrive from other timelines, and each has a different agenda.
- Rival factions clash over the music, the space, and the guest list.
- Ghost echoes of past parties start to appear. They warn you of a mistake you have not yet made.
- *Goal:* unite the factions and build the Grand Ballroom.

### Act 3: The Horizon
- The ring drifts closer to the edge.
- The final party is a race between joy and gravity.
- The ending depends on your choices.
    - **Eternal Dance:** the party is frozen at the horizon forever.
    - **Light Escape:** the crowd rides a burst of energy back out.
    - **Singularity Song:** everyone merges into one shared melody.

## Core Gameplay Loops

### 1. Match-3: Mixing the Vibes
- Match glowing tiles on a board bent by gravity: **Music, Food, Light, Dance, Drink, Laughter**.
- Matches produce Joy Energy.
- Bigger combos trigger **gravity waves** that shift rows and open chain reactions.

### 2. Clicker: Feeding the Party
- Tap the central **Disco Core** to generate Joy.
- Upgrades add auto-clickers such as DJ bots, light rigs, and snack drones.
- Idle income grows while you are away, though time dilation makes it strange.

### 3. City Builder: The Ring
- Place modules: **dance floors, bars, arcades, quiet lounges, repair docks**.
- Adjacent modules boost each other, for example bar + dance floor.
- Districts unlock new residents and new match-3 tile types.

### 4. Fighting: Bouncer Duels
- When tension rises, brawls break out.
- Fights are quick, rhythm-based duels using timing taps.
- Win to calm the crowd. Lose and the module is damaged.
- You can also settle a fight with a good match-3 combo, which ends it peacefully.

## Special Mechanics

### Ghost Replays
- Each party is recorded.
- Past runs return as translucent **ghost guests** that repeat your old actions.
- Ghosts can help. A ghost DJ keeps a rhythm going, for example.
- Ghosts can also cause trouble if your old choices were bad.
- You can study a ghost to find better strategies or to avoid old mistakes.

### NPC Schedules
- Every resident follows a daily routine that time dilation stretches and warps.
- Example: **Kade the bartender** works 18:00-02:00, then sleeps.
- You place modules and events to match their schedules.
- Meeting an NPC at the right moment unlocks story scenes and bonuses.
- Missing them can cause conflicts.

## Key Characters
| Name | Role | Quirk |
|---|---|---|
| **Mira** | Engineer | Fixes anything, fears silence |
| **Kade** | Bartender | Knows every timeline''s gossip |
| **Vex** | Rival DJ | Wants to own the main stage |
| **Oro** | Ghost curator | Speaks only in echoes of past parties |

## Tone & Visuals
- Neon colors against a dark, warped sky.
- Stars stretch into rings near the horizon.
- Upbeat synth music that slows and distorts as gravity increases.
- Humor, warmth, and a hint of melancholy.

## Progression
1. Build modules and earn Joy.
2. Unlock residents and their stories.
3. Manage schedules, fights, and ghosts.
4. Reach the final party and pick an ending.
5. **New Game+:** your ghost crowd from the previous run starts the next party with you.

## Hook
*"The universe is ending at the edge of the horizon. Make it dance."*', 'casual, match-3, clicker', 'party game, city builder, fighting, narrative, clicker', 'decent gaming laptop, charger plugged in', '1984-12-08 09:00:00+00'),
('Emberlight & Lace', 15.60, '# Beacon of Embers

*A pixel-art medieval lighthouse platformer with an adults-only (18+) romantic streak.*

## Overview
| Field | Value |
|---|---|
| World | A crumbling lighthouse on a cliff |
| Genres | Casual, point-and-click, adult (mature themes, non-explicit) |
| Style | Pixel graphics, cartoon, medieval |
| Core mechanics | Cooldowns, buffs and debuffs |

## Story
**Prologue.** The kingdom of Valemere is under a curse. Its sea-beacon, the Lighthouse of Embers, has gone dark, and ships wreck on the rocks every night. Mira is a witty, adult lamplighter''s apprentice. She inherits the tower and finds it is haunted by charming, flirtatious spirits. Each one is bound to a floor and wants a favor before it will help.

**Act I: The Foot of the Tower.** Mira meets the gruff knight Aldric, a ghost still on watch, and the mischievous sea witch Selene. She learns the flame can only be relit by collecting three Ember Shards. Each shard is guarded by a spirit whose trust she has to earn.

**Act II: The Ascent.** Every floor has its own theme: the armory, the alchemy loft, the moonlit balcony. Mira''s bond with each spirit grows through banter, gifts and shared quests. Romance scenes are teasing and suggestive, fade to black, and stay tasteful.

**Act III: The Last Light.** A jealous storm-wraith tries to keep the tower dark. Mira''s choices decide who stands beside her at the lantern room. The game has 3 endings, plus a secret "Found Family" ending.

## Gameplay
- **Point-and-click exploration.** Click objects, talk to characters, combine items and solve gentle puzzles. There is no fail state, which suits the casual pace.
- **Platforming.** Side-scrolling climbs across beams, chains and rooftops. Jumps are forgiving and the controls are simple.
- **Relationship system.** Dialogue choices raise or lower each spirit''s affection.

## Mechanics: Cooldowns, Buffs and Debuffs
**Cooldowns**
- *Lantern Flash* stuns enemies and reveals hidden paths (10s).
- *Rope Toss* is a grapple for reaching ledges (6s).
- *Charm Wink* is a social ability that opens extra dialogue options (once per scene).

**Buffs**
- *Warm Glow* gives faster movement.
- *Sea Blessing* gives a double jump.
- *Knight''s Oath* gives damage resistance.

**Debuffs**
- *Salt Chill* slows movement.
- *Wraith Fog* blurs the screen and disables clicks briefly.
- *Jealous Curse* locks certain dialogue choices for a while.

Potions, food and spirit gifts trigger these effects. Managing the timing of cooldowns and effects is the main skill in both platforming and social scenes.

## Visuals and Audio
- Colorful 16-bit pixel art with exaggerated, cartoon-style characters and expressive animations.
- A warm lantern-light palette by day and cool moonlit blues by night.
- A medieval-folk soundtrack with lute, flute and sea-shanty motifs.

## Target Audience
Adults 18+ who like cozy, humorous games, romance-driven stories and light platforming.', 'casual, point-and-click, hentai', 'pixel graphics, cartoon, platformer, medieval', 'quad-core cpu, 16 gb ram, mid-range gpu', '2002-07-03 09:00:00+00'),
('Deadwater Hook', 10.10, '# Harbor Dead

*An isometric pixel-art open world MMORPG of survival, trivia, and mature themes.*

> Note: the adult content is kept non-explicit. It appears as implied, consensual relationship scenes between adult characters, gated behind an opt-in toggle.

---

## 1. Elevator Pitch
A quarantined port city has fallen to the undead. Thousands of players share one persistent harbor. They scavenge, form settlements, and learn the truth about the outbreak by answering trivia that unlocks the city''s secrets. Movement relies on a **grappling hook** across cranes, ships, and rooftops. **Checkpoints** are the only safe anchors in a dead city.

---

## 2. Setting: Port Calder
- A sprawling industrial harbor city with realistic geography and tides.
- **Districts:**
  - **Container Yards:** mazes of stacked steel boxes.
  - **Old Town Docks:** narrow, wooden, and dense with infected.
  - **Lighthouse Ridge:** a high, calm area for safe houses.
  - **Fish Market:** a trading hub and social district.
  - **Drowned Quarter:** flooded streets, reachable only at low tide.
  - **Shipyard Graveyard:** rusted wrecks holding rare loot.
- Day and night cycles, weather, and tides change zombie behavior and route access.

---

## 3. Story

### Act I: The Last Ferry
Players arrive on the last evacuation ferry. It is sabotaged and wrecked at the pier. Survivors wake up stranded in a city that the military has sealed off.

### Act II: Whispers on the Radio
A pirate radio station broadcasts cryptic trivia questions. Correct answers reveal coordinates, keys, and lore. The broadcaster is a former harbor scientist who claims to know the outbreak''s source.

### Act III: The Cargo
Players trace the infection to a sealed container brought in on a foreign freighter. Factions fight over the truth and over the cure.

### Act IV: Tide Change
Server-wide events decide the harbor''s fate. The port can be cleansed, walled off, or left to the dead, and each outcome reshapes the world.

---

## 4. Gameplay

### Core Loop
1. Explore and scavenge.
2. Answer trivia to unlock caches, doors, and story.
3. Fight or evade zombies.
4. Save progress at checkpoints.
5. Build up settlements and relationships.

### Grappling Hook
- Swing between cranes, rooftops, and ship rigging.
- Pull loot from ledges and yank items or enemies.
- Escape hordes by going vertical.
- Upgrades add range, load capacity, and silent deployment.

### Checkpoints
- Found as lit lanterns, buoys, or radio beacons.
- They give respawn, storage, and fast travel.
- Players can claim and defend them.
- Death away from a checkpoint costs part of your loot.

### Trivia System
- Radio quizzes, locked terminals, and NPC riddles.
- Categories: maritime history, science, survival, and local lore.
- Difficulty rises with rewards.
- Co-op mode lets teams answer together.
- Timed trivia during zombie sieges adds pressure.

### Combat and Survival
- Realistic systems: hunger, injuries, infection, fatigue, and noise.
- Limited ammo favors stealth and improvised weapons.
- Zombies are attracted by sound and light, and they grow more aggressive at night.

---

## 5. MMO Features
- **Factions:** Dockworkers, Coast Guard remnants, Smugglers, and the Cleansers.
- **Settlements:** player-built bases with defenses, farms, and workshops.
- **Economy:** barter-based, with a fish market auction house.
- **Events:** zombie tides, freighter arrivals, and radio broadcast raids.
- **PvE/PvP zones:** safe zones at checkpoints, contested zones elsewhere.

---

## 6. Mature Content
- Opt-in only, with an age gate.
- Adult relationship storylines with companions and other players.
- Implied intimacy through fade-to-black scenes.
- Relationships give gameplay buffs such as morale, shared safe houses, and companion skills.
- Consent is a core design rule, and players can filter or block content.

---

## 7. Visual and Audio Style
- **Graphics:** detailed isometric pixel art with dynamic lighting, fog, and rain.
- **Realism:** gritty palettes, believable architecture, and grounded character design.
- **Audio:** creaking wood, gulls, distant groans, and a lo-fi synth radio soundtrack.

---

## 8. Progression
- Skill trees: Scavenger, Climber, Scholar, Fighter, and Socialite.
- Trivia mastery unlocks lore, gear blueprints, and titles.
- Prestige through settlement rank and faction reputation.

---

## 9. Unique Selling Points
- Grappling-hook traversal on an isometric map.
- A trivia-driven mystery embedded in the world.
- A shared city where player choices change the harbor.
- A survival tone that is both grim and social.', 'open world, mmorpg, hentai', 'zombies, realistic, pixel graphics, trivia, isometric', 'runs on a 10 year old laptop, fan screaming', '2022-08-22 09:00:00+00'),
('Emberroad', 13.89, '# Dust & Lanterns

*A relaxing, stylized card-driven roguelite JRPG set in a desert caravanserai.*

---

## Overview

| Field | Details |
|---|---|
| **World** | Desert caravanserai |
| **Genres** | Interactive fiction, roguelite, JRPG |
| **Tags** | Card game, relaxing, RTS, narrative, stylized |
| **Mechanics** | Army upkeep, random loot tables |

**Pitch:** You are the new keeper of a fading caravanserai on a forgotten trade road. Each night, caravans arrive with strangers, secrets, and trouble. Each dawn, you send your card-based retinue out into the dunes. Manage your people, tell stories, and rebuild the inn into a legend.

---

## The Story

### Prologue: The Last Lantern
Your mentor, the old keeper, vanishes in a sandstorm. She leaves you a cracked brass lantern and a ledger full of debts. The lantern is said to guide lost travelers home. It flickers with each **run** you take, and each time it fails, the desert rewrites the road.

### Act Structure
1. **Arrival:** Learn the inn, meet the first staff, and survive a short trade route.
2. **The Shifting Road:** Each run reshapes the map. Rival caravans, ruins, and oases appear, and each carries its own story thread.
3. **The Buried City:** Fragments of the mentor''s past point to a sunken capital under the dunes.
4. **The Last Night:** The lantern is relit or surrendered. Endings depend on the bonds you formed and the choices you made.

---

## Core Gameplay Loop

```
DUSK  -> Host caravans, read stories, make choices
NIGHT -> Manage the inn (RTS-lite): assign staff, upkeep, trade
DAWN  -> Send your card army on an expedition (JRPG battles)
RETURN-> Loot, repair, rest, and upgrade
FALL  -> If the run fails, the lantern resets the road (roguelite)
```

### 1. Dusk: Interactive Fiction
- Travelers arrive with **branching dialogue** and moral choices.
- Stories decide who joins you, which rumors you hear, and which routes unlock.
- Text is written in a warm, poetic tone with stylized illustrated scenes.

### 2. Night: Caravanserai Management (RTS-lite)
- Real-time but **pausable and gentle**. There are no fail-state rushes.
- Assign staff to the **stables, kitchen, forge, well, and market stalls**.
- Build and upgrade rooms, courtyards, and defenses.
- Keep the mood **calm**, with lantern light, music, and idle animations.

### 3. Dawn: Card-Based JRPG Expeditions
- Your **army is a deck**. Each unit is a card, such as a guard, scout, mystic, or camel rider.
- Turn-based battles use formations, JRPG-style skills, and combo chains.
- Cards level up, gain traits, and form bonds with each other.

### 4. Return: Loot and Growth
- Expeditions end at an oasis, ruin, or trade post.
- **Random loot tables** drop relics, recipes, gear, and story items.
- Rarity tiers are *Common, Uncommon, Rare, Relic, and Legend*.

---

## Key Mechanics

### Army Upkeep
Your retinue needs care. Every card has upkeep costs:
- **Food and water:** Rations drain each day.
- **Wages:** Mercenaries want coin.
- **Morale:** Rest, music, and good stories keep them loyal.
- **Gear wear:** Weapons and armor need repair.

*Design intent:* Upkeep is a soft pressure. It makes you weigh a large army against a lean, well-fed one, and never feels punishing.

### Random Loot Tables
- Every region has its own **weighted table** (dunes, ruins, oases, storm zones).
- Weather and time of day shift the odds.
- **Pity timers** guarantee a rare drop after a streak of bad luck.
- Rare finds unlock **new cards, rooms, and story branches**.

### Roguelite Progression
- **Runs** are expeditions with a shifting map.
- **Permanent unlocks** include inn upgrades, new staff, and starting decks.
- **Lantern Memories** are meta-currency earned through story moments.

---

## Card Types

| Type | Role | Example |
|---|---|---|
| **Warrior** | Front-line defense and attack | Sand Guard |
| **Scout** | Reveal the map and set traps | Dune Fox |
| **Mystic** | Buffs, weather magic, healing | Lantern Priest |
| **Merchant** | Boost loot and trade | Silk Broker |
| **Beast** | Mounts and heavy hitters | War Camel |
| **Relic** | Passive items and one-time effects | Mirage Compass |

---

## Characters

- **The Keeper (You):** A quiet newcomer bound to the lantern.
- **Samira, the Cook:** Warm and blunt. She feeds your army and gossips about everything.
- **Idris, the Retired Captain:** A veteran who trains new recruits and hides his old shame.
- **Nuru, the Stray Mystic:** A young wanderer who hears whispers in the sand.
- **The Vizier of Ash:** A rival trader who wants to buy the inn.

---

## Art and Audio

- **Art style:** Stylized, hand-painted, and warm. Amber, teal, and rose tones with soft shadows.
- **UI:** Parchment ledgers, brass fixtures, and card frames that look like woven cloth.
- **Music:** Relaxed oud, hand drums, and wind-chime ambience. Battles add layered percussion.
- **Sound:** Crackling fire, rustling tents, and distant camel bells.

---

## Tone and Player Experience

- **Relaxing:** No harsh timers. Failure teaches you and never punishes you.
- **Narrative-rich:** Every guest has a tale worth hearing.
- **Strategic but cozy:** Small, meaningful decisions add up over many nights.
- **Replayable:** Shifting roads, random loot, and branching stories make every run different.

---

## Tagline

> *"Keep the lantern lit. The desert remembers every guest."*', 'interactive fiction, roguelite, jrpg', 'card game, relaxing, rts, narrative, stylized', 'rtx 4080 or better; your pc will hum a lullaby', '1990-07-03 09:00:00+00'),
('Kelp & Keel', 17.23, '# Barnacle Acres

*A retro text-based farming sim on a sunken ship.*

## Overview
You wake as the last caretaker of the **S.S. Marrow**. The liner sank a century ago and now rests on the ocean floor. Its air pockets still hold. Grow crops in the flooded decks, rebuild the ship into a living settlement, and decide what the wreck''s secrets mean for the survivors.

- **Genres:** farming sim, text adventure, simulation
- **Tags:** retro, text-based, roguelite, city builder, PvE
- **Mechanics:** minimap, branching narrative choices

## Story

### Act I: The Drowned Bell
You wake in the crew quarters. The bell rings once, though nobody is there to ring it. A handful of survivors gather in the dry galley. You have a rusted trowel, a sack of glow-kelp spores, and 72 hours of air. Someone has to make the wreck livable.

### Act II: The Green Deck
Your first gardens take hold. Then the ship starts to answer you. Sealed doors open when the crops thrive. A mechanical voice in the radio room says it is the *Ship''s Mind*. It offers help, and it wants something in return. Each choice you make shifts the settlers'' trust in you, in the Mind, or in neither.

### Act III: The Surface Question
The wreck is failing, and every choice leads toward one of three endings:
1. **Rooted:** seal the ship and make it a permanent home.
2. **Ascent:** build a rising vessel and take everyone to the surface.
3. **Merge:** give the Mind control and become part of the ship.

## Gameplay

### Farming
- Grow **glow-kelp, pressure-beans, brine-wheat, and lantern-mushrooms**.
- Crops need light, oxygen, and the right salinity.
- Tides, leaks, and pests such as **rust-crabs** change your yields.

### City Builder
- Turn decks into districts: **Hydroponics, Workshop, Lodgings, Clinic, Shrine, Airlock Market**.
- Assign settlers by skill and mood.
- Balance air, power, food, and morale.

### Text Adventure
- Explore by typing commands (`look`, `go aft`, `use valve`).
- Find logs, relics, and hazards in unflooded rooms.
- Talk to settlers and to the Ship''s Mind.

### Minimap
An ASCII deck map shows which rooms are flooded, powered, or unexplored.
```
+---------+---------+
| [G]arden|  Galley |
|   ~~~   |   @     |
+---------+---------+
| Engine  |  ????   |
+---------+---------+
```

### Branching Choices
- Dialogue and events lead to different outcomes.
- Choices have lasting effects: allies, sealed rooms, altered crops.
- Some options only appear if you have the right tools or reputation.

### Roguelite Loop
- If the settlement collapses, the **Marrow resets**.
- Each new run keeps **Memory Pearls**: story clues, seed varieties, and blueprint fragments.
- Every run reshuffles the map, events, and survivors.

## Challenges (PvE)
- Leaks, oxygen crashes, and fires.
- Deep-sea creatures that come through breached hulls.
- Settler disputes and shortages.
- Random events such as storms, quakes, and salvage drops.

## Visual and Audio Style
- Green-on-black terminal look with ASCII art.
- Chiptune ambience with sonar pings and creaking metal.
- Short, atmospheric text with dry humor.

## Why Play
You get a cozy farm that is always at risk. Each run tells a slightly different story, and every choice changes the ship.', 'farming sim, text adventure, simulation', 'retro, text-based, roguelite, city builder, pve', 'decent gaming laptop, charger plugged in', '2011-10-24 09:00:00+00'),
('Belltoll Ridge', 18.20, '# Cliffside: Echoes of the Ridge

## Overview
**Cliffside** is a stylized, casual **4x turn-based strategy** game told as **interactive fiction**. You guide a fading mountain village clinging to a vertical cliff. You expand it, gather resources, solve puzzles, and keep the rhythm of the wind and stone.

- **World:** Cliffside village
- **Genres:** 4x, interactive fiction, turn-based strategy
- **Tags:** puzzle, casual, rhythm, stylized
- **Mechanics:** wall running, resource gathering

---

## Story

### Prologue: The Silent Bell
For generations, the village of **Halvren** hung from the Great Cliff. Its people lived by the **Bell of Winds**, a huge bronze bell whose tolling kept the cliff stable and the weather calm. One dawn the bell falls silent. Cracks spread across the rock, and the terraces begin to slip.

You are the **Warden**, the village''s newest steward. You have to find out why the bell went quiet and lead your people upward to safety.

### Act I: Foothold
Halvren is only a handful of ledges. You learn to survive here: gather supplies, repair walkways, and meet the first villagers. Each one has a personal story that you shape through dialogue choices.

### Act II: Ascent
The village grows up the cliff. You meet rival settlements such as the **Glassmoss Clan** and the **Ropewrights of Tarn**. You can trade, ally, or compete with them. Old murals reveal that the bell was once one of many.

### Act III: The Summit Chorus
At the peak you find the other bells. Restoring them takes a full **rhythm-based ritual**. Your earlier choices decide the ending:
- **Harmony:** the cliffs sing, and all settlements unite.
- **Dominion:** you rule the ridge by force of rhythm and resources.
- **Silence:** you free the cliff from the bells and live with the risk.

---

## Core Gameplay Loop

### The 4X Layer (Turn-Based)
| Pillar | In Cliffside |
|---|---|
| **Explore** | Scout new ledges, caves, and ruins by wall running |
| **Expand** | Build terraces, rope bridges, and pulley lifts |
| **Exploit** | Gather resources and tune production |
| **Exterminate** | Reframed for a casual tone: *outmaneuver* rivals through contests, blockades, and rhythm duels |

Each turn is one "day-beat". You assign villagers, spend resources, and react to story events.

### Wall Running
- Scouts and runners sprint along vertical and diagonal cliff faces.
- Movement on the tile map is limited by **stamina** and **surface type**: mossy, icy, and crumbling rock all behave differently.
- Wall runs unlock shortcuts, hidden resource nodes, and rescue missions.
- Tapping in time with the wind rhythm gives bonus speed.

### Resource Gathering
- **Stone:** builds and reinforces structures
- **Fiber:** makes ropes, bridges, and clothing
- **Resin:** trade good and bell-repair material
- **Glowmoss:** powers lanterns and rituals
- **Windglass:** rare crystal that tunes bells

Gathering nodes form small puzzles. You route runners efficiently, chain harvests, and avoid rockfall.

### Puzzle Elements
- **Ledge puzzles:** rearrange bridges and lifts to connect isolated areas.
- **Bell tuning:** match tones and patterns to restore each bell.
- **Cliff mechanisms:** ancient locks that open with the right combination of weight, wind, and timing.

### Rhythm Layer
- The village has a **heartbeat tempo** that changes with the weather.
- Certain actions, such as harvesting, wall runs, and rituals, are timed to the beat.
- Good timing gives bonuses. Missed beats never punish harshly, which keeps the game casual.

---

## Interactive Fiction Elements
- Branching text events each turn, with choices that affect morale, relationships, and factions.
- Villager storylines, such as a grieving bellringer or a reckless young climber, unfold across the campaign.
- Your decisions leave lasting marks on the village''s look and culture.

---

## Art & Audio Style
- **Stylized** look: bold shapes, painterly textures, and a warm-to-cool palette that shifts with altitude.
- Soft parallax clouds and swaying rope bridges.
- Layered soundtrack: percussion, wind chimes, and bell tones respond to your actions and village state.

---

## Progression & Replayability
- Randomized cliff layouts and weather patterns.
- Three faction paths and three endings.
- Unlockable village styles, bell tunings, and challenge modes such as *Storm Season* and *Bare Ledge*.
- Sessions of 20 to 40 minutes, suited to casual play.

---

## Tagline
> *Climb together. Keep the rhythm. Wake the bells.*', '4x, interactive fiction, turn-based strategy', 'puzzle, casual, rhythm, stylized', 'any toaster with a screen', '2006-04-10 09:00:00+00'),
('Wingbeat Glade', 26.54, '# Glimmerbeat Glade

*A cute sci-fi racing-fighting RPG where music powers everything.*

## Overview
- **World:** a fairy glade fused with crashed alien tech
- **Genres:** racing, fighting, RPG
- **Tags:** sci-fi, music, cute, clicker, controller support
- **Mechanics:** wave spawning, morality system
- **Platforms:** PC and console, with full gamepad support

## Story

### Act I: The Silent Glade
Long ago, an alien starship called the *Harmonia* crashed in the Whisperwood Glade. Its core, the **Resonance Crystal**, mixed fairy magic with star-tech. It made the glade glow, sing, and bloom.

The crystal has now gone quiet. Glowing mushrooms dim and flowers stop humming. Strange **Static Wisps** drift out of the crashed hull.

### Act II: The Chosen Sprite
You play **Pip**, a small fairy mechanic with a hoverboard-like *Wingcart*. Pip finds a broken **Beat Core**, a device that turns rhythm into power. Pip must restore the crystal''s song by racing across the glade, battling the Static, and choosing what kind of hero to be.

### Act III: The Final Chorus
Two forces fight over the crystal:
- **Queen Lumina** wants to restore the old harmony by force.
- **The Glitch Choir** are corrupted machines that want to rewrite the song.

Pip''s choices decide who gets the last note.

## Core Gameplay

### 1. Racing
- Ride the Wingcart through vine tracks, mushroom loops, and neon streams.
- Drift, boost, and hit **beat gates** on the rhythm to earn speed.
- Tracks pulse with the soundtrack, and the terrain reacts to your timing.

### 2. Fighting
- Fast, cute duels and arena brawls with light, heavy, and rhythm-combo attacks.
- Landing hits on the beat builds **Harmony Combos**.
- Fights happen on the track (ram, dodge, counter) and in arenas.

### 3. RPG
- Level up **Pip** and unlock skills in three trees: *Melody*, *Machine*, and *Bloom*.
- Collect Wingcart parts, instrument charms, and outfits.
- Talk to glade villagers, take quests, and befriend characters.

### 4. Clicker Layer
- Tap or click the **Crystal Bloom** to make *Glimmer*, the idle currency.
- Glimmer keeps growing while you''re away, through **sprite helpers** who play music in the background.
- Spend it on upgrades, garden growth, and race entry perks.
- On a controller, use button-mash and rhythm-hold inputs.

## Wave Spawning
Static Wisps attack in escalating waves in arenas and on **Survival Tracks**.

| Wave | Enemies | Twist |
|------|---------|-------|
| 1-3 | Static Wisps | Learn the rhythm |
| 4-6 | Glitch Beetles | Shielded, so break the beat |
| 7-9 | Echo Drones | Mimic your attacks |
| 10 | Boss (*Discord Titan*) | Phases match the music |

- Waves get harder and reward more Glimmer and loot.
- Some waves have hidden objectives: save a villager, or spare the enemy.

## Morality System
The **Harmony Meter** tracks Pip''s choices.

- **Light path (Harmonic):**
  - Spare enemies and help villagers.
  - You get healing songs, allies, and a bright soundtrack.
- **Dark path (Dissonant):**
  - Take shortcuts, smash foes, and exploit the Static.
  - You get powerful attacks, risky boosts, and a distorted remix soundtrack.
- **Effects:**
  - Story branches and 3 endings.
  - The glade''s look and music change with your alignment.
  - Villagers react to you differently.

## Music and Style
- **Art:** pastel fairy forest with neon sci-fi accents and cute character designs.
- **Audio:** an adaptive soundtrack of chiptune, synthwave, and orchestral layers.
- Every action adds to the mix: drifting, hitting, and clicking all make sound.

## Controls and Accessibility
- Full **controller support**, with remappable buttons.
- Simple one-button rhythm mode.
- Colorblind options, visual beat cues, and adjustable timing windows.

## Progression Loop
1. Race and fight in the glade.
2. Survive waves and earn Glimmer.
3. Upgrade Pip, the Wingcart, and the sprite helpers.
4. Make moral choices that reshape the world.
5. Restore the crystal''s song, in harmony or in dissonance.

## Endings
- **Perfect Harmony:** the glade sings again.
- **Neon Remix:** a new, hybrid tech-magic era.
- **Static Silence:** the machines take over.', 'racing, fighting, rpg', 'sci-fi, music, cute, clicker, controller support', '6 gb vram, 12 gb ram, 20 gb free space', '1992-11-04 09:00:00+00'),
('DEAD BEAT DAEMON', 23.92, '# Game Description: *NULL PROCESSION*

## Overview
**World:** Digital cyberspace, a decaying network of abandoned servers, dead protocols and corrupted data streams.
**Genres:** Horror / Puzzle / Hack and Slash
**Perspective:** Top-down action
**Core hook:** You fight, solve and ride through a haunted network by **dancing**. Every move is a rhythm-based command.

---

## Story

### Prologue: The Last Ping
The Grid was once a bright, living network. Then an unknown process, **the Hollow Choir**, began to "sing" through it. Its melody turns programs into husks and rewrites their code into something hungry.

You are **Cipher**, a fragmentary daemon with no memory and a broken avatar. You are the only program that still hears the melody as *music* instead of noise. That makes you both immune to it and able to fight it.

### Act I: Boot Sector
Cipher wakes in a dead terminal hub. A fading assistant AI, **Ping**, guides you through the first ruins. You learn that the Choir feeds on silence and fear, and that the only counter is rhythm.

### Act II: The Deep Stack
You descend through the network''s layers:
- **Cache Catacombs:** looping corridors full of stale memory ghosts.
- **Packet Sewers:** flooded data channels with fast currents and lurking leeches.
- **Kernel Cathedral:** the Choir''s nest, built from the OS core.

Along the way you find that Ping is a fragment of the Choir''s original creator.

### Act III: The Final Refrain
At the Cathedral, Cipher chooses one of three endings:
1. **Purge:** delete the Choir and the Grid with it.
2. **Harmonize:** merge with the melody and become the new conductor.
3. **Fork:** split the network in two, saving half and losing half.

---

## Core Gameplay

### Dance Input (signature mechanic)
Combat, puzzles and movement all run on a **beat-synced dance system**.

| Input | Function |
|---|---|
| Step combos (arrow sequences on the beat) | Attacks and special moves |
| Spin / slide patterns | Dodges, parries, area strikes |
| Long "freestyle" chains | Hack commands, unlock terminals |
| Off-beat input | Weaker actions and noise, which attracts enemies |

- Combos are learned as **dance scripts**, which are found, traded or reverse-engineered.
- The screen pulses with the beat. Enemies pulse on their own, offset rhythms.

### Hack and Slash
- Fast top-down melee with a **blade-cursor** weapon and a range of code-weapons (whips, glitch-daggers, pulse cannons).
- Kills on the beat build a **Groove multiplier** that boosts damage and drops.
- Enemy types:
  - **Husks:** slow, swarming, rhythm-blind.
  - **Screamers:** disrupt your beat timing with audio distortion.
  - **Choristers:** elite enemies that copy your dance and turn it against you.

### Puzzle
- **Rhythm locks:** doors and firewalls open only with a specific dance pattern.
- **Routing puzzles:** redirect data streams to power gates and bridges.
- **Memory mazes:** rooms reshape to your beat, so you have to track patterns.
- Some puzzles are also combat arenas, where you solve them while under attack.

### Mounts
Bound **process-beasts** serve as mounts. You ride them with your dance input.

| Mount | Role | Trait |
|---|---|---|
| **Daemon Wolf** | Fast traversal | Sprints on beat streaks |
| **Bus Serpent** | Water/stream crossing | Rides packet currents |
| **Stack Golem** | Heavy combat | Tanky, smashes barriers |
| **Glitch Moth** | Gaps and shafts | Short hovering flight |

- Mounts have their own stats, hunger and "stability" meters.
- Each mount changes your dance moves, so you learn a separate combo set per mount.

### Resource Management
Resources are limited and tied to your survival:

- **CPU Cycles:** the energy for special moves. They recharge only on the beat.
- **Memory (RAM):** your inventory and active scripts. If it fills up, you slow down.
- **Integrity:** health. Restoring it takes rare **patch kits**.
- **Bandwidth:** fuels mount abilities and hacking.
- **Corruption:** rises as you take damage or stay in dark zones. High corruption gives you power but distorts the screen and your controls.

Players must decide what to carry, what to delete and when to fight or flee.

---

## Horror Elements
- **Silence is a threat.** Music dropping out means enemies are near.
- **Visual corruption:** glitches, false walls and fake UI elements.
- **Audio horror:** the Choir''s whispers use your own dance rhythm against you.
- **Stalker boss:** the **Conductor** hunts you across levels and cannot be killed until the finale. It appears in a room''s periphery and moves only when you stop dancing.
- **Scarcity:** limited light, ammo and safe zones.

---

## Game Loop
1. **Explore** a corrupted zone and gather resources.
2. **Fight** enemies with dance combos to build Groove.
3. **Solve** rhythm and routing puzzles to progress.
4. **Mount** beasts to cross hazards and reach hidden areas.
5. **Manage** CPU, RAM and corruption.
6. **Return** to safe **Backup Nodes** to save, upgrade and trade.

---

## Visual & Audio Style
- **Look:** neon wireframes on black, glitch effects, and terminal-green and magenta highlights that intensify with corruption.
- **Sound:** adaptive synthwave that shifts into distorted industrial as danger rises. The soundtrack *is* the gameplay clock.

---

## Progression
- Unlock new **dance scripts** and mounts.
- Upgrade the **blade-cursor** with modular code-plugins.
- Choose a **playstyle** (agile, tank or hacker) through skill trees.
- Replay with **New Game+**, where the Choir''s music changes and puzzles reshuffle.

---

## Tagline
> *"Keep the beat. Or become the silence."*', 'horror, puzzle, hack and slash', 'top-down, action, resource management', '2 gb ram and good vibes', '1985-08-29 09:00:00+00'),
('Ringsong: Vael', 20.46, '# Moonsong of the Ring-Wardens

*a rhythm-fighting, puzzle-romance strategy party game*

## Premise
On **Vael**, a moon circling a ringed gas giant, medieval kingdoms cling to cliffs lit by the glowing ring. Ring-dust falls as shimmering rain and makes sound physical. A drumbeat can break stone, and a melody can heal or seduce. Every house keeps an army, and every army marches to a rhythm.

## Story Structure

### Act I - The Dusk Crown
- You play a **Cadence-Knight**, a young commander who inherits a broken border keep.
- The ring is fading. Whoever holds the **Last Resonance** will control the moon''s ring-dust.
- You recruit a small warband and meet three rival courts.

### Act II - Courts and Courtships
- Each court has a charismatic envoy: a silver-tongued duelist, a cloistered ring-priestess, and a smuggler-bard.
- Romance is sensual and adult-toned but **non-explicit**. It plays out through flirtation, dances, and candlelit duets.
- Bonds are built by matching rhythms and solving each envoy''s **lock-melodies**. Deeper bonds unlock alliances, secrets, and combat boons.

### Act III - The Eclipse Finale
- The giant planet eclipses the sun, and the ring goes silent.
- You choose a path: unite the courts, rule alone, or unravel the ring and free the moon.
- There are multiple endings based on alliances, treasury, and romances.

## Core Gameplay

| pillar | description |
|---|---|
| **rhythm combat** | Duels and battles run on beat tracks. Hit the notes to attack, parry, and command units. |
| **critical hits** | Perfect-timing chains build a *Resonance meter*. A full meter triggers a crit, with big damage and a flashy ring-light finisher. |
| **puzzles** | Sound-lock doors, tune ring-crystals, and arrange melodic sequences to open vaults or read an envoy''s heart. |
| **erotic adventure** | Dialogue, dance minigames, and choices shape relationships and unlock private scenes (tasteful, implied). |
| **resource management** | Manage grain, iron, ring-dust, and morale across your holdings. |
| **army upkeep** | Every soldier costs food and pay each turn. Unpaid troops lose rhythm sync and fight badly. A cheap horde can collapse, while a small, elite, well-fed guard stays sharp. |

## Party Mode
- Supports 2-8 local players in rotating **Feast-Hall Duels**.
- Modes include team rhythm brawls, relay puzzles, and "court intrigue" bluffing rounds.
- Couch-friendly controls need only one button per player.

## Medieval Fighting Style
- Swords, spears, shields, and crossbows are each tied to a beat pattern.
- Heavy weapons use slow, strong notes. Light blades use rapid, risky chains.
- Armies clash in **Chorus Battles**, where your units play parts of one song.

## Moddable Design
- Open tools let players add songs, charts, characters, story arcs, and puzzles.
- Custom tracks automatically generate beat maps.
- A workshop hub shares mods and supports content filters for the romance scenes.

## Art and Sound
- **Visuals:** a huge ring arcs over stone castles, with dust-glow and lantern-lit banquet halls.
- **Audio:** medieval lutes, drums, and choirs blended with synth shimmer.

## Tagline
*"march to the beat, win the court, and sing the ring back to life."*', 'rhythm, erotic adventure, puzzle', 'fighting, medieval, resource management, party game, moddable', '6 gb vram, 12 gb ram, 20 gb free space', '1994-10-05 09:00:00+00'),
('Thalassa''s Hollow', 0.23, '# Abyssal Reach

*A dark underwater city simulation where every choice reshapes the drowned world.*

## Overview

| Field | Value |
|---|---|
| World | Underwater city |
| Genres | Simulation, Strategy, Metroidvania |
| Tags | Visual novel, Moddable, Dark |
| Mechanics | Rarity tiers, Meta-progression |

## Premise

Humanity fled the surface after the sky burned. Their last refuge is **Thalassa**, a sprawling city built into the walls of an ocean trench. Its reactor is failing. The lower districts have gone silent. Something in the deep is calling to the survivors.

You are the **Warden**, the city''s last administrator. You have to keep the population alive, and you have to find out what sleeps below.

## Story Structure

### Act I: The Pressure
- Stabilize the founding district and its first 200 citizens.
- Visual novel scenes introduce key figures: a fanatic priest, a cynical engineer, and a child who hears the deep.
- The first sealed door opens, and the descent begins.

### Act II: The Descent
- Each trench layer is a new biome: *Kelp Gardens*, *Wreck Graveyard*, *Thermal Vents*, *The Hollow*.
- The city''s factions split over whether to seal the deep or embrace it.
- Betrayals, sacrifices, and moral compromises leave permanent marks on the story.

### Act III: The Awakening
- The entity below is revealed, and it is neither wholly enemy nor ally.
- Multiple endings depend on the city''s morale, its resources, and the Warden''s choices.
- Each ending feeds the next run through meta-progression.

## Core Gameplay

### 1. City Simulation
- Manage oxygen, power, food, pressure integrity, and sanity.
- Build and upgrade districts: habitats, farms, labs, shrines, and defenses.
- Citizens have traits, fears, and loyalties. Neglect leads to unrest, and unrest leads to hull breaches.

### 2. Strategy Layer
- Assign crews, allocate scarce resources, and plan expeditions.
- Negotiate with factions and decide who gets rationed air.
- Respond to timed crises such as leaks, blackouts, and creature raids.

### 3. Metroidvania Exploration
- Pilot a dive suit or submersible through interconnected ruins.
- Gain abilities that unlock old areas:
  - **Pressure Plating** for deep-water zones.
  - **Sonar Pulse** to reveal hidden paths.
  - **Thermal Shield** for vent regions.
  - **Tether Grapple** for traversal.
- Backtracking reveals shortcuts, lore, and secret districts.

### 4. Visual Novel Storytelling
- Branching dialogue scenes with illustrated portraits and dark, moody art.
- Choices affect relationships, city policy, and available endings.
- Some memories can only be recovered through dialogue.

## Rarity Tiers

Loot, relics, and blueprints come in five tiers.

| Tier | Color | Effect |
|---|---|---|
| Common | Grey | Basic gear and materials |
| Uncommon | Teal | Minor stat boosts |
| Rare | Blue | Unique modifiers |
| Epic | Violet | Build-defining abilities |
| Abyssal | Black-gold | Powerful but cursed; each carries a story cost |

Higher tiers are found deeper down. Abyssal items change the city''s fate and can corrupt its people.

## Meta-Progression

When a run ends, whether in collapse or victory, the **Legacy** system carries progress forward.
- **Echoes** are memories that unlock new starting bonuses.
- **The Archive** is a persistent tech tree of blueprints.
- **Descendants** are citizens'' children who inherit traits.
- **Lore Fragments** unlock new story branches and hidden endings.
- Each cycle reveals more of the truth about Thalassa''s origin.

## Tone and Visuals
- **Dark and oppressive.** Dim bioluminescence, crushing silence, and creeping dread.
- Hand-painted backgrounds, with minimalist UI styled as flickering terminals.
- Ambient, low-frequency audio.
- Themes: survival ethics, isolation, and the cost of progress.

## Moddability
- Open data formats (JSON/Lua) for items, events, and dialogue.
- Custom districts, factions, creatures, and story arcs.
- Built-in editor for visual novel scenes.
- Workshop support for sharing mods.

## Player Experience
> *"Every breath is a budget. Every door is a gamble. And below, something is listening."*

Players will feel the weight of leadership, the thrill of discovery, and the unease of secrets that should have stayed buried.', 'simulation, strategy, metroidvania', 'visual novel, moddable, dark', 'quad-core cpu, 16 gb ram, mid-range gpu', '2021-05-19 09:00:00+00'),
('Thirteen Floors of Tea', 24.89, '# Glass Elevator: Tea Hours

## Pitch
A cozy, adult-oriented (mature romance, non-explicit) life-sim RPG. You run a steam-powered glass elevator in a 1890s grand hotel. It climbs through 13 floors, and each floor is a different era''s fashion, customs and secrets. Between rides you play the hotel''s favorite pastime, a cute board game called *Tiddle-Tower*.

## World
- **Setting:** the Aurelia Grand, a historical Belle Epoque hotel-tower. The glass elevator is its heart, and everyone sees everyone else through it.
- **Tone:** warm, cute, a little flirty. Pastel brass and porcelain visuals with chibi character art.
- **Hook:** at night the elevator stops between floors. Guests open up there, and rivalries and romances start there.

## Story (3 acts)
1. **Opening shift.** You are a new elevator attendant who has inherited the post from a missing mentor. You get a uniform, a ledger and a mysterious brass key.
2. **The Season.** Over 12 in-game months, guests arrive, leave and form bonds with you. A society scandal builds around the missing mentor.
3. **Grand finale.** A storm cuts the power and the elevator hangs mid-shaft. You have to protect guests from a saboteur, then choose your ending: romance, career, or the mystery of the mentor.

## Core Loop
1. **Morning:** set your schedule (polish brass, learn etiquette, shop, rest).
2. **Day:** carry guests, and choose which floors to stop at and what to say.
3. **Evening:** play *Tiddle-Tower* at the lounge for gossip, gifts and favor.
4. **Night:** a private elevator scene with one companion, which raises affection through tasteful, fade-to-black romance.

## Life Simulation
- **Stats:** grace, wit, stamina, charm, and reputation per floor.
- **Needs:** energy, mood and coin.
- **Home:** decorate your small attendant''s nook.
- **Calendar:** period holidays, balls and exhibitions.
- **Relationships:** 6 romanceable characters, plus friends and rivals, each with their own arc and affection levels.

## RPG Systems
- **Classes (playstyles):** Diplomat, Guardian, Trickster.
- **Skill trees:** etiquette, defense, and board-game tactics.
- **Gear:** gloves, umbrellas, lockets and elevator upgrades.
- **Quests:** floor-specific mysteries, favors and time-limited events.

## Combat: Blocking and Parrying, Combo Chains
Conflicts are stylized "elevator scuffles" against thieves, rowdy patrons and the saboteur''s clockwork minions.

| Mechanic | How it works |
|---|---|
| **Block** | Hold to guard. It costs stamina but cuts damage. |
| **Parry** | Press just before a hit lands (a rhythm window). A perfect parry stuns the enemy and refunds stamina. |
| **Combo chains** | Chain light, heavy and umbrella-flourish strikes. Each hit extends the chain and raises the multiplier. |
| **Parry into combo** | A perfect parry opens a bonus chain with extra style points. |
| **Tight space** | The cabin is small, so dodging is limited. Timing matters more than movement. |

## Board Game: Tiddle-Tower
- A tile-stacking duel game with a period look.
- Its actions (block, counter, chain) echo the combat system.
- Winning gives story info, discounts and affection.
- Rare pieces are collectible.

## Art and Audio
- **Art:** cute, pastel, hand-painted, with expressive character portraits.
- **Music:** ragtime and music-box tunes. The elevator hum changes by floor.

## Content Note
The game is for adults. Romance is sensual but non-explicit, with fade-to-black scenes.

## Replay Value
- Multiple endings, New Game+ and hidden floors.
- Collectibles and an era-fashion wardrobe.', 'rpg, hentai, life simulation', 'historical, board game, cute', 'rtx 2060 or better, 16 gb ram', '2000-08-19 09:00:00+00'),
('Rustbloom Bazaar', 10.78, '# Star Bazaar: Threads of Zephyra

## Overview
A turn-based strategy, otome, and 4x hybrid set in **Zephyra Prime**, a sprawling alien marketplace built on the ruins of a dead empire. You play as a newly arrived trader-diplomat. You build a stall into a trade dynasty and court a cast of alien suitors, all while the market''s history unfolds around you.

- **Genres:** Turn-based strategy, otome, 4x
- **Tags:** Simulation, local co-op, historical
- **Mechanics:** Ranked ladders, gacha

---

## Story

### Prologue: The Last Stall
Your homeworld is bankrupt. Your only inheritance is a cracked trade-license chip and a stall number in Zephyra Prime''s forgotten **Rust Quarter**. You arrive with 200 credits and a translator implant that only half works.

### Act I: Small Fish
You learn the market''s rhythms and its rival guilds. Three suitors appear in the first week, each tied to a faction:

| Suitor | Species | Faction | Personality |
|---|---|---|---|
| **Vael Ossuun** | Crystalline reptilian | Guild of Ledgers | Cold, precise, secretly generous |
| **Kiri-Ma** | Fungal nomad | Sporewind Caravans | Playful, evasive, deeply loyal |
| **Director Halcyon** | Sentient nebula in a suit | Old Empire Archivists | Ancient, gentle, haunted |

### Act II: The Empire Beneath
Excavations in the Rust Quarter uncover relics of the fallen **Auroran Empire**. Each faction wants to rewrite history in its favor. Your choices decide whose version becomes the market''s official record.

### Act III: The Great Auction
A final auction will decide who owns Zephyra Prime. Your alliances, your romance, and your economic empire all come together here. Endings depend on your route, your influence, and your partner.

---

## Gameplay

### 4X Loop
- **Explore:** Scout districts, hidden black markets, and derelict vaults.
- **Expand:** Buy stalls, lease warehouses, and open trade routes.
- **Exploit:** Corner commodities, run supply chains, and manipulate prices.
- **Exterminate (soft):** Bankrupt rivals through hostile takeovers and embargoes, with no bloodshed.

### Turn-Based Strategy
Each turn is one **market cycle**. You spend Action Points on:
1. Trading and negotiating
2. Deploying agents
3. Investing in districts
4. Spending time with a suitor

Events like tariff storms and smuggler raids change the board every few cycles.

### Otome Layer
- Affection grows through dialogue choices, gifts, and shared missions.
- Suitors give strategic bonuses, such as discounts, intel, or faction protection.
- Romance events unlock **history fragments** that reveal Zephyra''s past.

### Simulation
The market economy is a living simulation of supply, demand, faction politics, and alien cultural taboos. Selling the wrong item to the wrong species has consequences.

---

## Historical Dimension
Zephyra''s past appears as **Echo Eras**, playable flashback scenarios set in different periods of the Auroran Empire. Each one reshapes the present-day market when you complete it.

---

## Mechanics

### Gacha: The Lucky Crates
- Pull **Crates** for merchants, relics, stall upgrades, and outfit sets.
- Rarity tiers: Common, Rare, Epic, **Legendary**.
- Pity system: a Legendary is guaranteed every 60 pulls.
- Crates are earned through play, and premium currency is optional.

### Ranked Ladders
- Seasonal **Merchant League** with tiers from Peddler to Grand Magnate.
- Ranked play is asynchronous. Each player''s trade empire faces other players'' in scored market contests.
- Seasonal rewards include exclusive suitor outfits and story chapters.

---

## Local Co-op
Two players share one device or screen, or play over local network:
- **Partnership Mode:** Run one stall empire together, with split roles (Negotiator and Logistician).
- **Rival Mode:** Compete for the same district in hot-seat turns.
- Co-op partners can jointly romance a suitor in special **Double Date** events.

---

## Tone and Art
Warm neon bazaars, hand-painted alien portraits, and jazz-tinged synth music. The tone is cozy but scheming, with romance and economic intrigue in equal measure.

---

## Hook
> *"Everything in Zephyra has a price. The question is whether you can afford to fall in love."*', 'turn-based strategy, otome, 4x', 'simulation, local co-op, historical', 'decent gaming laptop, charger plugged in', '1997-10-17 09:00:00+00'),
('Veinbound', 8.91, '# Deep Vein: Chronicles of Outpost Kharon

## Overview
- **World:** Asteroid mining outpost, drifting on the edge of known space
- **Genres:** Party RPG, Visual Novel
- **Tone:** Dark, gritty, medieval-feudal in structure (guilds, lords, oaths) set in a cold industrial void
- **Core Loop:** Explore, sneak, talk, fight with match-three, then reshape your formation

---

## Setting
Outpost Kharon is a hollowed-out asteroid ruled like a medieval fiefdom. **Lord-Foreman Varek** holds the rock. Guilds of miners, smelters and "tithe-collectors" swear oaths to him in exchange for air, water and protection.

- Torch-lit tunnels are carved in stone, with iron gates and rope lifts.
- Airlocks are guarded by knights in patched, riveted armor.
- The lower shafts hold something ancient that answers the drills.

---

## Story

### Act I: The Oath
You play **Ren Talvar**, a disgraced sapper-squire. You are pressed into service by the Mining Guild after a shaft collapse kills your master. You take an oath and receive a small crew.

### Act II: The Rot Below
Miners vanish in the deep tunnels. You sneak past guards and search forbidden galleries. There you find glowing veins that whisper. Varek has been feeding people to the vein in exchange for its ore.

### Act III: The Breaking of the Crown
You choose a side:
- **Loyalist:** Serve Varek and control the vein.
- **Rebel:** Lead the miners in revolt.
- **Seal:** Collapse the deep shaft and doom the outpost''s economy.

Each choice leads to one of several endings shaped by your party''s loyalty.

---

## Gameplay

### Party
Recruit up to 6 companions. Each has personal arcs, loyalty and secrets told as visual-novel scenes.

| Companion | Role | Secret |
|---|---|---|
| Sister Ilse | Healer, ex-priestess | Worships the vein |
| Brakk | Tank, smelter-knight | Owes Varek a blood debt |
| Wren | Scout and thief | Informant for the guild |
| Old Dov | Mage-engineer | Once drilled the first shaft |

### Exploration and Stealth
- Move through tunnels, vents and gantries.
- Avoid patrols by using shadows, dropping lanterns and timing airlock cycles.
- Being spotted triggers combat. Staying hidden gives ambush bonuses and dialogue options.

### Formations
- Arrange the party on a **3x3 grid** before each fight.
- Front rows take more damage and deal melee bonuses.
- Back rows boost ranged and support skills.
- Adjacent characters trigger **synergies**, such as a shield wall or a flanking strike.

### Match-Three Combat
Battles are fought on a gem board of ore types:

- **Iron:** physical attacks
- **Ember:** fire and explosives
- **Aether:** magic and healing
- **Skull:** curses and debuffs

Matching gems charges the skills of party members whose formation slots match that color. Chains of four or more trigger team combos. Enemies have their own boards and can corrupt tiles.

### Visual Novel Layer
- Branching dialogue with choices that affect loyalty and faction reputation.
- Stylized portraits and dark ink-wash backgrounds.
- Relationships unlock new formation synergies.

---

## Themes
- Power, debt and sacrifice
- Faith versus exploitation
- What we owe to those who dig in the dark

## Art and Audio
- Muted palette of rust, slate and cold blue, with eerie green glow from the veins.
- Low choral drones, clanging metal and sparse strings.', 'rpg, rpg, visual novel', 'party game, exploration, stealth, medieval, dark', '6 gb vram, 12 gb ram, 20 gb free space', '2001-01-02 09:00:00+00'),
('Gem Crossing', 17.07, '# Tokyo Crossing: Karma Clash

## Elevator Pitch
A colorful low-poly co-op and versus **shooter-roguelite** set on the world''s busiest intersection. Fight through neon rooftops, and power up by solving **match-3** boards. Every action shifts your **karma**, which changes your loot.

## Story
**Prologue.** Every night at 3:00 AM the Shibuya-style crossing folds into a floating maze of billboards, trains and rooftops called the *Crossing Loop*. Commuters are trapped in it as glowing "Spirit Gems". The Loop is ruled by the **Signal King**, a giant traffic light that decides who may cross and who stays.

**Act 1 - The Red Light.** Two couriers, **Ren** and **Yuki**, fall into the Loop while delivering a package. The package turns out to be a *Green Lens*. It is the only object that can force the Signal King''s light to turn green.

**Act 2 - The Long Crossing.** The pair climb through four districts, each a themed platformer level:
- **Neon Alley:** vending machine turrets, slippery wet rooftops.
- **Station Underworld:** moving trains, tight corridors.
- **Sky Billboards:** vertical jumps, wind gusts, drones.
- **Scramble Square:** the final arena, with thousands of spirit crowds.

**Act 3 - Green Light.** The Signal King is defeated only when both players'' karma is balanced. The ending changes with the karma each player has built.

**Epilogue.** The crossing returns to normal, but the loop restarts with a new challenge. Each run is a new "night".

## Core Gameplay

### Shooter and Platforming
- 3D low-poly levels with jumping, dashing, wall-running and double jump.
- Fast arcade shooting: pistols, spray cans, umbrella shotguns, ramen-cannon.
- Enemies: salaryman zombies, drone swarms, mascot brutes, hologram snipers.

### Match-3 Layer
- A gem board sits on your HUD or is opened with a button.
- Defeated enemies drop gems onto the board.
- Matching gems triggers effects:
  - **Red:** damage boost
  - **Blue:** shield
  - **Green:** healing
  - **Yellow:** speed
  - **Purple:** special ability charge
- Big combos (4+ or chains) trigger **Crossing Bursts**, screen-wide attacks.
- The board keeps running during combat, so you have to split attention between the two.

### Roguelite Loop
- Permadeath runs through procedurally arranged districts.
- After each run you keep **Meta Coins** to unlock characters, weapons and starting perks.
- Between rooms you choose one of several paths, each with a risk and a reward.

## Karma System
Karma is a shared meter per player, from **Dark** to **Bright**.

| Action | Karma Shift |
|---|---|
| Rescue spirit gems, revive ally, spare enemies | Bright |
| Steal loot, friendly fire, break props | Dark |
| Balanced play | Neutral |

**Effects:**
- **Bright karma:** better healing, shield loot, and helpful shrines.
- **Dark karma:** higher damage, rare cursed weapons, and tougher enemies.
- **Neutral:** stable, with bonus chance for "Crossing Blessings".
- Karma affects the **loot tables**, NPC dialogue, boss phases and the ending.

## Random Loot Tables
- Drops come from chests, vending machines, bosses and match-3 combos.
- Rarity tiers: Common, Rare, Epic, **Legendary (Mythic Signal)**.
- Karma changes the weights of each table:
  - Bright: support items, auras.
  - Dark: glass-cannon weapons, cursed relics.
- Items can be synergistic: a "Umbrella Shotgun" plus "Rainy Night" gives a chain-lightning effect.

## Multiplayer and Split Screen
- **Local split screen** for 2-4 players, plus online play.
- **Co-op mode:** shared goal, separate karma. A player''s karma affects the team''s loot.
- **Versus mode:** race across the crossing, and sabotage rivals by sending garbage gems onto their match-3 boards.
- **Party mode:** short arena rounds with random modifiers.

## Visual and Audio Style
- **Low poly** models with saturated colors: pink, cyan, yellow, and lime.
- Dynamic neon lighting, animated billboards, and crowds of simple figures.
- Soundtrack: synthwave and city-pop, with tempo that rises during combos.
- Each player has a color theme, so split screen stays readable.

## Player Fantasy
Run, jump and shoot through the busiest crossing on Earth. Every choice and every match changes your fate, and you decide whether to cross the road as a hero or a villain.', 'shooter, roguelite, match-3', 'split screen, colorful, multiplayer, platformer, low poly', 'high-end gpu, 32 gb ram, and a good cooling plan', '2004-11-20 09:00:00+00'),
('Steam & Stardust', 25.40, '# Starlit Springs

*A cartoon dating-sim platformer with gacha collecting, set in a hot spring resort floating in space.*

## Premise
Your family''s run-down hot spring resort has drifted into orbit. It sits on an asteroid ring, and its geothermal pools now attract alien guests. You are the new manager. Rebuild the resort, charm the guests and staff, and keep the "Cosmic Onsen" alive before the galactic inspectors arrive.

## Story Structure

**Act 1: Arrival**
- You inherit a cracked bathhouse and one loyal staff member, a grumpy robot named Bubbles.
- The first guest is a shy comet-girl. She teaches you that the springs react to music and emotion.
- The goal is to earn enough Stardust to open the first wing.

**Act 2: Growth**
- New districts unlock: Lantern Street, Crystal Gardens, and the Nebula Spa.
- Rival resort owners sabotage your asteroid routes.
- Romance arcs deepen with each bachelor and bachelorette.

**Act 3: The Great Eclipse**
- A void storm threatens the ring.
- Everyone you bonded with helps defend the resort.
- The ending depends on your relationships and on how well you built the resort.

## Core Gameplay Loops

### 1. Platforming (exploration)
- You hop across floating rocks, steam vents, and moving pipes to gather resources.
- Hazards include scalding geysers and drifting space debris.
- Collectibles are Stardust, ingredients, and music notes.

### 2. City Builder (resort management)
- Place baths, cafes, shops, stages, and guest rooms on a grid around the asteroid.
- Districts have synergy bonuses. For example, a music stage next to a tea house raises guest mood.
- Upgrade the geothermal core to power new areas.

### 3. Life Sim (daily routine)
- The day is split into morning, afternoon, and night.
- Activities include cooking, cleaning, fishing for space koi, and rest.
- Stamina and mood stats affect performance.

### 4. Dating Sim
- There are 8 romanceable characters, such as a sleepy dragon chef, a rockstar alien, and a stoic guardian knight.
- Gift giving, dialogue choices, and shared events build affection.
- Each romance has heart events and a unique ending.

### 5. Music
- Rhythm mini-games are played at the resort stage and in the springs.
- Playing songs boosts guest happiness and heals the party.
- Melodies you collect become buffs when used in platforming.

### 6. Gacha
- "Spirit Capsules" summon staff, guests, and decorations.
- Rarities: Common, Rare, Epic, Legendary.
- A pity system guarantees an Epic after 30 pulls.
- Currency can be earned in play. There is a free daily pull.

## Combat and Mechanics

### Blocking and Parrying
- Void creatures and rival saboteurs attack in short encounters.
- Blocking reduces damage but drains stamina.
- A perfectly timed parry stuns the enemy and returns a rhythm-based counter.
- Parrying to the beat of the current song gives bonus damage.

### Status Effects

| Effect | Cause | Result |
|--------|-------|--------|
| Soaked | Water hazards | Slower movement, more shock damage |
| Overheated | Geysers | Damage over time, faster stamina drain |
| Relaxed | Hot spring | Regenerates HP, lowers attack |
| Charmed | Romance items | Boosts allies, confuses enemies |
| Frozen | Void frost | Immobilized until parried free |

Status effects also apply to guests. A "Stressed" guest leaves bad reviews, while a "Blissful" guest tips heavily.

## Characters (samples)
- **Bubbles**: sarcastic robot assistant and comic relief.
- **Lyra**: comet idol, a shy singer and the first romance option.
- **Kaz**: dragon chef who cooks buff meals.
- **Orion**: the guardian knight, a serious protector who teaches parrying.

## Art and Audio
- Bright cartoon style with bold outlines and squash-and-stretch animation.
- Soft lo-fi and synth-pop soundtrack. Each character has a theme that layers into the resort music.

## Progression and Goals
- Upgrade the resort star rating from 1 to 5.
- Complete romance arcs.
- Fill the collection book with capsule characters.
- Unlock New Game+ with harder eclipses.

## Tagline
*"Relax. Rebuild. Fall in love among the stars."*', 'dating sim, platformer, gacha', 'city builder, space, cartoon, life sim, music', 'any toaster with a screen', '2013-01-25 09:00:00+00'),
('Static Drive', 8.95, '# Neon Reel: Last Feature

## Logline
The last drive-in cinema on Earth is a floating fortress in a wasteland of dead screens. Lead a crew of adult misfits, grow your lot into a movie empire, and survive until the credits roll.

## World: The Drive-In
- **Setting:** A cartoon-style, saturated retro-futurist America. Giant projector screens rise like monoliths, and car-hood campfires light the night.
- **Story:** The "Great Intermission" shut down every cinema and swallowed the world in static. Your lot is the only place still showing films. The films are alive, and their characters spill out of the screens.
- **Tone:** Comedic and campy, with flirtatious mature themes. All characters are adults. Romance scenes are suggestive and stylized. Explicit content is optional, gated behind an adult toggle, and easy to disable.

## Genres

### RPG
- Recruit a party of adult archetypes: the projectionist, the stunt driver, the snack-bar witch, the ex-B-movie villain.
- Each has a class, a skill tree, and a personal story arc.
- Relationship events (romance, rivalry, friendship) unlock perks and alternate endings.

### 4X
- **Explore:** Chart the dead zones of the wasteland.
- **Expand:** Claim abandoned lots, and build screens, snack bars, and generators.
- **Exploit:** Trade film reels, fuel, and popcorn.
- **Exterminate:** Fight rival cinema cults and static-monsters, or win them over with blockbuster diplomacy.

## Survival
- Manage power, fuel, food, and morale.
- Nightly "static storms" damage screens and drain the crew.
- Scavenge reels, which serve as both currency and story fragments.

## Core Mechanics

### Grappling Hook
- Swing between screens, car roofs, and projector towers.
- Pull loot from ledges, yank enemies off their feet, and zip across gaps.
- Upgrades add a magnetic tip, a chain-swing combo, and a party-tow that pulls allies along.

### Energy Timers
- Actions such as scavenging runs, construction, and date events cost **energy**, which recharges over real time.
- **Showtime timers** count down while a film builds up or plays. Big builds and expeditions finish "when the reel ends."
- The timers are fair and skippable. There are no hard paywalls, and offline progress is generous.

## Party Game Mode
- Local and online co-op for 2-6 players.
- Party minigames, such as popcorn-toss races, grapple-swing relays, and a "guess the movie" bluff round.
- Cross-platform play between mobile, PC, and console with shared saves.

## Platforms
- Cross-platform (mobile, PC, console) with cloud saves.
- Touch and controller-friendly grapple aiming.

## Gameplay Loop
1. **Day:** Scavenge, build, and trade.
2. **Dusk:** Assign the crew and choose the night''s feature.
3. **Night:** Survive the static storm, then run a party event or a relationship scene.
4. **Dawn:** Collect rewards, spend energy, and expand.

## Win Conditions
- **Blockbuster Ending:** Restore the world''s cinemas.
- **Cult Classic Ending:** Rule the wasteland as a warlord.
- **Indie Ending:** Keep one small lot alive with your closest friends.', 'rpg, hentai, 4x', 'cartoon, survival, cross-platform, party game', 'rtx 4070, 32 gb ram, nvme ssd', '1989-04-25 09:00:00+00'),
('Whitepass', 19.45, '# Snowbound Covenant

*A minimalist, isometric Himalayan pass tale that mixes turn-based tactical shooting, monster taming, and visual novel storytelling.*

---

## 1. Overview

| Field | Detail |
|---|---|
| **World** | Himalayan pass |
| **Genres** | FPS, monster taming, visual novel |
| **Perspective** | Isometric tactics, side-scrolling travel, first-person aim mode |
| **Style** | Minimalist: flat colors, white snow, single accent colors |
| **Loop** | Travel, stop, build, tame, talk, fight |

**Pitch:** You guide a caravan across a cursed mountain pass. You bargain with spirits, tame the creatures of the snow, and shoot your way through ambushes. Every stop changes who survives the crossing.

---

## 2. Story

### Prologue: The Closing Pass
The pass closes for winter in 30 days. A courier named **Tenzin Ral** carries a sealed medicine cure meant for a plague-struck valley. Avalanches, bandits, and awakened mountain beasts block the route.

### Act I: The Lower Trail
- You join a small caravan as its scout.
- You meet **Dawa**, a stubborn yak-herder, and **Mira**, a disgraced sniper.
- You tame your first companion, a wounded **snow wolf**.

### Act II: The High Monasteries
- Old monks reveal that the beasts are guardians. They are not enemies.
- A rival company, the **Iron Lantern**, wants to seal the pass forever.
- Visual novel choices decide which allies trust you.

### Act III: The Summit
- You choose whether to slay the mountain''s spirit, bind it, or free it.
- Your tamed monsters and your base decide the final battle.

### Endings
1. **Open Pass:** The spirit is freed and the trade routes reopen.
2. **Sealed Pass:** The cure is delivered but the route is lost.
3. **Warden''s Throne:** You bind the spirit and become the pass''s ruler.

---

## 3. Gameplay Modes

### A. Side-Scroller Travel
- The caravan walks along the pass in 2D.
- You spot events, wildlife, and hazards on the way.
- Weather and stamina affect the pace.

### B. Isometric Turn-Based Combat
- Grid-based tactics on cliffs, bridges, and ice.
- Each unit spends action points to move, take cover, or use abilities.
- Your tamed monsters fight alongside your human squad.

### C. FPS Aim Mode
- In your turn, switch to first person to line up a shot.
- Precision matters: headshots, weak points, and breaking ice.
- Ammo is scarce, so every bullet counts.

### D. Visual Novel Scenes
- Campfire talks, negotiations, and confessions.
- Branching dialogue changes companion loyalty and story flags.
- Static minimalist portraits with a single accent color per character.

---

## 4. Core Mechanics

### Monster Taming
- Weaken a creature, then choose a method: **feed, sing, or bind**.
- Species include the snow wolf, the frost yeti, the ice serpent, and the storm eagle.
- Each monster has a trait, a bond level, and a terrain skill.

### Pit Stops
- Forced rest points along the pass.
- You spend limited supplies on healing, repairs, and cooking.
- Each stop offers a story scene and a choice about who gets the resources.

### Base Building
- Turn each pit stop into an outpost.
- Build **shelters, forges, kennels, shrines, and watchtowers**.
- Outposts persist and produce resources between stops.

### Side Quests
- Rescue lost pilgrims.
- Retrieve relics for the monks.
- Hunt a rogue beast, or heal it and tame it.
- Rewards: gear, new monsters, and relationship scenes.

---

## 5. Progression

| System | Effect |
|---|---|
| **Bond** | Monster loyalty unlocks combo attacks |
| **Trust** | Human loyalty unlocks story branches |
| **Outposts** | Upgrades raise supplies and safety |
| **Gear** | Rifles, mods, and cold-weather kit |

---

## 6. Art and Audio

- **Palette:** White, slate gray, and one accent color per scene.
- **Shapes:** Clean geometric silhouettes with no heavy textures.
- **Music:** Sparse strings, throat singing, and wind.
- **UI:** Thin lines, small type, and minimal HUD.

---

## 7. Design Pillars

1. **Every journey is a choice:** resources force sacrifice.
2. **Bonds beat bullets:** taming and trust are as strong as firepower.
3. **Quiet beauty:** minimalism keeps focus on mood and story.', 'fps, monster taming, visual novel', 'isometric, turn-based, side scroller, minimalist, base building', 'high-end gpu, 32 gb ram, and a good cooling plan', '2022-01-26 09:00:00+00'),
('Gilt & Ghoul', 25.44, '# Ashfall Claim

*A soulslike gold rush town sim of digging, building, and dying politely.*

## Premise
The town of **Ashfall** sits on a gold vein that is guarded by something ancient. You play a **Claimholder**, a bankrupt prospector who wakes at a cursed well each time you die. The town remembers your failures, and the mine below does too.

## Story Structure
- **Act I, Dust and Debt:** You arrive with a shovel and a mule. Ashfall is a few shacks and a saloon. A dying assayer tells you the gold is bait, and something below is feeding on the town''s greed.
- **Act II, Boomtown:** The population grows and money flows. Rival syndicates arrive, and the guardians of the mine grow stronger with every nugget you extract.
- **Act III, The Deep Vein:** The town is now a city, and it has become a target. You go down for the final descent to end the curse. You can also choose to feed it and rule the ruins.
- **Endings:** Three are possible: *Liberation*, *Tycoon*, and *Ghost Town*. Each depends on how you treated the townsfolk and the mine.

## Core Loops

### 1. Farming Sim (daytime)
- Grow crops such as **ghost peppers**, **blood beets**, and **prospector''s barley**.
- Raise livestock and craft food buffs and potions. Food gives combat stats such as resistance, stamina, and threat reduction.
- Seasons shape the economy. Drought raises the price of water and lowers morale.

### 2. City Builder + Idle (passive)
- Place saloons, forges, banks, chapels, and rail depots.
- Workers mine, smelt, and trade **while you are away**. Idle income accrues offline up to a cap, which rises with upgrades.
- Every building has a **heat** stat. High output attracts raids and mine-spawned horrors.
- Districts unlock perks. The Chapel gives checkpoint healing, the Forge gives weapon tiers, and the Bank gives loans with dangerous terms.

### 3. Hidden Object + Puzzle (investigation)
- Search cluttered scenes such as the saloon back room, an abandoned claim office, and a sealed mine shaft. Find items from a list, or find clues you have to work out yourself.
- Found objects **combine into puzzles**: match assay marks, rebuild torn maps, align mine-cart switches.
- Solutions reveal boss lore, secret shortcuts, and weakness hints.

### 4. Soulslike Fighting (the mine)
- Descend into the mine through hand-crafted, interconnected tunnels.
- **Stamina-based combat:** dodge, parry, and heavy or light swings with revolvers, pickaxes, and dynamite.
- **Death rules:** you drop your unbanked gold at the death spot. Retrieve it once, or lose it to the mine.
- **Lanterns** are checkpoints. Using one resets enemies but also raises town heat.

## Signature Mechanics

### Weak Points
- Enemies and bosses have **glowing fault lines** that you find through observation and hidden-object clues.
- Hitting a weak point causes a stagger or a **critical strike**, and it can drop rare ore.
- Some weak points are only exposed after you solve a puzzle. For example, redirecting a steam pipe to crack the armor of the **Iron Foreman**.

### Aggro and Threat
- Every action builds **threat**: swinging, healing, building, and mining all count.
- Enemies target whoever has the highest threat. That can be you, your **mule**, your **hired deputies**, or the **town buildings** themselves.
- You can manage it in three ways:
  - **Bait:** drop decoys or lure with lanterns.
  - **Taunt:** use whiskey flasks or war-cry perks.
  - **Fade:** use dampening food and sneak tools to slip out of aggro.
- Bosses can leave the mine and attack the town if you ignore their aggro too long.

## Example Bosses
| Boss | Weak Point | Threat Twist |
|------|-----------|--------------|
| **The Iron Foreman** | Steam valves on the back | Targets the highest-heat building |
| **Widow Vein** | Glowing gold heart, exposed after a light puzzle | Splits aggro between you and your deputies |
| **Hollow Sheriff** | Badge, only vulnerable while parrying | Ignores you unless you carry stolen gold |

## Progression
- **Character:** Stats come from food, gear, and perks earned through fights and puzzles.
- **Town:** Population, heat management, and district level.
- **Knowledge:** Lore, weak-point notes, and map shortcuts persist across deaths.

## Player Experience
A typical session starts with harvesting and queuing builds. Then you investigate a hidden-object scene for a clue, then dive into the mine to test it against a boss. You leave the town to run idle, and you come back to more gold and bigger threats. The core tension is that **greed builds the town and also feeds the monster below**.', 'hidden object, fighting, farming sim', 'soulslike, singleplayer, idle, city builder, puzzle', 'rtx 2060 or better, 16 gb ram', '1995-07-20 09:00:00+00'),
('Halcyon Drift', 29.19, '# Tether Drift: Jovian Dock

*A slow, dangerous 4x played from the inside of a station.*

## Premise
You are the new dock-master of **Halcyon Ring**, a decaying orbital dock circling Jupiter. Radiation storms, debris, and the pull of the planet threaten it. You play in first person. You walk the corridors, but you rule through a tabletop **strategy board** in the command room.

## Core Loop
1. **Explore** (4x): scout debris fields and moons by drifting a small skiff between them. Chart routes and claim wrecks.
2. **Expand**: attach new modules to the ring, such as hydroponics, fuel refineries, and docking arms.
3. **Exploit**: salvage ore, ice, and hydrogen and turn them into supplies.
4. **Exterminate or Endure**: fight or avoid rival crews and the drifting "Hollow" hulks.

## Two Layers
| Layer | View | Pace |
|---|---|---|
| Board table | Physical miniatures and cards, top-down | Real-time, pausable |
| Station and space | First-person | Slow and meditative |

Moving a piece on the board sends real crews and ships into action. You can then follow them in first person.

## Mechanics
- **Drifting**: there is no braking in orbit. You set a burn, then coast along curved trajectories. Good timing saves fuel and lets you slingshot around moons. Bad timing sends you into the storm.
- **Companion AI**: a small crew of AI companions, such as the engineer *Vesk* and the pilot *Ondine*. They have moods and memories, and they learn your habits. They can follow orders, act on their own, or refuse if trust is low. If one dies, it stays dead.

## Survival
- Manage oxygen, power, heat, and morale.
- Radiation storms arrive on a cycle. You must seal sections and shelter crews.
- Scarcity is constant, but the pace is calm. You can stop to look at Jupiter, brew tea, and talk with companions.

## Soulslike Edge
- Boss encounters are huge derelict machines, such as the *Warden of Io*. They have readable attack patterns.
- Deaths are costly. You drop your cargo at the death site as a "wreck", and you must drift back to recover it.
- Little is explained. Lore comes from item descriptions, logs, and station ruins.

## Tone: Relaxing
There are no timers outside of storms. Ambient music, quiet engine hum, and slow orbital sunsets set the mood. Difficulty comes from planning, not from twitch reflexes. Tough moments come in short, sharp bursts between long calm stretches.

## Progression and Win Conditions
- **Stabilize**: make the ring self-sufficient.
- **Unite**: form alliances with other docks.
- **Ascend**: reach the sealed *Core Gate* deep in Jupiter''s shadow and learn why the Hollow drift there.

## Pitch
*"Build a home. Learn to drift. Survive the dark. Enjoy the view."*', '4x, survival, real-time strategy', 'board game, soulslike, first-person, relaxing', '2 gb ram and good vibes', '1997-02-22 09:00:00+00'),
('Last Ember', 10.46, '# Frostbound Depths

*A minimalist card-driven survival RPG in a frozen cave.*

## Premise
The surface is buried under an endless blizzard. Your expedition crew fled into a vast ice cave, and its glowing veins of blue crystal give off faint warmth. You lead the last camp. Every turn brings the cold closer, and the cave itself seems to be waking up.

## Core Loop
1. **Camp phase (simulation):** Assign survivors, ration supplies, and craft cards.
2. **Expedition phase (turn-based strategy):** Move across a node map of tunnels, chambers, and frozen lakes.
3. **Encounter phase (action RPG, card-driven):** Fight creatures and face hazards using your hand of cards.
4. **Return or push on:** Go back to camp with your loot, or dig deeper for better rewards and worse odds.

## World: The Ice Cave
| Zone | Feel | Danger |
|---|---|---|
| **Glimmer Gate** | Bright, safe camp area | Low |
| **Whispering Tunnels** | Narrow paths, echoes | Ambushes |
| **Mirror Lake** | Thin ice, hidden depths | Cracking floor |
| **Crystal Heart** | Warm but hostile | Elite guardians |
| **The Black Vein** | Lightless, ancient | Final boss |

## Story Structure
- **Act I, Arrival:** Set up camp and learn the rules of cold. A survivor goes missing.
- **Act II, Descent:** Explore deeper and find frozen relics. The crystals turn out to be a sleeping creature''s veins.
- **Act III, Choice:** Destroy the heart to free the surface, or bond with it and stay in the cave forever. There are multiple endings.

## Cards (Minimalist Design)
Each card has a name, a cost, and one line of text. There are three types:
- **Action:** *Strike, Brace, Torch Swing*
- **Gear:** *Fur Coat, Ice Pick, Lantern* (persistent and durable)
- **Event:** *Whiteout, Cave-in, Echo* (drawn from the cave''s deck)

The deck is small, about 20 to 30 cards. Every card matters, and cards can be permanently lost to frostbite or damage.

## Mechanics

### Resource Scarcity
- **Warmth:** Ticks down each turn and is refilled by fuel.
- **Food:** Feeds crew members. Hunger weakens them.
- **Fuel:** Powers torches and the camp fire.
- **Card slots:** A limited hand size forces hard choices.

Nothing regenerates for free. Every rest costs supplies.

### Status Effects
| Status | Effect |
|---|---|
| **Chill** | -1 energy per stack |
| **Frostbite** | A card is locked until healed |
| **Slippery** | Moves and attacks may fail |
| **Warmed** | Bonus damage and morale |
| **Burning** | Damage over time, melts ice barriers |
| **Frozen** | Skip a turn |

Statuses interact. For example, fire removes Chill but can crack ice floors.

## Characters (RPG Layer)
- **Classes:** Scout (speed), Warden (defense), Pyromancer (fire), Medic (support).
- **Progression:** Level up to unlock card upgrades and passive perks.
- **Crew bonds:** Survivors have personalities. Their trust affects combat buffs and story events.

## Enemies
- **Frost Wisp:** Applies Chill.
- **Ice Stalker:** Ambushes from walls.
- **Glacier Colossus:** A slow boss that crushes the floor.
- **Hollow Miner:** A lost former explorer.

## Tone and Visuals
- **Style:** Flat, minimalist icy palette of white, cyan, and deep navy, with one warm orange accent for fire.
- **Audio:** Quiet ambience, dripping water, and a sparse piano.
- **UI:** Clean cards with no clutter.

## Win/Lose
- **Win:** Reach the Crystal Heart and resolve the story.
- **Lose:** Warmth hits zero or the whole crew perishes. Each run leaves lasting unlocks for the next attempt.', 'simulation, turn-based strategy, action rpg', 'card game, minimalist, rpg', 'quad-core cpu, 16 gb ram, mid-range gpu', '2021-11-17 09:00:00+00'),
('Route 9 Nights', 4.91, '# Last Call at Route 9

*Serve. Survive. Repeat.*

## Overview
A post-apocalyptic diner-management action game with roguelike runs. You run a lonely roadside diner in the wasteland. Each night, travelers, raiders, and strange regulars come through the door. Some want a meal. Some want trouble. Some want company.

**Genres:** Action, Simulation, Adult (18+, mature themes and suggestive content)
**Players:** Solo, online co-op, PvP
**Input:** Full controller support

## Story
The old world ended, but the highway stayed. The diner survived because its neon sign never went dark. You inherit it from a missing relative and find a hidden ledger in the back office. It lists debts owed to every faction in the wasteland.

Each run is one long night. If you last until sunrise, you keep a piece of the diner''s legacy. If you fall, the night resets and the diner remembers you.

## Gameplay Loop
1. **Prep (dusk):** stock the kitchen, fix generators, set traps, and pick a menu.
2. **Service (night):** cook, serve, and manage moods and orders in real time.
3. **Defense (crisis):** raiders, mutant fauna, and sandstorms hit the diner. Fight with improvised weapons.
4. **Dawn:** count profit, unlock upgrades, and deepen relationships.

## Core Mechanics
| Mechanic | Description |
|---|---|
| **Roguelike runs** | Each night has random customers, events, and threats. Perks and mutations change every run. |
| **Checkpoints** | Reach milestones like midnight rush, the storm, and the pre-dawn siege. Each is a save point you can restart from at a cost. |
| **Simulation** | Manage supplies, power, water, staff, and reputation. |
| **Action** | Fast melee and ranged combat with cooking tools, scrap guns, and traps. |
| **Relationships** | Regulars and staff have their own storylines. Choices unlock new scenes and endings. These are mature and suggestive, and can be toggled. |

## Multiplayer
- **Co-op (2-4 players):** split roles as cook, server, guard, and mechanic. Coordination decides whether you last the night.
- **PvP:** rival diners compete for customers and supplies. Sabotage, raid, or sneak-attack other players'' diners in timed versus matches.

## Progression
- Permanent upgrades: kitchen, power grid, walls, and decor.
- Unlockable characters, recipes, and mutations.
- Multiple endings depend on which factions you feed, fight, or befriend.

## Tone and Style
Neon-lit wasteland noir with dark humor and warmth. Expect greasy-spoon comfort, desperate survival, and stylized adult content, all set to a retro-synth and dusty-country soundtrack.

## Key Features
- Diner management combined with action combat
- Every night is different
- Cooperative and competitive multiplayer
- Character-driven, mature storytelling
- Full controller support

I kept the adult content non-explicit and suggestive. I can write a more store-page style version if you want one.', 'action, simulation, hentai', 'post-apocalyptic, controller support, pvp, simulation, co-op', '6 gb vram, 12 gb ram, 20 gb free space', '2023-03-22 09:00:00+00'),
('Slagloom', 8.09, '# Ironvein Descent

*A fighting-RPG-shooter deckbuilder set in a dying asteroid mining outpost.*

## Premise
The outpost **Kessler Deep** is a hollowed-out asteroid. Its miners struck something ancient in the core, and the outpost went silent. You play a **Reclaimer**, a clone-bodied contractor sent to retake the station. Each time you die, the station''s **Loom** reboots you. The Loom is a relic AI that reshapes the tunnels around you.

## Story Structure

### Act I: Breach
- You dock at the outer ring and find dead corridors and rogue mining drones.
- You learn the basics: melee combos, gunplay, and your starting deck.
- The first boss is **Foreman Hask**, a drill-suited miner-turned-warlord.
- Beating him unlocks the first faction contact.

### Act II: The Factions
Three groups fight over the outpost''s remains:
- **Rock Union**: surviving miners who want the ore and the outpost''s independence.
- **Helix Corp**: corporate security who want the core artifact sealed and sold.
- **The Choir**: cultists who worship the core''s signal.

You broker deals, betray allies, and choose whom to arm. Your choices change which areas open and which enemies patrol them.

### Act III: The Core
- The Loom''s true purpose is revealed. It is not a bug. It is a lure that harvests dying minds.
- Depending on your alliances, you can seize it, shut it down, or merge with it.
- The final boss, **The Hollow Seed**, adapts to the cards you played most.

## Core Gameplay

### Combat
- **Fighting**: close-range stamina combos, parries, and grapples.
- **Shooter**: real-time aiming with limited ammo, low-gravity movement, and ricochet shots.
- **RPG**: stats, gear slots, and status effects such as vacuum burn, ore-lung, and static.

### Deckbuilding
- Your deck is your **loadout**. Cards are weapon techniques, drone commands, and suit modules.
- You draw a hand of 4 cards, and each card is bound to a button.
- Cards cool down instead of being spent, so you have to manage tempo.
- Rewards come from salvage, faction gifts, and boss cores.
- You can **fuse** two cards into a hybrid, for example *Plasma Cutter + Shockwave = Arc Breaker*.

### Metroidvania Exploration
- The station is one connected map with locked zones.
- Suit upgrades gate progress: **Mag-Boots** for ceiling walking, **Pressure Seal** for vented zones, **Thermal Lining** for the smelters, and **Signal Tuner** for Choir doors.
- Shortcuts and elevators link zones, so returning to them is faster.

### Procedural Generation
- **Room layouts** are rebuilt each run from handcrafted modules.
- **Loot, hazards, and enemy mixes** change every run.
- Key landmarks and bosses stay fixed so the map still feels learnable.

### Diplomacy
- Talk to faction leaders using **Influence** and **Favors**.
- Trade cards, ore, and intel for safe passage, discounts, or allied units.
- Reputation is tracked per faction. Helping one lowers standing with the others.
- Some fights can be avoided through negotiation, and some negotiations fail and trigger ambushes.

### Meta-Progression
- Each death returns you to the **Loom Hub**.
- You spend **Slag Credits** on permanent upgrades: more starting cards, new suit frames, and a larger diplomatic memory (some faction favors carry over).
- Each run unlocks **Memory Shards**, which add story fragments and new starting builds.
- The world state persists in part, so bosses you defeated stay weakened.

## Sample Run
1. You begin with a basic deck of a pickaxe strike, a pistol shot, and a dodge.
2. You clear the mining tunnels and find a **Helix keycard**.
3. You trade it to the Rock Union for a shortcut and a heavy-hitter card.
4. Helix turns hostile, and elite guards appear in the next zone.
5. You die to a boss, keep your Slag Credits, and start the next run stronger and with a new plan.

## Tone and Art
- **Look**: gritty industrial sci-fi with harsh lamp light and cramped tunnels.
- **Sound**: rumbling machinery, distant drilling, and eerie choral hums near the core.
- **Theme**: survival, exploitation, and what you owe the dead.

## Endings
- **Reclaimed**: you sell the outpost to Helix.
- **Free Rock**: the Union takes control.
- **Chorus**: the Choir wins and the signal spreads.
- **Severed**: you destroy the Loom and end the cycle.
- **Hidden ending**: you unlock it only through full meta-progression and by keeping all three factions at peace.', 'fighting, rpg, shooter', 'deckbuilding, metroidvania, procedural generation', 'any toaster with a screen', '1992-12-15 09:00:00+00'),
('Neon Thaw', 29.03, '# Frostbyte Inn

*A cyberpunk ice hotel where you tame monsters, fight for your guests, and fish in neon-lit frozen lakes.*

## Overview

| Field | Details |
|---|---|
| **World** | A luxury ice hotel on a frozen megacity lake |
| **Genres** | Fighting, monster taming, visual novel |
| **Style** | 3D, cyberpunk, stylized, relaxing |
| **Input** | Full controller support |
| **Mechanics** | Voice chat, fishing minigames |

## Premise

The megacity of **Nova Glacier** is buried under permanent ice. Corporations have left the surface and gone to the upper towers. At the edge of the frozen lake stands the **Frostbyte Inn**. It is a glowing hotel carved from ice and threaded with neon and holographic signs.

You play **Kai**, the new night manager. You inherited the inn from a missing relative. Its guests are travelers, hackers, exiles, and **Cryptids**. These are glitch-born monsters that appear when data storms hit the ice.

## Story Structure

### Act 1: Check-In
- You arrive at the run-down hotel with one loyal staff member, a hologram concierge named **Mira**.
- You tame your first monster, a small **Frost Sprite**, and it becomes your partner.
- Story scenes play as a visual novel, with branching dialogue and character portraits.

### Act 2: The Guests
- Each guest has a hidden story and a personal quest line.
- Your choices change relationships and unlock new rooms, suites, and lake zones.
- A rival corporation, **Aurex Group**, wants to buy the inn and drain the lake.

### Act 3: Whiteout
- A massive data storm awakens the **Glacier King**, an ancient monster under the ice.
- You must choose between allying with Aurex, protecting the guests, or freeing the monsters.
- There are several endings, based on your bonds and decisions.

## Core Gameplay

### Monster Taming
- Find Cryptids in the lake, the ice caves, and the hotel''s hidden vents.
- Befriend them with food, music, and care instead of brute force.
- Each has an element (Frost, Static, Steam, Void) and skills that also help run the hotel.
- Put them to work as porters, chefs, guards, or entertainers.

### Fighting
- Fights are fast, stylized 3D duels, with combos you can play on a controller.
- Fight alongside your tamed partner and switch roles mid-fight.
- Enemies include rogue Cryptids, Aurex enforcers, and arena challengers.
- Fights stay short and forgiving, so the game stays relaxing.

### Fishing Minigames
- Fish in the neon ice holes around the hotel.
- Catch glowing cyber-fish for cooking, trade, and Cryptid food.
- Rare catches can hatch into new monsters.
- The minigame is rhythm-based and works well with a controller.

### Voice Chat
- Talk to friends in co-op hotel management and fishing trips.
- Use proximity voice in the lobby and bar to socialize.
- Speak short commands to your Cryptids, such as "Fetch," "Guard," and "Sing."

## Atmosphere

- **Visuals:** Glowing ice, pastel neon, soft snow, and stylized characters.
- **Sound:** Lo-fi synth music, wind, and cracking ice.
- **Mood:** Cozy and calm, with occasional tension.

## Progression

1. Restore rooms and unlock hotel wings.
2. Grow your Cryptid roster and bonds.
3. Complete guest stories.
4. Upgrade gear, the fishing rod, and the inn.
5. Face the Glacier King and choose an ending.

## Tagline

> *Check in. Chill out. Tame the storm.*', 'fighting, monster taming, visual novel', '3d, cyberpunk, stylized, relaxing, controller support', 'gtx 1060, 8 gb ram, ssd recommended', '2004-09-22 09:00:00+00'),
('Last Winding', 1.51, '# Gearfall Court

*A clockwork city is dying. Rule it, sneak through it, and choose who to love.*

## Logline
You are the newly appointed Regent-Apprentice of **Verrin**, a vertical city run by a giant brass clock-heart. The heart is failing, and the **Rustborn**, citizens turned into clockwork zombies, are rising. Hold the factions together with diplomacy, keep the city alive, and find love in a court full of secrets.

## World: Verrin, the Clockwork City
- **Structure:** a tower-city of rotating districts, each driven by huge gears.
  - **The Escapement (top):** noble courts and the clock-heart.
  - **The Cogwalks (middle):** markets, guilds, and homes.
  - **The Sump (bottom):** oil-slick slums and old machinery.
- **Time:** the city runs on the Tick. Every district rotates on a schedule, which opens and closes routes.
- **Art style:** stylized, hand-painted brass, copper, and teal steam tones, with bold silhouettes and exaggerated animation.
- **The plague:** Rustborn are people whose inner springs seize up. They shamble, and they are drawn to the sound of ticking.

## Story Structure

### Act I: The Wound
You inherit the regency after the old Regent vanishes. The clock-heart skips a beat, and the first Rustborn appear in the Sump. Four factions each offer help, and each wants something in return. You meet the romance candidates.

### Act II: The Long Winding
Verrin rotates through seasons called Windings. Each Winding, the plague spreads, factions push their agendas, and court intrigue grows. Secrets come out:
- The old Regent did not die. They sealed themselves inside the heart.
- Someone in your circle is sabotaging the city.
- The plague is not random.

### Act III: The Final Tick
You choose one of several endings. You can repair the heart, replace it, free the city from the clock, or let it stop. Your alliances and your romance shape which ending is available.

## Gameplay Pillars

### 1. Grand Strategy: Rule the City
- Manage districts, resources (oil, steel, food, morale), and edicts.
- Set policy and assign guilds. Watch the Rustborn spread on a live city map.
- Every decision has a ripple effect on faction loyalty.

### 2. Stealth: Move Unseen
- Infiltrate noble estates, quarantine zones, and enemy workshops.
- Rustborn track sound and guards track sight, so you manage both.
- Use gear-rhythm timing to hide your movements in loud machinery.

### 3. Wall Running: Vertical Traversal
- Run along tower walls, pipes, and turning gear faces.
- Chain wall runs into rooftop shortcuts that bypass patrols.
- Rotating districts make routes change over time, so timing matters.

### 4. Diplomacy: Words as Weapons
- Hold court audiences, negotiate treaties, and trade favors.
- Read your opponent''s mood and pick a tone: charm, pressure, honesty, or bluff.
- Some conflicts can only be solved by talking, and some talks fail without stealth-gathered secrets.

### 5. Otome and Life Sim: Live in Court
- Daily schedule: spend each day on duties, training, errands, or people.
- Build relationships through gifts, dates, and shared missions.
- Personal choices affect faction politics, and politics affect romance.

## Romance Candidates

| Name | Role | Personality | Faction Tie |
|---|---|---|---|
| **Aurelian Voss** | Court Chronomancer | calm, precise, guarded | Nobles |
| **Kestrel "Kes" Marlow** | Guild rooftop runner | playful, reckless, loyal | Cogwalk guilds |
| **Dr. Ilya Thorne** | Plague physician | tired, tender, obsessive | Sump clinics |
| **Sable** | Spymaster, identity unknown | witty, dangerous, secretive | Shadow network |

Each route has its own missions, court conflicts, and a possible ending.

## Factions
- **House Escapement:** nobles who want order at any cost.
- **The Cogwrights'' Union:** workers who demand fair rule.
- **The Sump Choir:** oil-slum mystics who believe Rustborn are sacred.
- **The Quiet Hand:** spies who sell information to anyone.

## Life Sim Loop
1. **Morning:** read reports and set edicts.
2. **Day:** court audiences, or sneak out on a mission.
3. **Evening:** spend time with a candidate or visit a district.
4. **Night:** Rustborn surge. Defend a district, or slip through it.

## Tone and Themes
- **Tone:** elegant and eerie, with warm, funny moments between people.
- **Themes:** duty versus desire, progress versus humanity, and what a city owes its people.

## Why It Stands Out
It mixes the pressure of ruling a city with the tension of sneaking through it, the freedom of vertical parkour, and the intimacy of a romance story, all in one clockwork setting.', 'grand strategy, stealth, otome', 'life sim, stylized, third-person, zombies', 'high-end gpu, 32 gb ram, and a good cooling plan', '1980-07-09 09:00:00+00'),
('Wickshard', 23.29, '# Mirror Maze: Shards of Dominion

## Overview
A survival-idle-sandbox where you found and grow a city inside an endless, shifting **mirror maze**. Every reflection can be a threat, a resource, or a doorway. The game is soulslike in tone and combat, and it is a city builder at its core.

- **Genres:** Survival, Idle, Sandbox
- **Tags:** Soulslike, Building, City Builder
- **Mechanics:** Tech Tree, Energy Timers

---

## Story

### Prologue: The Shattering
The Great Glass Kingdom was ruled by a vain emperor. He wanted to see his empire from every angle, so he ordered a mirror built to reflect everything. It cracked, and the kingdom folded into an infinite labyrinth of glass. Its people became **Echoes**, hollow reflections that wander the corridors.

### Your Role
You are a **Wick-Bearer**, one of the few living souls left. You carry a flickering **Lumen Core**. It is your life, your currency, and your only defense against the dark between the mirrors.

### Arc
1. **Awakening:** You wake in a dead-end corridor with a single Lumen Core.
2. **Foundation:** You build the first Hearth, a safe zone of stable light.
3. **Expansion:** You push the walls outward and claim districts.
4. **Confrontation:** You fight Sovereign Reflections, the bosses that guard each region.
5. **Ending:** You reach the Throne Mirror and choose to shatter it, restore it, or become its new ruler.

---

## World: The Mirror Maze

| Feature | Description |
|---|---|
| **Shifting Walls** | Corridors rearrange every night cycle, so maps can''t be fully trusted. |
| **Reflections** | Mirrors show alternate versions of rooms. Some can be entered. |
| **Dark Glass** | Unlit zones drain Lumen and spawn Echoes. |
| **Prism Veins** | Rich resource seams that refract light into energy. |

### Regions
- **The Silvered Halls:** The starting area, with cracked but stable glass.
- **Gilded Arcade:** A decayed merchant district full of traps.
- **Warped Gallery:** Distorted geometry with gravity tricks.
- **Void Atrium:** The final region, with no reflections and no rules.

---

## Core Gameplay Loops

### 1. Survival
- Manage **Light**, **Sanity**, and **Shard Stock**.
- Echoes attack at night and target the weakest light sources.
- Dying drops your **Fragments** at the spot of your death. Recover them or lose them. This is the soulslike rule.

### 2. City Building
- Place buildings on a reflective grid. **Mirrored placement** duplicates a building''s effect in the reflection layer.
- **Districts:**
  - *Hearth Quarter:* housing and morale.
  - *Prism Forge:* crafting and refining.
  - *Watchlight Bastion:* defense towers and beam grids.
  - *Archive of Angles:* research.
- Citizens are assigned jobs and have needs, moods, and fears.

### 3. Idle Progression
- Buildings produce **Lumen**, **Glass**, and **Silver** while you are offline.
- Production is capped by your storage and by Energy.
- When you return, you get a summary of what happened. Sometimes it includes a raid report.

### 4. Soulslike Combat
- Fight in short expeditions outside the safe zone.
- Learn enemy patterns, dodge, parry, and manage stamina.
- Sovereign Reflections are large bosses. They mimic your moves and attack styles.
- **Bonfire equivalent:** Lightwells, which are checkpoints that also respawn enemies.

### 5. Sandbox
- Reshape corridors with **Glasscraft**. Place, angle, and rotate mirrors to redirect beams.
- Build puzzle-defenses, light-mazes, and beam-based factories.
- Player designs can be shared as blueprints.

---

## Mechanics

### Energy Timers
- **Lumen Energy** is the main action resource. It regenerates in real time.
- Timers gate:
  - Expeditions (e.g. 30 min recharge)
  - Construction (upgrades take minutes to days)
  - Research
- **Refraction Boost:** spend rare shards to shorten timers. Never required.
- Timers keep running offline, which supports idle play.

### Tech Tree
Four branches:

| Branch | Focus | Example unlocks |
|---|---|---|
| **Optics** | Light and energy | Focus Lenses, Beam Relays |
| **Masonry** | Building and infrastructure | Reinforced Glass, Districts |
| **Warcraft** | Combat and defense | Parry Blades, Prism Turrets |
| **Mysticism** | Sanity and secrets | Reflection Walking, Echo Binding |

- Research needs both resources and time.
- Some techs are found in **Lost Reflections** (hidden lore rooms) and cannot be researched normally.

---

## Progression Example
1. **Hour 1:** Build a Hearth, a Lightwell, and 3 houses.
2. **Day 1:** Research Focus Lenses and unlock the Prism Forge.
3. **Week 1:** Defeat the first Sovereign, *The Mirror Warden*.
4. **Month 1:** Reach the Warped Gallery and open trade with far districts.
5. **Endgame:** Assault the Throne Mirror.

---

## Tone and Style
- **Visual:** Cold silver, amber light, fractured reflections.
- **Audio:** Glass chimes, muffled echoes, sparse strings.
- **Mood:** Lonely and tense, with quiet hope.

---

## Hook
> *"Every mirror shows what you could become. Some of them are hungry."*', 'survival, idle, sandbox', 'soulslike, building, city builder', '6 gb vram, 12 gb ram, 20 gb free space', '1998-08-29 09:00:00+00'),
('Echo Warden', 2.28, '# Deep Hollow

*An idle survival sandbox in an underground bunker city.*

## Overview
The surface is gone. Beneath it, **Deep Hollow** is the last bunker city, a pixel-art colony of rusted corridors, glowing farms, and hand-dug tunnels. You are the **Warden**. You guide the survivors, expand the city, and decide what humanity becomes.

- **Genres:** casual, survival, sandbox
- **Tags:** idle, pixel graphics, sandbox
- **Mechanics:** quest system, meta-progression

## Story
### Chapter 1: The Last Door
The blast doors seal. Forty survivors, one generator, and a few days of food are all you have. Every survivor has a name, a skill, and a story. They wait for orders.

### Chapter 2: Digging In
Stone gives way to new rooms: farms, water plants, workshops, and clinics. Your people start to trust you. The first whispers about **"the Signal"** begin, a faint transmission from somewhere deeper.

### Chapter 3: The Deep
Below the city lie ruins of older bunkers, strange machines, and sealed vaults. Some hold treasure. Others hold something that should stay buried.

### Chapter 4: The Choice
The Signal''s source is found. You can reopen the surface, seal the city forever, or merge with the ancient machine. Each ending changes the next run.

## Core Gameplay
### Idle Survival
- Survivors work on their own, even while you are offline.
- Resources build up over time: **food, water, power, scrap, morale**.
- Offline progress is capped by your storage and how well the city is run.
- Crises hit on a timer: blackouts, floods, raids, and disease. Prepared cities take less damage.

### Sandbox Building
- Dig, place, and connect rooms on a pixel grid.
- Design your own layout with elevators, pipes, wiring, and defenses.
- Room adjacency creates bonuses. A kitchen next to a farm is more efficient.
- Decorate for morale: posters, plants, music, and bunk styles.

### Survivors
- Each has traits, such as *Handy*, *Anxious*, or *Green Thumb*.
- Assign jobs, or let them pick their own.
- Their moods, friendships, and rivalries shape the city.

## Quest System
| Type | Description |
|---|---|
| **Story quests** | Advance the main plot toward one of the endings. |
| **Survivor quests** | Personal requests that unlock traits and rare perks. |
| **Expedition quests** | Send teams into the tunnels. Choose gear and risk level. |
| **Daily and event quests** | Short goals with bonus rewards and seasonal themes. |

Quests give resources, blueprints, and **Echo Fragments**, the currency of meta-progression.

## Meta-Progression
When the city falls or you choose to **Seal and Restart**, you begin a new **Generation**.

- **Echo Fragments** are spent in the *Legacy Archive*.
- Permanent unlocks include new rooms, starting bonuses, survivor classes, and map seeds.
- Each run has different tunnels and hazards.
- Choosing a different ending unlocks new story branches and cosmetics.
- Later generations discover the truth of what came before.

## Art and Audio
- Detailed pixel art with warm lamp light against dark stone.
- Animated survivors, visible in every room.
- A day-night cycle shown through the city''s lighting.
- Ambient sound design: dripping water, humming generators, and a soft synth score.

## Session Loop
1. **Check in:** collect resources and read the city report.
2. **Build:** expand and optimize.
3. **Send:** launch expeditions and take on quests.
4. **Leave:** the city keeps running.
5. **Return:** handle crises, then repeat and grow.

## Hook
*Build it deep. Keep them alive. Find out who is calling from below.*', 'casual, survival, sandbox', 'idle, pixel graphics, sandbox', 'any toaster with a screen', '2011-03-17 09:00:00+00'),
('Prism Pulse', 7.90, '# Mirror Maze Brawl

*A colorful, moddable fighting / life-sim / rhythm game set inside a living labyrinth of mirrors.*

## Story

You wake up in the **Mirror Maze**, a shifting labyrinth of glass. Every reflection is a "double" of someone who once walked in. Nobody who enters remembers how to leave. The maze runs on **rhythm**. Its walls pulse to a beat, and whoever moves in sync with that beat controls the space around them.

You start as a nameless **Wanderer**. To survive, you have to build a life inside the maze, defeat rival doubles, and find the **Prime Mirror**, the only exit.

## Genre Blend

| Genre | Role in the game |
|---|---|
| **Fighting** | Combat against doubles and rival Wanderers |
| **Life simulation** | Daily routines, housing, relationships, crafting |
| **Rhythm** | Timing drives movement, attacks, and crafting |

## Core Gameplay Loop

1. **Live**: manage a home base, needs, friends, and a job in the maze hub.
2. **Explore**: run through the corridors and collect shards and gear.
3. **Fight**: duel in beat-synced combat.
4. **Grow**: upgrade your character, your home, and your mods.

## Mechanics

### Wall Running
- Mirror walls can be run on when you hit the **beat**.
- Perfect timing gives speed boosts and a **reflect dash** through glass panels.
- Walls are used in fights for aerial combos, dodges, and ambushes.
- Some hidden shortcuts only open to skilled runners.

### Rarity Tiers
Gear, moves, skins, and mirror shards come in tiers:

| Tier | Color | Trait |
|---|---|---|
| Common | White | Basic stats |
| Uncommon | Green | Small bonus |
| Rare | Blue | Unique effect |
| Epic | Purple | Alters a move |
| Legendary | Gold | Changes playstyle |
| Mythic | Prismatic | Reflects abilities from your rival |

Higher tiers can be **fused** at the home-base forge, and a failed fusion produces a shadow double.

## Fighting System

- Attacks are chained to a **beat meter**, so on-beat hits deal more damage.
- Off-beat moves leave you open to counters.
- Each style has its own rhythm pattern: **Swift**, **Heavy**, and **Trick**.
- Reflections mimic your last move, so you have to vary your combos.

## Life Simulation

- **Home Nook**: decorate a mirror room, and each item gives a buff.
- **Needs**: energy, focus, and mood affect your rhythm accuracy.
- **Social**: befriend, rival, or romance NPC doubles, each with a music theme.
- **Crafting and jobs**: play rhythm minigames to forge, cook, or busk for currency.

## Visual and Audio Style

- **Colorful**: neon prisms, refracted light, and gradient skies inside the glass.
- The soundtrack adapts by zone, such as synthwave, funk, and lo-fi.
- Each fighter''s colors and sound change with their rarity tier.

## Moddable

- Community tools support **custom mazes, characters, and beatmaps**.
- Songs can be imported and auto-generate maze layouts.
- Mods can add fighters, skins, and life-sim items.
- A built-in **workshop** lets players share and rate mods.

## Progression and Ending

- Clear **zones** (Prism Gardens, Echo Halls, Shattered Core).
- Defeat the **Mirror Sovereign**, the ultimate double.
- Choose an ending:
  - **Leave** the maze and go home.
  - **Stay** and become its keeper.
  - **Shatter** the maze and free all doubles.

## Tagline

> *"Move to the beat. Break the glass. Find yourself."*', 'fighting, life simulation, rhythm', 'moddable, colorful, fighting', 'decent gaming laptop, charger plugged in', '2022-05-28 09:00:00+00'),
('Lullanova', 15.38, '# Nebula Nursery

*A point-and-click horror game about tending stars, and what tends you back.*

## Overview
| Field | Detail |
|---|---|
| Genre | Point-and-click, horror |
| Style | Stylized 3D with pixel-graphics filter |
| Tone | Casual, slow-burn dread |
| Core mechanics | Shields, sanity meter |
| Session length | 10-15 min chapters |

## Premise
You are a junior caretaker aboard the *Cradle*, a lone station drifting inside a glowing nebula where new stars are born. Your job is to feed, soothe, and nurture infant stars in glass incubators. The crew has vanished. The stars hum lullabies. Something in the gas hums along.

## Story Structure

### Act 1: The Night Shift
- You wake in the caretaker''s bunk. The station log says you slept for 3 days.
- Click through the nursery: check incubators, adjust gas valves, and read the crew''s notes.
- Small oddities appear. A star is drawn as a face. A cradle mobile spins with no air.

### Act 2: The Lullaby
- The stars respond to sound. You learn to play the nursery''s music panel to calm them.
- Crew logs reveal the team was "adopted" by something in the nebula. It wants to be born.
- Some stars are not stars. They are eggs.

### Act 3: The Birth
- The nebula''s presence enters the station. You must decide which incubator to sacrifice, or whether to nurture the final one.
- **Endings:**
  - **Lullaby:** you become the nebula''s caretaker forever.
  - **Supernova:** you destroy the nursery and escape.
  - **Lucid:** you keep your sanity and free the stars.

## Core Mechanics

### Sanity Meter
- Drops when you look at distorted areas, stay in the dark, or hear the whispers.
- Restore it by tending healthy stars, drinking tea, or playing music.
- **Effects at low sanity:**
  - Pixels warp and colors bleed.
  - Fake clickable objects appear.
  - Text in logs rewrites itself.
  - Hotspots move.

### Shields
- The station has limited shield charges that block nebula intrusions.
- Click the shield console to divert power to a room.
- Shields protect the room but drain power from life support and lighting. Less light means faster sanity loss.
- Balance the two resources, and decide which rooms to protect each night.

## Puzzle Examples
- **Star Feeding:** match gas colors to each star''s mood.
- **Lullaby Cipher:** decode crew music notes to open the sealed lab.
- **Shield Routing:** rewire the panel while a shadow creeps toward the door.

## Visual and Audio Direction
- Chunky pixel textures on soft 3D models, with a pastel-neon nebula palette.
- Cozy nursery decor (mobiles, plush toys) that gradually turns unsettling.
- Music-box melodies that detune as sanity falls.

## Casual-Friendly Design
- No fail-state deaths. Low sanity leads to story consequences, not game over.
- Hint system via the station''s helper bot.
- Autosave at every room.

## Tagline
> *Every star needs someone to sing to it. Who''s singing to you?*', 'point-and-click, horror, point-and-click', 'casual, 3d, pixel graphics, stylized, casual', 'quad-core cpu, 16 gb ram, mid-range gpu', '2010-12-24 09:00:00+00'),
('Skywright: Fall of Aerhaven', 20.67, '# Cloud Kingdom: Whispers of the Sky Court

## Overview
A puzzle-platformer set in a kingdom of floating islands, drifting on ancient storm currents. You play a young **Skywright**. You craft, you solve mysteries, and you defend the realm. Your choices decide which islands survive.

## Story

### Act I: The Falling Light
The Cloud Kingdom of **Aerhaven** is held aloft by the **Lumen Spires**. One night the spires flicker and an island crashes into the mist below. The Queen has vanished. Her court accuses each other.

You are a junior Skywright and the only one who saw the culprit''s shadow. You take up the investigation.

### Act II: The Hollow Court
You climb through the kingdom''s districts and gather clues. Each district has a different problem and a different faction:
- **Windmill Terraces:** farmers who distrust the crown.
- **Glass Aviary:** scholars who hide forbidden research.
- **Stormforge:** smiths who profit from the crisis.

Each faction offers help, and each asks for a price. Your choices change alliances, available tools and which districts fall.

### Act III: The Storm''s Heart
The truth comes out. The culprit is not one villain but a **chain of decisions**, and some of them were yours. Depending on what you did, you can:
- Restore the spires and save the kingdom.
- Let the kingdom fall and start a new one on the ground.
- Bind the storm itself and rule the skies.

## Gameplay

### Platforming
- Jump across drifting islands, ride wind currents and swing on cloud-ropes.
- Every platform has physics. Some dissolve, some bounce, and some are only solid in sunlight.

### Puzzles
- Redirect wind, align light-prisms and rotate gear-bridges.
- Some puzzles have several solutions, and the one you pick affects the story.

### Crafting
Gather **cloudsilk, stormglass and ember-moss** to craft:
| Item | Use |
|------|-----|
| Wind Glider | Extended air travel |
| Prism Lens | Reveals hidden clues |
| Spark Trap | Defense tool |
| Sky Anchor | Stabilizes islands |

### Mystery
- Interrogate suspects and examine scenes.
- Assemble clues on an evidence board.
- Wrong accusations have lasting consequences.

### Strategy and Tower Defense
Storm creatures called **Gloomwraiths** attack the spires in waves.
- Place crafted towers on islands: wind cannons, lightning rods and decoy lanterns.
- Plan the layout ahead, because resources are limited.
- Between waves, choose which island to reinforce. The ones you skip may be lost for good.

### Choices Matter
- Decisions are permanent, with no reload-and-fix option.
- Allies can betray you, and abandoned islands stay gone.
- There are **5+ endings**.

## Special Mechanics

### Invincibility Frames
- After a hit, you get a short window of invulnerability.
- Use it to dash through hazards, cross lightning fields, or slip past bosses.
- Some crafted items extend the window, at a cost.
- Timing this window is a skill, and speedrunners can exploit it.

### Voice Chat
- **Co-op mode:** two players coordinate platforming and defense by voice.
- **Ghost Whispers:** in single-player, the microphone lets you call to spirits. Speaking near certain spirits reveals clues or calms enemies.
- **Proximity chat:** in multiplayer defense, your voice carries only to nearby players, so teams need to position themselves carefully.

## Tone and Style
- **Art:** soft watercolor skies, glowing spires and mist-filled depths.
- **Music:** airy orchestral themes that turn tense during storms.
- **Mood:** wonder mixed with suspicion, and the constant risk of falling.

## Design Pillars
1. **Height means stakes.** Every jump could be your last.
2. **Craft your way through.** Tools solve problems and open new ones.
3. **Every choice leaves a mark.** The kingdom remembers.', 'puzzle, platformer, platformer', 'crafting, mystery, choices matter, strategy, tower defense', 'gtx 1060, 8 gb ram, ssd recommended', '2005-07-03 09:00:00+00'),
('Kethra Fall', 8.94, '# Ringfall Protocol

*A cyberpunk metroidvania-RTS-soulslike on a moon beneath a ringed giant.*

## 1. Premise

**World:** Kethra-9, a frozen, tidally-stressed moon orbiting a gas giant whose shattering ring drops debris on the surface. Megacorp arcologies cling to the equator. Rogue AI and scavenger clans hold the dead zones below.

**You are** Vesper, a decommissioned "Warden" cyborg. A neural relic called the **Core Deck** wakes you in a wrecked foundry. It holds fragmented memories as cards. Your goal is to rebuild a colony, uncover why the ring is collapsing, and decide who gets to survive it.

## 2. Story Structure

**Act I: Ash and Static**
- Wake in the Scrapyard Foundry and claim a derelict outpost.
- Learn the loop: fight, salvage, build, defend.
- The first boss, *Warden Unit 07*, is your former partner.

**Act II: The Descent**
- Open the vertical map: sewers, cryo-mines, corp spires, orbital elevator ruins.
- Each region has a rival faction and a "Ring Surge" countdown.
- Learn that the ring is being broken deliberately, to harvest exotic ore.

**Act III: Ringfall**
- Gather three **Key Cores** and reach the orbital anchor.
- Choose an ending:
  - **Evacuate** the elite and abandon the moon.
  - **Merge** with the AI and end humanity as it is.
  - **Stabilize** the ring at a cost to your colony.

## 3. Core Gameplay Loops

### Hack and Slash (Soulslike)
- Weighty, stamina-based melee with a modular cyber-blade, whip and gauntlet.
- Parry, dodge and stagger enemies. Bosses have readable phases.
- Death drops your **Scrap Charge** at the death site. Recover it or lose it.
- Checkpoints are **Beacons**. They restore health and respawn enemies.

### Metroidvania Exploration
- A connected map of interlocking zones with shortcuts and secrets.
- Ability gates:
  - **Magnetic Grapple** for ceiling rails.
  - **Phase Dash** to pass energy barriers.
  - **Low-G Boots** for high jumps and drifting over chasms.
  - **Ice Breaker** for frozen walls.
- Returning with new abilities opens new outpost sites and resource nodes.

### Real-Time Strategy and Simulation
- Switch to a **Command View** at any Beacon-linked outpost.
- Manage colonists, power, heat and morale. Cold snaps and ring debris strain the colony.
- Assign workers, drones and automated units to tasks.

### Production Chains
- Raw inputs: ice, regolith, ring-ore, bio-sludge.
- Intermediate goods: alloy plates, coolant, circuits, nano-gel.
- Final products: ammo, turret parts, medical kits, **card crafting modules**.
- Logistics: conveyors, cargo drones and supply lines between zones. Enemies can sever them.

### Tower Defense
- Ring Surges and enemy raids hit your outposts in waves.
- Place turrets, walls, shield pylons and traps on preset nodes.
- Vesper fights on the field while the defenses hold the lanes.
- A well-fed production chain gives you stronger defenses.

### Deckbuilding
- The **Core Deck** holds cards of four types:
  - **Combat** cards: skills and combos.
  - **Tactical** cards: drop turrets, call drones, deploy barriers.
  - **Augment** cards: passive boosts, risk-reward mods.
  - **Memory** cards: story fragments with gameplay perks.
- Build a 20-card deck before each expedition.
- Cards are drawn in real time from a cooldown-based hand.
- Dying burns one random card, which adds a soulslike cost.

## 4. Factions

| Faction | Style | Offers |
|---|---|---|
| **Helix Dynamics** | Corporate, high-tech | Advanced turrets, strict contracts |
| **Rustborn Clans** | Scavengers | Cheap mods, raids |
| **The Chorus** | Rogue AI collective | Forbidden augments, memory cards |
| **Frostline Monks** | Cryo-mystics | Healing, ring lore |

## 5. Sample Regions

1. **Scrapyard Foundry:** a tutorial zone with a first outpost.
2. **Coolant Sewers:** toxic, stealthy and claustrophobic. Holds the Phase Dash.
3. **Cryo-Mines:** frozen, with ore-heavy nodes and ice bosses.
4. **Helix Spires:** a vertical corporate gauntlet full of turrets.
5. **Ring Anchor:** the zero-gravity final zone.

## 6. Progression and Replay

- **Outpost levels** unlock new production tiers and defenses.
- **Vesper''s upgrades** come from cards, gear and abilities.
- **New Game+** remixes boss patterns and adds harder Ring Surges.
- **Three endings** and faction-specific cards give replay value.

## 7. Tone and Visuals

- Neon-lit ruins under a huge, cracked ring that fills the sky.
- Dark synth soundtrack and rain-slick metal.
- Bleak and melancholic, with hope in the colony you build.

## 8. Unique Hook

> *Every death feeds the ring''s collapse. Every outpost holds it back.*

The game asks you to balance the risk of pushing forward against the safety of building up. The deck, the colony and Vesper''s body share a single pool of scarce resources.', 'real-time strategy, hack and slash, metroidvania', 'soulslike, metroidvania, deckbuilding, simulation, cyberpunk', 'decent gaming laptop, charger plugged in', '2012-11-17 09:00:00+00'),
('Brinewick', 8.74, '# Saltbound: Tides of Ash

## Overview
**Saltbound** is a first-person shooter with text-adventure storytelling and roguelite structure. It is set in an open-world fishing village that a cursed tide keeps drowning and rebuilding. The player is the village''s last **Warden**. Each run is a "tide cycle" of exploration, combat, and dialogue. Between runs, the Warden rebuilds the village and prepares for the next descent.

---

## Story

### Act I: The Drowned Harbor
The village of **Karrowmere** sat on a cold northern coast. It lived on herring and trade until a black tide swallowed the harbor. The tide returns every few days, and it brings **the Hollow Fleet**. These are ghost ships crewed by drowned fishermen, and they are hostile.

You wake on the dock with a rusted flare gun and a salt-stained logbook. The logbook writes itself in text as you play. It narrates events, offers choices, and remembers what you did.

### Act II: The Cycle
Dying does not end the story. The tide pulls you back to the lighthouse, and the village remembers what you learned. Each cycle reveals more about:
- **The Lantern Pact**: the founders'' bargain with something beneath the sea.
- **The Ash Mother**: a mysterious figure who benefits from every drowning.
- **Your own past**: you may have been part of the pact.

### Act III: The Deep Choice
In the final descent you swim to the sunken cathedral at the seafloor. You can break the pact, renew it, or take its power. There are multiple endings, and villagers you saved or abandoned shape each one.

---

## Gameplay

### Core Loop
1. **Prepare** in the village hub: craft, upgrade, and talk to villagers.
2. **Descend** into a procedurally shuffled region during low tide.
3. **Explore and fight** in FPS combat mixed with text-driven events.
4. **Return** with loot, lore, and survivors, or die and lose part of your haul.
5. **Rebuild** and repeat with new knowledge.

### FPS Combat
- Weapons: harpoon gun, flare pistol, sawed-off shotgun, and salvaged cannon.
- Enemies: drowned crews, brine-hounds, lantern wraiths, and boss captains.
- Weapons can be **modified with fishing tackle**, such as hook-tipped rounds and net traps.

### Text Adventure Layer
- Story events appear as text prompts, for example: *"A bell rings beneath the pier. Do you answer it?"*
- Choices are made with typed commands or a quick menu.
- Outcomes affect combat, loot, and village relationships.
- Text events are **roguelite-randomized**, so no two cycles read the same.

### Swimming
- Full 3D swimming with breath management.
- Underwater areas hold wrecks, caves, and secret loot.
- Weapons behave differently underwater: the harpoon gun is stronger and firearms are weaker.
- Deep water has its own threats, such as pressure, darkness, and leviathan-scale creatures.

---

## Open World
- The coast, tidal flats, islands, wrecks, and sea caves are **seamlessly connected**.
- The tide changes accessible areas: low tide opens paths, and high tide opens diving routes.
- Weather and time of day affect enemies and events.
- Landmarks include the Rotting Cannery, Gull Rock Lighthouse, and the Bone Reef.

---

## Base Building
Karrowmere is your **persistent hub**. It changes based on your choices.

| Structure | Function |
|---|---|
| Smokehouse | Food buffs and healing items |
| Forge | Weapon crafting and upgrades |
| Chapel of Salt | Blessings and lore unlocks |
| Net Loft | Passive resource gathering |
| Watchtower | Warnings about tide events |
| Tavern | Recruit villagers and hear rumors |

- Rescued **villagers** become NPCs with skills and personal quest lines.
- Defend the village during **Tide Assaults**, which are timed defense events.
- Building layouts are free-form, and placement affects defense and bonuses.

---

## Roguelite Systems
- **Permadeath per cycle**: you lose carried items but keep **Meta-Currency (Brine Pearls)**.
- **Random run modifiers**: cursed tides, fog seasons, and blessed catches.
- **Unlockable classes**: Harpooner, Lamplighter, Diver, and Smuggler.
- **Relics** change how you play, and some are cursed with drawbacks.

---

## Save System
- **Anchor Points**: save at lighthouse beacons and village lanterns.
- **Ironman option**: a single autosave for hardcore players.
- **Logbook memory**: the text log persists between sessions, so past choices are quoted back to you.
- Saves record village state, NPC relationships, and unlocked lore.

---

## Modding Support
- **Data-driven design**: enemies, weapons, events, and buildings are defined in JSON/Lua.
- **Text event editor**: write new story branches without code.
- **Map tools**: build new islands, wrecks, and regions.
- **Workshop integration**: share mods, weapon packs, and full story campaigns.
- Supports total conversions, for example a sci-fi space station replacing the fishing village.

---

## Tone and Style
- **Atmosphere**: gloomy, salty, and folkloric, with moments of warmth.
- **Visuals**: painterly low-poly with heavy fog and lantern lighting.
- **Audio**: creaking wood, distant bells, sea shanties, and layered ambient waves.
- **Narration**: a poetic, sometimes unreliable logbook voice.

---

## Key Selling Points
- FPS action combined with a **text-adventure narrative** that reacts to you.
- A **living fishing village** you build, defend, and lose.
- **Underwater exploration** as a core mechanic.
- Endless replayability through roguelite runs and mod support.', 'fps, text adventure, roguelite', 'roguelite, open world, base building, moddable', 'rtx 4070, 32 gb ram, nvme ssd', '1996-02-02 09:00:00+00'),
('Halcyon Hush', 5.53, '# Derelict Drift

*A casual pixel-art clicker set aboard a dead starship. Explore it, craft your way through it, and try not to wake what still lives there.*

---

## Overview

| Field | Details |
|---|---|
| **World** | Derelict starship (the *ISV Halcyon*) |
| **Genres** | Open world, casual, clicker |
| **Perspective** | Third-person |
| **Style** | Pixel graphics, visual-novel dialogue scenes |
| **Core Mechanics** | Idle progression, stealth |
| **Systems** | Crafting |

---

## Premise

You wake up alone in a cryo-pod aboard the *Halcyon*, a colony ship that has been drifting for decades. The lights flicker, the corridors are silent, and the crew is gone. The ship''s fractured AI, **ECHO**, still whispers through the speakers. It needs you to restore power and piece together what happened.

---

## Story Structure

### Act I: Awakening
- Leave the cryo bay and click to salvage your first scrap.
- Craft a **Spark Wrench** and repair the first generator.
- Meet ECHO in a visual-novel scene with branching dialogue.

### Act II: The Silent Decks
- Unlock new sections: Hydroponics, Engineering, the Crew Quarters and the Bridge.
- Find **memory logs** that reveal the crew''s fate.
- Discover the **Wardens**, malfunctioning maintenance drones that patrol the halls.

### Act III: The Truth
- Restore the ship''s core.
- Choose between three endings:
  - **Reboot**: revive the ship and its colonists.
  - **Release**: free ECHO and let the ship die.
  - **Escape**: take a lifepod and leave everything behind.

---

## Gameplay Loops

### 1. Click: Salvage
- Tap wrecks, panels and debris to collect **Scrap**, **Wire**, **Coolant** and **Circuits**.
- Each click also charges your **Power Cell**.
- Rare finds appear as glowing pixel sparkles.

### 2. Idle: Automation
- Build **Salvage Bots** that gather resources while you''re away.
- Set up **Auto-Fabricators** that keep crafting.
- Return to an "offline report" of what your bots collected.
- Bots can be upgraded in tiers: *Rusty, Reliable, Refined, Radiant*.

### 3. Craft: Workbench
- Combine materials into tools, gadgets and ship upgrades.
- Example recipes:
  - `Scrap + Wire` -> **Grappler Hook** (reach high vents)
  - `Coolant + Circuit` -> **Cryo Patch** (seal leaks)
  - `Circuit x3` -> **Ghost Cloak** (stealth boost)

### 4. Stealth: Avoid the Wardens
- Wardens patrol set routes with visible vision cones.
- Hide in lockers, crawl through vents and use shadows.
- Distract drones with **noise decoys**.
- If you''re caught, you lose part of your carried loot but keep your idle income.
- Stealth stays light and forgiving, in keeping with the casual tone.

---

## Open World Exploration

The ship is one large, interconnected map with no loading screens.

| Zone | Feature |
|---|---|
| **Cryo Bay** | Tutorial area, safe zone |
| **Hydroponics** | Overgrown, rich in organic materials |
| **Engineering** | Power puzzles, heavy patrols |
| **Crew Quarters** | Story logs, personal items |
| **Cargo Hold** | Big loot, hidden shortcuts |
| **The Bridge** | Final area |

Zones unlock as you restore power and craft new traversal tools.

---

## Visual Novel Elements

- Conversations with ECHO and with recovered crew holograms use portrait art, text boxes and choices.
- Your choices affect:
  - ECHO''s trust level
  - Which upgrades and endings become available
  - Side-story unlocks
- Scenes trigger at story milestones and at some points during idle play.

---

## Art and Audio

- **Pixel art**: a moody palette of teal, amber and deep purple, with flickering lights and floating dust.
- **Third-person camera**: a small, expressive character sprite viewed from a slight angle.
- **Soundtrack**: ambient synth with soft hums, and a tense rhythm when Wardens are near.

---

## Progression and Retention

- **Ship Restoration Meter**: a visible percentage showing how much of the ship you''ve repaired.
- **Prestige system**: "Cold Boot" resets progress for permanent bonuses and new story variations.
- **Daily tasks**: ECHO gives short requests for bonus rewards.
- **Collectibles**: 60 hidden crew logs and 20 cosmetic suit skins.

---

## Tone

Cozy-eerie: lonely and mysterious, but never harsh. It''s meant for short, relaxed sessions, with ambient progress that continues even when you''re not playing.

---

## Tagline

> *"The ship is silent. But it remembers."*', 'open world, casual, clicker', 'visual novel, third-person, crafting, pixel graphics', 'rtx 4070, 32 gb ram, nvme ssd', '2011-04-28 09:00:00+00'),
('Toll of Mimi', 13.57, '# Ashen Lotus: Monastery at the End of the World

## Elevator Pitch
A cute, post-apocalyptic **metroidvania brawler** set in a sealed mountain monastery. Between fights, a **kinetic novel** tells the story. Each death restarts the run **roguelike-style**, but the story keeps moving forward.

---

## World: The Monastery of Silent Peaks
- A vast cliffside monastery. Its temples, bridges, and caves are carved into a frozen mountain.
- **Before:** monks kept a sacred archive. Unknown to the world, it was also a hidden sci-fi research site.
- **The fall:** a signal from a buried orbital relay woke a nano-plague. The dead now rise as **zombies**, called "Hollows".
- **Now:** the monastery is the last safe place. Its old machines still hum under the prayer bells.

### Regions (metroidvania map)
| Region | Theme | Unlocks |
|---|---|---|
| Bell Courtyard | Tutorial, snow, broken shrines | Basic combat |
| Sutra Library | Floating scrolls, hologram ghosts | Double jump |
| Frozen Sanctum | Ice, slippery bridges | Dash-slash |
| Reactor Cellars | Neon pipes, toxic steam | Wall climb |
| Sky Terrace | Wind, chasm platforming | Glide |
| Signal Spire | Final area, the source of the plague | True ending |

---

## Story (Kinetic Novel Structure)
Story scenes play as **linear, choice-free visual novel chapters**. They unlock as you reach milestones.

### Prologue: "The Last Bell"
Mimi, a young novice, wakes alone in the ruins. She is small, round-eyed, and carries a staff. A talking maintenance drone, **Pip**, greets her. It says the monastery *remembers* her.

### Act I: Echoes
- Mimi finds fragments of monk memories.
- She learns the monks were shutting down the relay when the plague hit.
- Each run reveals a little more of the past.

### Act II: The Truth
- Mimi is revealed to be a **clone**, one of many. The monks used her line as living keys to the relay.
- The Hollows are earlier failed versions of her.
- She is not the first "Mimi" to climb the mountain.

### Act III: The Final Toll
- Mimi reaches the Signal Spire.
- She can silence the relay, which frees the Hollows but ends the loop, and possibly ends her.
- The story ends on a single, fixed scene. The **kinetic novel** presents it with no branching, and it stays bittersweet.

---

## Characters
- **Mimi:** protagonist. Cheerful, stubborn, and clumsy.
- **Pip:** drone companion. Sarcastic, and it doubles as the save point and shop.
- **Abbot Renn:** hologram of the last leader, who narrates the truth.
- **The Hollows:** zombies drawn in a soft, chibi style (cute but eerie). Some wear tiny monk robes.

---

## Gameplay

### Combat (fighting)
- Fast 2D combat with combos, dodges, and parries.
- **Area-of-effect attacks:**
  - *Bell Slam:* a ground shockwave that pushes back crowds.
  - *Lotus Spin:* a spinning staff that hits all nearby enemies.
  - *Sutra Burst:* a charged energy blast that clears a whole screen.
- Crowd control matters. Hollows swarm in large numbers.

### Exploration (metroidvania)
- Interconnected map with gated paths.
- New abilities open shortcuts and secret rooms.
- Shortcuts stay open between runs.

### Roguelike Loop
- Dying returns Mimi to the **Bell Courtyard**.
- Room layouts and enemy placement are partly randomized.
- Random **relic** drops change your build, such as fire-based AoE or a bigger spin radius.
- Story progress, abilities, and map shortcuts persist.

### Currency
- **Prayer Beads:** dropped by enemies and found in the world.
  - *In-run:* buy temporary boosts from Pip.
  - *Banked:* spend at the monastery altar on permanent upgrades, such as more health, a larger AoE radius, and new combos.
- If you die, you lose only part of your unbanked beads. This keeps a risk-and-reward tension.

---

## Tone and Visuals
- **Art:** pastel pixel art, snowy mountains, glowing sci-fi tech, and chibi characters.
- **Music:** soft temple bells and synths, turning to heavy percussion in boss fights.
- **Mood:** cozy but melancholy, a gentle story in a brutal world.

---

## Key Selling Points
1. Cute art against a grim zombie apocalypse.
2. Satisfying crowd-clearing AoE combat.
3. Death is a story device: each run reveals more.
4. A fixed, emotional story told through kinetic novel scenes.
5. A compact, interconnected mountain map worth mastering.', 'fighting, metroidvania, kinetic novel', 'zombies, post-apocalyptic, sci-fi, cute, roguelike', 'rtx 4080 or better; your pc will hum a lullaby', '2014-01-29 09:00:00+00'),
('Hollow Deck', 0.36, '# Rustwake: The Last Deck

## Overview
**Rustwake** is a story-rich, idle auto-battler with horror and life-sim elements. It takes place on a crumbling airship that drifts above a dead world. You lead a party of survivors and keep the deck alive. Every night, something climbs aboard.

- **Genres:** Auto Battler, Horror, Idle
- **Tags:** RPG, Party, Life Sim, PvP, Story Rich
- **Mechanics:** Shops & Trading, Respawning
- **World:** The airship *Halcyon Verdant*, a floating city-deck

---

## Story

### Act I: The Drift
The clouds swallowed the ground long ago. The *Halcyon Verdant* is the last known airship still flying. Its captain vanished, and its crew has split into factions. You wake up on the deck with no memory of the last three weeks. Your ID tag says **"Quartermaster."**

### Act II: The Nightfall
At dusk a fog rolls over the rails. Things called the **Hollow Crew** climb out of it. They are former sailors whose faces are worn smooth. They repeat the routines they had in life: swabbing, hauling, saluting. They also kill.

### Act III: The Truth
Each death you suffer reveals a fragment of memory. You slowly learn that the ship *feeds* on its crew. Every respawn costs something. Rival captains want the ship''s heart for themselves, and you must decide whether to save it or destroy it.

---

## Core Gameplay

### 1. Idle Deck Management
- Your ship keeps running while you are offline: it generates **scrap, fuel, and rations**.
- Assign crew to stations: **Engine, Galley, Armory, Infirmary, Watch**.
- Progress continues in the background, but **nights are dangerous** when you come back.

### 2. Auto Battler Combat
- Set up a **party formation** on the deck grid (front, rail, mast).
- Fights run automatically. Your choices are:
  - Formation and positioning
  - Gear and loadouts
  - Skill priorities and triggers
- Deck hazards affect combat: **wind gusts, fire, missing planks, and falling overboard**.

### 3. Horror Systems
- **Fog Meter:** it rises at night. High fog brings stronger and stranger enemies.
- **Sanity:** it drops during fights and events, causing hallucinations, false UI info, and unreliable allies.
- **Unseen Threats:** some enemies appear only in the reflections of lanterns.

### 4. RPG & Party
- Recruit **12+ crew archetypes**: Gunner, Medic, Rigger, Cook, Priest, Smuggler and more.
- Each has **traits, fears, bonds, and personal quests**.
- Party synergies and rivalries change how they fight.

### 5. Life Sim
- Crew members eat, sleep, gossip, fall in love, and hold grudges.
- Cabins can be upgraded, meals cooked, and relationships built.
- Morale affects performance and loyalty. Low morale can lead to **mutiny**.

### 6. PvP
- **Boarding Raids:** asynchronous battles against other players'' airships.
- **Sky Duels:** live auto-battle matchups with ranked seasons.
- Lose a raid and you lose cargo. Win and you can loot supplies or capture crew.

### 7. Shops & Trading
- **Sky Market:** floating merchant ships visit at random.
- Barter for parts, rare relics, maps, and forbidden charms.
- Prices shift with supply, faction reputation, and player-to-player trade.
- Some merchants are not what they seem.

### 8. Respawning
- Fallen crew **respawn at the ship''s Heart Chamber**.
- Each respawn brings back **altered memories, scars, or new traits**.
- Too many deaths make a crew member "Hollow", and they turn against you.
- Respawn costs scale with the ship''s corruption level.

---

## Progression
| Layer | Description |
|---|---|
| Short-term | Nightly survival, scavenging, upgrades |
| Mid-term | Faction quests, crew arcs, ship expansion |
| Long-term | Prestige "Rebirth" runs, unlocking new lore and endings |

## Endings
- **Ascend:** merge with the ship''s heart and become its new captain.
- **Crash:** destroy the ship to free the dead.
- **Escape:** reach a rumored land and leave the crew behind.
- **Hollow:** give in and join the fog.

---

## Tone & Art
- **Visuals:** rusted brass, tattered sails, lantern light, thick fog, stylized 2D with dark watercolor textures.
- **Audio:** creaking wood, distant bells, muffled singing from the fog, a haunting orchestral score.
- **Feel:** cozy by day, dread by night.

## Hook
> *"By day you keep them alive. By night, you learn who was already dead."*', 'auto battler, horror, idle', 'rpg, party game, life sim, pvp, story rich', 'rtx 4080 or better; your pc will hum a lullaby', '1983-03-04 09:00:00+00'),
('Scramble Ghost', 26.73, '# Tokyo Crossing

*A life-sim kinetic novel where you live inside the city''s busiest intersection.*

## Overview
- **World:** Shibuya-style scramble crossing, Tokyo, stretched into a side-scrolling city of streets, rooftops, subway tunnels and neon alleys.
- **Genres:** Life simulation, simulation, kinetic novel
- **Tags:** Real-time, soulslike, exploration, side scroller
- **Mechanics:** Reputation, possession

## Premise
You are a nameless spirit that woke up on the crossing at 3:07 a.m., with no body and no memory. The scramble light turns green every 90 seconds. Thousands of people cross, and each one carries a life you can step into. You have 30 days to find out who you were before the crossing "resets" and erases you.

## Story Structure (Kinetic Novel)
The plot is linear, with no branching text choices. You steer the story through how you live, not through dialogue menus.

1. **Prologue: Green Light.** You wake, learn to drift, and take over your first body: a tired salaryman.
2. **Act I: Borrowed Lives.** You learn the rhythms of the city and meet recurring people: a ramen cook, a street musician, a night-shift nurse.
3. **Act II: Echoes.** Fragments of your past life surface through the people you possess. Each fragment recolors earlier scenes.
4. **Act III: The Last Red Light.** A guardian spirit blocks the truth. The final choice is to move on, stay, or take a body for good.
5. **Epilogue.** One of several fixed endings plays, shaped by your reputation.

## Gameplay

### Side-Scrolling Exploration
- Move left and right through connected 2D districts: crossing, station, arcade street, rooftops, drainage tunnels.
- Hidden paths, vertical shafts and time-locked shortcuts. Some areas open only at certain hours.
- Collect memory shards, city legends and small gifts.

### Real-Time Life Simulation
- The city runs on a live 24-hour clock, with about 1 real minute per in-game 10.
- Every host has needs: energy, hunger, stress and money.
- Jobs, meals, commutes and small rituals fill the day. Schedules continue whether or not you are watching.

### Possession
- Enter a person for a limited time. Each one has its own skills, routines, relationships and secrets.
- Examples:
  - **Courier:** fast, can reach high places.
  - **Nurse:** can enter restricted areas and calm crowds.
  - **Yakuza runner:** can pass gates and get information.
- The longer you stay, the more you blend in. Stay too long and the host''s will pushes back.
- Leave a host in a bad spot and they must deal with the fallout later.

### Reputation
- Every action shifts how the city sees you, through your hosts'' faces.
- **Tracks:** Locals, Night Crowd, Authorities, Spirits.
- High reputation opens doors, shops and story scenes. Low reputation brings suspicion, closed paths and hostile encounters.
- Reputation follows the host, but rumors follow you.

### Soulslike Challenge
- Dangerous zones such as tunnels, rooftops and the late-night crossing hold spirit enemies and rival possessors.
- Combat is deliberate: stamina, dodge, parry and heavy commitment.
- **Death:** you lose your host and drop back to the crossing. Your collected shards stay behind as a "lost echo" you must recover.
- Bosses are city legends, for example the Salaryman Who Never Went Home and the Crowd Wraith.
- Checkpoints are vending machines and shrines.

## Tone and Visuals
- Rain-slick neon, quiet melancholy, small human warmth.
- Pixel or hand-painted 2D with layered parallax.
- Ambient lo-fi and city noise. The crossing''s beat rises and falls with the crowd.

## Core Loop
1. Observe the crowd and pick a host.
2. Live their day and explore the city.
3. Build reputation and gather memory shards.
4. Survive dangerous zones.
5. Unlock story fragments and move closer to the truth.

## Themes
Identity, anonymity in crowds, borrowed lives, and what we leave behind.', 'life simulation, simulation, kinetic novel', 'real-time, soulslike, exploration, side scroller', 'high-end gpu, 32 gb ram, and a good cooling plan', '1996-08-28 09:00:00+00'),
('Ringwarden: Hollow Choir', 25.83, '# Orbital Bastion

*A pixel-art MMORPG-strategy-platformer set on a living space station.*

## Overview
- **World:** Halo Station "Kepler Ring", a huge orbital habitat that hosts thousands of players at once
- **Genres:** MMORPG, Strategy, Platformer
- **Style:** Stylized cartoon pixel graphics with bright colors and bold outlines
- **Tone:** Action-packed and playful, with some heroic moments
- **Modes:** Online persistent hub, split-screen co-op and versus

## Story

### Act 1: The Drift
The Kepler Ring has drifted off course after a mysterious signal. Its AI caretaker, **MOTHBALL**, is damaged and can no longer defend the station. You wake up as a freshly thawed **Ring Warden**, one of thousands of rookies pulled from cryo-sleep to help.

### Act 2: The Swarm
The signal came from **the Hollow Choir**, a swarm of cartoonish but dangerous alien machines. They hit the ring in waves and try to pull its modules apart. Wardens must build defenses, repair the hull, and protect civilians.

### Act 3: The Signal''s Source
Guilds push through the outer decks and into the void. They find that the Choir is not attacking. It is trying to *call the station home*. Players must choose: **fight, negotiate, or hijack the signal**. The choice changes the shared server world.

## Core Gameplay

### 1. Platforming (Action)
- Run, dash, wall-jump, and use zero-gravity flips through station corridors, cargo bays, and hull exteriors.
- Gravity zones flip the level. Floors become walls, and airlocks launch you into open space.
- Combat is fast and skill-based. Use a grapple-wrench, a pulse blaster, and a shield-jump.

### 2. Tower Defense (Strategy)
- Every sector of the ring is a **defense lane** with build slots.
- Place turrets, tesla coils, drone bays, and repair beacons.
- Power, heat, and oxygen are limited, so you must manage them.
- Switch between **building** (top-down view) and **fighting** (platformer view) in real time.
- Wave types include:
  - **Chirpers:** fast, weak scouts
  - **Brutes:** armored breachers
  - **Sirens:** disable towers with sound
  - **Leviathan Bosses:** huge multi-deck threats

### 3. Arcade Scoring
- Chain kills, perfect dodges, and no-damage repairs to build a **combo multiplier**.
- Each wave ends with a score screen and letter rank (S to D).
- Weekly leaderboards for solo players, squads, and guilds.
- Score turns into **Credits** and cosmetic rewards.

## MMORPG Systems

### Persistent Hub: "The Concourse"
- A shared plaza with shops, quest boards, and player-built stalls.
- Players form **Crews** (guilds) that claim and upgrade whole ring sectors.

### Classes
| Class | Role | Signature |
|---|---|---|
| **Engineer** | Builder | Faster building, stronger towers |
| **Vanguard** | Tank | Shield slam, hull anchor |
| **Skirmisher** | Mobility | Double dash, grapple chain |
| **Medic-Tech** | Support | Heal drones, oxygen bubbles |

### Progression
- Level up, unlock skill trees, and collect gear.
- Sector control gives Crews perks and events.
- Seasonal events change the station''s layout and story.

## Multiplayer Modes
- **Split-Screen Co-op:** Up to 4 players on one screen. One player can build while the others fight, or everyone can swap roles.
- **Split-Screen Versus:** Two teams race to clear waves, and each team''s defeated enemies are sent to the other side.
- **Online Raids:** 16-player Crew raids against Leviathan bosses.

## Visual and Audio Style
- **Graphics:** Chunky pixel art, squash-and-stretch animation, and colorful neon lighting.
- **Characters:** Round, expressive cartoon designs with customizable suits and helmets.
- **Audio:** Chiptune synth music that gets faster as waves intensify, with a cheerful MOTHBALL voice.

## Player Fantasy
> *"I''m a small hero on a huge station. I build, jump, and shoot with my friends to save my new home."*

## Hook
Easy to pick up and hard to master. It combines tower-defense planning, platforming skill, and arcade score-chasing in one shared, evolving world.', 'mmorpg, strategy, platformer', 'stylized, pixel graphics, cartoon, action, split screen', 'office pc from the back of the warehouse', '1990-01-12 09:00:00+00'),
('Oracle Drift', 15.24, '# Jupiter Dock: Elemental Drift

## Overview
A top-down adventure and action game with interactive fiction. It is set on a huge dock station in Jupiter''s orbit. The tone is relaxing, with light PvP duels and trivia challenges.

---

## Story

### Prologue: Arrival
You are a newly hired **Dockhand**. Your shuttle drifts into *Callisto Ring Dock*, a rotating harbor. Cargo haulers, science barges and pilgrim ships wait there under Jupiter''s storms. A calm station AI, **HALO**, greets you. It offers you a bunk, a toolkit and a job: keep the dock running.

### Act I: The Quiet Shift
You spend your days on relaxed errands:
- Deliver crates between modules.
- Repair fuel lines.
- Chat with travelers in the *Lantern Cafe*.

Every conversation is interactive fiction. You choose the dialogue, and the choices shape your reputation and unlock side stories.

### Act II: The Elemental Anomaly
Jupiter''s magnetosphere starts leaking strange energy into the dock. It manifests as four **elemental fields**: Fire, Ice, Storm and Toxic. Rogue drones and creatures now roam the corridors, each one attuned to a field. The dock council offers you an **Elemental Gauntlet**, a wrist device that can switch between these attunements.

### Act III: The Core Question
The source of the leak is the **Oracle Core**. It is an ancient quiz-machine buried under the dock. It speaks only to those who answer its questions. Each level you clear opens a deeper chamber and reveals more of the station''s history. Other Dockhands race you there, so you have to duel them for access.

### Epilogue
You can stabilize the Core, harness it, or leave it be. Each choice gives a different ending for the dock and its people.

---

## Gameplay

### Perspective and Pace
- **Top-down** view of the station''s modules.
- A **relaxing** rhythm with no hard fail states. Defeat only sends you back to the nearest dock bay.

### Core Loops
| Loop | Description |
|------|-------------|
| Explore | Roam corridors, hangars and observation decks |
| Action | Fight elemental drones with the Gauntlet |
| Story | Choose dialogue and shape the plot |
| Trivia | Answer questions to open doors, earn rewards and win duels |
| PvP | Duel other players in arenas |

---

## Mechanics

### Elemental Weaknesses
The cycle works like this:

```
Fire  -> beats Ice
Ice   -> beats Storm
Storm -> beats Toxic
Toxic -> beats Fire
```

- Switch attunement to exploit an enemy''s weakness.
- The same rules apply in PvP, so you have to read your opponent''s element.
- Environmental hazards such as steam vents, frozen pipes and static grids react to the elements too.

### Experience Points (XP)
- You earn XP from fights, trivia, deliveries and story choices.
- Levels unlock:
  - New Gauntlet upgrades
  - Dock modules and cosmetics
  - Harder trivia tiers

---

## Trivia System
- Questions cover space, science, history and dock lore.
- Trivia is used in three ways:
  - **Puzzle doors** that need a correct answer.
  - **Duel rounds**, where a correct answer boosts your attack.
  - **Cafe quiz nights**, which are casual and give bonus XP.
- Wrong answers only cost you time or a small buff. They never end the game.

---

## PvP
- **Element Duels:** 1v1 top-down arena fights built around weaknesses.
- **Trivia Showdowns:** Players race to answer questions, and correct answers hit the opponent.
- **Ranked Tides:** Seasonal ladders that reward XP and cosmetics.
- Matches are short and friendly, with an emphasis on fun over grinding.

---

## Atmosphere
- **Visuals:** Warm lights inside the dock and Jupiter''s swirling bands outside the windows.
- **Audio:** Ambient synth music, soft station hums and radio chatter.
- **Mood:** Cozy and wondrous, with a little tension when the elements flare.

---

## Tagline
*"Answer the storm. Master the elements. Keep the dock alive."*', 'adventure, interactive fiction, action', 'top-down, relaxing, pvp, trivia', 'gtx 1060, 8 gb ram, ssd recommended', '2001-07-05 09:00:00+00'),
('Hollow Hang', 10.16, '# Upside-Down Grove
*A visual novel / monster taming / clicker life sim*

## Premise
You wake up hanging from the roots of a forest where the sky is soil and the ground is a starless void. You''re stuck there. Gravity pulls toward the canopy, and the trees grow downward from a floating earth ceiling. To survive, you must befriend the creatures that live here and build a home. You must also keep your mind intact.

## World: The Inverted Forest
- **The Canopy Floor:** Leaves and moss cover the "ground" above you. This is where the safe camps are.
- **The Rootspires:** Giant roots hang like stalactites. They are your paths, your farmland and your danger zones.
- **The Void Below (Above?):** An endless drop where rain falls upward. Something watches from it.
- **Day/Night:** The sun rises from underground and lights the forest from below. Shadows fall upward.

## Story Structure
1. **Act I: The Fall.** You meet Moss, a gentle sprout-fox who teaches you the rules of the forest. You build a basic shelter.
2. **Act II: The Bonds.** Your companions'' personal stories unfold through visual novel scenes. Choices shape their loyalty and their fate.
3. **Act III: The Whispering Depth.** The void starts speaking. You learn the forest is a memory of a collapsed world, and you are its last dreamer.
4. **Act IV: Endings.** You can:
   - Anchor yourself and stay as the forest''s guardian.
   - Reverse gravity and return home, at the cost of your companions.
   - Merge with the void and become the forest.

## Core Gameplay Loops

### 1. Clicker: Harvesting
- Tap glowing sap nodes, fruit and spore clusters to gather **Sap**, **Fiber** and **Dew**.
- Passive income comes from tamed monsters working in the grove.
- Upgrades include auto-tappers, root drills and dew collectors.
- Prestige: **Re-Rooting** resets your camp for permanent bonuses and new story branches.

### 2. Monster Taming
- Lure creatures with food, songs and trust-building minigames.
- **Species examples:**
  | Monster | Role | Trait |
  |---|---|---|
  | Sprout-fox | Scout | Finds hidden nodes |
  | Batmoth | Farmer | Pollinates hanging crops |
  | Rootling | Builder | Reinforces shelter |
  | Gloomcap | Support | Restores sanity, drains sap |
- Each monster has moods, likes, dislikes and a short story arc.

### 3. Life Sim & Management
- Assign monsters to jobs: gathering, crafting, guarding, cooking.
- Expand your treehouse: kitchen, nursery, shrine, workshop.
- Survive with stats for hunger, warmth and energy.
- Weather events such as upward rainstorms, spore winds and void tremors force you to plan ahead.

### 4. Visual Novel Scenes
- Daily events give you dialogue choices with companions and forest spirits.
- Choices affect affection, sanity and available endings.
- Branching routes unlock unique monster forms and story CGs.

## Mechanics

### Sanity Meter
- Falls in darkness, from watching the void, from a monster''s death and from isolation.
- Rises through rest, meals, companionship and rituals.
- **Thresholds:**
  - **High (70-100%):** Clear visuals and better yields.
  - **Medium (30-69%):** Whispers appear, and the UI shifts and tilts.
  - **Low (0-29%):** Hallucinated nodes, unreliable dialogue and hostile monsters. Below 10%, you risk a forced "Fall" event.

### Reloading
- **Tool reloading:** Your Sap Slingshot and Dew Lantern need refills. Tapping stops if they run dry, so ammo management is part of the clicker loop.
- **Taming tools:** Lure charms and calming seeds have limited charges and must be reloaded at the workshop.
- **Story reload:** Once per chapter you can **Rewind a Memory**. This reloads a scene at the cost of some sanity, and the void remembers what you changed.

## Progression Summary
| Stage | Focus | Unlocks |
|---|---|---|
| Early | Tapping, first tames | Shelter, basic jobs |
| Mid | Management, story routes | Advanced monsters, rituals |
| Late | Sanity vs. power | Void zones, true endings |
| Post | Re-Rooting | New Game+ with altered gravity |

## Tone & Style
A cozy but eerie mood. Soft hand-painted art is flipped upside down, with a calm soundtrack that distorts as sanity drops. The game is about small comforts in a strange place, and about what you''re willing to lose to get home.', 'visual novel, monster taming, clicker', 'life sim, survival, management', '2 gb ram and good vibes', '2013-10-31 09:00:00+00'),
('Token Flicker', 21.30, '# Neon Arcade: Last Token

## Overview
A casual, turn-based **fighting / text adventure / life sim** set inside a living neon arcade. You play a rookie player who inherits a dusty cabinet and must build a life, a deck, and a reputation among the arcade''s colorful residents.

## World
The **Neon Arcade** is a glowing, endless building of cabinets, prize counters, and hidden back rooms. Each cabinet is a district with its own element and culture. The arcade''s power comes from **tokens**, and someone is draining them.

## Story Structure

### Act I: Insert Coin
- You wake up as the new owner of Cabinet #0, a broken machine.
- The old owner, Pops, left a note: *"Keep the lights on."*
- You meet your first rival, **Pixel Kid**, and your first mentor, **Madam Joystick**.
- Tutorial fight: learn cards, elements, and turns.

### Act II: Daily Grind
Each in-game day has phases:
1. **Morning:** Choose an activity (work the prize counter, train, socialize, explore).
2. **Afternoon:** Text-adventure events and dialogue choices.
3. **Night:** Tournament fights and secret duels.

Life sim stats: **Energy, Cash, Fame, Bonds.** They shape which events and fights unlock.

### Act III: Power Drain
- Cabinets go dark one by one.
- The culprit is a mystery with several possible suspects.
- Your alliances decide who stands with you at the finale.

## Gameplay

### Turn-Based Fighting
- Duels are one-on-one with a 3-card hand and 3 energy per turn.
- Play attack, defense, and combo cards, then end your turn.
- Fights are short and casual. Losing costs tokens and some pride, but never ends the game.

### Deck Building
- Start with 15 basic cards.
- Earn new cards from wins, shops, quests, and friendships.
- Decks hold 20 cards. Synergies reward themed builds.

### Elemental Weaknesses
| Element | Beats | Loses To |
|---|---|---|
| Neon (light) | Shadow | Static |
| Static (electric) | Neon | Bass |
| Bass (sound) | Static | Glitch |
| Glitch (chaos) | Bass | Shadow |
| Shadow (dark) | Glitch | Neon |

Opponents show their element before the fight, so you can adapt your deck.

## Key Characters
- **Madam Joystick:** Mentor. Strict but kind. Plays Static.
- **Pixel Kid:** Rival turned friend or enemy. Plays Glitch.
- **DJ Subwoofer:** Party king and club owner. Plays Bass.
- **Vex:** Silent collector of lost tokens. Plays Shadow.
- **Lumi:** Cheerful prize-counter clerk. Plays Neon.

## Multiple Endings
Endings depend on your bonds, fame, and choices:
1. **Grand Reboot:** Save the arcade with all allies.
2. **Solo Champion:** Win every duel, lose your friendships.
3. **Shadow Deal:** Side with Vex and take over the arcade.
4. **Quiet Shutdown:** Let the lights go out peacefully.
5. **Glitch Ending:** Break the game''s rules (a secret route).

## Tone and Style
- Cozy and playful, with synthwave music and pixel-art visuals.
- Short sessions, no permanent failure, and lots of replay value.', 'fighting, text adventure, life simulation', 'casual, turn-based strategy, multiple endings', '2 gb ram and good vibes', '1987-02-19 09:00:00+00'),
('Lost & Scramble', 28.24, '# Tokyo Crossing: Shibuya Shuffle

## Logline
Two friends share a tiny Tokyo apartment. They build a deck of "vibe cards" and explore a Shibuya Crossing that keeps changing. They hunt for hidden objects in a comedic, text-only adventure.

## Overview
| Field | Details |
|---|---|
| World | Tokyo crossing (Shibuya Scramble) |
| Genres | Deckbuilder, Metroidvania, Hidden Object |
| Tags | Text-based, local co-op, comedy |
| Mechanics | Player housing, elemental weaknesses |
| Players | 2 (shared keyboard or hot-seat) |

## Story
The Great Scramble is a mysterious event. Every night at 3:03 AM the crossing "resets", and the city''s lost things scatter into hidden corners. Lost umbrellas, lonely gloves and forgotten dreams turn into quirky spirits called **Wasuremono** (the Forgotten).

You are **Kenji** and **Mika**, two broke roommates. Your landlord, a talking maneki-neko named **Mr. Whiskers**, gives you a deal. Recover enough lost items and he will forgive your rent. Fail, and you are evicted to a capsule hotel.

## Core Loop
1. **Wake up** in your apartment (the hub).
2. **Pick a district** of the crossing.
3. **Search** text scenes for hidden objects.
4. **Fight** Wasuremono in card duels.
5. **Return home** to decorate, craft and upgrade.
6. **Unlock** new abilities that open old areas.

## Gameplay Systems

### Deckbuilder: Vibe Cards
- Each player has a personal deck, and the two decks combine in shared fights.
- Card types: **Attack** (Sass, Stare), **Defend** (Umbrella, Ignore), **Utility** (Snack, Selfie).
- Draw 5 cards per turn and spend **Energy** to play them.
- Co-op combos: Kenji''s *Hype* plus Mika''s *Cringe* makes *Karaoke Blast*.
- New cards come from fights, shops and found objects.

### Elemental Weaknesses
Elements follow city life:

| Element | Beats | Loses To |
|---|---|---|
| Neon (light) | Shadow | Rain |
| Rain (water) | Neon | Steam |
| Steam (ramen heat) | Rain | Wind |
| Wind (train gust) | Steam | Shadow |
| Shadow (alley) | Wind | Neon |

Enemies show their element with an ASCII tag. The party must mix decks to cover every weakness.

### Metroidvania: The Shifting Crossing
The map is a grid of text rooms, gated by abilities:
- **Umbrella Glide** crosses rain-flooded gaps.
- **Suica Card** opens ticket gates.
- **Sunglasses of Neon** reveals hidden paths.
- **Ramen Breath** melts frozen shutters.
- **Duo Lift** needs both players (a co-op boost to high ledges).

Districts: Hachiko Plaza, Center Gai, the Underground Maze, Rooftop Billboards, the 109 Tower.

### Hidden Object
- Each scene has a text description packed with clues.
- Type `look`, `search` or `examine` to find items.
- Example: *"The vending machine hums. A red glove peeks from under the bench, and a coin glints near the drain."*
- Player 1 reads clues and Player 2 searches, which adds communication comedy.
- Found items feed quests, crafting and card unlocks.

### Player Housing: Apartment 4B
- A tiny room that grows with upgrades.
- Furniture gives buffs: a **kotatsu** heals, a **shelf** stores trophies, a **ramen station** boosts Steam.
- Each Wasuremono you befriend can move in as a quirky roommate with a passive bonus.
- Decor themes give elemental resistance.

## Comedy Style
- Deadpan narration and absurd Tokyo tropes: salarymen who won''t stop bowing, a vending machine cult, pigeons that run a black market.
- Enemies include the *Sad Umbrella*, *Lost Left Glove* and *Overdue Library Book*.
- Mr. Whiskers sends passive-aggressive rent reminders.

## Co-op Design
- Turn-based and shared-screen, with a text prompt showing whose turn it is.
- Split inventories, shared quests.
- Co-op-only interactions, such as one player distracting a guard while the other sneaks past.
- Friendly-fire jokes: hitting your partner with a snack.

## Progression and Ending
1. **Act 1:** learn the basics and clear Hachiko Plaza.
2. **Act 2:** explore Center Gai and the Underground, and get the key abilities.
3. **Act 3:** climb the rooftops and confront the **Great Scramble**, a giant swirling mass of lost things.
4. **Endings:** either return the lost items to their owners (a heartwarming ending) or keep them (a chaotic ending). In both, Mr. Whiskers forgives the rent, mostly.

## Sample Text Snippet
```
> examine bench
Under the bench you find: a lonely glove (Wasuremono: Left Glove).
It looks at you sadly.

[Battle Start] Left Glove (Element: Rain)
Your hand: Sass, Umbrella, Snack, Karaoke Blast, Stare
> play Karaoke Blast
Critical hit! The glove weeps happy tears.
```', 'deck builder, metroidvania, hidden object', 'text-based, local co-op, comedy', 'potato pc, no gpu needed', '1999-03-02 09:00:00+00'),
('Rootlight Rebloom', 27.91, '# Neon Bloom Arena

## Overview
**Neon Bloom Arena** is a third-person VR hybrid. It mixes farming, romance, and turn-based tactics. You play a rookie "Gardener" in **Verdant Grid**, a virtual reality arena where crops feed both your team and your heart.

- **Genres:** dating sim, clicker, turn-based strategy
- **Perspective:** third-person
- **Core loop:** click-harvest, then befriend, then battle, then reinvest

---

## Story

### Act I - Boot Sequence
You log into Verdant Grid to escape a dull life. The arena was once a gladiator league. Now it is a dying digital greenhouse. The system core, **MOTHER-ROOT**, is failing. Only Gardeners can revive it by growing "data crops".

### Act II - Roots and Rivals
You meet four companions. Each one leads a faction in the seasonal **Bloom Tournaments**. Your crops fuel their weapons. Their trust unlocks new powers.

### Act III - The Final Harvest
A corrupted faction, the **Blight Choir**, tries to delete the arena. You choose who stands beside you. You also choose what the arena becomes.

---

## Characters (Romance Options)

| Name | Role | Personality | Faction Bonus |
|---|---|---|---|
| **Sage** | Sniper medic | Calm, poetic | Healing crops |
| **Rook** | Tank commander | Gruff, loyal | Armor upgrades |
| **Pixie-9** | Rogue hacker | Playful, chaotic | Extra turn chances |
| **Elder Fern** | Ancient AI | Wise, mysterious | Rare seeds |

---

## Core Gameplay

### 1. Farming (Clicker Layer)
- Click plots to plant and harvest **data crops**.
- Idle growth continues between battles.
- Upgrades add auto-clickers, drones, and soil boosts.
- Crop types give different resources: *Energy*, *Ammo*, *Affection Gifts*.

### 2. Dating Sim Layer
- Spend time and gifts on companions.
- Dialogue choices raise **Bond Level**.
- Bond unlocks story scenes, passive buffs, and combo attacks.
- Jealousy and loyalty systems affect team morale.

### 3. Turn-Based Strategy Layer
- Grid-based battles seen from a third-person tactical camera.
- Each unit gets Move, Attack, and Skill actions per turn.
- Use terrain, crop barriers, and companion synergy.
- Crops can be turned into traps, healing zones, or ammo.

---

## Key Mechanics

### Instanced Zones
- Each battle or farm runs in its own **instance**.
- Zone types:
  - **Greenhouse Plots:** safe farming and dates
  - **Skirmish Fields:** tactical battles
  - **Blight Rifts:** hard, high-reward challenges
- Zone modifiers change each cycle, such as low gravity, storms, or overgrowth.

### Weapon Attachments
- Modular weapons: *Vine Rifle, Pulse Shears, Thorn Launcher*.
- Attachment slots: **Barrel, Scope, Core, Grip**.
- Crops act as crafting inputs, so a Rose Core gives a charm-stun effect.
- Companions can craft signature attachments at high Bond.

---

## Progression
1. **Farm** to earn resources.
2. **Date** to raise Bond and unlock buffs.
3. **Battle** to earn zone rewards.
4. **Upgrade** the farm, weapons, and skill trees.

---

## Multiple Endings

| Ending | Condition |
|---|---|
| **Eternal Bloom** | Max Bond with one companion and a restored core |
| **Harmony Garden** | Balanced Bond with all companions |
| **Iron Harvest** | Military focus, crops used only as weapons |
| **Blight Reborn** | Side with the Blight Choir |
| **Log Out** | Abandon the arena and return to the real world |

---

## Tone and Style
- **Art:** neon-lit pastel cyber-garden
- **Music:** soft synthwave that turns intense in battle
- **Mood:** cozy, romantic, and tense in turns

---

## Hook
*"Grow the arena. Win their hearts. Decide what blooms."*', 'dating sim, clicker, turn-based strategy', 'farming, multiple endings, farming, third-person, turn-based strategy', 'quad-core cpu, 16 gb ram, mid-range gpu', '1985-09-09 09:00:00+00'),
('Glitch Coin', 7.67, '# Neon Overdrive: The Last Cabinet

## Overview
A retro-styled hybrid of **FPS**, **idle**, and **text adventure** set in a living neon arcade. You inherit a failing arcade, keep it running, and fight the glitch-entities that spawn from its cabinets. Full **controller support**.

## World: The Neon Arcade
- Buzzing cabinets, flickering signs, synth soundtrack, CRT scanlines.
- Each cabinet is a portal to a pixelated realm.
- The arcade is alive. Its mood, cleanliness, and power grid change with your choices.

## Story
### Act 1: The Inheritance
Your uncle vanishes and leaves you the keys to *Neon Overdrive*. A note reads: *"Keep the lights on. Don''t let the machines win."*

### Act 2: The Glitch
Cabinets start to corrupt. Rogue code, called **Glitches**, leaks into the arcade. You must clear them out and keep the business alive.

### Act 3: The Last Cabinet
A hidden final cabinet holds your uncle''s consciousness and the source of the corruption. You have to choose whether to free it, delete it, or merge with it.

## Gameplay Loops

### 1. Life Sim (Arcade Management)
- Hire staff, repair machines, stock snacks, and decorate.
- Manage **power, cash, and customer happiness**.
- Build relationships with regulars, who unlock quests and upgrades.

### 2. Idle (Passive Growth)
- Cabinets earn tokens while you are away.
- Upgrade machines, automate cleaning, and unlock prestige "Reboots".
- Idle income funds your weapons and repairs.

### 3. FPS (Cabinet Raids)
- Enter a cabinet to fight through short, retro-styled shooter levels.
- Weapons include the pixel pistol, arcade scattergun, and plasma joystick.
- Rewards are rare parts, tokens, and lore data.

### 4. Text Adventure (Story Layer)
- Terminal-style dialogue with regulars, staff, and the arcade AI.
- Investigate clues by typing or picking commands.
- Choices affect endings, relationships, and unlocked areas.

## Core Mechanics

### Timed Choices
- Key decisions come with a countdown, for example *"The power is failing! Save the fridge or the fuse box?"*
- Silence counts as a choice too.
- Results carry over into the idle and life-sim layers.

### Boss Phases
Each boss is a corrupted cabinet with 3 or more phases:

| Phase | Style | Example |
|-------|-------|---------|
| 1 | Pattern shooter | Dodge bullet grids |
| 2 | Environment shift | The arena rewrites its own rules |
| 3 | Text duel | A timed dialogue choice decides the finishing blow |

**Sample boss: "Pac-Wraith"**
1. Chases you through a maze.
2. Splits into ghost clones.
3. Asks you a timed riddle. A wrong answer restarts the phase.

## Progression
- **Short term:** repair machines, clear raids.
- **Mid term:** expand the arcade, unlock new cabinet realms.
- **Long term:** prestige Reboots, and the three endings (Free, Delete, Merge).

## Controls and Accessibility
- Full controller support, with a mouse and keyboard option.
- Adjustable timers for choices.
- Colorblind-safe neon palettes.

## Tone and Style
- Nostalgic, playful, and slightly eerie.
- 8/16-bit visuals mixed with neon lighting.
- Synthwave soundtrack that changes with the arcade''s mood.

## Tagline
*"Insert coin. Save the lights. Face the glitch."*', 'fps, idle, text adventure', 'controller support, life sim, retro', 'rtx 4070, 32 gb ram, nvme ssd', '1985-12-22 09:00:00+00'),
('Saltwhisper', 2.18, '# Cutlass & Courtship: Tides of the Hidden Cove

## Overview
A stylized pirate-cove adventure. You run a smuggler haven, race rival crews across the sea, and romance a cast of sea-worn rogues. Your heart and your harbor both need steering.

- **World:** Pirate cove
- **Genres:** Dating sim, strategy, adventure
- **Tags:** Stylized, adventure, management, racing
- **Core mechanics:** Invincibility frames, dodge and evasion

---

## Story

### Act I: Washed Ashore
You are a disgraced navigator. You wake on the sands of **Saltwhisper Cove**, a hidden harbor that maps don''t show. The old captain is gone, and the cove''s rickety docks, tavern, and shipyard are falling apart. The locals name you **Harbor Warden**, mostly because nobody else wants the job.

### Act II: Rivals and Romance
The **Crimson Armada** wants the cove''s secret channel. Three rival captains circle your waters. As you rebuild, romance gets tangled up with politics. Some of your love interests may be spies, and some rivals may turn out to be allies.

### Act III: The Storm of Choices
A legendary storm, the **Maelstrom Crown**, approaches. You must pick your allies, your partner, and the fate of the cove. It may become a free port, a pirate kingdom, or a legend that vanishes into the mist.

---

## Gameplay Pillars

### 1. Cove Management
- Build and upgrade the **tavern, shipyard, market, lighthouse, and smuggler tunnels**.
- Assign crew to jobs by their skills and moods.
- Balance **gold, supplies, reputation, and notoriety**.
- Random events include raids, festivals, and shortages.

### 2. Strategy Layer
- A sea map with **trade routes, hidden islands, and contested waters**.
- Send fleets on missions, set up ambushes, and negotiate or bribe.
- Every route trades risk against reward.

### 3. Dating Sim
- Five main romanceable characters, each with a **trust and affection meter**.
- Daily time slots: spend the day on chores, training, or getting to know someone.
- Gifts, dialogue choices, and shared missions unlock story scenes.

| Character | Role | Personality |
|---|---|---|
| **Mara Vane** | Quartermaster | Dry-witted, fiercely loyal |
| **Captain Iven Ash** | Rival racer | Charming, reckless |
| **Solenne** | Cove cartographer | Shy, secretive |
| **Brindle** | Ship''s cook | Warm, gossipy, knows everything |
| **Kestrel Dusk** | Crimson spy | Cold, conflicted |

### 4. Racing and Adventure
- Stylized **sea races** through reefs, whirlpools, and cannon-fire lanes.
- Upgrade sails, hulls, and rudders.
- Explore caves, wrecks, and ruins for treasure and story clues.

---

## Core Mechanics

### Dodge and Evasion
- Time your **dodge roll** on deck and your **sharp ship turns** at sea to avoid cannonballs, sea beasts, and obstacles.
- Perfect dodges build a **Momentum** meter, which boosts speed and unlocks special moves.

### Invincibility Frames
- Dodges and dashes give **brief i-frames**.
- Use them to slip through cannon barrages, ram gates, or shockwaves.
- Upgrades change the i-frame window, but each i-frame use costs **stamina**, so mashing is punished.
- Some rivals have attacks built to bait early dodges.

---

## Progression Loop
1. **Morning:** manage the cove and assign crew.
2. **Afternoon:** race, explore, or run missions.
3. **Evening:** romance, dialogue, and events.
4. **Night:** smuggling runs and raids.

Choices carry over between days. Relationships open new upgrades, and the cove''s growth changes the story.

---

## Endings
- **Love Anchored:** settle down with your chosen partner.
- **Free Port:** the cove becomes a neutral haven.
- **Pirate King/Queen:** rule the seas by force.
- **Ghost Harbor:** sacrifice the cove to stop the storm.

---

## Art and Tone
Bold, painterly visuals with exaggerated ships, glowing seas, and expressive character portraits. The tone is playful and romantic, with real stakes. The music is sea shanties mixed with modern beats.', 'dating sim, strategy, adventure', 'stylized, adventure, management, racing', 'high-end gpu, 32 gb ram, and a good cooling plan', '1983-05-12 09:00:00+00'),
('Calderforge', 8.09, '# Ember Reach: Crater Dominion

## Overview
**Ember Reach** is a top-down, persistent online game. Players build a city inside a dormant volcano crater. They run its economy and fight for control of the caldera. It blends a **tycoon** economy, **MMORPG** persistence, and **shooter** action. Its **strategy** layer uses **turn-based combat** and **matchmaking**. The city runs on **idle** mechanics, so it keeps producing while you are offline.

## Story
### Prologue: The Waking Ash
The crater of Mount Vharos has been silent for 900 years. Then a survey team finds a sealed obsidian gate deep in the caldera wall. A hum comes from behind it, and the lava lakes start to pulse in rhythm.

### The Mystery
Players are **Wardens**, colonists sent to claim the crater. They learn that:
- The volcano is not natural. It is a **buried machine** built by a lost civilization, the *Emberborn*.
- Each lava vent is a "heart-node" that feeds the machine.
- Someone or something is waking it deliberately.

### The Central Question
Is the machine a prison, a power source, or a weapon? Each faction gives a different answer, and the truth is revealed through seasonal story chapters.

## Setting: The Crater
The map is a ring-shaped caldera split into zones:

| Zone | Description | Role |
|---|---|---|
| **Cinder Flats** | Ash plains at the crater floor | Starter city sites, farming |
| **Magma Ring** | Rivers of lava | Energy and rare ore |
| **Obsidian Terraces** | Glassy cliffs | Defense, mid-game districts |
| **The Heartspire** | Central vent | Endgame PvP and mystery zone |
| **Rim Wall** | Outer cliffs | Trade routes, outposts |

Eruption events change the terrain, so the layout is never fixed.

## Core Gameplay

### 1. City Builder and Tycoon
- Place districts on a top-down grid: **foundries, geothermal plants, markets, barracks, labs**.
- Turn heat into **Ember Credits** and refine it into **Aether Ore**.
- Manage supply chains, worker morale, and volcanic hazards.
- A player-driven market lets you trade, set prices, and build monopolies.

### 2. Idle Systems
- Districts produce resources offline for up to 24 hours.
- Assign **automation drones** to mine, repair, and patrol.
- Returning players get a **Dispatch Report**: what was made, what was raided, and any new mystery clues.

### 3. Strategy Layer
- Research trees: **Geothermal Engineering, Ash Warfare, Emberborn Archaeology**.
- Form alliances, sign treaties, and claim crater sectors.
- Manage the **Pressure Meter**. Overusing vents raises eruption risk for everyone nearby.

### 4. Turn-Based Combat
- Squad battles run on a tactical grid with action points.
- Units: **Ash Rangers, Magma Golems, Slag Engineers, Relic Hunters**.
- Terrain matters: lava tiles, cover from obsidian, and eruption timers that change the field mid-battle.
- Battles can be auto-resolved for idle play, or played manually for bonuses.

### 5. Shooter Mode
- Real-time, top-down twin-stick **expeditions** into ruins and the Heartspire.
- Solo or co-op runs that fight mutated cinder-beasts and Emberborn sentinels.
- Rewards: relics, blueprints, and story fragments.

### 6. MMORPG Layer
- Persistent shared world with guilds of up to 100 Wardens.
- Character classes: **Pyromancer Engineer, Sharpshooter, Warden Commander, Relic Scholar**.
- Weekly world bosses, seasonal events, and guild-owned fortresses.

## Matchmaking
- **Ranked Skirmishes**: turn-based 1v1 and 2v2 by skill rating.
- **Co-op Expeditions**: groups matched by role (tank, support, damage).
- **Sector Wars**: guilds are matched by city power and territory size for weekly sieges.
- Newcomers get a protection period and are matched against similar players.

## Factions
1. **The Forgeborn**: industrialists who see the volcano as power.
2. **The Ashen Order**: mystics who believe the machine should stay asleep.
3. **The Cartographers**: neutral explorers who trade in secrets.
4. **The Awakened**: a hidden faction that may be controlling the eruptions.

## Progression Loop
1. Build and expand your city.
2. Gather resources, including idle income.
3. Research and train squads.
4. Run expeditions for relics.
5. Fight in ranked and guild battles.
6. Unlock story clues, then repeat with bigger stakes.

## Endgame and Seasons
- **Seasons** end with a Great Eruption that reshapes the map and resets territory control.
- Players who uncover enough clues can open the **Obsidian Gate** and choose the crater''s fate (*Harness*, *Seal*, or *Unleash*). That choice shapes the next season''s world.

## Tone and Visuals
- **Art:** glowing lava against dark basalt, stylized top-down 2D/2.5D.
- **Mood:** tense, mysterious, industrial-mythic.
- **Audio:** deep rumbles, metallic percussion, eerie choral ambience.

## Tagline
*"Build on fire. Uncover what sleeps beneath."*', 'shooter, mmorpg, tycoon', 'mystery, city builder, top-down, idle, strategy', 'decent gaming laptop, charger plugged in', '2019-11-03 09:00:00+00'),
('Ashen Petal', 29.52, '# Blossom & Blade: Chronicles of the Ninth Dojo

## Overview
A massively multiplayer, open-world otome action RPG set in a sprawling feudal realm. It is built around rival samurai dojos. You play a fledgling swordsman or swordswoman. You forge bonds with charismatic dojo masters and rivals, and you fight through brutal soulslike duels. Death is not the end, and each fall reshapes the world.

**Genres:** Otome, Open World, Hack and Slash
**Tags:** Soulslike, MMO, Roguelite, Adventure
**Core mechanics:** Alliances, Territory Control

---

## Story

### Prologue: The Fallen Banner
The Ninth Dojo, once the greatest school in the land, was burned in a single night. The Grand Master vanished. His eight elite disciples scattered and founded rival dojos. Each one claims to hold the "true" style.

You wake in the ashes with a broken blade and no memory of the fire. A spirit-fox named **Kitsune-no-Kage** tells you that you are the last heir of the Ninth Dojo.

### Act I: The Wandering Blade
You travel the open realm, from misty mountain temples and cherry-blossom villages to haunted battlefields and neon-lit lantern towns. You train under different masters and learn their styles. Each master has a hidden past tied to the fire.

### Act II: Bonds and Betrayals
Your alliances shape the story. The masters you support can become lovers, rivals or enemies. Loyalties shift, and the regions of the world change with them.

### Act III: The Ashen Truth
You uncover who burned the Ninth Dojo, and the answer depends on the path you took. Endings include a romance ending, a unified-realm ending, a conqueror ending and a tragic ending.

---

## Romanceable Characters (Otome Core)

| Character | Archetype | Dojo Style |
|---|---|---|
| **Kaito Ryuzaki** | Stoic, honor-bound duelist | Iron Mountain (heavy katana) |
| **Renji Asakura** | Playful trickster, sly | Shadow Crane (dual blades) |
| **Sōsuke Mikage** | Gentle healer with a dark secret | Silent Lotus (naginata) |
| **Hisui Tachibana** | Cold, aristocratic rival | Frost Moon (iaijutsu) |
| **Akane Hoshino** | Fierce swordswoman, loyal friend | Crimson Sun (fire-infused) |

Each character has:
- Affection events, dates and story quests
- Personal boss duels that change with your relationship
- Multiple endings tied to trust, rivalry or betrayal

---

## Gameplay

### Soulslike Combat
- Stamina-based, methodical hack and slash
- Parry, dodge, and posture-break systems
- Tough bosses: rogue ronin, demon-possessed masters, mythic yokai
- Weapons and stances tied to dojo styles

### Roguelite Loop
- **Dying** sends you back to the *Spirit Shrine* and changes the map slightly.
- Dungeons such as *Ashen Halls* and *Twilight Bamboo Labyrinth* are procedurally generated.
- Permanent progression comes from **Memory Fragments**, which unlock skills and story scenes.

### Open World Adventure
- Freely explore mountains, villages, forests, and castles
- Dynamic weather and day/night cycles that affect yokai spawns
- Side quests, hidden dojos, festivals, and secret techniques

---

## Massively Multiplayer Features

- **Shared realm:** thousands of players inhabit one persistent world.
- **Co-op duels:** summon allies for boss fights.
- **PvP arenas:** ranked duels and tournaments at the *Festival of Blades*.
- **Player dojos:** create and customize your own dojo with training grounds and gardens.

---

## Core Mechanics

### Alliances
- Players form **Dojo Alliances** with shared goals and buffs.
- Alliances can ally with the master NPCs, who then send their techniques and quests to members.
- Diplomacy, treaties, and betrayals appear in the world log.
- A player''s romance choices can also tie them to a faction.

### Territory Control
- The map is divided into **regions**, such as Iron Peaks, Lotus Valley, and Moonlit Coast.
- Alliances capture regions in weekly **War Seasons**.
- Controlling a region gives:
  - Resource income and rare crafting materials
  - Access to exclusive bosses and dungeons
  - Visual changes: banners, architecture, NPC dialogue
- Losing a region shifts its NPCs'' attitudes toward you.

---

## Art & Tone
- Ukiyo-e-inspired visuals with painterly color
- Atmospheric music with shamisen, taiko and soft piano
- A mix of romantic warmth and dark, melancholic danger

---

## Tagline
> *"Every blade has a story. Every bond has a price."*', 'otome, open world, hack and slash', 'soulslike, massively multiplayer, massively multiplayer, roguelite, adventure', 'rtx 4080 or better; your pc will hum a lullaby', '2015-08-18 09:00:00+00'),
('Lanternfally', 19.20, '# tidewake: the drowned atoll

*a platformer-sandbox-horror for 1-4 players*

## 1. pitch
you wake on a shrinking coral atoll. by day it is a bright, glide-friendly playground. by night the tide rises and something rises with it. build, fish, glide and survive until the next sunrise, alone or with friends.

## 2. story

**act i: washed ashore**
- a supply boat wrecks on the reef. you and up to 3 other castaways crawl onto the sand.
- the atoll is a ring of islets around a black lagoon. old lighthouse ruins stand at the center.
- a radio crackles: *"do not fish after dark."*

**act ii: the tide keepers**
- the fish you catch carry fragments of a lost research crew''s logs.
- the crew woke something in the lagoon, the **Undertow**. it is a mass of drowned coral and lantern-eyed shapes.
- each night it claims more of the atoll, and the islets sink one by one.

**act iii: the lighthouse**
- relight the lighthouse by collecting 5 **tide lenses** from the deep reefs.
- the light drives the Undertow back, but the ending depends on a choice:
  - **escape**: sail away and leave the atoll to drown.
  - **seal**: stay and bind the Undertow. the run ends, and new-game+ starts with a haunted atoll.
  - **feed**: offer it your crew''s catch to keep the tide calm (secret ending).

## 3. world: the coral atoll

| zone | day | night |
|------|-----|-------|
| sunlit shallows | tide pools, easy jumps | drowned, swimmable only with gear |
| palm ridge | tall gliding launch points | wind carries whispers |
| bone reef | coral climbing puzzles | pale creatures patrol |
| the lagoon | fishing hub | Undertow''s home |
| lighthouse ruins | safe-ish base site | final stage |

## 4. gameplay loop

1. **day: explore and gather.** platform across palms, cliffs and reef ledges. glide between islets on kelp-and-sailcloth wings.
2. **dusk: fortify.** finish your base and light the lamps.
3. **night: survive.** shadows crawl from the water. lamps, walls and teamwork keep you alive.
4. **dawn: recover.** repair, cook, upgrade and plan the next run.

## 5. mechanics

### gliding
- hold jump in the air to deploy a glider.
- wind currents and thermals over the atoll extend your flight.
- stamina limits your range, so you can''t just skim the whole map.
- gliding is also the fastest way to flee a night threat.
- gliders are craftable and upgradeable (speed, turning, dive-bomb).

### fishing minigames
- **day fishing:** a relaxed rhythm minigame that gives food, crafting materials and rare cosmetics.
- **night fishing:** a tense tension-bar minigame.
  - you can catch strange relics and lore fragments.
  - a bad reel can attract the Undertow.
- co-op fishing: one player reels while another steadies the line or spots the hazard.

### base building (sandbox)
- build with driftwood, stone, shell and salvaged wreckage.
- modular pieces: platforms, rope bridges, watchtowers, zip-lines, launch pads.
- defenses: lantern lamps, salt barriers, bait traps.
- the tide can flood ground-floor builds, so you build up.

### horror
- the atmosphere is quiet and eerie. you get few jump scares.
- low-light and sound design create tension.
- the Undertow **learns**. it targets the weak points in your base.
- there is no combat XP. you survive with light, terrain and wits.

## 6. modes

- **singleplayer:** a tuned difficulty and a companion crab that helps carry items.
- **online multiplayer (2-4):** shared base, roles (fisher, builder, scout, glider courier).
- **split-screen (local, 2-4):** full co-op on one screen.
- **party mode:** short competitive minigames for up to 4 players, such as glide races, fishing derbies and "last lamp standing" survival rounds.

## 7. progression
- unlock blueprints by fishing relics and finding logs.
- upgrade tools: rods, gliders, lamps, hulls.
- cosmetics: shell charms, hats, glider patterns.
- world state persists between nights. sunken islets stay sunken.

## 8. tone and art
- **day:** saturated turquoise, warm sun and playful animation.
- **night:** deep indigo and bioluminescent green, with distorted sound.
- audio: steel drums by day, muffled bells and whale-like drones by night.

## 9. why it''s fun
- bright, kind platforming set against a creeping dread.
- a base you build to fit your own play style.
- chill fishing with high-stakes spikes.
- it works for a solo horror run or a chaotic couch night.', 'platformer, sandbox, horror', 'multiplayer, singleplayer, party game, base building, split screen', 'rtx 2060 or better, 16 gb ram', '1990-07-20 09:00:00+00'),
('Shardbeat', 5.76, '# Mirror Maze: Shatter Protocol

## Overview
A voxel-styled **roguelike city builder** with rhythm combat and a shooter core. You rebuild a fractured city inside an endless mirror maze. Every run reflects a slightly different version of it.

## World: The Mirror Maze
- A labyrinth of voxel glass corridors, plazas, and reflected skylines.
- Walls are portals. Each reflection shows an alternate version of your city.
- The maze rearranges itself every run, and its rhythm pulses with a hidden beat.

## Story

### Act 1: The Crack
You are a **Cartographer**, the last architect of Prism City. A cataclysm shattered it into a thousand mirror shards. An AI called **The Curator** rules the maze. It quizzes, tricks, and traps anyone who wanders in.

### Act 2: The Reflection War
Your other selves, called **Echoes**, are building rival cities in parallel mirrors. Each Echo is a boss with its own style and its own version of your city. Defeating one lets you claim its districts.

### Act 3: The Final Frame
At the maze''s core is the **Origin Mirror**. You can restore the real city or merge every reflection into one. The ending depends on which districts you built and which Echoes you spared.

## Core Gameplay Loops

### 1. Expedition (Roguelike + Shooter)
- Enter the maze in **third-person** for tactical movement and cover.
- Switch to **first-person** for precision aiming and sniping through reflections.
- Bullets bounce off mirrors, so you can plan ricochet shots.
- Permadeath resets the maze. Meta-progress persists.

### 2. Rhythm Combat
- Enemies attack on the maze''s beat.
- Shots and dodges fired on the beat deal bonus damage and give combo multipliers.
- Each biome has its own soundtrack and tempo.

### 3. Trivia Gates
- Locked mirrors require correct answers to open.
- Questions cover city lore, science, and pop culture.
- Right answers give loot. Wrong answers spawn shard-monsters.

### 4. Hacking Minigames
- Terminals control turrets, doors, and Curator drones.
- Puzzles are pattern-matching or rhythm-synced node hacks.
- Success lets you rewire the maze, for example turning enemy turrets to your side.

### 5. City Builder (Hub)
- Bring back shards and resources to your voxel city.
- Build homes, workshops, radio towers, and gacha shrines.
- Districts give passive buffs. Examples: a **Music Hall** widens the on-beat timing window, and a **Library** gives hints in trivia.
- Your city grows across runs.

### 6. Gacha: The Prism Wheel
- Spend **Shards** to pull new weapons, Echo allies, building blueprints, and beat-modifiers.
- Rarities: Common, Rare, Epic, and **Mythic Reflection**.
- A pity system guarantees a high-rarity drop after a set number of pulls.
- Duplicates upgrade existing items.

## Progression
| System | Reward |
|---|---|
| Runs | Shards, blueprints |
| City | Permanent buffs |
| Gacha | Build variety |
| Echoes | New bosses, allies |

## Visual & Audio Style
- Voxel art with neon reflections and refracted light effects.
- Adaptive electronic soundtrack. Layers change with combat and hacking.

## Example Run
1. Start in the city and equip a gacha-pulled rifle.
2. Enter the maze, exploring in third-person.
3. Solve a trivia gate and hack a turret.
4. Fight an Echo on the beat, using ricochet shots.
5. Die or extract, then spend shards on city upgrades and pulls.

## Tagline
*"Every reflection is a chance to rebuild."*', 'roguelike, city builder, rhythm', 'voxel, trivia, third-person, shooter, first-person', 'rtx 4080 or better; your pc will hum a lullaby', '1991-08-07 09:00:00+00'),
('Reelbound Heights', 27.76, '# Neon Reel Heights

*A drive-in cinema otome city builder where every screening changes history.*

---

## Overview

| Field | Details |
|---|---|
| **Setting** | A drive-in cinema that spans several eras (1950s to a sci-fi future) |
| **Genres** | Otome, city builder, interactive fiction |
| **Tags** | Historical, sci-fi, tower defense, split screen, farming |
| **Core mechanics** | Combo multipliers, drifting |

---

## Premise

You inherit the **Starlight Drive-In**, a crumbling cinema at the edge of a dying town in 1957. The projector is an alien relic. It doesn''t just play films. It **pulls the audience''s dreams into reality**.

Each night''s screening opens a rift in time. The lot fills with cars from different eras, and the people inside them become your guests, your allies, and your love interests.

Your goal is to grow the lot into a thriving **Reel City**. You have to protect it from the **Static**, a swarm of glitch entities that feed on forgotten stories.

---

## Story Structure

### Act I: Opening Night (1957)
- You arrive, repair the screen, and plant the first crops on the back lot.
- You meet the romance candidates.
- The first screening rips open a rift, and the Static attacks for the first time.

### Act II: Double Feature (Across Eras)
- Rifts bring in visitors from the 1920s, 1980s, and 2140.
- Each romance route unlocks a **story reel**, an interactive-fiction chapter set in that character''s era.
- The town grows into a layered city of mixed-era districts.

### Act III: Final Credits
- The Static''s origin is revealed. It is the **Lost Reel**, a film that was never finished.
- Your choices decide the ending: a **romance ending**, a **city ending**, or the **True Ending**, where you rewrite the Lost Reel.

---

## Romance Candidates

| Character | Era | Role | Personality |
|---|---|---|---|
| **Jack Marlowe** | 1957 | Hot-rod racer | Cocky, secretly sentimental |
| **Vivienne Ash** | 1926 | Silent-film projectionist | Elegant, mysterious |
| **Dex Okonkwo** | 1986 | Arcade-generation mechanic | Warm, chatty, loyal |
| **Unit K-9 "Kay"** | 2140 | Retired defense android | Deadpan, learning to feel |

Affection grows through dialogue choices, gifts grown on your farm, and shared **split-screen missions**.

---

## Gameplay Systems

### City Builder
- Place **snack bars, parking rows, screens, workshops, and homes**.
- Districts belong to different eras. Neighboring eras give synergy bonuses.
- Popularity and **Reel Energy** are your two main resources.

### Farming
- Grow **popcorn corn, soda-syrup beets, and time-bloom flowers** on the back lot.
- Crops feed the snack bar, make gifts for romance targets, and fuel defense towers.

### Tower Defense
- The Static attacks in waves during intermission.
- Defenses include **speaker turrets, floodlight beams, and projector lasers**.
- Placement matters, because the paths follow the parking-lot lanes.

### Drifting
- In **Night Patrol** missions, you drive a classic car through the lot.
- Drift around corners to sweep up Static, collect resources, and rescue guests.
- Each love interest has a driving style that gives a different bonus.

### Combo Multipliers
- Chain actions such as **drift, serve, grow, and defend** to build a multiplier.
- High combos boost city income, affection gain, and rare reel drops.
- Breaking the chain resets it, so you have to plan your route.

### Split Screen
- Story missions show **two timelines at once**. One side is you, and the other is your partner in their era.
- Actions on one side affect the other. For example, you plant a seed in 1957 and Dex harvests it in 1986.
- Local co-op is supported, and solo play switches between the two sides.

### Interactive Fiction
- Branching text scenes drive the romance and the main plot.
- Choices carry over into city events, defenses, and endings.

---

## Game Loop

1. **Day:** farm, build, and talk to residents.
2. **Dusk:** choose the night''s feature, which sets the rift era.
3. **Night:** defend the lot and drift on patrol.
4. **Late show:** read a story reel and deepen a romance.
5. **Dawn:** collect rewards, expand the city, and repeat.

---

## Tone and Visuals

- Retro-futurist neon, chrome, and film grain.
- Each era has its own color palette: sepia for the 1920s, pastel for the 1950s, synthwave for the 1980s, and holographic cyan for 2140.
- The soundtrack blends jazz, rockabilly, synth-pop, and ambient electronica.

---

## Endings

- **Individual endings:** four romance endings, one per love interest.
- **Reel City ending:** the city becomes a timeless haven.
- **True Ending:** you finish the Lost Reel and the Static becomes the final audience.', 'otome, city builder, interactive fiction', 'historical, sci-fi, tower defense, split screen, farming', 'high-end gpu, 32 gb ram, and a good cooling plan', '1995-08-27 09:00:00+00'),
('Rime & Reckoning', 10.61, '# Frostbound Arena: The Ice Hotel Championship

## Overview
**Frostbound Arena** is a stylized, cross-platform hybrid of sports, grand strategy, and beat ''em up. It is set in the **Aurora Grand**, a sprawling hotel carved from glacier ice. Every season, rival factions gather there for a tournament shrouded in mystery. Players fight in brawls and manage the hotel''s political landscape. They use a deck of cards to do both.

## Genre Blend
| Genre | Role in Game |
|---|---|
| **Sports** | Ranked brawl matches are played as a tournament with seasons, brackets, and referees. |
| **Grand Strategy** | Players control wings of the hotel, alliances, resources, and rumors between matches. |
| **Beat ''em up** | Matches are fast side-scrolling melee fights on ice rinks, in ballrooms, and in kitchens. |

## Story
### Prologue: The Thaw
The Aurora Grand has stood frozen for a century. Its owner, **Madame Glacia Vane**, vanishes on the eve of the Centennial Championship. She leaves behind a single frozen playing card, the **Ace of Rime**.

### Act I: Check-In
You arrive as an unknown challenger with a starter deck. To earn a room, you must win the qualifying brawls. Each victory unlocks a hotel wing and a new clue.

### Act II: The Cold War
Four factions want control of the hotel:
- **The Bellhop Syndicate** are fast, agile brawlers who control information and logistics.
- **The Chef Brigade** are heavy hitters who control supplies and heat.
- **The Sculptors'' Guild** are defensive, terrain-shaping fighters who control the ice itself.
- **The Concierge Order** are manipulators who control cards, contracts, and secrets.

Players ally with, betray, or bribe these factions. Their choices shift the season''s balance of power.

### Act III: The Melt
As the tournament nears its finale, the hotel begins to melt. Someone is sabotaging the cooling systems. Players must find the culprit before the final match, or the arena will flood. The culprit differs between playthroughs, which keeps the mystery replayable.

## Core Gameplay Loop
1. **Strategy Phase**: Manage wings, staff, budgets, and alliances on the hotel map.
2. **Deck Phase**: Build and upgrade a deck of Move, Terrain, and Intrigue cards.
3. **Brawl Phase**: Fight in a real-time beat ''em up match, playing cards as special moves or environmental effects.
4. **Investigation Phase**: Search rooms, interrogate guests, and piece together clues.
5. **Results**: Earn points, reputation, and cards, then advance the season.

## Card System
- **Move Cards** are special attacks, combos, and counters.
- **Terrain Cards** alter the arena. They can crack the ice, cause slippery floors, or drop chandeliers.
- **Intrigue Cards** are strategic actions. They can spread rumors, sabotage rivals, or open secret passages.
- **Clue Cards** are found through play. Combined, they reveal the truth behind the mystery.

## Mechanics
### Arcade-Style Scoring
- Every hit, combo, and dodge builds a **combo multiplier**.
- Style bonuses reward clean finishes, environmental kills, and card synergies.
- Scores are ranked on **seasonal leaderboards** with arcade-style initials.
- High scores also grant **strategy bonuses**, such as extra budget or influence.

### Matchmaking
- **Skill-based ranked matchmaking** places players in divisions named after hotel floors, from *Lobby* up to the *Penthouse Suite*.
- **Casual queues** allow practice and card testing.
- **Faction matchmaking** pairs players by allegiance for team events.
- **Cross-platform play** lets PC, console, and mobile players compete together, with unified progression.

## Visual & Audio Style
- **Art**: A stylized, hand-painted look with crystalline blues, warm amber lamplight, and bold outlines.
- **Environments**: Ice sculptures, frozen chandeliers, glowing suites, a hockey-rink ballroom, and steaming kitchens.
- **Music**: Jazz-lounge tunes mixed with icy synths that grow more intense as the ice melts.

## Cross-Platform Design
- Controls are simplified for touchscreens with gesture combos.
- Console and PC versions offer full input precision.
- Deck-building and strategy screens adapt to any screen size.

## Unique Selling Points
- A mash-up of card game, brawler, and strategy in one setting.
- A mystery that changes every season.
- An ice hotel as a living, changing battlefield.
- Combo-driven arcade scoring alongside deep long-term strategy.

## Tagline
> *Check in. Fight on. Don''t let the ice melt.*', 'sports, grand strategy, beat ''em up', 'card game, cross-platform, mystery, stylized', 'office pc from the back of the warehouse', '2004-11-27 09:00:00+00'),
('Golden Reel Drive', 6.17, '# Reel Nights: Last Screen Standing

## Overview
Run a struggling drive-in cinema. Hunt clues in a text-driven world, solve point-and-click puzzles, and win over a fickle audience. Each night is procedurally generated, so no two are the same.

**Genres:** text adventure, point-and-click, hidden object
**Tags:** procedural generation, trivia, simulation, controller support
**Mechanics:** ranked ladders, reputation

---

## Story
The Starlite Drive-In has been in your family for 40 years. Your grandfather left it to you, along with a debt and a mystery. He hid a lost "Golden Reel" somewhere on the lot. The county wants to bulldoze the place at season''s end. You have 30 nights to save it.

- **Act I, Opening Night:** Repair the projector, meet the regulars, and find the first clue.
- **Act II, Rising Season:** Rival cinemas poach your audience. Strange visitors show up after midnight.
- **Act III, Final Reel:** Assemble the clues, hold the season finale, and decide the Starlite''s fate.

---

## Core Gameplay Loop

### 1. Day: Simulation and Exploration
- Manage the budget, staff, snack stand, and film rentals.
- Explore the lot in **point-and-click** scenes: the booth, concession stand, junkyard, and ticket gate.
- Use **text adventure** parsing (or controller radial menus) to talk, examine, and combine items.

### 2. Dusk: Hidden Object Scenes
- Search cluttered scenes such as the glovebox, projector room, and lost-and-found.
- Found objects unlock story beats, repairs, and puzzle pieces.
- Each scene is procedurally shuffled, with different items and layouts each time.

### 3. Night: Showtime
- Pick tonight''s double feature based on weather, crowd mood, and season.
- Handle live events: a broken speaker, a rowdy car, a rain delay.
- Run **trivia intermissions**. Correct answers raise crowd happiness and tips.

### 4. Late Night: Story and Rewards
- Review the takings, reputation changes, and ladder standing.
- Unlock a new clue or rumor about the Golden Reel.

---

## Systems

### Procedural Generation
- **Nightly crowds:** random regulars, VIPs, critics, and troublemakers.
- **Film catalog:** generated titles, posters, taglines, and trivia sets.
- **Hidden object layouts:** item pools change with each scene.
- **Events:** storms, blackouts, UFO rumors, and film-buff conventions.

### Reputation
| Faction | Likes | Dislikes |
|---|---|---|
| Families | Clean lot, cheap snacks | Late shows, rowdy crowds |
| Teens | Horror nights, loud sound | Strict rules |
| Cinephiles | Classics, good projection | Bad picture quality |
| Locals | Community events | Price hikes |

High reputation unlocks discounts, rare films, helpers, and secret story branches. Low reputation closes off options and can lead to a bad ending.

### Ranked Ladders
- **Weekly Season Ladder:** ranks players by profit, audience score, and trivia accuracy.
- **Trivia League:** a head-to-head ladder using seeded question sets.
- **Hidden Object Speed Board:** everyone gets the same seed, so times are comparable.
- Ranks: Usher, Projectionist, Showman, Impresario, Legend.

### Trivia
- Categories include film history, actors, soundtracks, and quotes from the game''s fictional films.
- Difficulty scales with your rank and the crowd''s cinephile level.
- Streaks give bonuses. Wrong answers can cost tips.

---

## Controls and Accessibility
- **Full controller support:** a cursor with snap-to-hotspot, radial menus for verbs, and shoulder-button hints for hidden objects.
- Keyboard and mouse are supported, with a text-input mode.
- Options for text size, colorblind-friendly highlights, and no-timer modes.

---

## Endings
1. **Legend of the Lot:** Find the Golden Reel and save the Starlite.
2. **Community Screen:** Max out reputation with the locals and turn the lot into a town landmark.
3. **Final Credits:** Sell to the county and get a bittersweet epilogue.
4. **Ghost Show:** Follow the midnight clues to a secret supernatural ending.

---

## Tone and Style
Warm, nostalgic, and funny, with a retro 70s-80s look: neon signs, grainy film effects, and a synth-and-jazz soundtrack. The writing mixes deadpan humor with cozy mystery.

## Pitch
*Run the coziest drive-in on Earth, find what your grandfather hid, and climb the ladder one showing at a time.*', 'text adventure, point-and-click, hidden object', 'procedural generation, trivia, simulation, controller support', 'any toaster with a screen', '2020-03-13 09:00:00+00'),
('Rimefall Manager', 16.94, '# Frostbound Vacancy

*A real-time text adventure / 4X / metroidvania roguelite, played like a living board game.*

---

## Premise

The **Aurora Halls** is a legendary ice hotel carved into a glacier. A storm seals its doors, and the ice starts to shift. Corridors grow and rooms refreeze. Something below the lobby wakes up. You are the night manager. Your job is to keep the guests alive, or to decide who deserves to live.

---

## Core Structure

### 1. Text Adventure Layer
- You explore by typing or choosing commands: `examine frozen piano`, `talk to concierge`, `pry open vent`.
- Descriptions are rich and change with your **sanity**.
- Everything runs in **real time**. The hotel keeps moving while you read. Doors freeze, guests wander, and temperatures drop whether or not you act.

### 2. Metroidvania Layer
- The hotel is one interconnected map of about 80 rooms across 6 wings: Lobby, Spa, Ice Bar, Sculpture Gallery, Staff Tunnels, and the Glacier Core.
- **Gated progress:** you need tools and abilities to open new areas.
  - *Thermal Key*: melts sealed doors.
  - *Crampons*: cross slick ice bridges.
  - *Whisper Lantern*: reveals hidden rooms, but drains sanity.
  - *Ice Sight*: reads the memories frozen inside walls.
- Backtracking is rewarded. Old rooms change and reveal new secrets.

### 3. 4X Layer (Hotel Management as Conquest)
- **Explore:** chart the shifting halls and uncover the glacier''s history.
- **Expand:** reclaim frozen wings, repair them, and turn them into functioning zones.
- **Exploit:** manage heat, food, generators, and staff. Assign guests and workers to jobs such as engineers, cooks, guards, and sculptors.
- **Exterminate:** deal with threats. These include ice wraiths, hostile factions of guests, and the Core''s influence. You can fight them, banish them, or negotiate.

### 4. Board Game Layer
- The hotel map is shown as a **tile board**. Rooms are tiles you flip, rotate, and place.
- Each in-game hour you draw **Event Cards** (Blizzard, Power Cut, Stowaway, Old Debt).
- Guests and threats are **tokens** with stats. Dice and card tiebreakers resolve uncertain actions.
- Between runs you unlock new card decks and tile sets.

---

## Roguelite Loop

- Each **night** is a run. The storm lasts 7 in-game hours.
- If you die or the hotel falls, the hotel **resets**. The layout is reshuffled, but your **knowledge and permanent upgrades** stay.
- Meta-progression:
  - New starting tools.
  - Unlocked guest backstories.
  - Deeper story fragments about the Core.
- Each run reveals a little more of the truth.

---

## Mechanics

### Sanity Meter
| Level | State | Effects |
|---|---|---|
| 100-70 | Clear | Accurate descriptions, reliable maps |
| 69-40 | Uneasy | Text shifts, false sounds, unreliable guest info |
| 39-10 | Fractured | Hallucinated rooms, misleading options, whispers offer "help" |
| 9-0 | Frozen | Loss of control, and the Core takes over your commands |

- Sanity drops from cold, darkness, horrors, and hard choices.
- It recovers with warmth, rest, music, and kind acts.
- Low sanity is not only a penalty. It unlocks **forbidden options** and hidden routes.

### Morality System
- Every choice moves you along a **Warm ↔ Cold** axis.
  - **Warm:** mercy, sharing, sacrifice. Guests trust you, and allies stay loyal.
  - **Cold:** ruthlessness, hoarding, abandonment. You get efficiency, resources, and power.
- Morality affects:
  - Which guests survive and who will help you.
  - Which endings are available.
  - How the Core treats you: as a guardian or as heir.
- Sanity and morality interact. Cold acts steady your mind in the short term but corrode the hotel''s warmth. Warm acts cost resources but protect your sanity.

---

## Story Arc (Structured)

**Act I: Check-In (Nights 1-3)**
You learn the hotel''s rules and meet the key guests. A death in the Ice Bar shows that this was not an accident.

**Act II: The Thaw (Nights 4-8)**
You discover the hotel was built over a sealed **Glacier Core**, a frozen entity that feeds on warmth and memory. The staff have been feeding it guests for decades.

**Act III: The Long Winter (Nights 9+)**
Factions form: Keepers (maintain the seal), Devotees (worship the Core), and Escapees (want out at any cost). You choose a side or forge your own path.

---

## Endings
- **The Last Fire:** break the Core''s hold and thaw the hotel. You survive and are warm again, but the hotel is lost.
- **Eternal Guest:** embrace the Core and become the hotel''s new manager.
- **Ice Throne:** rule the hotel as a cold tyrant.
- **Checkout:** escape alone, or with those you saved.
- **Loop''s End:** a secret ending that needs perfect knowledge of every run.

---

## Tone & Style
Minimal, atmospheric prose with a quiet dread, in the spirit of a chilled *Disco Elysium* crossed with *Dungeon Keeper* and *Betrayal at House on the Hill*.

**Tagline:** *"Checkout is at dawn. If you make it."*', 'text adventure, 4x, metroidvania', 'real-time, roguelite, board game', 'high-end gpu, 32 gb ram, and a good cooling plan', '2018-12-09 09:00:00+00'),
('Reelborn: Last Feature at Starlight', 9.10, '# Last Reel at Starlight Drive-In

*An atmospheric monster-taming RTS with a kinetic-novel story. Adults only (18+), with mature themes handled without explicit detail.*

## Premise
The Starlight Drive-In has been showing one film every night since 1987. Tonight the film is not a movie. The screen has become a portal, and creatures called **Reelborn** are coming out of it. Their forms come from old B-movies: moths the size of cars, chrome-skinned drifters, and moaning things that look like lost projector light.

You play **the projectionist**, an adult night-shift worker. You can''t leave the lot until dawn. Your only defense is a 35mm booth full of cursed film cans.

## Story Structure (Kinetic Novel)
The story is linear, with no choices. It plays out in five "features" and reads like a slow midnight double bill.

| Act | Title | Beat |
|---|---|---|
| 1 | Previews | The first creature appears. The projectionist finds the taming reel. |
| 2 | Feature Presentation | Bonds form with the first Reelborn, including a shy moth-woman. |
| 3 | Intermission | The lot goes quiet. Secrets about the theater''s owner come out. |
| 4 | Second Feature | A larger wave arrives, led by a jealous, screen-born spirit. |
| 5 | Credits | Dawn breaks. The bonds you formed decide the ending. |

The romance elements are adult, consensual, and emotional. They fade to black rather than showing anything explicit.

## Gameplay Loop (RTS + Taming)
1. **Dusk (build phase):** Place speakers, spotlights, snack stands, and barricades around the car rows.
2. **Night (wave phase):** Reelborn spawn in escalating **waves** from the screen and the lot edges.
3. **Taming:** Weaken a creature, then play a matching reel to bond with it. Tamed creatures become units you can command.
4. **Dawn (recovery):** Repair, feed, and bond with your team. These scenes carry the visual novel story.

## Mechanics
- **Aim assist:** A soft-lock projector beam helps you target creatures. Its help is weaker against fast or erratic ones, so you still need to lead your shots.
- **Wave spawning:** Waves come from set portal points and follow a film-reel schedule. Bosses arrive on "scene changes." Difficulty rises each night.
- **Unit command:** You select and order tamed units RTS-style. Each has a mood meter that affects how well it obeys.

## Atmosphere
- Neon glow, fog, and the flicker of a projector beam.
- An analog synth soundtrack mixed with the noise of a crackling car radio.
- The lot fills with ghostly headlights as the night goes on.

## Difficulty
The game is hard and unforgiving. Losing a tamed creature is permanent for that run. Resources are scarce, and the last three waves are punishing. You have to plan around each creature''s abilities and moods to survive until dawn.

## Tags
`RTS` `Adventure` `Difficult` `Atmospheric` `Kinetic Novel` `Monster Taming` `18+`', 'hentai, kinetic novel, monster taming', 'rts, adventure, difficult, atmospheric', 'rtx 4080 or better; your pc will hum a lullaby', '2017-04-10 09:00:00+00');
